const INTERVALLES=[{nom:"unisson",deg:0},{nom:"seconde",deg:1},{nom:"tierce",deg:2},{nom:"quarte",deg:3},
  {nom:"quinte",deg:4},{nom:"sixte",deg:5},{nom:"septième",deg:6},{nom:"octave",deg:7}];
/* intervalles disponibles selon le niveau (pour l'écoute / la reconnaissance) :
   6e-5e : unisson, seconde, tierce ; 4e : + quarte, quinte ; 3e : tout (jusqu'à l'octave). */
function intervallesNiveau(){
  // Reconnaissance d'intervalles (sans unisson, on part de la seconde) :
  if(difficulte===1)return INTERVALLES.filter(i=>i.deg>=1&&i.deg<=3);   // seconde → quarte
  if(difficulte===2)return INTERVALLES.filter(i=>i.deg>=1&&i.deg<=5);   // seconde → sixte
  return INTERVALLES.filter(i=>i.deg>=1);                               // seconde → octave
}
