/* photo d'un orchestre symphonique (remplacée par le data-URI base64 au build) */
const IMG_ORCHESTRE="images/img-087.webp";
/* Galerie d'instruments (photos déjà embarquées dans INSTR_IMG), regroupée par famille,
   utilisée dans la leçon « Les instruments en images ». */
function galerieInstrumentsHTML(){
  const ordre=["Cordes","Vents – bois","Vents – cuivres","Percussions"];
  const parFam={};
  INSTR_IMG.forEach(i=>{(parFam[i.fam4]=parFam[i.fam4]||[]).push(i);});
  let h="";
  ordre.forEach(f=>{
    if(!parFam[f])return;
    h+=`<div class="instr-gal-fam">${f}</div><div class="instr-gal">`;
    parFam[f].forEach(i=>{h+=`<figure class="instr-vign"><img src="${i.img}" alt="${i.n}" loading="lazy"><figcaption>${cap(i.n)}</figcaption></figure>`;});
    h+=`</div>`;
  });
  return h;
}

/* instruments filtrés selon le niveau de difficulté courant (cumulatif) */
function famillesNiveau(){const seuil=difficulte; const o={};
  for(const f of Object.keys(FAMILLES)){const l=FAMILLES[f].filter(i=>(i.r||1)<=seuil);if(l.length)o[f]=l;}
  return o;}
