/* Badges visibles dans la grille et comptés dans le total /30 (hors caché) */
const BADGES_VISIBLES=BADGES.filter(b=>!b.cache);
function verifierBadges(){
  const nouveaux=[];
  /* Un seul badge par vérification : on évite les rafales (« plusieurs d'un coup »).
     Le prochain badge mérité arrivera à la vérification suivante. */
  for(let i=0;i<BADGES.length;i++){ const b=BADGES[i];
    if(!profil.badges.includes(b.id)&&b.test(profil)){
      profil.badges.push(b.id); nouveaux.push(b);
      /* Les badges ne donnent PAS de points (complémentaires aux niveaux) : ils
         offrent un BONUS (si le badge en prévoit un et si l'emplacement est libre). */
      if(b.bonus&&typeof donnerBonus==="function"&&typeof bonusFaire==="function"){
        try{ donnerBonus(bonusFaire(b.bonus,"badge")); }catch(e){}
      }
      /* Certains badges offrent en plus un JOKER de Survie (réserve consommable). */
      if(b.jokerSurvie){ profil.jokersSurvie=(profil.jokersSurvie||0)+1; }
      break;
    } }
  try{ verifierCollectionComplete(); }catch(e){}
  return nouveaux;
}
/* GROS BONUS : quand un élève a décroché TOUS les badges visibles, une récompense
   exceptionnelle, une seule fois (drapeau profil.badgesTousVu). Distinct du badge
   caché « Légende », qui exige, lui, 100 % de réussite partout. */
function collectionBadgesComplete(){
  return BADGES_VISIBLES.every(function(b){ return profil.badges.includes(b.id); });
}
function verifierCollectionComplete(){
  if(!profil||profil.badgesTousVu)return false;
  if(!collectionBadgesComplete())return false;
  profil.badgesTousVu=true;
  /* 1) pluie de points hors plafond quotidien (comme les duels / le Calmar) : une
        vraie récompense, non bridée par la limite du jour */
  const WINDFALL=300;
  profil.points=(profil.points||0)+WINDFALL;
  /* 2) le meilleur bonus d'évaluation, GARANTI, dans l'emplacement BADGE (récompense
        de collection de badges ; remplace l'éventuel bonus de badge en cours) */
  try{ profil.bonusBadge=bonusFaire("note2","collection"); }catch(e){}
  try{ sauverProfil(profil); }catch(e){}
  try{ if(typeof majEnteteProfil==="function")majEnteteProfil(); }catch(e){}
  try{ if(typeof envoyerScoreClassement==="function")envoyerScoreClassement(); }catch(e){}
  try{ if(typeof syncEleve==="function")syncEleve(); }catch(e){}
  setTimeout(function(){ try{ annoncerCollectionComplete(WINDFALL); }catch(e){} },1200);
  return true;
}
function annoncerCollectionComplete(pts){
  const ov=document.createElement("div");ov.className="celebr-overlay";
  ov.innerHTML=`<div class="celebr-carte">
      <button class="celebr-fermer" title="Fermer" aria-label="Fermer" onclick="this.closest('.celebr-overlay').remove()"><i class="ph ph-x"></i></button>
      <div style="font-size:3.4rem;line-height:1;color:var(--or-texte)"><i class="ph-fill ph-medal"></i></div>
      <h3>Tous les badges&nbsp;!</h3>
      <p>Incroyable&nbsp;: tu as décroché <b>la collection complète</b> des badges de MusEduc. Un immense bravo&nbsp;!</p>
      <div class="score20" style="font-size:1.4rem">GROS BONUS</div>
      <p style="margin-top:8px;color:var(--laiton);font-weight:700"><i class="ph ph-star"></i> +${pts} points offerts <span style="color:var(--encre-doux);font-weight:600">(hors plafond du jour)</span></p>
      <p style="color:var(--encre-doux);font-size:.9rem"><i class="ph ph-plus-circle"></i> Et un <b>Super bonus (+2 points)</b> à utiliser sur une évaluation.</p>
      <div style="margin-top:16px"><button class="action btn-defi" onclick="this.closest('.celebr-overlay').remove()"><i class="ph ph-check"></i> Génial&nbsp;!</button></div>
    </div>`;
  document.body.appendChild(ov);
  try{ jouerEffet("victoire"); }catch(e){}
  if(animOk())lancerConfettis();
}
/* nombre de badges (hors caché) déjà obtenus, pour l'affichage X/30 */
function nbBadgesObtenus(){return profil.badges.filter(id=>{const b=BADGES.find(x=>x.id===id);return b&&!b.cache;}).length;}
function aLeBadgeCache(){return profil.badges.includes("legende");}
/* Indice de la SEMAINE : un seul indice par semaine (stable du lundi au dimanche),
   pour que « tout débloquer » reste un vrai défi sur l'année. Le badge caché n'est
   inclus que lorsque tous les autres sont obtenus. */
function indiceBadgeDuJour(){
  let manquants=BADGES_VISIBLES.filter(b=>!profil.badges.includes(b.id));
  if(!manquants.length){const bc=BADGES.find(b=>b.id==="legende");manquants=aLeBadgeCache()?[]:[bc];}
  if(!manquants.length)return "Tu as déjà tout débloqué, bravo !";
  // graine = numéro de semaine de l'année, pour un indice stable sur la semaine
  const j=new Date();const jour=Math.floor((j-new Date(j.getFullYear(),0,0))/86400000);
  const graine=Math.floor(jour/7);
  const b=manquants[graine%manquants.length];
  return b.indice;
}
/* niveau de maîtrise d'un thème : 0 (jamais vu) / "faible"/"moyen"/"fort" */
/* Palier atteint par l'élève sur un thème (sans l'ouverture totale du prof) :
   1 = Facile en cours, 2 = Facile validé, 3 = Intermédiaire validé,
   4 = Difficile validé (évaluation débloquée) = MAÎTRISÉ. */
function palierEleve(id){
  if(profil.niveauMax&&profil.niveauMax[id]!=null)return profil.niveauMax[id];
  const e=(profil.entrainOK&&profil.entrainOK[id])||{};
  let nm=1; if(e[1])nm=2; if(e[1]&&e[2])nm=3; if(e[1]&&e[2]&&e[3])nm=4;
  return nm;
}
/* Tout ce qu'il faut pour dire où en est l'élève sur un thème. */
function palierInfo(id){
  const nm=palierEleve(id), joue=(profil.best&&profil.best[id]!==undefined)||nm>1;
  const serie=(nm<4)?((profil.serieNiv&&profil.serieNiv[id+"|"+nm])||0):0;
  const tps=Math.round((profil.tempsTheme&&profil.tempsTheme[id])||0);
  let total=3; try{ total=serieDebloc(); }catch(e){}
  return {nm:nm, joue:joue, serie:serie, total:total, tps:tps};
}
/* Maîtrise : « fort » seulement quand les TROIS niveaux sont validés (avant,
   80 % en Facile suffisait, ce qui affichait « maîtrisé » beaucoup trop tôt). */
function maitrise(id){
  const p=palierInfo(id); if(!p.joue)return 0;
  return p.nm>=4?"fort":(p.nm>=2?"moyen":"faible");
}
/* Pastilles F · I · D, identiques chez l'élève et chez le professeur.
   p = {nm, serie, total} ; validé = coche, en cours = x/3, pas encore = cadenas. */
function palierPastillesHTML(p){
  return '<span class="pl-pastilles">'+[1,2,3].map(function(L){
    const lib=NIV_NOMS[L];
    if(p.nm>L)return '<span class="pl-p ok" title="'+lib+' validé"><i class="ph ph-check"></i>'+lib.charAt(0)+'</span>';
    if(p.nm===L)return '<span class="pl-p cours" title="'+lib+' en cours : '+p.serie+' série'+(p.serie>1?"s":"")+' réussie'+(p.serie>1?"s":"")+' sur '+p.total+'">'+lib.charAt(0)+' '+p.serie+'/'+p.total+'</span>';
    return '<span class="pl-p non" title="'+lib+' pas encore débloqué"><i class="ph ph-lock-simple"></i>'+lib.charAt(0)+'</span>';
  }).join("")+'</span>';
}
function palierTexte(nm){ return nm>=4?"Maîtrisé":(nm===3?"Niveau difficile":(nm===2?"Niveau intermédiaire":"Niveau facile")); }

/* Durée de l'évaluation, en minutes, et nombre de questions */
const EVAL_MINUTES = 15;
const EVAL_NB_QUESTIONS = 20;
/* Temps supplémentaire accordé aux élèves PAP (tiers-temps), en minutes.
   1/3 de 15 min ≈ 5 min. Ajustez si besoin. */
const EVAL_MINUTES_PAP = 5;

/* ---------- État évaluation ---------- */
let evalActif=false, evalDomaine=null, evalDiff=2, evalIndex=0, evalReponses=[],
    evalExos=[], evalTimer=null, evalFinAt=0, evalSorties=0, evalEleve={}, evalGraine=0, evalPap=false, evalBonusVoulu=null, evalTempsBonus=0;

/* =====================================================================
   RNG à graine (mélange reproductible, propre à chaque élève)
   ===================================================================== */
function graineDepuis(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function rngFactory(seed){let s=seed>>>0;return function(){s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
let evalRng=Math.random; // remplacé par un rng à graine pendant l'éval

/* Capitalise joliment en gardant les séparateurs : "JEAN-LUC" -> "Jean-Luc" */
function joliNom(s){return (s||"").toLowerCase().replace(/[a-zà-ÿ0-9]+/g,m=>m.charAt(0).toUpperCase()+m.slice(1));}
/* =====================================================================
   TRANSPORT DE SECOURS : Google Apps Script
   Hérité d'avant Firebase. Ne sert plus qu'au multijoueur et au classement
   quand Firebase n'est pas disponible (voir jeuPost/jeuGet). Aucun nom en clair.
   ===================================================================== */
const CLE_URL_SHEET="musiceduc_sheet_url";
/* Pour que l'envoi marche quand les élèves ouvrent le fichier CHEZ EUX,
   le professeur peut écrire l'URL ici, une fois pour toutes, entre les guillemets. */
const URL_SHEET_PAR_DEFAUT="https://script.google.com/macros/s/AKfycbxCb2VVmBsMouAOYgTylwjUzRaLKji9aATX-_yfFg3HmQSF67EPEH6JDg3RujE3YY6W/exec";
/* Le lien inscrit dans le fichier (URL_SHEET_PAR_DEFAUT) a PRIORITÉ : ainsi, un vieux
   lien enregistré autrefois dans le navigateur ne peut plus désynchroniser l'application.
   Le lien enregistré localement ne sert que si le fichier n'en contient aucun. */
function lireUrlSheet(){try{const u=(localStorage.getItem(CLE_URL_SHEET)||"").trim();if(u)return u;}catch(e){}return URL_SHEET_PAR_DEFAUT||"";}
/* Envoie une charge utile au Sheet. Retourne une promesse (résolue si la
   requête est partie sans erreur réseau). Ne bloque jamais l'élève. */
function envoyerCharge(charge){
  const url=lireUrlSheet();
  if(!url)return Promise.reject("Aucun lien configuré.");
  return fetch(url,{method:"POST",redirect:"follow",
    headers:{"Content-Type":"text/plain;charset=utf-8"},
    body:JSON.stringify(charge)});
}

/* =====================================================================
   CLASSEMENT EN DIRECT (via le même Google Sheet)
   - Chaque élève envoie automatiquement {classe, nom, prénom, points}
     quand ses points changent (au plus toutes les 40 s, jamais bloquant).
   - L'écran « Classement » relit le Sheet (GET ?classement=1) toutes les
     30 s et affiche le palmarès par classe.
   ===================================================================== */
/* --- RGPD : identifiant anonyme stable + noms chiffrés (jamais en clair sur le tableur) ---
   - uid : identifiant aléatoire généré une fois et gardé dans le navigateur. C'est LUI qui
     identifie l'élève dans le tableur -> changer de nom ou de classe met à jour la MÊME
     ligne (plus de doublons).
   - nom/prénom : chiffrés (XOR à flux, clé = secret embarqué + uid) puis encodés en
     base64url. Le tableur ne voit que des suites illisibles ; seule l'application sait
     les déchiffrer pour afficher le classement. */
const SECRET_NOMS="MUSEDUC-NOMS-2026"; // clé de déchiffrement embarquée dans l'application
function uidProfil(){
  if(!profil.uid){
    profil.uid=Date.now().toString(36)+Math.floor(Math.random()*1679616).toString(36)+Math.floor(Math.random()*1679616).toString(36);
    sauverProfil(profil);
  }
  return profil.uid;
}
let dernierEnvoiClassement=0, derniersPointsEnvoyes=-1;
let modeGraine=false;
const rnd=n=>Math.floor((modeGraine?evalRng():Math.random())*n);
const pick=a=>a[rnd(a.length)];
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=rnd(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
const norm=s=>{
  const t=(s||"").toString().trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
  const a=t.replace(/[^a-z0-9]/g,"");
  /* Une réponse faite UNIQUEMENT de symboles (« ÷ », « × », « + », « ♯ ») se
     réduisait à du vide : toutes les options devenaient alors identiques et la
     correction tombait au hasard (albums d'Ed Sheeran, altérations…).
     Dans ce cas on garde le texte brut, espaces retirés. */
  return a||t.replace(/\s+/g,"");
};
const frac=x=>({0.25:"¼",0.5:"½",0.75:"¾",1.5:"1½"}[x]||x.toString().replace(".",","));
/* empreinte d'une question = sa consigne nettoyée (sans les options mélangées,
   qui ne changent pas la question posée). Sert à éviter les doublons. */
function empreinteEx(e){
  if(e&&e.emp!==undefined)return "k:"+e.emp;   // empreinte explicite fournie par le générateur
  let s=(e&&e.consigne)||"";
  s=s.replace(/<[^>]*>/g,"");            // enlève le HTML
  if(e&&e.visuel&&e.bonneRep!==undefined)s+="|v:"+e.bonneRep;
  return s.replace(/\s+/g," ").trim().toLowerCase();
}
/* Génère n questions en évitant les répétitions autant que possible.
   - On retente tant qu'on tombe sur une empreinte déjà vue (jusqu'à maxTry).
   - Si la catégorie n'a pas assez de variété, on accepte au moins une question
     différente de la précédente ; en dernier recours on accepte quand même
     (pour ne jamais boucler indéfiniment). */
/* « groupe » (facultatif, fourni par le générateur) : ce sur quoi porte la question
   (un instrument, une mélodie). Deux questions différentes sur la même photo se
   ressemblent trop : on évite d'abord de reprendre un groupe déjà vu, et on ne
   l'accepte qu'une fois tous les groupes passés, avec une question différente. */
const mapEx=(n,fn)=>{
  const out=[], vues=new Set(), groupes=new Set();
  for(let i=0;i<n;i++){
    let cand=fn(), emp=empreinteEx(cand), essais=0;
    const prev=out.length?empreinteEx(out[out.length-1]):null;
    const grpVu=c=>!!(c&&c.groupe&&groupes.has(c.groupe));
    while((vues.has(emp)||emp===prev||grpVu(cand))&&essais<80){cand=fn();emp=empreinteEx(cand);essais++;}
    /* plus de groupe neuf : on se contente d'une question jamais posée */
    essais=0;
    while((vues.has(emp)||emp===prev)&&essais<60){cand=fn();emp=empreinteEx(cand);essais++;}
    // si on n'a pas réussi à éviter un déjà-vu, on tente au moins d'éviter l'identique consécutif
    if(emp===prev){let e2=0;while(emp===prev&&e2<40){cand=fn();emp=empreinteEx(cand);e2++;}}
    out.push(cand); vues.add(emp); if(cand&&cand.groupe)groupes.add(cand.groupe);
  }
  return out;
};
function selNotes(){return choixBoutons(GAMME.slice());}
/* selListe(liste[, bonne]) :
   - sans "bonne" : affiche toutes les options (mélangées), comportement d'origine ;
   - avec "bonne" : le nombre d'options proposées grandit avec le niveau
     (6e/5e = 3 options, 4e = 4, 3e = jusqu'à 6), ce qui rend le choix plus
     difficile au fur et à mesure tout en gardant toujours la bonne réponse. */
function selListe(l,bonne){
  let liste=l.slice();
  if(bonne!==undefined&&liste.length>3){
    const nb=difficulte===1?3:difficulte===2?4:Math.min(6,liste.length);
    if(liste.length>nb){
      /* on garde d'abord les distracteurs de LONGUEUR proche de la bonne réponse :
         sinon, à force d'écarter les options courtes, la bonne réponse finissait
         par être la plus longue de la liste, et se devinait sans rien savoir. */
      const lb=String(bonne).length;
      const distract=shuffle(liste.filter(x=>x!==bonne))
        .sort((a,b)=>Math.abs(String(a).length-lb)-Math.abs(String(b).length-lb))
        .slice(0,nb-1);
      liste=shuffle([bonne,...distract]);
    }
  }
  return choixBoutons(shuffle(liste));
}
/* Rend un groupe de boutons-réponses (remplace l'ancien <select>).
   Le conteneur .rep porte data-value = réponse choisie (lue comme l'était .value). */
function choixBoutons(options){
  const btns=options.map(n=>`<button type="button" class="opt" data-val="${escAttr(n)}" onclick="choisirOpt(this)">${n}</button>`).join("");
  return `<div class="rep choix-btns" data-value="" role="group">${btns}</div>`;
}
function escAttr(s){return (""+s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
/* lit la réponse d'un champ .rep, qu'il soit un <select>/<input> (.value) ou un groupe de boutons (data-value) */
function valRep(el){if(!el)return "";
  if(el.classList&&el.classList.contains("choix-btns")){
    if(el.dataset.value)return el.dataset.value;
    const sel=el.querySelector(".opt.sel");return sel?(sel.dataset.val||""):""; // filet de sécurité : bouton sélectionné
  }
  return el.value||"";}
/* clic sur une option : sélectionne, stocke la valeur dans le conteneur .rep */
function choisirOpt(btn){
  const grp=btn.closest(".choix-btns");
  if(!grp||grp.classList.contains("verrou"))return;
  /* en évaluation, un appui dans le quart de seconde qui suit l'affichage d'une
     question est le 2e toucher d'un double appui sur la précédente : on l'ignore */
  if(typeof evalActif!=="undefined"&&evalActif&&Date.now()-_evalAfficheLe<300)return;
  grp.querySelectorAll(".opt").forEach(b=>b.classList.remove("sel"));
  btn.classList.add("sel");
  grp.dataset.value=btn.dataset.val;
  // déclenche un évènement "change" pour la correction immédiate éventuelle
  grp.dispatchEvent(new Event("change",{bubbles:true}));
  /* En évaluation, choisir VAUT valider : on passe à la question suivante sans
     que l'élève ait à cliquer « Suivant ». */
  if(typeof evalActif!=="undefined"&&evalActif&&typeof evalAvanceAuto==="function")evalAvanceAuto();
}
/* article défini : "le violon", "la trompette", "l'orgue", "les cymbales" */
function article(inst){return inst.pl?`les ${inst.n}`:(inst.e?`l'${inst.n}`:(inst.g==="f"?`la ${inst.n}`:`le ${inst.n}`));}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1);}
/* pluriel des figures rythmiques : "double croche" -> "doubles croches" */
function plurFig(nom,n){if(n<=1)return nom;
  if(nom==="double croche")return "doubles croches";
  return nom+"s";}
/* renvoie un objet instrument tiré au hasard, avec sa famille */
function tirerInstrument(){const FN=famillesNiveau();const fam=pick(Object.keys(FN));const inst=pick(FN[fam]);return {fam,inst};}

/* =====================================================================
   SON : Web Audio API (aucun fichier externe)
   f = 440 × 2^((midi − 69)/12) ; La3(latin) = A4 = midi 69 = 440 Hz
   ===================================================================== */
let actx=null;
function audio(){if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();return actx;}
const MIDI_BASE={Do:60,"Ré":62,Mi:64,Fa:65,Sol:67,La:69,Si:71}; // octave centrale (Do3 = midi 60)
function midiVersFreq(m){return 440*Math.pow(2,(m-69)/12);}

/* ============ MÉLODIES CÉLÈBRES À RECONNAÎTRE (« Pour aller plus loin ») ============
   Notation lisible -> [ [midi,durée en temps], ... ]. Ex : "E4 E4:0.5 R:1 C#5:2".
   Ce sont les MOTIFS D'OUVERTURE, synthétisés au piano. niv : 1 facile, 2 inter, 3 difficile. */
function mel(str){
  const semi={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
  return str.trim().split(/\s+/).map(tok=>{
    const i=tok.indexOf(":");const dur=i>=0?parseFloat(tok.slice(i+1)):1;const p=i>=0?tok.slice(0,i):tok;
    if(p[0]==="R")return [null,dur];
    const mm=p.match(/^([A-G])([#b]?)(-?\d)$/);if(!mm)return [null,dur];
    return [(parseInt(mm[3])+1)*12+semi[mm[1]]+(mm[2]==="#"?1:mm[2]==="b"?-1:0),dur];
  });
}
