function jouerMel(i){const it=MELODIES[i];if(it){try{audio().resume();}catch(e){}jouerSonBtn({melodie:it.m});}}
/* galerie des mélodies pour la leçon, groupée par niveau */
function galerieMelodiesHTML(){
  const niveaux=[[1,"<i class='ph-fill ph-circle' style='color:#2f9e63'></i> Faciles : à connaître absolument"],[2,"<i class='ph-fill ph-circle' style='color:#EBAA27'></i> Intermédiaires : très célèbres"],[3,"<i class='ph-fill ph-circle' style='color:#e0483b'></i> Difficiles : pour la culture générale"]];
  let h="";
  niveaux.forEach(([n,lib])=>{
    h+=`<div class="mel-niv">${lib}</div><div class="mel-gal">`;
    MELODIES.forEach((it,i)=>{ if(it.niv!==n)return;
      h+=`<div class="mel-carte"><button class="btn-son mini" onclick="jouerMel(${i})" title="Écouter"><i class="ph ph-play"></i></button><span class="mel-t">${it.t}</span><span class="mel-c">${it.c}</span></div>`;
    });
    h+=`</div>`;
  });
  return h;
}
function jouerFreq(freq,debut,duree,vol=0.25){
  const ctx=audio(), t=ctx.currentTime+debut;
  // Timbre de piano : harmoniques + enveloppe à longue résonance (sustain), attaque douce.
  const sortie=ctx.createGain();
  sortie.gain.value=vol;
  sortie.connect(ctx.destination);
  // filtre passe-bas qui se referme lentement : le son s'assombrit en s'éteignant, comme un vrai piano
  const filtre=ctx.createBiquadFilter();
  filtre.type="lowpass";
  filtre.frequency.setValueAtTime(Math.min(8500,freq*7+2000),t);
  filtre.frequency.exponentialRampToValueAtTime(Math.max(600,freq*1.6),t+2.6);
  filtre.connect(sortie);
  // résonance longue et chaleureuse : la note tient bien au-delà de sa durée nominale
  const reso=Math.max(2.6,duree*2.4);
  // harmoniques : fondamental dominant (son chaud), partiels aigus discrets
  // [rang, amplitude relative, facteur de raccourcissement de l'extinction]
  const partiels=[[1,1,1],[2,0.32,1.3],[3,0.14,1.7],[4,0.07,2.1],[5,0.035,2.6],[6,0.018,3.1]];
  partiels.forEach(([rang,amp,decay])=>{
    const f=freq*rang; if(f>15000)return;
    const osc=ctx.createOscillator(), g=ctx.createGain();
    osc.type="sine"; osc.frequency.value=f;
    const fin=t+reso/decay;            // les aigus s'éteignent avant le fondamental
    g.gain.setValueAtTime(0,t);
    g.gain.linearRampToValueAtTime(amp,t+0.02);            // attaque douce (pas de claquement)
    g.gain.exponentialRampToValueAtTime(amp*0.55,t+0.4);   // léger fléchissement naturel
    g.gain.exponentialRampToValueAtTime(0.0001,fin);       // longue extinction progressive
    osc.connect(g).connect(filtre);
    osc.start(t); osc.stop(fin+0.05);
  });
}
function jouerMidi(m,debut=0,duree=0.7,vol=0.25){jouerFreq(midiVersFreq(m),debut,duree,vol);}
const IMG_CLE_SOL="images/img-088.png";
const IMG_CLE_FA="images/img-089.png";
/* géométrie des images de clés : largeur,hauteur, y de la ligne de référence, interligne (px image) */
const CLE_SOL_GEO={w:269,h:705,refY:430,inter:103.25}; // refY = 2e ligne (œil de la spirale)
const CLE_FA_GEO={w:302,h:343,refY:99,inter:102};       // refY = 4e ligne (entre les 2 points)
function dessinerPortee(cle,pos,afficher){
  const W=230,H=140,x0=24,e=12,top=52,baseY=top+4*e,nx=140;
  const yLigne=n=>top+(4-n)*e; // n=1 (bas) .. 5 (haut)
  let s=`<svg class="portee" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Portée en clé de ${cle==="fa"?"fa":"sol"}${afficher?", avec une note à lire (exercice visuel)":""}">`;
  for(let i=0;i<5;i++){const y=top+i*e;s+=`<line x1="${x0}" y1="${y}" x2="${W-15}" y2="${y}" stroke="#1f2440" stroke-width="1.4"/>`;}
  s+=cleSVG(cle,e,yLigne);
  if(afficher){
    const ny=baseY-pos*(e/2);
    if(pos<0)for(let p=-2;p>=pos;p-=2){const ly=baseY-p*(e/2);s+=`<line x1="${nx-12}" y1="${ly}" x2="${nx+12}" y2="${ly}" stroke="#1f2440" stroke-width="1.4"/>`;}
    if(pos>8)for(let p=10;p<=pos;p+=2){const ly=baseY-p*(e/2);s+=`<line x1="${nx-12}" y1="${ly}" x2="${nx+12}" y2="${ly}" stroke="#1f2440" stroke-width="1.4"/>`;}
    s+=`<ellipse cx="${nx}" cy="${ny}" rx="8" ry="6" fill="#1f2440" transform="rotate(-18 ${nx} ${ny})"/>`;
    s+=`<line x1="${nx+7}" y1="${ny}" x2="${nx+7}" y2="${ny-34}" stroke="#1f2440" stroke-width="1.6"/>`;
  }
  return s+`</svg>`;
}
/* Clés dessinées en tracés vectoriels (rendu identique sur tous les ordinateurs).
   Les chemins sont dessinés dans un repère propre puis placés/redimensionnés pour
   que leur point de référence tombe sur la bonne ligne de la portée. */
function cleSVG(cle,e,yLigne){
  if(cle==="sol"){
    const g=CLE_SOL_GEO, sc=e/g.inter, w=g.w*sc, h=g.h*sc;
    const x=22, y=yLigne(2)-g.refY*sc+e; // œil de la spirale calé sur la 2e ligne (la ligne du Sol)
    return `<image href="${IMG_CLE_SOL}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="none"/>`;
  } else {
    const g=CLE_FA_GEO, sc=e/g.inter, w=g.w*sc, h=g.h*sc;
    const x=24, y=yLigne(4)-g.refY*sc+e; // entre-les-deux-points calé sur la 4e ligne (la ligne du Fa)
    return `<image href="${IMG_CLE_FA}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="none"/>`;
  }
}
function noteDepuisPos(cle,pos){const ref=cle==="sol"?2:4;return GAMME[((ref+pos)%7+7)%7];}

/* Repère visuel de lecture : la gamme de Do dessinée sur la portée, avec le nom
   de chaque note dessous. L'élève voit OÙ se placent les notes avant de lire.
   Positions : 0 = 1re ligne (Mi en clé de sol, Sol en clé de fa), +1 par degré. */
function dessinerGamme(cle){
  const debut = (cle==="sol") ? -2 : 3;        // le Do le plus lisible pour chaque clé
  const e=13, x0=20, top=40, baseY=top+4*e, H=baseY+52, pas=38, xNote=96;
  const W=xNote+8*pas;
  const yLigne=n=>top+(4-n)*e;
  let s=`<svg class="portee-gamme" viewBox="0 0 ${W} ${H}" width="100%" style="max-width:${W}px" role="img" aria-label="Gamme de do majeur en clé de ${cle==="fa"?"fa":"sol"} : do, ré, mi, fa, sol, la, si, do">`;
  for(let i=0;i<5;i++){const y=top+i*e;
    s+=`<line x1="${x0}" y1="${y}" x2="${W-10}" y2="${y}" stroke="currentColor" stroke-width="1.4" opacity=".85"/>`;}
  s+=cleSVG(cle,e,yLigne);
  for(let k=0;k<8;k++){
    const pos=debut+k, x=xNote+k*pas, y=baseY-pos*(e/2);
    /* lignes supplémentaires quand la note sort de la portée */
    if(pos<0)for(let p=-2;p>=pos;p-=2){const ly=baseY-p*(e/2);
      s+=`<line x1="${x-13}" y1="${ly}" x2="${x+13}" y2="${ly}" stroke="currentColor" stroke-width="1.4"/>`;}
    if(pos>8)for(let p=10;p<=pos;p+=2){const ly=baseY-p*(e/2);
      s+=`<line x1="${x-13}" y1="${ly}" x2="${x+13}" y2="${ly}" stroke="currentColor" stroke-width="1.4"/>`;}
    s+=`<ellipse cx="${x}" cy="${y}" rx="8.5" ry="6.4" fill="currentColor" transform="rotate(-18 ${x} ${y})"/>`;
    s+=`<text x="${x}" y="${baseY+34}" text-anchor="middle" font-size="15" font-weight="700"
         fill="currentColor" font-family="Baloo 2,Inter,sans-serif">${noteDepuisPos(cle,pos)}</text>`;
  }
  return s+`</svg>`;
}
/* Encart complet « où sont les notes ? », à insérer en tête des leçons de lecture. */
function encartGamme(cle,titre){
  const lib=cle==="sol"?"clé de Sol":"clé de Fa";
  return `<div class="carte gamme-repere">
    <h3><i class="ph ph-eyes"></i> ${titre||("Où se placent les notes en "+lib+"&nbsp;?")}</h3>
    <p>Voici la <b>gamme de Do</b> écrite en ${lib}, de la plus grave à la plus aiguë. Chaque note monte d'un cran&nbsp;:
      une note sur une <b>ligne</b>, la suivante dans un <b>interligne</b>, et ainsi de suite.
      Observe bien ce repère avant de commencer&nbsp;: c'est la base de toute la lecture.</p>
    <div class="gamme-vue">${dessinerGamme(cle)}</div>
    <p class="gamme-astuce"><i class="ph ph-lightbulb"></i> Retiens surtout <b>un point de repère</b>
      (par exemple le ${cle==="sol"?"Sol de la 2ᵉ ligne, celle que la clé entoure":"Fa de la 4ᵉ ligne, celle entre les deux points de la clé"}),
      puis compte de proche en proche.</p>
  </div>`;
}

/* Tirage d'une position de note selon le niveau.
   La portée visible occupe les positions 0 (Mi grave, 1re ligne) à 8 (Fa aigu, 5e ligne).
   - 6e/5e (niv 1) : uniquement dans la portée, ambitus réduit autour du centre.
   - 4e (niv 2) : toute la portée, et de temps en temps 1 cran dehors.
   - 3e (niv 3) : toute la portée + débordements plus fréquents avec lignes supplémentaires.
   On renvoie une position, en privilégiant l'intérieur de la portée. */
function tirerPos(){
  if(difficulte===1){
    // dans la portée, ambitus resserré mais varié : positions 0 à 8 (les 5 lignes + interlignes)
    return rnd(9); // 0..8
  }
  if(difficulte===2){
    // 80% dans la portée (0..8), 20% un cran dehors (-2..-1 ou 9..10)
    if(rnd(100)<80) return rnd(9); // 0..8
    return pick([-2,-1,9,10]);
  }
  // niv 3 : 65% dans la portée, 35% dehors (jusqu'à 2 lignes supplémentaires)
  if(rnd(100)<65) return rnd(9); // 0..8
  return pick([-4,-3,-2,-1,9,10,11,12]);
}

/* =====================================================================
   GRILLE DE BLUES
   Tonalités à notes naturelles (pour que IV et V tombent juste, sans altération).
   IV = 4e degré (quarte juste au-dessus), V = 5e degré (quinte juste au-dessus).
   Grille enseignée (12 mesures, 3 lignes de 4), se terminant par V (turnaround) :
       Ligne 1 :  I  I  I  I
       Ligne 2 :  IV IV I  I
       Ligne 3 :  V  IV I  V
   ===================================================================== */
const BLUES_TONS=["Do","Ré","Mi","Sol","La"]; // toniques simples (degrés I/IV/V tous naturels)
/* index chromatique pour calculer quarte (+5 demi-tons) et quinte (+7 demi-tons) */
const CHROMA=["Do","Do♯","Ré","Ré♯","Mi","Fa","Fa♯","Sol","Sol♯","La","La♯","Si"];
function degreBlues(tonique,degre){ // degre = 1, 4 ou 5
  const demi=degre===1?0:(degre===4?5:7);
  const i=CHROMA.indexOf(tonique);
  return CHROMA[(i+demi)%12];
}
/* la grille en degrés, ligne par ligne */
const BLUES_GRILLE=[["I","I","I","I"],["IV","IV","I","I"],["V","IV","I","V"]];
function bluesAccord(tonique,degreRomain){
  return degreBlues(tonique,degreRomain==="I"?1:degreRomain==="IV"?4:5);
}
function bluesLigne(tonique,n){ // n = 1,2,3 -> tableau de 4 noms d'accords
  return BLUES_GRILLE[n-1].map(d=>bluesAccord(tonique,d));
}

