/* =====================================================================
   LEÇONS : un cours par domaine, adapté au niveau (1=6e/5e, 2=4e, 3=3e).
   Facultatives : on peut passer directement aux exercices.
   Le contenu est cumulatif : un niveau supérieur approfondit le précédent.
   ===================================================================== */
/* ---------- Leçon « Les modulations » : dessins et exemples sonores ----------
   Portée avec armure et petite mélodie, clavier de deux octaves avec touches
   marquées, et démonstrations jouées (mélodie transposée, enchaînements d'accords). */
/* notes : [{p, alt}] ; p = position sur la portée de sol (0 = 1re ligne, Mi), 1 par degré ;
   alt : "#" | "b" | "" ; armure : même format ; legende : texte sous chaque note. */
function modPorteeSVG(notes,armure,legendes){
  armure=armure||[]; legendes=legendes||[];
  const e=12, top=30, x0=6, base=top+4*e, xCle=10;
  const xArm=58, pasArm=11, xNotes=xArm+armure.length*pasArm+20, pas=30;
  const W=xNotes+notes.length*pas+8, H=legendes.length?150:128;
  const yP=p=>base-p*(e/2);
  const yLigne=n=>top+(4-n)*e;
  let s='<svg class="mod-portee" viewBox="0 0 '+W+' '+H+'" style="max-width:'+W+'px" role="img">';
  for(let i=0;i<5;i++){ const y=top+i*e; s+='<line x1="'+x0+'" y1="'+y+'" x2="'+(W-4)+'" y2="'+y+'" stroke="#1f2440" stroke-width="1.3"/>'; }
  s+=cleSVG("sol",e,yLigne).replace('x="22"','x="'+xCle+'"');
  const glyphe=function(alt,x,p,taille){ const c=alt==="#"?"♯":"♭";
    return '<text x="'+x+'" y="'+(yP(p)+(alt==="#"?6:3))+'" font-size="'+(taille||19)+'" font-family="Segoe UI Symbol,DejaVu Sans,serif" fill="#1f2440" text-anchor="middle">'+c+'</text>'; };
  armure.forEach(function(a,i){ s+=glyphe(a.alt,xArm+i*pasArm,a.p); });
  notes.forEach(function(n,i){
    const x=xNotes+i*pas, y=yP(n.p);
    if(n.p<=-2)for(let q=-2;q>=n.p;q-=2)s+='<line x1="'+(x-11)+'" y1="'+yP(q)+'" x2="'+(x+11)+'" y2="'+yP(q)+'" stroke="#1f2440" stroke-width="1.3"/>';
    if(n.p>=10)for(let q=10;q<=n.p;q+=2)s+='<line x1="'+(x-11)+'" y1="'+yP(q)+'" x2="'+(x+11)+'" y2="'+yP(q)+'" stroke="#1f2440" stroke-width="1.3"/>';
    if(n.alt)s+=glyphe(n.alt,x-15,n.p,17);
    const col=n.c||"#1f2440";
    s+='<ellipse cx="'+x+'" cy="'+y+'" rx="7" ry="5.2" fill="'+col+'" transform="rotate(-18 '+x+' '+y+')"/>';
    if(n.p<4)s+='<line x1="'+(x+6.3)+'" y1="'+y+'" x2="'+(x+6.3)+'" y2="'+(y-30)+'" stroke="'+col+'" stroke-width="1.5"/>';
    else s+='<line x1="'+(x-6.3)+'" y1="'+y+'" x2="'+(x-6.3)+'" y2="'+(y+30)+'" stroke="'+col+'" stroke-width="1.5"/>';
    if(legendes[i])s+='<text x="'+x+'" y="'+(H-8)+'" font-size="12" font-family="Inter,Arial,sans-serif" fill="#44506a" text-anchor="middle">'+legendes[i]+'</text>';
  });
  return s+'</svg>';
}
/* Clavier de deux octaves à partir de Do (midi 60). marques : {midi:{t:"texte",c:"couleur"}} */
function modClavierSVG(marques){
  marques=marques||{};
  const blanches=[0,2,4,5,7,9,11], noms=["Do","Ré","Mi","Fa","Sol","La","Si"];
  const L=26, H=104, hN=64, lN=16, n=15;
  let s='<svg class="mod-clavier" viewBox="0 0 '+(n*L+2)+' '+(H+22)+'" role="img">', noires="";
  for(let i=0;i<n;i++){
    const oct=Math.floor(i/7), m=60+12*oct+blanches[i%7], mq=marques[m];
    s+='<rect x="'+(1+i*L)+'" y="1" width="'+L+'" height="'+H+'" rx="3" fill="'+(mq?mq.c:"#fff")+'" stroke="#1f2440" stroke-width="1"/>';
    s+='<text x="'+(1+i*L+L/2)+'" y="'+(H-7)+'" font-size="9" font-family="Inter,Arial,sans-serif" fill="'+(mq?"#fff":"#8a93a6")+'" text-anchor="middle">'+noms[i%7]+'</text>';
    if(mq&&mq.t)s+='<text x="'+(1+i*L+L/2)+'" y="'+(H+16)+'" font-size="10" font-weight="700" font-family="Inter,Arial,sans-serif" fill="#1f2440" text-anchor="middle">'+mq.t+'</text>';
    if(i%7!==2&&i%7!==6&&i<n-1){
      const mn=m+1, mqn=marques[mn], x=1+(i+1)*L-lN/2;
      noires+='<rect x="'+x+'" y="1" width="'+lN+'" height="'+hN+'" rx="2" fill="'+(mqn?mqn.c:"#1f2440")+'" stroke="#1f2440" stroke-width="1"/>';
      if(mqn&&mqn.t)noires+='<text x="'+(x+lN/2)+'" y="'+(hN-6)+'" font-size="8.5" font-weight="700" font-family="Inter,Arial,sans-serif" fill="#fff" text-anchor="middle">'+mqn.t+'</text>';
    }
  }
  return s+noires+'</svg>';
}
const MOD_CLAIR=[[0,1],[0,1],[0,1],[2,1],[4,2],[2,2],[0,1],[4,1],[2,1],[2,1],[0,3]];
function jouerModul(cle){
  try{ audio().resume(); }catch(e){}
  const mel=function(dec,t0,spb){ let t=t0; MOD_CLAIR.forEach(function(n){ jouerMidi(60+dec+n[0],t,Math.min(1.1,n[1]*spb*0.92),0.24); t+=n[1]*spb; }); return t; };
  const acc=function(l,t,d){ l.forEach(function(m){ jouerMidi(m,t,d,0.13); }); };
  if(cle==="clair-do"){ mel(0,0,0.4); return; }
  if(cle==="clair-la"){ mel(9,0,0.4); return; }
  if(cle==="clair-mi"){ mel(4,0,0.4); return; }
  if(cle==="sans"){ const t=mel(0,0,0.32); mel(0,t+0.5,0.32); return; }
  if(cle==="camion"){ const t=mel(0,0,0.32); mel(1,t+0.5,0.32); return; }
  if(cle==="ton"){ const t=mel(0,0,0.32); mel(2,t+0.5,0.32); return; }
  if(cle==="vers-fa"){ acc([48,60,64,67],0,1.1); acc([48,58,64,67],1.25,1.1); acc([41,57,65,69,72],2.5,1.6); return; }
  if(cle==="vers-sol"){ acc([48,60,64,67],0,1.1); acc([50,60,66,69],1.25,1.1); acc([43,59,67,71,74],2.5,1.6); return; }
  if(cle==="reste-do"){ acc([48,60,64,67],0,1.1); acc([43,59,62,67],1.25,1.1); acc([48,60,64,67,72],2.5,1.6); return; }
  if(cle==="mineur"){ acc([48,60,64,67],0,1.2); acc([48,60,63,67],1.4,1.6); return; }
}
