function ecranCompositeurs(){
  masquerInterfaceNormale();
  categorieCourante=null;
  document.querySelectorAll(".cat-btn").forEach(b=>b.classList.toggle("actif",b.dataset.id==="_compositeurs"));
  document.getElementById("titre").innerHTML='<i class="ph ph-music-notes"></i> Compositeurs';
  document.getElementById("intro").textContent="Choisis un compositeur pour lire sa biographie, puis lance le quiz (plus de 100 questions chacun).";
  majRetour(accueil,"Accueil");
  const ordreEpoques=["Moyen Âge","Renaissance","Baroque","Classique","Classique → Romantique","Romantique","Moderne","Contemporaine"];
  const parEpoque={};
  Object.keys(QUIZ_COMPO).forEach(cid=>{const e=QUIZ_COMPO[cid].epoque;(parEpoque[e]=parEpoque[e]||[]).push(cid);});
  /* dans chaque époque, ordre chronologique de naissance (première année des dates : « v. 1300 », « né en 1982 »…) */
  const anNaiss=cid=>{const m=String(QUIZ_COMPO[cid].dates||"").match(/\d{3,4}/);return m?+m[0]:9999;};
  Object.keys(parEpoque).forEach(e=>parEpoque[e].sort((a,b)=>anNaiss(a)-anNaiss(b)));
  const epoques=[...ordreEpoques.filter(e=>parEpoque[e]),...Object.keys(parEpoque).filter(e=>!ordreEpoques.includes(e))];
  let h=`<div class="compo-accueil">`;
  epoques.forEach(ep=>{
    h+=`<section class="compo-epoque"><h2 class="compo-epoque-titre">${ep}</h2><div class="compo-grille">`;
    parEpoque[ep].forEach(cid=>{const c=QUIZ_COMPO[cid];
      h+=`<button class="compo-carte" onclick="ouvrir('compo-${cid}')">
            ${IMG_COMPO[cid]?`<img class="compo-portrait" src="${IMG_COMPO[cid]}" alt="" loading="lazy"${(typeof IMG_CREDIT!=="undefined"&&IMG_CREDIT[cid])?` title="Photo : ${IMG_CREDIT[cid].auteur} · ${IMG_CREDIT[cid].licence} (Wikimedia Commons)"`:""}>`:`<span class="compo-ic">${c.ic}</span>`}
            <span class="compo-nom">${c.nom}</span>
            <span class="compo-dates">${c.dates}</span>
            <span class="compo-pays">${c.pays}</span>
          </button>`;});
    h+=`</div></section>`;
  });
  h+=`</div>`;
  document.getElementById("zone").innerHTML=h;
  remonter();
}

/* Liste fixe des classes du collège : 6e1..6e6, 5e1.., 4e1.., 3e1..3e6.
   Évite toute faute de frappe : l'élève choisit dans un menu déroulant. */
const CLASSES_COLLEGE=(function(){const out=[];["6","5","4","3"].forEach(n=>{for(let i=1;i<=6;i++)out.push(n+"e"+i);});return out;})();
function genererEval(domId,diff,n){
  const oldDiff=difficulte,oldNb=nbQuestions;
  difficulte=diff; nbQuestions=n;
  evalRng=rngFactory(evalGraine);
  modeGraine=true;
  let exos;
  try{exos=GEN[domId]();}finally{modeGraine=false;difficulte=oldDiff;nbQuestions=oldNb;}
  return exos;
}
/* Évaluation COMPOSÉE d'un cours : on assemble des questions de la banque du cours
   ET des questions tirées au hasard dans d'autres modules (familles, images,
   compositeur…), selon le dosage choisi par le prof (parts = [{src,n}]). src peut
   être "cours" (la banque) ou n'importe quel identifiant de module GEN. */
let evalCompoActif=null;
function genererEvalCours(coursId,parts,diff){
  const def=(typeof EVALCOURS_DEF!=="undefined"&&EVALCOURS_DEF[coursId])||{}; const bank=def.bank||[];
  const out=[]; const oldD=difficulte, oldNb=nbQuestions;
  try{
    (parts||[]).forEach(function(p){
      const n=Math.max(0,parseInt(p.n,10)||0); if(!n)return;
      if(p.src==="cours"){
        if(!bank.length)return;
        const pool=shuffle(bank.slice());
        for(let k=0;k<Math.min(n,pool.length);k++)out.push(qProfEx(pool[k]));   /* jamais deux fois la même question */
      }else if(GEN[p.src]){
        difficulte=diff||2; nbQuestions=n;
        try{ const lot=GEN[p.src](); (lot||[]).slice(0,n).forEach(function(e){ out.push(e); }); }catch(e){}
      }
    });
  }finally{ difficulte=oldD; nbQuestions=oldNb; }
  return shuffle(out);
}
function evalCompoTotal(parts){ return (parts||[]).reduce(function(t,p){ return t+Math.max(0,parseInt(p.n,10)||0); },0); }

function majChrono(){const reste=Math.max(0,evalFinAt-Date.now());
  const el=document.getElementById("evChrono");
  if(el){const m=Math.floor(reste/60000),s=Math.floor((reste%60000)/1000);
    el.textContent=`${m}:${s<10?"0":""}${s}`;
    if(reste<60000)el.style.color="var(--faux)";}
  if(reste<=0)terminerEval(true);}

function afficherQuestionEval(){
  const i=evalIndex, ex=evalExos[i], total=evalExos.length;
  _evalAfficheLe=Date.now();
  try{ evalSurvQuestion(i); }catch(e){}
  let champ="";
  if(ex.studio){champ=`<div class="stu" id="stuEval"></div>`;}
  else if(ex.visuel){champ=`<div class="choix" data-vis="1">`+ex.visuel.map(o=>`<label data-val="${o.val}"><input type="radio" name="q" value="${o.val}" ${evalReponses[i]==o.val?"checked":""}>${o.html}</label>`).join("")+`</div>`;}
  else champ=`<div class="reponse-zone">${injecterValeur(ex.champ,evalReponses[i])}</div>`;
  let son=ex.sonBtn?`<div class="reponse-zone"><button class="btn-son" onclick='jouerSonEval()'>${ex.sonBtn.label}</button></div>`:"";
  document.getElementById("zone").innerHTML=`
    <div class="eval-topbar">
      <span>Question <b>${i+1}</b> / ${total}</span>
      <span class="eval-chrono"><i class="ph ph-timer"></i> <span id="evChrono">--:--</span></span>
    </div>
    <div class="eval-progress"><div style="width:${i/total*100}%"></div></div>
    <div class="ex" style="margin-top:14px">
      <div class="consigne">${ex.consigne}</div>${son}${champ}
    </div>
    <div class="eval-nav">
      ${i>0?`<button class="action btn-nouv" onclick="navEval(-1)">← Précédent</button>`:`<span></span>`}
      ${i<total-1?`<button class="action btn-corr" onclick="navEval(1)">Suivant →</button>`
                 :`<button class="action btn-corr" onclick="terminerEval(false)"><i class="ph ph-check"></i> Terminer</button>`}
    </div>
    <p class="eval-warn">${evalBoss?"Concentre-toi : "+BOSS_SEUIL+"/20 pour vaincre le boss.":"Ne quitte pas le plein écran : chaque sortie est enregistrée pour ton professeur."}</p>`;
  majChrono();
  if(ex.studio)stuDemarrer(document.getElementById("stuEval"),ex.studio,{mode:"eval"});
  if(document.querySelector("#zone .ce-yt")&&typeof ceMonterYT==="function")ceMonterYT();
  document.getElementById("zone").querySelectorAll('.choix[data-vis] label').forEach(l=>l.addEventListener("click",()=>{
    l.parentElement.querySelectorAll("label").forEach(x=>x.classList.remove("sel"));l.classList.add("sel");}));
}
function injecterValeur(champHtml,val){
  if(!val)return champHtml;
  if(champHtml.includes("choix-btns")){
    const v=escAttr(val);
    let h=champHtml.replace('data-value=""','data-value="'+v+'"');
    // ajoute la classe "sel" au bouton dont data-val correspond
    h=h.replace('class="opt" data-val="'+v+'"','class="opt sel" data-val="'+v+'"');
    return h;
  }
  if(champHtml.includes("<select"))return champHtml.replace(`<option>${val}</option>`,`<option selected>${val}</option>`).replace(`<option value="${val}">`,`<option value="${val}" selected>`);
  return champHtml.replace("<input","<input value=\""+(""+val).replace(/"/g,"&quot;")+"\"");
}
function lireValeurEval(){const card=document.getElementById("zone");const ex=evalExos[evalIndex];
  if(ex.studio)return "studio";
  if(ex.visuel){const c=card.querySelector('input[name="q"]:checked');return c?c.value:"";}
  const ch=card.querySelector(".rep");return valRep(ch);}
function jouerSonEval(){const s=evalExos[evalIndex].sonBtn;try{audio().resume();}catch(e){}
  jouerSonBtn(s);}
function navEval(d){
  /* un clic sur « Suivant »/« Précédent » annule le passage automatique en attente :
     sinon il s'ajoutait au clic et sautait la question suivante (vide, comptée fausse) */
  if(_evalAuto){ clearTimeout(_evalAuto); _evalAuto=null; }
  evalReponses[evalIndex]=lireValeurEval();evalIndex+=d;
  if(evalIndex<0)evalIndex=0;if(evalIndex>=evalExos.length)evalIndex=evalExos.length-1;afficherQuestionEval();}
/* Un clic sur une option enchaîne sur la question suivante : le bouton
   « Suivant » restait à cliquer alors que la réponse était déjà donnée.
   On laisse un court délai pour que l'élève VOIE son choix sélectionné, et on
   n'avance jamais depuis la dernière question (il doit terminer lui-même). */
let _evalAuto=null, _evalAfficheLe=0;
function evalAvanceAuto(){
  if(!evalActif)return;
  if(evalIndex>=evalExos.length-1)return;      /* dernière question : on reste */
  if(_evalAuto)clearTimeout(_evalAuto);
  const q=evalIndex;                           /* on n'avance QUE depuis la question où l'on a répondu */
  _evalAuto=setTimeout(function(){ _evalAuto=null; if(evalActif&&evalIndex===q)navEval(1); },320);
}

/* ---- Surveillance anti-triche ---- */
function demanderPleinEcran(){const el=document.documentElement;
  try{const p=(el.requestFullscreen||el.webkitRequestFullscreen||(()=>{})).call(el);   /* promesse : un refus (tablette, réglage) ne doit pas remonter en erreur */
    if(p&&typeof p.catch==="function")p.catch(function(){});}catch(e){}}
function sortiePleinEcran(){return !(document.fullscreenElement||document.webkitFullscreenElement);}
let survInstallee=false;
/* Journal de passation (v2). Un simple compteur ne distinguait pas un coup d'œil
   d'une absence de trois minutes, ni un changement d'onglet d'une capture d'écran.
   On relève désormais, pendant l'évaluation seulement :
   - chaque absence (onglet quitté ou fenêtre ayant perdu le focus) avec sa durée et
     la question en cours, et les réponses corrigées juste après un retour ;
   - copier (énoncé recopié), coller (réponse collée), clic droit (« Rechercher avec… ») ;
   - captures d'écran repérables : touche Impr. écran, raccourcis Mac, outil Capture
     de Windows (focus perdu une fraction de seconde après la touche Windows) ;
   - redimensionnement de la fenêtre (écran partagé, panneau latéral d'assistant IA) ;
   - réponses insérées d'un bloc (dictée, remplissage automatique, extension) ;
   - le temps passé sur chaque question.
   Limite honnête : sur téléphone, une capture d'écran ou une IA sur un AUTRE appareil
   ne laissent aucune trace dans la page ; seuls les indices indirects (temps, écarts
   de résultats) peuvent les trahir, côté professeur. */
let evalSurv=null;
function evalSurvNouveau(){
  evalSurv={t0:Date.now(),abs:[],enCours:null,fsT:[],copies:0,collages:0,captures:0,clicDroit:0,redim:0,saisies:0,
    tq:[],qCour:-1,qT0:0,qAbs:{},snap:null,modifJuste:0,derMeta:0,derCapture:0,derFs:0,largeur:window.innerWidth};
}
function evalSurvDebutAbs(type){
  const S=evalSurv; if(!evalActif||!S)return;
  if(S.enCours){ if(type==="onglet")S.enCours.type="onglet"; return; }
  const now=Date.now();
  /* focus perdu juste après la touche Windows / Cmd : outil de capture d'écran */
  const capture=type==="focus"&&(now-S.derMeta)<1500;
  if(capture&&(now-S.derCapture)>1500){ S.captures++; S.derCapture=now; }
  S.enCours={type:type,t0:now,q:evalIndex,capture:capture};
  let rep=""; try{ rep=lireValeurEval(); }catch(e){}
  S.snap={q:evalIndex,rep:String(rep==null?"":rep)};
}
function evalSurvFinAbs(){
  const S=evalSurv; if(!S||!S.enCours)return;
  const a=S.enCours; S.enCours=null;
  const dur=Date.now()-a.t0;
  /* une perte de focus de moins de 2 s sans changer d'onglet : notification, capture… */
  const micro=a.capture||(a.type==="focus"&&dur<2000);
  if(!micro)S.qAbs[a.q]=1;
  S.abs.push({type:a.type,q:a.q,t0:a.t0,d:Math.round(dur/100)/10,micro:micro});
}
/* Temps passé par question + réponse devenue juste après un retour sur la page. */
function evalSurvQuestion(i){
  const S=evalSurv; if(!S)return;
  const now=Date.now();
  if(S.qCour>=0){
    S.tq[S.qCour]=(S.tq[S.qCour]||0)+(now-S.qT0);
    if(S.snap&&S.snap.q===S.qCour&&!S.enCours){
      const nv=String(evalReponses[S.qCour]==null?"":evalReponses[S.qCour]);
      let ok=false; try{ ok=!!evalExos[S.qCour].verif(evalReponses[S.qCour]); }catch(e){}
      if(nv!==S.snap.rep&&ok)S.modifJuste++;
      S.snap=null;
    }
  }
  S.qCour=i; S.qT0=now;
}
function evalSurvResume(detail){
  const S=evalSurv||{abs:[],tq:[],qAbs:{},fsT:[]};
  if(S.enCours)evalSurvFinAbs();
  const vraies=S.abs.filter(function(a){return !a.micro;});
  /* une sortie du plein écran qui accompagne une absence n'est pas comptée deux fois */
  const fsSeules=(S.fsT||[]).filter(function(ft){ return !S.abs.some(function(a){ return Math.abs(a.t0-ft)<2500; }); }).length;
  const tq=detail.map(function(d,i){ return Math.round((S.tq[i]||0)/1000); });
  const qAbs=Object.keys(S.qAbs||{}).map(Number);
  const tri=tq.filter(function(x){return x>0;}).sort(function(a,b){return a-b;});
  const now=new Date();
  return { v:2,
    sorties:vraies.length, onglet:vraies.filter(function(a){return a.type==="onglet";}).length,
    micro:S.abs.length-vraies.length,
    absDur:Math.round(vraies.reduce(function(n,a){return n+a.d;},0)),
    absMax:Math.round(vraies.reduce(function(m,a){return Math.max(m,a.d);},0)),
    absLongues:vraies.filter(function(a){return a.d>=15;}).length,
    fs:fsSeules, copies:S.copies||0, collages:S.collages||0, captures:S.captures||0,
    clicDroit:S.clicDroit||0, redim:S.redim||0, saisies:S.saisies||0,
    qAbs:qAbs.length, qAbsJuste:qAbs.filter(function(i){return detail[i]&&detail[i].ok;}).length,
    modifJuste:S.modifJuste||0,
    tqMed:tri.length?tri[Math.floor(tri.length/2)]:0,
    rapidesJustes:detail.filter(function(d,i){return d.ok&&tq[i]>0&&tq[i]<=3;}).length,
    tactile:(typeof ecranTactile==="function")?ecranTactile():false,
    h:now.getHours(), j:now.getDay(), tq:tq,
    qA:qAbs };
}
function installerSurveillance(){if(survInstallee)return;survInstallee=true;
  document.addEventListener("visibilitychange",function(){ if(!evalActif)return; if(document.hidden)evalSurvDebutAbs("onglet"); else evalSurvFinAbs(); });
  window.addEventListener("blur",function(){ if(!evalActif)return;
    /* le focus part dans le lecteur YouTube d'une question d'écoute : l'élève est toujours sur la page */
    setTimeout(function(){ const a=document.activeElement;
      if(a&&a.tagName==="IFRAME"&&a.closest&&a.closest(".ce-yt")&&!document.hidden)return;
      evalSurvDebutAbs("focus"); },0); });
  window.addEventListener("focus",function(){ if(evalActif&&!document.hidden)evalSurvFinAbs(); });
  document.addEventListener("fullscreenchange",function(){ if(evalActif&&evalSurv){ evalSurv.derFs=Date.now(); if(sortiePleinEcran())evalSurv.fsT.push(Date.now()); } });
  document.addEventListener("copy",function(){ if(evalActif&&evalSurv)evalSurv.copies++; },true);
  document.addEventListener("cut",function(){ if(evalActif&&evalSurv)evalSurv.copies++; },true);
  document.addEventListener("paste",function(){ if(evalActif&&evalSurv)evalSurv.collages++; },true);
  document.addEventListener("contextmenu",function(){ if(evalActif&&evalSurv)evalSurv.clicDroit++; },true);
  document.addEventListener("keydown",function(e){
    if(!evalActif||!evalSurv)return; const S=evalSurv, k=String(e.key||""), now=Date.now();
    if(k==="Meta"||k==="OS"){ S.derMeta=now; return; }
    const capture=k==="PrintScreen"
      ||((e.metaKey||e.ctrlKey)&&e.shiftKey&&/^[345sS]$/.test(k))
      ||((e.metaKey||e.ctrlKey)&&/^[pP]$/.test(k));
    if(capture&&(now-S.derCapture)>1500){ S.captures++; S.derCapture=now; }
  },true);
  /* Impr. écran ne produit souvent qu'un keyup sous Windows */
  document.addEventListener("keyup",function(e){
    if(!evalActif||!evalSurv)return; const S=evalSurv, now=Date.now();
    if(String(e.key||"")==="PrintScreen"&&(now-S.derCapture)>1500){ S.captures++; S.derCapture=now; }
  },true);
  document.addEventListener("input",function(e){
    if(!evalActif||!evalSurv)return;
    const it=e.inputType||"";
    if(it==="insertText"&&e.data&&String(e.data).length>=6)evalSurv.saisies++;
  },true);
  /* redimensionnement en LARGEUR seulement : le clavier virtuel ne change que la hauteur,
     et on ignore les secondes qui suivent l'entrée ou la sortie du plein écran */
  window.addEventListener("resize",function(){
    if(!evalActif||!evalSurv)return; const S=evalSurv, w=window.innerWidth;
    if(Date.now()-S.derFs<1500||Date.now()-S.t0<2500){ S.largeur=w; return; }
    if(Math.abs(w-S.largeur)>80){ S.redim++; S.largeur=w; }
  });
  window.addEventListener("orientationchange",function(){ if(evalSurv){ evalSurv.derFs=Date.now(); } });
}


/* =====================================================================
   CLASSEMENT EN DIRECT : écran élève/prof
   ===================================================================== */
let classementTimer=null, classementFiltre="";

/* =====================================================================
   MODE CLASSE EN DIRECT (multi-appareils, façon quiz télévisé)
   - Le prof (hôte) crée une partie -> PIN. Les élèves rejoignent avec le PIN.
   - Tout passe par le Google Sheet (mêmes réglages que le classement).
   - L'hôte est AUTORITAIRE : il génère les questions, collecte les réponses
     (boîte de réception), calcule les scores et publie l'état ; les élèves
     ne font que lire l'état et envoyer leur réponse.
   ===================================================================== */
const JEU_CATS=[
  {id:"reperes-compo",nom:"Compositeurs : époques & repères"},
  {id:"histoire-notation",nom:"Histoire de l'écriture musicale"},
  {id:"histoire-son",nom:"Histoire de l'enregistrement"},
  {id:"blues-histoire",nom:"Le blues : histoire et origines"},
];
const JEU_DUREE=20000;               // ms accordés par question
const JEU_LEAD=3500;                 // délai entre l'envoi et l'affichage synchronisé (masque la latence réseau)
const JEU_PART=50;                   // points pour toute réponse tentée (motive ceux qui essaient)
const JEU_BASE=500;                  // points de base d'une bonne réponse
const JEU_VITESSE=400;               // bonus de rapidité maximal
const JEU_SERIE=100;                 // bonus par cran de série (bonnes réponses d'affilée), capé à 5
const JEU_COUL=["#e74c3c","#2f6db0","#E9BE3C","#2a9d5c","#8e44ad","#16a085"];
const JEU_FORME=["▲","◆","●","■","★","✚"];
const JEU_AVATARS=["🦊","🐼","🦁","🐯","🐨","🐵","🐸","🦉","🐰","🐙","🦄","🐝","🐬","🦖","🐧","🐷","🦋","🐢","🐳","🦩"];
/* L'avatar arrive du joueur (base temps réel ou relais) : c'est une donnée
   extérieure, affichée ensuite en HTML sur l'écran du PROFESSEUR connecté. On
   n'accepte donc que les avatars de la liste ; tout le reste (y compris un
   script glissé à la place d'un animal) devient l'icône par défaut. */
const AVATAR_DEFAUT="<i class='ph ph-headphones'></i>";
function avatarSur(a){ return (typeof a==="string"&&JEU_AVATARS.indexOf(a)>=0)?a:AVATAR_DEFAUT; }
function avatarDe(uid){const p=hostGame&&hostGame.players[uid];return (p&&p.avatar)||AVATAR_DEFAUT;}

/* ============ TEMPS RÉEL (Firebase) : colle ici la config de TON projet ============
   Console Firebase → Paramètres du projet <i class='ph ph-gear'></i> → « Tes applications » → Config SDK.
   Le plus important est databaseURL (l'adresse de la Realtime Database).
   Si ces champs restent vides, le mode classe retombe automatiquement sur le Google
   Sheet (avec latence). Rempli, il devient quasi instantané. */
