function ephJour(){
  if(!Array.isArray(EPHEMERIDES)||!EPHEMERIDES.length)return null;
  const now=new Date();
  const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
  function df(m,d){
    const t=new Date(now.getFullYear(),m-1,d);
    let diff=Math.round((t-today)/86400000);
    if(diff>182)diff-=365; else if(diff<-182)diff+=365;
    return diff;
  }
  const cand=EPHEMERIDES.map(function(e){ return {e:e,df:df(e.m,e.d)}; });
  cand.sort(function(x,y){
    const ax=Math.abs(x.df), ay=Math.abs(y.df);
    if(ax!==ay)return ax-ay;
    if((x.df<0)!==(y.df<0))return x.df<0?1:-1;   /* aujourd'hui/futur avant le passé */
    return (x.e.an||0)-(y.e.an||0);
  });
  const b=cand[0];
  const top=cand.filter(function(c){ return Math.abs(c.df)===Math.abs(b.df) && (c.df<0)===(b.df<0); });
  return top[now.getFullYear()%top.length];   /* variété d'une année sur l'autre si égalité */
}
/* Éphéméride : une pastille discrète dans le bandeau de la carte d'accueil
   (élève et enseignant), au lieu d'une barre pleine largeur. Le clic ouvre la fiche. */
function ephPastilleHTML(){
  const p=(typeof ephJour==="function")?ephJour():null; if(!p)return "";
  const e=p.e, dff=p.df, a=Math.abs(dff); const idx=EPHEMERIDES.indexOf(e);
  const MOISC=["janv.","févr.","mars","avr.","mai","juin","juil.","août","sept.","oct.","nov.","déc."];
  let quand;
  if(dff===0)quand="Aujourd'hui";
  else if(dff===1)quand="Demain";
  else if(dff===-1)quand="Hier";
  else if(dff>0&&a<=7)quand="Dans "+dff+" jours";
  else if(dff<0&&a<=7)quand="Il y a "+a+" jours";
  else quand="Le "+e.d+" "+MOISC[e.m-1];
  const ic=(e.t==="n")?"ph-cake":(e.t==="m")?"ph-flower-lotus":(e.t==="o")?"ph-vinyl-record":"ph-confetti";
  const quoi=(e.t==="n")?"naissance de ":(e.t==="m")?"disparition de ":(e.t==="o")?"sortie de ":"";
  const titre=quand+" : "+quoi+e.nom+(e.an?" ("+e.an+")":"")+". Cliquer pour en savoir plus.";
  return '<button type="button" class="ac-pastille eph-pastille" title="'+escapeHtml(titre)+'" aria-label="'+escapeHtml("Éphéméride musicale. "+titre)+'" onclick="ephOuvrir('+idx+')">'
    +'<i class="ph-fill '+ic+'"></i><span class="eph-p-quand">'+escapeHtml(quand)+' ·</span><b>'+echapH(e.nom)+'</b></button>';
}

/* Pop-up détaillé d'un événement : croix, clic sur le fond ou Échap pour fermer. */
function ephOuvrir(i){
  const e=EPHEMERIDES[i]; if(!e)return;
  ephFermer();
  const MOIS=["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
  const dateTxt=e.d+" "+MOIS[e.m-1]+(e.an?" "+e.an:"");
  let sur;
  if(e.t==="n")sur="Naissance · "+dateTxt;
  else if(e.t==="m")sur="Disparition · "+dateTxt;
  else if(e.t==="o")sur="Sortie · "+dateTxt;
  else sur=dateTxt;
  const ic=(e.t==="n")?"ph-cake":(e.t==="m")?"ph-flower-lotus":(e.t==="o")?"ph-vinyl-record":"ph-confetti";
  const oeuvres=(Array.isArray(e.oeuvres)&&e.oeuvres.length)
    ? '<div class="eph-oeuvres"><div class="eph-oeuvres-t">À connaître</div><div class="eph-chips">'
      + e.oeuvres.map(function(o){ return '<span class="eph-chip">'+echapH(o)+'</span>'; }).join("")
      + '</div></div>'
    : '';
  const b=document.createElement("div");
  b.id="ephPop"; b.className="voc-pop-fond";
  b.onclick=function(ev){ if(ev.target===b)ephFermer(); };
  b.innerHTML='<div class="voc-pop" style="max-width:470px;position:relative" role="dialog" aria-modal="true">'
    +'<button class="ch-croix" onclick="ephFermer()" title="Fermer" aria-label="Fermer"><i class="ph ph-x"></i></button>'
    +'<div class="eph-modal-tete"><span class="eph-modal-ic"><i class="ph-fill '+ic+'"></i></span>'
    +'<div style="min-width:0"><div class="eph-modal-nom">'+echapH(e.nom)+'</div>'
    +'<div class="eph-modal-sous">'+echapH(e.sous||sur)+'</div></div></div>'
    +'<div class="eph-modal-corps"><p>'+echapH(e.txt)+'</p>'
    +(e.plus?'<p>'+echapH(e.plus)+'</p>':'')
    + oeuvres
    +'<div class="eph-modal-date"><i class="ph ph-calendar-blank"></i> '+echapH(sur)+'</div>'
    +'</div></div>';
  document.body.appendChild(b);
  document.addEventListener("keydown",ephEsc);
}
function ephEsc(ev){ if(ev.key==="Escape")ephFermer(); }
function ephFermer(){
  const b=document.getElementById("ephPop"); if(b)b.remove();
  document.removeEventListener("keydown",ephEsc);
}


