  if(nivPresents.length){
    h+='<div style="margin-bottom:10px"><div style="font-size:.84rem;color:var(--encre-doux);margin-bottom:5px">Niveaux entiers</div>'
      +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
      +nivPresents.map(function(n){
        return '<label class="ch-coche"><input type="checkbox" class="chNiv" value="'+n+'"'
          +(selN.indexOf(n)>=0?' checked':'')+' onchange="chCiblesMaj()"> Tous les '+CH_NIVEAUX_LIB[n]+'</label>';
      }).join("")+'</div></div>';
  }
  h+='<div><div style="font-size:.84rem;color:var(--encre-doux);margin-bottom:5px">Classes précises</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +cls.map(function(k){
      return '<label class="ch-coche"><input type="checkbox" class="chCls" value="'+k.id+'"'
        +(selC.indexOf(k.id)>=0?' checked':'')+' onchange="chCiblesMaj()"> '+echapH(k.nom||"Classe")+'</label>';
    }).join("")+'</div></div>'
    +'<div id="chCiblesAff" style="margin-top:12px;font-size:.9rem"></div></div>';
  /* ---- Comment ils rendent ---- */
  const grp=!!(c&&c.groupe), gmax=(c&&c.groupeMax)||3, motOk=!(c&&c.motAutorise===false);
  h+='<div class="ex" style="margin-top:14px"><h3 style="margin-top:0"><i class="ph ph-users-three"></i> Comment ils rendent</h3>'
    +'<label class="ch-coche" style="margin-bottom:8px"><input type="checkbox" id="chGroupe"'+(grp?' checked':'')+' onchange="chEditGroupe()"> Autoriser le rendu à plusieurs</label>'
    +'<div id="chGroupeMaxL" style="display:'+(grp?'block':'none')+';margin-top:6px">'
    +'<span style="font-size:.85rem;color:var(--encre-doux)">Jusqu\'à </span>'
    +'<select id="chGroupeMax" style="padding:6px 10px;border:1px solid var(--ligne);border-radius:8px;font-family:inherit;background:var(--surface);color:var(--encre)">'
    +[2,3,4,5].map(function(k){return '<option value="'+k+'"'+(k===gmax?' selected':'')+'>'+k+'</option>';}).join("")
    +'</select><span style="font-size:.85rem;color:var(--encre-doux)"> élèves par enregistrement.</span>'
    +'<p style="font-size:.82rem;color:var(--encre-doux);margin:8px 0 0"><i class="ph ph-info"></i> '
    +'Les noms de vos élèves ne quittent pas cet appareil : c\'est <b>vous</b> qui rattachez un enregistrement à un groupe au moment de la notation. Mieux : avant d\'envoyer, chaque élève peut déjà <b>marquer le code de ses camarades</b>, et la note, comme les points, comptent alors pour chacun d\'eux</p></div></div>';
  /* ---- Laisser un mot ---- */
  h+='<div class="ex" style="margin-top:14px"><h3 style="margin-top:0"><i class="ph ph-chat-teardrop-text"></i> Laisser un mot</h3>'
