          +'<button class="btn-son mini" title="Supprimer cette bande" onclick="chSupprimerPiste(\''+c.id+'\',\''+k+'\')">'
          +'<i class="ph ph-trash" style="color:var(--faux)"></i></button></div>'
          +'<div id="chp2-'+k+'" style="margin-top:6px">'
          +'<button class="action btn-nouv" style="padding:6px 12px;font-size:.85rem" onclick="chLecteurIci(\'chp2-'+k+'\',\''+chCleBande(c,k)+'\',1,\''+echapH(c.titre+"-"+k+"."+(p.ext||"mp3"))+'\')">'
          +'<i class="ph-fill ph-play"></i> Écouter</button></div>';
