async function appChangerTon(t){
  if(Object.keys(_appEdits).length&&!await dlgConfirmer("Changer de ton réécrit les appréciations que vous avez modifiées à la main.\n\nContinuer ?"))return;
  _appTon=t; _appEdits={}; if(typeof evalsRendre==="function"&&_evVue==="bilan"){evalsRendre();}else{appRendre();}
}
function appEditer(code,v){
  _appEdits[code]=v;
  const c=document.getElementById("cpt-"+code);
  if(c)c.textContent=v.length+" caractères";
}
function appTexteDe(e){ return (_appEdits[e.code]!=null)?_appEdits[e.code]:appTexte(e.nom,e.faits,_appTon,e.code); }
function appCopier(code,btn){
  const t=document.getElementById("app-"+code); if(!t)return;
  appPresse(t.value);
  if(btn){ const av=btn.innerHTML; btn.innerHTML='<i class="ph-fill ph-check-circle" style="color:var(--juste)"></i>';
    setTimeout(function(){btn.innerHTML=av;},1200); }
}
function appCopierTout(){
  if(!_appDonnees)return;
  const l=_appDonnees.map(function(e){ return (e.nom||e.code)+"\\t"+appTexteDe(e); }).join("\\n");
  appPresse(l);
  toast("Toutes les appréciations sont copiées.");
}
/* Le presse-papier moderne exige un contexte sécurisé : en file:// il faut le
   vieux document.execCommand, sinon rien ne se copie. */
/* CSV pour Pronote : encodage Windows-1252 (ANSI). Pronote lit l'ANSI sans
   problème mais pas toujours l'UTF-8 (accents cassés, import refusé). Les
   caractères absents de la table sont remplacés par leur équivalent sans
   accent, jamais par un caractère illisible. */
const CSV_1252={"€":128,"‚":130,"ƒ":131,"„":132,"…":133,"†":134,"‡":135,"ˆ":136,"‰":137,
  "Š":138,"‹":139,"Œ":140,"Ž":142,"‘":145,"’":146,"“":147,"”":148,"•":149,"–":150,"\u2014":151,
  "˜":152,"™":153,"š":154,"›":155,"œ":156,"ž":158,"Ÿ":159};
function csvOctets(txt){
  const t=String(txt||"");
  const out=[];
  for(let i=0;i<t.length;i++){
    const c=t[i], code=t.charCodeAt(i);
    if(code<256){ out.push(code); continue; }
    if(CSV_1252[c]!=null){ out.push(CSV_1252[c]); continue; }
    /* dernier recours : on retire les accents, sinon un point d'interrogation */
    const plat=c.normalize("NFD").replace(/[\u0300-\u036f]/g,"");
    for(let k=0;k<plat.length;k++){ const p=plat.charCodeAt(k); out.push(p<256?p:63); }
  }
  return new Uint8Array(out);
}
/* Fichier CSV téléchargé, en ANSI, sans marque d'octets (Pronote et Excel FR). */
function csvTelecharger(nom,csv){
  const blob=new Blob([csvOctets(csv)],{type:"text/csv;charset=windows-1252"});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a"); a.href=url; a.download=nom;
  document.body.appendChild(a); a.click();
  setTimeout(function(){ try{URL.revokeObjectURL(url);}catch(e){} a.remove(); },1500);
}
function appPresse(txt){
  try{
    if(navigator.clipboard&&window.isSecureContext){ navigator.clipboard.writeText(txt); return; }
  }catch(e){}
  const t=document.createElement("textarea");
  t.value=txt; t.style.position="fixed"; t.style.opacity="0";
  document.body.appendChild(t); t.select();
  try{ document.execCommand("copy"); }catch(e){}
  t.remove();
}
function appExporter(){
  if(!_appDonnees)return;
  const lignes=[["Nom","Code","Appréciation"]].concat(_appDonnees.map(function(e){
    return [e.nom||"", e.code, appTexteDe(e)]; }));
  const csv="\\ufeff"+lignes.map(function(l){
    return l.map(function(x){ return '"'+String(x).replace(/"/g,'""')+'"'; }).join(";"); }).join("\\r\\n");
  const blob=new Blob([csv],{type:"text/csv;charset=utf-8"});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url; a.download="museduc_appreciations.csv"; a.click();
  setTimeout(function(){URL.revokeObjectURL(url);},2000);
  toast("Appréciations enregistrées.");
}

/* ---------- Prof : les travaux RENDUS ----------
   Séparé de « Travail à donner » : une fois le devoir rendu, ce n'est plus une
   consigne à écrire mais un résultat à consulter. On y accède donc depuis la
   classe, à côté des évaluations. */
function dvDuree(s){
  s=Math.round(s||0);
  if(!s)return "-";
  if(s<60)return s+" s";
  const m=Math.floor(s/60);
  if(m<60)return m+" min";
  return Math.floor(m/60)+" h "+("0"+(m%60)).slice(-2);
}
function dvDateHeure(ts){
  if(!ts)return "-";
  try{ const d=new Date(ts);
    return d.toLocaleDateString("fr-FR",{day:"2-digit",month:"2-digit"})+" à "+
           d.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"});
  }catch(e){ return "-"; }
}
/* Agrège les mesures des volets d'un devoir pour un élève. */
function dvBilan(e,nbVolets){
  const r={faits:0,temps:0,essais:0,sorties:0,fini:e&&e.fini||0,pcts:[],notes:[]};
  const v=(e&&e.v)||{};
  for(let i=0;i<nbVolets;i++){
    const c=v[String(i)]; if(!c)continue;
    if(c.fait)r.faits++;
    r.temps+=(c.tempsS||0); r.essais+=(c.essais||0); r.sorties+=(c.sorties||0);
    if(c.pct!=null)r.pcts.push(c.pct);
    if(c.note!=null)r.notes.push(c.note+"/"+(c.sur||20));
  }
  return r;
}
function ecranRendus(classId){
  if(classId)_classeProfSel=classId;   /* la classe suit d'une page à l'autre */
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  titreProf('<i class="ph ph-check-square-offset"></i> Travaux rendus',
            "Ce que vos élèves ont réellement fait, et dans quelles conditions.");
  const z=document.getElementById("zone");
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u){ z.innerHTML=svcIndispo(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  Promise.all([ s.collection("classes").doc(classId).collection("devoirs").get(),
                s.collection("eleveCodes").where("ownerUid","==",u.uid).get(),
                s.collection("classes").doc(classId).collection("eleves").get() ])
  .then(function(r){
    const devs=[]; r[0].forEach(function(d){ const o=Object.assign({id:d.id},d.data()||{});
      if(!Array.isArray(o.volets))o.volets=[]; devs.push(o); });
    devs.sort(function(x,y){ return (y.echeance||0)-(x.echeance||0); });
    const codes=[]; r[1].forEach(function(d){ if((d.data()||{}).classId===classId)codes.push(d.id); });
    /* élèves invités (chorale) : ils reçoivent aussi le travail de cette classe */
    const _cl=((_profClasses||[]).filter(function(x){return x.id===classId;})[0]||{});
    (Array.isArray(_cl.membres)?_cl.membres:[]).forEach(function(c){ if(codes.indexOf(c)<0)codes.push(c); });
    const prog={}; r[2].forEach(function(d){ prog[d.id]=d.data()||{}; });
    if(!devs.length){
      z.innerHTML='<div class="accueil" style="max-width:900px">'+selClasseHTML("ecranRendus",classId)
        +'<p class="badge-vide">Aucun travail donné à cette classe pour l’instant.</p></div>';
      return;
    }
    let h='<div class="accueil" style="max-width:900px">'+selClasseHTML("ecranRendus",classId)
      +'<p class="rd-lien"><i class="ph ph-shield-warning"></i> Les conditions de passation des évaluations (absences, copier-coller, captures) sont analysées dans '
      +'<a href="#" onclick="_evVue=\'vigil\';ouvrirProf(\'evalsClasse\',\''+classId+'\');return false">Notes &amp; bulletins → Vigilance</a>.</p>';
    devs.forEach(function(d){
      const vises=Array.isArray(d.eleves)&&d.eleves.length
        ? codes.filter(function(c){return d.eleves.indexOf(c)>=0;}) : codes;
      const rendus=vises.filter(function(c){ const e=((prog[c]||{}).devoirs||{})[d.id]; return e&&e.fini; });
      const pct=vises.length?Math.round(100*rendus.length/vises.length):0;
      h+='<button class="ex" style="width:100%;text-align:left;display:flex;gap:14px;align-items:center;'
        +'margin-bottom:10px;cursor:pointer" onclick="detailDevoir(\''+classId+'\',\''+d.id+'\')">'
        +'<div style="flex:1;min-width:0"><b>'+echapH(d.titre||"Travail")+'</b><br>'
        +'<span style="font-size:.84rem;color:var(--encre-doux)"><i class="ph ph-calendar-dots"></i> '
        +devoirDateTxt(d.echeance)+(Array.isArray(d.eleves)&&d.eleves.length?' · '+d.eleves.length+' élève'+(d.eleves.length>1?'s':''):'')+'</span></div>'
        +'<div style="text-align:center;min-width:88px">'
        +'<div style="font-family:var(--police-titre);font-weight:800;font-size:1.3rem;color:'
        +(pct>=80?"var(--juste)":(pct>=40?"var(--or)":"var(--faux)"))+'">'+rendus.length+'/'+vises.length+'</div>'
        +'<div style="font-size:.76rem;color:var(--encre-doux)">rendus</div></div>'
        +'<i class="ph ph-arrow-right" style="color:var(--laiton)"></i></button>';
    });
    z.innerHTML=h+'</div>';
  }).catch(function(e){
    const c=String((e&&e.code)||(e&&e.message)||"");
    if(c.indexOf("permission-denied")>=0){
      z.innerHTML='<div class="ex" style="max-width:640px;margin:0 auto">'
        +'<h3 style="margin-top:0"><i class="ph ph-warning" style="color:var(--faux)"></i> Règles Firestore à publier</h3>'
        +'<p>Le serveur refuse l’accès aux devoirs : publiez les règles à jour depuis la console Firebase.</p></div>';
    }else z.innerHTML=svcIndispo("Impossible de charger les travaux.");
  });
}
function detailDevoir(classId,devoirId){
  masquerInterfaceNormale(); majRetour(function(){ecranRendus(classId);},"Travaux rendus");
  titreProf('<i class="ph ph-eye"></i> Qui a fait ce travail');
  const z=document.getElementById("zone");
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser; if(!s||!u)return;
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  Promise.all([ s.collection("classes").doc(classId).collection("devoirs").doc(devoirId).get(),
                s.collection("eleveCodes").where("ownerUid","==",u.uid).get(),
                s.collection("classes").doc(classId).collection("eleves").get() ])
  .then(function(r){
    const d=r[0].exists?Object.assign({id:devoirId},r[0].data()):{volets:[]};
    if(!Array.isArray(d.volets))d.volets=[];
    let codes=[]; r[1].forEach(function(x){ if((x.data()||{}).classId===classId)codes.push(x.id); });
    if(Array.isArray(d.eleves)&&d.eleves.length)codes=codes.filter(function(c){return d.eleves.indexOf(c)>=0;});
    const prog={}; r[2].forEach(function(x){ prog[x.id]=x.data()||{}; });
    codes.sort(function(x,y){ return (labelDe(classId,x)||"￿").localeCompare(labelDe(classId,y)||"￿","fr"); });
    let h='<div class="accueil" style="max-width:1000px">'
      +'<div class="ex" style="margin-bottom:16px;text-align:center"><b>'+echapH(d.titre||"")+'</b><br>'
      +'<span style="font-size:.84rem;color:var(--encre-doux)"><i class="ph ph-calendar-dots"></i> '
      +devoirDateTxt(d.echeance)+'</span></div>'
      +'<div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr>'
      +'<th>Nom (privé)</th><th>Code</th>'
      +d.volets.map(function(v){return "<th>"+echapH(devoirVoletNom(v))+"</th>";}).join("")
      +'<th title="Date et heure de validation">Validé le</th>'
      +'<th title="Temps réellement passé sur ce travail">Temps</th>'
      +'<th title="Nombre de séries d’entraînement tentées">Essais</th>'
      +'<th title="Changements d’onglet pendant le travail">Sorties</th>'
      +'</tr></thead><tbody>';
    codes.forEach(function(c){
      const e=((prog[c]||{}).devoirs||{})[devoirId]||{v:{}};
      const b=dvBilan(e,d.volets.length);
      const lab=labelDe(classId,c);
      h+='<tr><td><b>'+(lab?echapH(lab):'<span style="color:var(--encre-doux)">(sans nom)</span>')+'</b></td>'
        +'<td><b style="letter-spacing:1px;color:var(--laiton)">'+c+'</b></td>';
      d.volets.forEach(function(v,i){
        const st=(e.v||{})[String(i)]||{};
        let txt='<i class="ph ph-circle" style="color:var(--encre-doux)"></i>';
        if(st.fait){
          txt='<i class="ph-fill ph-check-circle" style="color:var(--juste)"></i>';
          if(st.note!=null)txt+=" <b>"+st.note+"/"+(st.sur||20)+"</b>";
          else if(st.pct!=null)txt+=" "+st.pct+"%";
        }else if(st.pct!=null){ txt='<span style="color:var(--faux)">'+st.pct+"%</span>"; }
        else if(st.lu){ txt='<span style="color:var(--encre-doux);font-size:.8rem">lue</span>'; }
        h+="<td>"+txt+"</td>";
      });
      const alerte=b.sorties>2?' style="color:var(--faux);font-weight:700"':'';
      h+='<td style="white-space:nowrap">'+(b.fini?dvDateHeure(b.fini):"-")+'</td>'
        +'<td>'+dvDuree(b.temps)+'</td>'
        +'<td>'+(b.essais||"-")+'</td>'
        +'<td'+alerte+'>'+(b.sorties||0)+'</td></tr>';
    });
    z.innerHTML=h+'</tbody></table></div>'
      +'<p style="color:var(--encre-doux);font-size:.84rem;margin-top:12px"><i class="ph ph-info"></i> '
      +'Un pourcentage en rouge signale un élève qui a essayé sans atteindre le score demandé. '
      +'Les « sorties » comptent les changements d’onglet pendant le travail : au-delà de deux, la colonne passe en rouge. '
      +'Le temps est mesuré à partir du moment où l’élève ouvre le travail, et cesse dès qu’il quitte la page.</p></div>';
  }).catch(function(){ z.innerHTML=svcIndispo("Impossible de charger le détail."); });
}

/* ============================================================
   QUESTIONS DU PROFESSEUR
   Jusqu'ici, MusEduc ne proposait que les questions écrites par l'auteur : un
   collègue qui n'enseigne pas dans le même ordre s'en servait à moitié. Ici, le
   professeur écrit SES questions, pour SES propres leçons (voir plus bas).
   Elles ne se mêlent JAMAIS aux questions d'origine : les 66 leçons de
   l'application gardent exactement leur contenu. L'apport du professeur vient
   en plus, dans son propre domaine.
   Elles sont rangées sous son compte, et lues par les élèves de ses classes.
   ============================================================ */
let _qProf={};            /* cat -> [{id,q,r,o,diff,expl}] */
let _qProfCharge=false;

/* Pool selon la difficulté, calqué sur les banques existantes :
   facile = les faciles ; intermédiaire = faciles + moyennes ; difficile = moyennes + difficiles. */
function qProfPool(cat,diff){
  const l=_qProf[cat]||[];
  if(!l.length)return [];
  if(diff===1)return l.filter(function(x){return x.diff===1;});
  if(diff===2)return l.filter(function(x){return x.diff<=2;});
  return l.filter(function(x){return x.diff>=2;});
}
/* Convertit une question du professeur en exercice, exactement dans la forme
   attendue par le moteur (mêmes champs que les banques de l'application). */
function qProfEx(q){
  return {emp:"qp-"+q.id,
    consigne:q.q,
    champ:selListe(q.o,q.r),
    verif:function(v){ return norm(v)===norm(q.r); },
    solution:"Réponse&nbsp;: <b>"+q.r+"</b>."+(q.expl?" "+q.expl:"")};
}
/* Les questions du professeur ne servent QUE dans SES leçons : on n'enrobe
   aucun générateur d'origine. Les 66 leçons et leurs banques de questions
   restent strictement inchangées, l'apport du professeur vient EN PLUS. */

/* Charge les questions : les siennes pour un professeur, celles du professeur de
   sa classe pour un élève. */
/* Identifiant du professeur dont il faut lire les contenus : le sien pour un
   enseignant, celui de sa classe pour un élève.
   ⚠️ On ATTEND la session anonyme avant toute lecture : au démarrage,
   a.currentUser est encore null côté élève, la requête partait sans
   authentification et le serveur la refusait en silence. C'était la raison pour
   laquelle les leçons du professeur n'apparaissaient jamais. */
function profProprietaire(){
  const s=fbStore(), a=fbAuth();
  if(!s||!a)return Promise.resolve(null);
  const u=a.currentUser;
  if(u&&estProf(u))return Promise.resolve(u.uid);
  if(!profil.classeId)return Promise.resolve(null);
  const pret=(typeof authElevePret==="function")?authElevePret():Promise.resolve(u);
  return pret.then(function(){
    return s.collection("classes").doc(profil.classeId).get()
      .then(function(d){ return d.exists?(d.data()||{}).ownerUid:null; });
  }).catch(function(){ return null; });
}
/* Charge les contenus du professeur : les questions PUIS les leçons.
   Les trois points de démarrage n'appelaient que qProfCharger : lpCharger
   n'était jamais exécuté, donc les leçons du professeur n'existaient pas côté
   élève. On retente une fois si rien n'est remonté alors que l'élève appartient
   bien à une classe (session anonyme tardive, réseau lent au lancement). */
function chargerContenusProf(essai){
  return qProfCharger(true).then(function(){ return lpCharger(); }).then(function(l){
    const vide=!(l&&l.length)&&!Object.keys(_qProf||{}).length;
    if(vide&&profil.classeId&&!(essai>=1))setTimeout(function(){ chargerContenusProf(1); },4000);
    return l;
  }).catch(function(){ return []; });
}
function qProfCharger(force){
  if(_qProfCharge&&!force)return Promise.resolve(_qProf);
  const s=fbStore(), a=fbAuth(); if(!s||!a)return Promise.resolve({});
  return profProprietaire().then(function(uid){
    if(!uid)return {};
    return s.collection("teachers").doc(uid).collection("questions").get()
      .then(function(snap){
        const par={};
        snap.forEach(function(d){
          const v=d.data()||{};
          if(!v.cat||!v.q||!v.r||!Array.isArray(v.o))return;
          (par[v.cat]=par[v.cat]||[]).push({id:d.id,q:v.q,r:v.r,o:v.o,
            diff:v.diff||2,expl:v.expl||""});
        });
        return par;
      });
  }).then(function(par){
    _qProf=par||{}; _qProfCharge=true;
    try{ jeuThemesCache=null; }catch(e){}   /* une leçon du professeur peut devenir jouable */
    return _qProf;
  }).catch(function(){ _qProfCharge=true; return _qProf; });
}
const QPROF_DIFF={1:"Facile",2:"Intermédiaire",3:"Difficile"};
let _qpFixe=null, _qpEdit=null, _qpListe=[];
/* ================= Import CSV des questions (lecons du prof) ================= */
function qCsvCat(){ return _qpFixe || (((document.getElementById("qpCat")||{}).value)||"").trim(); }
function qCsvChoisir(){ const i=document.getElementById("qCsvFichier"); if(i)i.click(); }
function qCsvEchap(v){ v=String(v==null?"":v); return /[";\n,\r]/.test(v) ? '"'+v.replace(/"/g,'""')+'"' : v; }
function qCsvTelecharger(txt,nom){
  const blob=new Blob([txt],{type:"text/csv;charset=utf-8"});
  const url=URL.createObjectURL(blob); const a=document.createElement("a");
  a.href=url; a.download=nom; document.body.appendChild(a); a.click();
  setTimeout(function(){ try{URL.revokeObjectURL(url);}catch(e){} a.remove(); },1500);
}
function qCsvModele(){
  const sep=";";
  const lignes=[
    ["question","bonne_reponse","mauvaise_1","mauvaise_2","mauvaise_3","difficulte","explication"],
    ["Combien de temps vaut une blanche ?","2 temps","1 temps","3 temps","4 temps","1","La blanche vaut deux noires."],
    ["Quel signe monte une note d'un demi-ton ?","Le dièse","Le bémol","Le bécarre","La clef","2","Le dièse (#) monte la note d'un demi-ton."],
    ["Qui a composé l'Ode à la joie ?","Beethoven","Mozart","Vivaldi","Chopin","2","C'est l'hymne européen, tiré de sa 9e Symphonie."]
  ];
  const csv="\ufeff"+lignes.map(function(r){ return r.map(qCsvEchap).join(sep); }).join("\r\n")+"\r\n";
  qCsvTelecharger(csv,"modele-questions-museduc.csv");
}
function qCsvSepDetect(texte){
  const l=(texte.split(/\r?\n/)[0]||"");
  const pv=(l.match(/;/g)||[]).length, vg=(l.match(/,/g)||[]).length, tb=(l.match(/\t/g)||[]).length;
  if(tb>0 && tb>=pv && tb>=vg)return "\t";
  return (pv>=vg)?";":",";
}
function qCsvParser(texte,sep){
  const out=[]; let champ="",ligne=[],i=0,q=false; const n=texte.length;
  while(i<n){
    const c=texte[i];
    if(q){
      if(c==='"'){ if(texte[i+1]==='"'){champ+='"';i+=2;continue;} q=false;i++;continue; }
      champ+=c;i++;continue;
    }
    if(c==='"'){ q=true;i++;continue; }
    if(c===sep){ ligne.push(champ);champ="";i++;continue; }
    if(c==='\r'){ i++;continue; }
    if(c==='\n'){ ligne.push(champ);out.push(ligne);ligne=[];champ="";i++;continue; }
    champ+=c;i++;
  }
  ligne.push(champ); out.push(ligne);
  return out.filter(function(r){ return r.some(function(x){return String(x).trim()!=="";}); });
}
function qCsvImporter(input){
  const f=input&&input.files&&input.files[0]; if(input)input.value="";
  const msg=document.getElementById("qCsvMsg");
  const dire=function(t,ok){ if(msg){ msg.style.color=ok?"var(--juste)":"var(--faux)"; msg.innerHTML=t; } else if(!ok)toast(t); };
  if(!f)return;
  const cat=qCsvCat();
  if(!cat){ dire("Choisissez d'abord une leçon dans la liste.",false); return; }
  const r=new FileReader();
  r.onerror=function(){ dire("Lecture du fichier impossible.",false); };
  r.onload=function(){
    let txt=String(r.result||""); if(txt.charCodeAt(0)===0xFEFF)txt=txt.slice(1);
    const sep=qCsvSepDetect(txt);
    const rows=qCsvParser(txt,sep);
    if(!rows.length){ dire("Le fichier est vide.",false); return; }
    const norm=function(x){ return String(x||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,""); };
    const h0=rows[0].map(norm);
    const aHeader = h0.indexOf("question")>=0 || h0.some(function(x){return x.indexOf("bonne")>=0 || x==="reponse";});
    let idx={q:0,r:1,m1:2,m2:3,m3:4,diff:5,expl:6}, data=rows;
    if(aHeader){
      const find=function(cands){ for(let i=0;i<h0.length;i++){ if(cands.indexOf(h0[i])>=0)return i; } return -1; };
      idx={
        q:find(["question","enonce","q"]),
        r:find(["bonne_reponse","bonne","reponse","reponse_correcte","correct","r"]),
        m1:find(["mauvaise_1","mauvaise1","fausse_1","faux_1","distracteur_1","mauvaise"]),
        m2:find(["mauvaise_2","mauvaise2","fausse_2","faux_2","distracteur_2"]),
        m3:find(["mauvaise_3","mauvaise3","fausse_3","faux_3","distracteur_3"]),
        diff:find(["difficulte","diff","niveau"]),
        expl:find(["explication","expl","commentaire","justification"])
      };
      data=rows.slice(1);
    }
    const cell=function(row,k){ const i=idx[k]; return (i>=0 && i<row.length)? String(row[i]||"").trim() : ""; };
    const diffMap=function(v){ v=String(v||"").toLowerCase().trim();
      if(v==="1"||v.indexOf("facile")>=0)return 1;
      if(v==="3"||v.indexOf("diffic")>=0)return 3;
      return 2; };
    const docs=[]; let ignore=0;
    data.forEach(function(row){
      const q=cell(row,"q"), rr=cell(row,"r");
      const mau=[cell(row,"m1"),cell(row,"m2"),cell(row,"m3")].filter(function(x){return x;});
      if(!q||!rr||!mau.length){ ignore++; return; }
      const seen={}; let dup=false;
      [rr].concat(mau).forEach(function(x){ const k=x.toLowerCase(); if(seen[k])dup=true; seen[k]=1; });
      if(dup){ ignore++; return; }
      docs.push({cat:cat, diff:diffMap(cell(row,"diff")), q:q, r:rr, o:[rr].concat(mau), expl:cell(row,"expl")});
    });
    if(!docs.length){ dire("Aucune question valide : chaque ligne a besoin d'une question, d'une bonne réponse et d'au moins une mauvaise réponse.",false); return; }
    if(docs.length>300){ dire("Trop de questions d'un coup (300 maximum). Découpez le fichier.",false); return; }
    const st=fbStore(), au=fbAuth(), u=au&&au.currentUser;
    if(!st||!u){ dire("Service indisponible.",false); return; }
    dire('<i class="ph ph-spinner-gap"></i> Import de '+docs.length+' question(s)…',true);
    const col=st.collection("teachers").doc(u.uid).collection("questions");
    const batch=st.batch();
    docs.forEach(function(d){ batch.set(col.doc(), d); });
    const p=unSeul("qCsvImport",function(){ return batch.commit(); });
    if(!p){ dire("Import déjà en cours…",false); return; }
    p.then(function(){
      toast(docs.length+" question(s) importée(s)"+(ignore?" · "+ignore+" ligne(s) ignorée(s)":"")+".");
      try{ _qProfCharge=false; if(typeof qProfCharger==="function")qProfCharger(); }catch(e){}
      ecranQuestionsProf(_qpFixe);
    }).catch(function(){ dire("L'import a échoué. Réessayez.",false); });
  };
  r.readAsText(f,"utf-8");
}
function ecranQuestionsProf(catFixe){
  _qpFixe=catFixe||null; _qpEdit=null;
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale();
  /* appelé depuis une leçon personnelle : on y revient, et le thème est imposé */
  if(catFixe)majRetour(ecranLeconsProf,"Mes leçons");
  else majRetour(accueil,"Accueil");
  titreProf('<i class="ph ph-pencil-line"></i> '+(catFixe?"Questions : "+devoirNomCible(catFixe):"Mes questions"),
    catFixe?"Une question suffit pour ouvrir l'entraînement et l'évaluation ; plusieurs valent mieux."
           :"Vos questions servent dans vos propres leçons.");
  const z=document.getElementById("zone");
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u||!estProf(u)){ z.innerHTML=svcIndispo("Cet espace est réservé aux professeurs connectés."); return; }
  z.innerHTML=`<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>`;
  /* les leçons d'abord : c'est parmi elles qu'on choisit le thème */
  lpCharger().then(function(){
    return s.collection("teachers").doc(u.uid).collection("questions").get();
  }).then(function(snap){
    let l=[]; snap.forEach(function(d){ l.push(Object.assign({id:d.id},d.data()||{})); });
    if(catFixe)l=l.filter(function(x){return x.cat===catFixe;});
    _qpListe=l;
    l.sort(function(x,y){ return String(x.cat||"").localeCompare(String(y.cat||""),"fr")
                              || (x.diff||2)-(y.diff||2); });
    if(!_lecPerso.length){
      z.innerHTML=`<div class="accueil" style="max-width:620px"><div class="ex" style="text-align:center">
        <h3 style="margin-top:0"><i class="ph ph-info"></i> Créez d'abord une leçon</h3>
        <p>Vos questions se rattachent à <b>vos propres leçons</b>. Les leçons d'origine de
          l'application gardent leurs questions telles quelles : votre travail vient en plus.</p>
        <button class="rm-cta" onclick="ecranLeconsProf()"><i class="ph-fill ph-plus"></i> Créer une leçon</button>
      </div></div>`;
      return;
    }
    let h=`<div class="accueil" style="max-width:900px">
      <div class="ex" style="margin-bottom:22px;background:var(--surface-2)">
        <h3 style="margin-top:0;text-align:center"><i class="ph ph-file-csv"></i> Importer des questions (CSV)</h3>
        <p style="text-align:center;color:var(--encre-doux);font-size:.9rem;margin:0 0 12px">Préparez vos questions dans un tableur, ou demandez-les à une IA à partir du modèle, puis importez le fichier. Colonnes&nbsp;: question, bonne réponse, 1 à 3 mauvaises réponses, difficulté (1&nbsp;facile · 2&nbsp;moyen · 3&nbsp;difficile), explication.</p>
        <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">
          <button class="action btn-nouv" onclick="qCsvModele()"><i class="ph ph-download-simple"></i> Télécharger le modèle</button>
          <input type="file" id="qCsvFichier" accept=".csv,text/csv" style="display:none" onchange="qCsvImporter(this)">
          <button class="rm-cta" onclick="qCsvChoisir()"><i class="ph ph-upload-simple"></i> Importer un CSV</button>
        </div>
        <div id="qCsvMsg" style="text-align:center;font-size:.85rem;margin-top:10px;min-height:18px"></div>
      </div>
      <div class="ex" style="margin-bottom:22px">
        <h3 style="margin-top:0;text-align:center"><i class="ph ph-plus-circle"></i> Écrire une question</h3>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px">
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Pour quelle leçon ?
            <select id="qpCat" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)">
              ${_lecPerso.map(function(x){return `<option value="perso-${x.id}"${catFixe==="perso-"+x.id?" selected":""}>${echapH(x.titre)}</option>`;}).join("")}
            </select></label>
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Niveau
            <select id="qpDiff" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)">
              <option value="1">Facile</option><option value="2" selected>Intermédiaire</option><option value="3">Difficile</option>
            </select></label>
        </div>
        <label style="display:block;font-size:.86rem;color:var(--encre-doux);margin-top:12px">Question
          <input id="qpQ" type="text" maxlength="180" placeholder="Ex : Combien de temps dure une blanche ?" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-top:12px">
          <label style="display:block;font-size:.86rem;color:var(--juste)">Bonne réponse
            <input id="qpR" type="text" maxlength="90" placeholder="2 temps" style="width:100%;margin-top:4px;padding:9px 10px;border:2px solid var(--juste);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Mauvaise réponse 1
            <input id="qpO1" type="text" maxlength="90" placeholder="1 temps" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Mauvaise réponse 2
            <input id="qpO2" type="text" maxlength="90" placeholder="4 temps" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Mauvaise réponse 3 (facultatif)
            <input id="qpO3" type="text" maxlength="90" placeholder="" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
        </div>
        <label style="display:block;font-size:.86rem;color:var(--encre-doux);margin-top:12px">Explication montrée après la correction (facultatif)
          <input id="qpExpl" type="text" maxlength="200" placeholder="Ex : la blanche vaut deux noires." style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.95rem;background:var(--surface);color:var(--encre)"></label>
        <div id="qpErr" style="color:var(--faux);font-size:.86rem;margin-top:8px;display:none"></div>
        <div id="qpEditBandeau" style="display:none;margin-top:10px;padding:8px 12px;border-radius:10px;
             background:var(--teinte-douce);font-size:.88rem">
          <i class="ph ph-pencil-simple"></i> Vous modifiez une question existante.
          <button class="btn-son mini" style="margin-left:6px" onclick="qProfAnnulerEdition()" title="Revenir à la création">
            <i class="ph ph-x"></i></button></div>
        <div id="qpApercu" style="margin-top:14px"></div>
        <div style="display:flex;gap:10px;justify-content:center;margin-top:14px;flex-wrap:wrap">
          <button class="action btn-nouv" onclick="qProfApercu()"><i class="ph ph-eye"></i> Aperçu élève</button>
          <button class="rm-cta" id="qpBtnSave" onclick="qProfAjouter()"><i class="ph-fill ph-floppy-disk"></i> Enregistrer la question</button>
        </div>
      </div>`;
    if(!l.length){
      h+=`<p class="badge-vide">Aucune question pour l'instant. Celles que vous écrirez apparaîtront chez vos élèves
        dès leur prochaine connexion, mélangées à celles de l'application.</p>`;
    }else{
      h+=`<h3 class="prog-titre" style="text-align:center"><i class="ph ph-list-bullets"></i> Mes questions (${l.length})</h3>`;
      let catCourante=null;
      l.forEach(function(q){
        if(q.cat!==catCourante){
          catCourante=q.cat;
          h+=`<h4 style="margin:18px 0 8px;font-family:var(--police-titre);text-align:center">
            ${echapH(devoirNomCible(q.cat))}</h4>`;
        }
        h+=`<div class="ex" style="margin-bottom:10px;display:flex;gap:12px;align-items:flex-start">
          <div style="flex:1;min-width:0">
            <b>${echapH(q.q||"")}</b>
            <br><span style="font-size:.86rem;color:var(--juste)"><i class="ph-fill ph-check-circle"></i> ${echapH(q.r||"")}</span>
            <span style="font-size:.86rem;color:var(--encre-doux)"> · ${(q.o||[]).filter(function(x){return x!==q.r;}).map(echapH).join(" · ")}</span>
            <br><span style="font-size:.8rem;color:var(--encre-doux)">${QPROF_DIFF[q.diff||2]}${q.expl?" · "+echapH(q.expl):""}</span>
          </div>
          <button class="btn-son mini" title="Modifier cette question" onclick="qProfModifier('${q.id}')"><i class="ph ph-pencil-simple"></i></button>
          <button class="btn-son mini" title="Supprimer" onclick="qProfSupprimer('${q.id}')"><i class="ph ph-trash" style="color:var(--faux)"></i></button>
        </div>`;
      });
    }
    z.innerHTML=h+`</div>`;
    if(catFixe){ const sel=document.getElementById("qpCat");
      if(sel){ sel.value=catFixe; sel.disabled=true; sel.style.opacity=".7"; } }
  }).catch(function(e){
    const c=String((e&&e.code)||(e&&e.message)||"");
    if(c.indexOf("permission-denied")>=0){
      z.innerHTML=`<div class="ex" style="max-width:640px;margin:0 auto">
        <h3 style="margin-top:0"><i class="ph ph-warning" style="color:var(--faux)"></i> Règles Firestore à publier</h3>
        <p>Le serveur refuse l'accès à vos questions : il faut publier les règles de sécurité à jour.</p>
        <p style="color:var(--encre-doux);font-size:.9rem">Console Firebase → <i>Firestore Database</i> →
          <i>Règles</i> → coller <b>firestore.rules</b> → <b>Publier</b>.</p></div>`;
    }else z.innerHTML=svcIndispo("Impossible de charger vos questions.");
  });
}
/* Lit le formulaire, avec les mêmes contrôles que l'enregistrement. */
function qProfLire(){
  const val=function(id){ return (((document.getElementById(id)||{}).value)||"").trim(); };
  const q=val("qpQ"), r=val("qpR");
  const mauvaises=[val("qpO1"),val("qpO2"),val("qpO3")].filter(function(x){return x;});
  return {cat:val("qpCat"), diff:parseInt(val("qpDiff"),10)||2, q:q, r:r,
          o:[r].concat(mauvaises), expl:val("qpExpl"), mauvaises:mauvaises};
}
function qProfValider(o,dire){
  if(!o.q){dire("Écrivez la question.");return false;}
  if(!o.r){dire("Indiquez la bonne réponse.");return false;}
  if(o.mauvaises.length<1){dire("Donnez au moins une mauvaise réponse : sans quoi il n'y a pas de choix.");return false;}
  const vus={};
  for(let i=0;i<o.o.length;i++){
    const k=norm(o.o[i]);
    if(vus[k]){dire("Deux réponses sont identiques : « "+o.o[i]+" ».");return false;}
    vus[k]=1;
  }
  return true;
}
/* Aperçu exactement tel que l'élève le verra : mêmes boutons, même rendu. */
function qProfApercu(){
  const err=document.getElementById("qpErr");
  const dire=function(m){ if(err){err.textContent=m;err.style.display="block";} };
  const o=qProfLire();
  const z=document.getElementById("qpApercu"); if(!z)return;
  if(!qProfValider(o,dire)){ z.innerHTML=""; return; }
  if(err)err.style.display="none";
  const av=difficulte; difficulte=o.diff;
  let champ=""; try{ champ=selListe(o.o,o.r); }catch(e){}
  difficulte=av;
  z.innerHTML=`<div class="ex" style="border-style:dashed">
    <div style="font-size:.8rem;color:var(--encre-doux);margin-bottom:8px">
      <i class="ph ph-eye"></i> Aperçu tel que l'élève le verra (${echapH(devoirNomCible(o.cat))} · ${QPROF_DIFF[o.diff]})</div>
    <div class="consigne">${echapH(o.q)}</div>
    <div class="reponse-zone">${champ}</div>
    <div style="margin-top:10px;font-size:.86rem;color:var(--juste)">
      <i class="ph-fill ph-check-circle"></i> Correction : <b>${echapH(o.r)}</b>${o.expl?" · "+echapH(o.expl):""}</div>
  </div>`;
}
function qProfAjouter(){
  const err=document.getElementById("qpErr");
  const dire=function(m){ if(err){err.textContent=m;err.style.display="block";} else toast(m); };
  const o=qProfLire();
  if(!qProfValider(o,dire))return;
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u){dire("Service indisponible.");return;}
  if(err)err.style.display="none";
  const col=s.collection("teachers").doc(u.uid).collection("questions");
  const donnees={cat:o.cat, diff:o.diff, q:o.q, r:o.r, o:o.o, expl:o.expl};
  const p=unSeul("question",function(){
    return pendant(_qpEdit?"Modification de la question…":"Enregistrement de la question…",
      _qpEdit ? col.doc(_qpEdit).set(Object.assign({maj:Date.now()},donnees),{merge:true})
              : col.add(Object.assign({cree:Date.now()},donnees))); });
  if(!p)return;
  p.then(function(){
    toast(_qpEdit?"Question modifiée !":"Question enregistrée !");
    _qProfCharge=false;
    qProfCharger(true).then(lpCharger).then(function(){ ecranQuestionsProf(o.cat.indexOf("perso-")===0?o.cat:null); });
  }).catch(function(){ dire("Impossible d'enregistrer. Vérifiez que les règles Firestore sont publiées."); });
}
/* Recharge le formulaire avec une question existante : on modifie sur place,
   au lieu de supprimer puis réécrire. */
function qProfModifier(id){
  const q=_qpListe.filter(function(x){return x.id===id;})[0]; if(!q)return;
  _qpEdit=id;
  const met=function(k,v){ const e=document.getElementById(k); if(e)e.value=v==null?"":v; };
  met("qpCat",q.cat); met("qpDiff",String(q.diff||2));
  met("qpQ",q.q); met("qpR",q.r); met("qpExpl",q.expl||"");
  const mauvaises=(q.o||[]).filter(function(x){return x!==q.r;});
  met("qpO1",mauvaises[0]||""); met("qpO2",mauvaises[1]||""); met("qpO3",mauvaises[2]||"");
  const b=document.getElementById("qpEditBandeau"); if(b)b.style.display="block";
  const s=document.getElementById("qpBtnSave");
  if(s)s.innerHTML='<i class="ph-fill ph-floppy-disk"></i> Enregistrer les modifications';
  const a=document.getElementById("qpApercu"); if(a)a.innerHTML="";
  const e=document.getElementById("qpErr"); if(e)e.style.display="none";
  const champ=document.getElementById("qpQ");
  if(champ&&champ.scrollIntoView)champ.scrollIntoView({block:"center",behavior:"smooth"});
  if(champ)champ.focus();
}
function qProfAnnulerEdition(){
  _qpEdit=null;
  ["qpQ","qpR","qpO1","qpO2","qpO3","qpExpl"].forEach(function(k){
    const e=document.getElementById(k); if(e)e.value=""; });
  const b=document.getElementById("qpEditBandeau"); if(b)b.style.display="none";
  const s=document.getElementById("qpBtnSave");
  if(s)s.innerHTML='<i class="ph-fill ph-floppy-disk"></i> Enregistrer la question';
  const a=document.getElementById("qpApercu"); if(a)a.innerHTML="";
}
async function qProfSupprimer(id){
  if(!await dlgConfirmer("Supprimer cette question ?\n\nElle ne sera plus proposée à vos élèves."))return;
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser; if(!s||!u)return;
  pendant("Suppression…",s.collection("teachers").doc(u.uid).collection("questions").doc(id).delete())
   .then(function(){ toast("Question supprimée.");
     _qProfCharge=false; qProfCharger(true).then(lpCharger).then(function(){ ecranQuestionsProf(_qpFixe); }); })
   .catch(function(){ toast("La suppression a échoué."); });
}

/* ============================================================
   LEÇONS DU PROFESSEUR
   Un collègue qui traite un sujet absent de l'application (une œuvre au
   programme, un projet de classe, une sortie) écrit ici sa propre leçon et ses
   propres questions. Ses élèves la lisent, s'entraînent dessus et peuvent être
   évalués, exactement comme sur les leçons d'origine.
   Tout passe par une INJECTION dans les structures existantes (CATEGORIES,
   LECONS, GEN) : la vignette du domaine, le menu déroulant des devoirs, le mode
   séance et les jeux la reprennent alors sans une ligne de code de plus.
   ============================================================ */
/* Le nom dépend de qui regarde : « Mon professeur » n'avait aucun sens pour le
   professeur lui-même, et restait vague pour l'élève. */
function lpGroupeNom(){
  return (typeof profConnecte==="function"&&profConnecte())?"Mes leçons":"Leçons de la classe";
}
/* Icônes proposées : libellés en français, l'identifiant Phosphor reste interne. */
const LP_ICONES=[["chalkboard-teacher","Tableau (cours)"],["music-notes","Notes de musique"],
                 ["book-open-text","Livre ouvert"],["ear","Oreille (écoute)"],["guitar","Guitare"],
                 ["piano-keys","Piano"],["microphone-stage","Micro (chant)"],["metronome","Métronome / rythme"],
                 ["globe-hemisphere-west","Monde (musiques du monde)"],["mask-happy","Théâtre / opéra"],
                 ["waveform","Onde sonore"],["film-slate","Musique de film"],
                 ["users-three","Projet de classe"],["star","Étoile"]];
let _lecPerso=[];          /* [{id,titre,texte,ic}] */
/* Où revenir après une création, une modification ou une suppression : la
   grille des leçons (gestion au survol) ou l'écran « Mes leçons ». */
let _lpRetourGrille=false;
function lpRetour(){
  if(_lpRetourGrille&&typeof ecranLeconsCat==="function"){
    const gi=(typeof lecDernierDomaine==="number"&&lecDernierDomaine>=0)?lecDernierDomaine:0;
    ecranLeconsCat(gi); return;
  }
  ecranLeconsProf();
}
let _lecPersoInjecte=false;

/* Mise en forme du texte saisi par le professeur.
   On ÉCHAPPE tout, puis on rétablit une poignée de marques : le contenu est
   affiché chez les élèves, il ne doit jamais pouvoir injecter de HTML. */
function lpRendre(txt){
  const esc=echapH(String(txt||""));
  const blocs=esc.split(/\n{2,}/);
  return blocs.map(function(b){
    const lignes=b.split("\n").map(function(l){return l.trim();}).filter(function(l){return l;});
    if(!lignes.length)return "";
    if(lignes.every(function(l){return l.indexOf("- ")===0;}))
      return "<ul>"+lignes.map(function(l){return "<li>"+lpGras(l.slice(2))+"</li>";}).join("")+"</ul>";
    if(lignes.length===1&&lignes[0].indexOf("## ")===0)
      return "<h3>"+lpGras(lignes[0].slice(3))+"</h3>";
    return "<p>"+lignes.map(lpGras).join("<br>")+"</p>";
  }).join("");
}
function lpGras(s){ return s.replace(/\*\*([^*]+)\*\*/g,"<b>$1</b>"); }

/* Construit le HTML de la leçon, au format attendu par afficherLecon. */
function lpHtmlLecon(l){
  return `<div class="carte"><h3>${echapH(l.titre||"Leçon")}</h3>${lpRendre(l.texte)}</div>`;
}
/* Générateur d'exercices : uniquement les questions écrites par le professeur
   pour CETTE leçon. Sans question, pas de générateur : la leçon reste lisible
   mais l'entraînement et l'évaluation ne sont pas proposés (voir afficherLecon). */
function lpInstallerGen(cat){
  GEN[cat]=function(){
    /* on ne demande jamais plus de questions que le professeur n'en a écrit :
       au-delà, mapEx ne pourrait que répéter les mêmes */
    const pool=qProfPool(cat,difficulte);
    const l=pool.length?pool:(_qProf[cat]||[]);
    if(!l.length)return [];
    return mapEx(Math.min(nbQuestions,l.length),function(){
      return qProfEx(l[Math.floor(Math.random()*l.length)]);
    });
  };
}
/* Injecte les leçons dans les structures de l'application. Idempotent : on
   remplace le groupe au lieu de l'empiler, pour pouvoir recharger. */
function lpInjecter(){
  /* on retire l'ancien groupe s'il existe déjà (le nom a pu changer avec le rôle) */
  for(let i=CATEGORIES.length-1;i>=0;i--){
    if(CATEGORIES[i].perso)CATEGORIES.splice(i,1);
  }
  const nomGroupe=lpGroupeNom();
  const items=[];
  _lecPerso.forEach(function(l){
    const cat="perso-"+l.id;
    LECONS[cat]={titre:l.titre||"Leçon",html:lpHtmlLecon(l),perso:true};
    const nbQ=(_qProf[cat]||[]).length;
    if(nbQ>=1)lpInstallerGen(cat);
    else { delete GEN[cat]; LECONS[cat].sansExos=true; }
    items.push({id:cat,nom:l.titre||"Leçon",ic:"<i class='ph ph-"+(l.ic||"chalkboard-teacher")+"'></i>",niv:""});
  });
  /* Pour un ENSEIGNANT la vignette existe toujours, même sans aucune leçon :
     c'est de là qu'il en crée une. Pour un élève, rien à montrer s'il n'y en a pas. */
  const estProfIci=(typeof profConnecte==="function"&&profConnecte());
  if(items.length||estProfIci){
    CATEGORIES.unshift({groupe:nomGroupe,items:items,perso:true});
    LEC_ICONES[nomGroupe]="<i class='ph ph-chalkboard-teacher'></i>";
    LEC_COURTS[nomGroupe]=nomGroupe;
  }
  _lecPersoInjecte=true;
  try{ jeuThemesCache=null; }catch(e){}
  try{ if(typeof construireMenu==="function")construireMenu(); }catch(e){}
}
/* Charge les leçons : les siennes pour un professeur, celles du professeur de sa
   classe pour un élève. Appelée juste après les questions, dont elle dépend
   (c'est le nombre de questions qui décide si la leçon est entraînable). */
function lpCharger(){
  const s=fbStore(), a=fbAuth(); if(!s||!a)return Promise.resolve([]);
  return profProprietaire().then(function(uid){
    if(!uid){ _lecPerso=[]; lpInjecter(); return []; }
    return s.collection("teachers").doc(uid).collection("lecons").get().then(function(snap){
      const l=[]; snap.forEach(function(d){
        const v=d.data()||{};
        l.push({id:d.id,titre:v.titre||"Leçon",texte:v.texte||"",ic:v.ic||"chalkboard-teacher",cree:v.cree||0});
      });
      l.sort(function(x,y){ return (x.cree||0)-(y.cree||0); });
      _lecPerso=l; lpInjecter();
      return l;
    });
  }).catch(function(){ return _lecPerso; });
}

/* ---------- Écrans du professeur ---------- */
function ecranLeconsProf(){
  _lpRetourGrille=false;
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  titreProf('<i class="ph ph-chalkboard-teacher"></i> Mes leçons',
    "Vos leçons apparaissent chez vos élèves, dans « Leçons », avec entraînement et évaluation.");
  const z=document.getElementById("zone");
  const a=fbAuth(), u=a&&a.currentUser;
  if(!fbStore()||!u||!estProf(u)){ z.innerHTML=svcIndispo("Cet espace est réservé aux professeurs connectés."); return; }
  z.innerHTML=`<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>`;
  lpCharger().then(function(l){
    let h=`<div class="accueil" style="max-width:820px">
      <div style="text-align:center;margin-bottom:20px">
        <button class="rm-cta" onclick="ecranLeconProfEdit('')"><i class="ph-fill ph-plus"></i> Créer une leçon</button>
      </div>`;
    if(!l.length){
      h+=`<div class="ex">
        <h3 style="margin-top:0"><i class="ph ph-lightbulb"></i> À quoi ça sert ?</h3>
        <p>Vous traitez un sujet que l'application ne couvre pas : une œuvre au programme, un projet de
          classe, une sortie, un artiste que vous étudiez. Écrivez la leçon ici, ajoutez-y vos questions,
          et vos élèves pourront la lire, s'entraîner dessus et <b>être évalués</b> comme sur les autres.</p>
        <p style="color:var(--encre-doux);font-size:.9rem">Elle apparaîtra chez eux dans <b>Leçons</b>,
          domaine « Mon professeur », et vous pourrez la donner en <b>devoir</b>.</p></div>`;
    }else{
      l.forEach(function(x){
        const nbQ=(_qProf["perso-"+x.id]||[]).length;
        h+=`<div class="ex" style="margin-bottom:12px;display:flex;gap:14px;align-items:center;flex-wrap:wrap">
          <span style="font-size:1.5rem"><i class="ph ph-${x.ic}"></i></span>
          <div style="flex:1;min-width:180px">
            <b>${echapH(x.titre)}</b><br>
            <span style="font-size:.86rem;color:${nbQ?"var(--encre-doux)":"var(--faux)"}">
              ${nbQ} question${nbQ>1?"s":""}${!nbQ?" · sans question, la leçon est seulement à lire"
                :(nbQ<5?" · ajoutez-en pour varier les séries":"")}</span>
          </div>
          <button class="action btn-nouv" onclick="ecranLeconProfEdit('${x.id}')"><i class="ph ph-pencil-simple"></i> Modifier</button>
          <button class="action btn-corr" onclick="ecranQuestionsProf('perso-${x.id}')"><i class="ph ph-list-plus"></i> Ses questions</button>
          <button class="btn-son mini" title="Voir comme un élève" onclick="afficherLecon('perso-${x.id}')"><i class="ph ph-eye"></i></button>
          <button class="btn-son mini" title="Supprimer" onclick="lpSupprimer('${x.id}')"><i class="ph ph-trash" style="color:var(--faux)"></i></button>
        </div>`;
      });
    }
    z.innerHTML=h+`</div>`;
  }).catch(function(){ z.innerHTML=svcIndispo("Impossible de charger vos leçons."); });
}
function ecranLeconProfEdit(id,depuisGrille){
  if(depuisGrille!==undefined)_lpRetourGrille=!!depuisGrille;
  masquerInterfaceNormale(); majRetour(lpRetour,"Mes leçons");
  titreProf(id?'<i class="ph ph-pencil-simple"></i> Modifier la leçon':'<i class="ph ph-plus-circle"></i> Nouvelle leçon');
  const l=_lecPerso.filter(function(x){return x.id===id;})[0]||{titre:"",texte:"",ic:"chalkboard-teacher"};
  document.getElementById("zone").innerHTML=`
    <div class="accueil" style="max-width:800px">
      <div class="ex">
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end">
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Titre de la leçon
            <input id="lpTitre" type="text" maxlength="70" value="${echapH(l.titre)}" placeholder="Ex : Le tango argentin"
              style="width:100%;margin-top:4px;padding:10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:1rem;background:var(--surface);color:var(--encre)"></label>
          <label style="display:block;font-size:.86rem;color:var(--encre-doux)">Icône
            <select id="lpIc" style="margin-top:4px;padding:10px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:1rem;background:var(--surface);color:var(--encre)">
              ${LP_ICONES.map(function(i){return `<option value="${i[0]}"${l.ic===i[0]?" selected":""}>${i[1]}</option>`;}).join("")}
            </select></label>
        </div>
        <label style="display:block;font-size:.86rem;color:var(--encre-doux);margin-top:14px">Contenu de la leçon
          <textarea id="lpTexte" rows="14" placeholder="Écrivez votre leçon ici…"
            style="width:100%;margin-top:4px;padding:12px;border:1px solid var(--ligne);border-radius:10px;font-family:inherit;font-size:.98rem;line-height:1.6;background:var(--surface);color:var(--encre);resize:vertical">${echapH(l.texte)}</textarea></label>
        <details style="margin-top:8px">
          <summary style="cursor:pointer;color:var(--encre-doux);font-size:.88rem">
            <i class="ph ph-question"></i> Comment mettre en forme le texte&nbsp;?</summary>
          <div style="margin-top:8px;font-size:.88rem;line-height:1.7">
            <p style="margin:0 0 8px">Écrivez normalement. Si vous voulez aller plus loin&nbsp;:</p>
            <table style="width:100%;border-collapse:collapse">
              <tr><th style="text-align:left;padding:4px 8px;border-bottom:1px solid var(--ligne)">Vous tapez</th>
                  <th style="text-align:left;padding:4px 8px;border-bottom:1px solid var(--ligne)">L'élève voit</th></tr>
              <tr><td style="padding:6px 8px"><code>## Les instruments</code></td>
                  <td style="padding:6px 8px"><b style="font-size:1.1em">Les instruments</b> (sous-titre)</td></tr>
              <tr><td style="padding:6px 8px"><code>- le violon</code></td>
                  <td style="padding:6px 8px">• le violon (liste à puces)</td></tr>
              <tr><td style="padding:6px 8px"><code>C'est **important**</code></td>
                  <td style="padding:6px 8px">C'est <b>important</b></td></tr>
              <tr><td style="padding:6px 8px">Une ligne vide</td>
                  <td style="padding:6px 8px">un nouveau paragraphe</td></tr>
            </table>
          </div>
        </details>
        <div id="lpErr" style="color:var(--faux);font-size:.86rem;margin-top:8px;display:none"></div>
        <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:14px">
          <button class="action btn-nouv" onclick="lpApercu()"><i class="ph ph-eye"></i> Aperçu</button>
          <button class="rm-cta" onclick="lpEnregistrer('${id}')"><i class="ph-fill ph-floppy-disk"></i> Enregistrer</button>
        </div>
        <div id="lpApercu" style="margin-top:16px"></div>
      </div>
      ${lpBlocExercices(id)}
    </div>`;
}
/* Les exercices d'une leçon, juste sous son contenu : c'est là qu'on y pense,
   une fois le texte écrit. Une leçon sans exercice n'est qu'à lire. */
function lpBlocExercices(id){
  if(!id){
    return `<div class="ex" style="margin-top:16px;text-align:center;border-style:dashed">
      <p style="margin:0;color:var(--encre-doux)"><i class="ph ph-info"></i>
        Enregistrez la leçon : vous passerez aussitôt à ses <b>exercices</b>.</p></div>`;
  }
  const qs=(_qProf["perso-"+id]||[]);
  return `<div class="ex" style="margin-top:16px">
    <h3 style="margin-top:0;text-align:center"><i class="ph ph-list-checks"></i> Les exercices de cette leçon</h3>
    <p style="text-align:center;color:${qs.length?"var(--encre-doux)":"var(--faux)"};font-size:.9rem;margin-top:0">
      ${qs.length? qs.length+" question"+(qs.length>1?"s":"")+" · l'élève peut s'entraîner et être évalué"
                 : "Aucune question : la leçon est seulement à lire."}</p>
    ${qs.length?`<ul style="margin:0 0 14px;padding-left:20px;line-height:1.7">
      ${qs.slice(0,5).map(function(q){return "<li>"+echapH(q.q||"")+"</li>";}).join("")}
      ${qs.length>5?`<li style="color:var(--encre-doux)">… et ${qs.length-5} autre${qs.length>6?"s":""}</li>`:""}
    </ul>`:""}
    <div style="text-align:center">
      <button class="rm-cta" onclick="ecranQuestionsProf('perso-${id}')">
        <i class="ph-fill ph-plus-circle"></i> ${qs.length?"Ajouter ou modifier les questions":"Créer les exercices"}</button>
    </div>
  </div>`;
}
function lpApercu(){
  const t=((document.getElementById("lpTitre")||{}).value||"").trim();
  const x=((document.getElementById("lpTexte")||{}).value||"");
  const z=document.getElementById("lpApercu"); if(!z)return;
  z.innerHTML=`<div class="lecon" style="border:1px dashed var(--ligne);border-radius:14px;padding:14px">
    <div style="font-size:.8rem;color:var(--encre-doux);margin-bottom:8px"><i class="ph ph-eye"></i> Aperçu tel que l'élève le verra</div>
    ${lpHtmlLecon({titre:t||"(sans titre)",texte:x})}</div>`;
}
function lpEnregistrer(id){
  const err=document.getElementById("lpErr");
  const dire=function(m){ if(err){err.textContent=m;err.style.display="block";} else toast(m); };
  const titre=((document.getElementById("lpTitre")||{}).value||"").trim();
  const texte=((document.getElementById("lpTexte")||{}).value||"");
  const ic=((document.getElementById("lpIc")||{}).value||"chalkboard-teacher");
  if(!titre){dire("Donnez un titre à la leçon.");return;}
  if(texte.trim().length<20){dire("Le contenu est trop court : écrivez au moins quelques phrases.");return;}
  if(texte.length>20000){dire("La leçon est trop longue (20 000 caractères au maximum).");return;}
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u){dire("Service indisponible.");return;}
  if(err)err.style.display="none";
  const col=s.collection("teachers").doc(u.uid).collection("lecons");
  const donnees={titre:titre,texte:texte,ic:ic,maj:Date.now()};
  const p=unSeul("lecon",function(){
    return pendant(id?"Modification de la leçon…":"Création de la leçon…",
      id ? col.doc(id).set(donnees,{merge:true})
         : col.add(Object.assign({cree:Date.now()},donnees))); });
  if(!p)return;
  let neuf=null;
  p.then(function(ref){ if(!id&&ref&&ref.id)neuf=ref.id;
     toast("Leçon enregistrée !"); return lpCharger(); })
   .then(function(){
     /* une leçon qu'on vient de créer n'a aucun exercice : on y va tout de suite,
        c'est la suite naturelle et cela évite d'oublier cette étape */
     if(neuf){ ecranQuestionsProf("perso-"+neuf); return; }
     lpRetour(); })
   .catch(function(){ dire("Impossible d'enregistrer. Vérifiez que les règles Firestore sont publiées."); });
}
async function lpSupprimer(id,depuisGrille){
  if(depuisGrille!==undefined)_lpRetourGrille=!!depuisGrille;
  const l=_lecPerso.filter(function(x){return x.id===id;})[0];
  const nbQ=(_qProf["perso-"+id]||[]).length;
  if(!await dlgConfirmer("Supprimer la leçon « "+((l&&l.titre)||"")+" » ?\n\n"
    +(nbQ?(nbQ>1?"Ses "+nbQ+" questions seront également supprimées.\n"
                :"Sa question sera également supprimée.\n"):"")
    +"Elle disparaîtra de l'écran de vos élèves. Cette action est irréversible."))return;
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser; if(!s||!u)return;
  const base=s.collection("teachers").doc(u.uid);
  /* les questions d'abord : orphelines, elles resteraient facturées et
     ressortiraient si un futur identifiant de leçon retombait dessus */
  const sup=unSeul("lecon-sup",function(){ return pendant("Suppression…",
    base.collection("questions").where("cat","==","perso-"+id).get()
    .then(function(snap){ return Promise.all(snap.docs.map(function(d){return d.ref.delete().catch(function(){});})); })
    .then(function(){ return base.collection("lecons").doc(id).delete(); })); });
  if(!sup)return;
  sup.then(function(){ toast("Leçon supprimée."); _qProfCharge=false;
      return qProfCharger(true).then(lpCharger); })
    .then(function(){ lpRetour(); })
    .catch(function(){ toast("La suppression a échoué."); });
}

/* ============================================================
   MODE SÉANCE : faire cours au tableau
   Le mode « projection » existant agrandit l'écran courant ; il ne pilote rien.
   Ici, le contenu est découpé en écrans successifs que le professeur fait
   défiler : une idée à la fois, en très gros, et la réponse d'un exercice n'est
   dévoilée QUE sur demande. C'est ce qui permet de poser la question à la
   classe avant de la corriger.
   Les leçons se découpent sur leurs cartes, les cours interactifs sur leurs
   étapes et leurs exercices.
   ============================================================ */
let seance=null;

/* Réponse attendue d'un exercice de cours, reformulée pour le tableau. */
function seanceSolutionHTML(x){
  if(!x)return "";
  let h="";
  if(x.type==="qcm"){
    h=`<div class="sc-rep"><b>Réponse :</b> ${x.opts[x.r]}</div>`;
  }else if(x.type==="sondage"){
    h=`<div class="sc-rep"><b>Il n'y a pas de mauvaise réponse ici.</b></div>`;
  }else if(x.type==="grille"){
    h=`<table class="sc-tab"><tr><th></th>${(x.cols||[]).map(function(c){return "<th>"+c+"</th>";}).join("")}</tr>`;
    (x.rows||[]).forEach(function(r){
      h+=`<tr><td>${r.t}</td>${(x.cols||[]).map(function(_,k){
        return "<td>"+(k===r.r?'<i class="ph-fill ph-check-circle" style="color:var(--juste)"></i>':"")+"</td>";}).join("")}</tr>`;
    });
    h+=`</table>`;
  }else if(x.type==="etiquettes"){
    h=`<div class="sc-paires">`+(x.cases||[]).map(function(c){
      return `<div><b>${c.lib}</b> <i class="ph ph-arrow-right"></i> ${c.r}</div>`;}).join("")+`</div>`;
  }else if(x.type==="ordre"){
    h=`<ol class="sc-ordre">`+(x.items||[]).map(function(it){return "<li>"+it+"</li>";}).join("")+`</ol>`;
  }else if(x.type==="calcul"){
    h=`<div class="sc-paires">`+(x.champs||[]).map(function(c){
      return `<div>${c.lib} <b>${c.r}${c.unite?" "+c.unite:""}</b></div>`;}).join("")+`</div>`;
  }else if(x.type==="lettres"){
    h=`<div class="sc-rep"><b>Réponse :</b> <span class="sc-mot">${x.mot}</span></div>`;
  }else if(x.type==="libre"){
    h=x.modele?`<div class="sc-rep"><b>Réponse attendue :</b> ${x.modele}</div>`:"";
  }
  if(x.expl)h+=`<div class="sc-expl"><i class="ph ph-lightbulb"></i> ${x.expl}</div>`;
  return h;
}
/* Énoncé d'un exercice, sans champ de saisie : on interroge la classe à l'oral. */
function seanceQuestionHTML(x){
  let h=`<div class="sc-q">${x.q||x.consigne||""}</div>`;
  if(x.type==="qcm"||x.type==="sondage"){
    h+=`<ol class="sc-opts">`+(x.opts||[]).map(function(o){return "<li>"+o+"</li>";}).join("")+`</ol>`;
  }else if(x.type==="grille"){
    h+=`<table class="sc-tab"><tr><th></th>${(x.cols||[]).map(function(c){return "<th>"+c+"</th>";}).join("")}</tr>`;
    (x.rows||[]).forEach(function(r){
      h+=`<tr><td>${r.t}</td>${(x.cols||[]).map(function(){return "<td></td>";}).join("")}</tr>`; });
    h+=`</table>`;
  }else if(x.type==="etiquettes"){
    h+=`<div class="sc-etiq">`+(x.mots||[]).map(function(m){return `<span>${m}</span>`;}).join("")+`</div>`;
    h+=`<div class="sc-paires">`+(x.cases||[]).map(function(c){
      return `<div><b>${c.lib}</b> <i class="ph ph-arrow-right"></i> <span class="sc-trou">?</span></div>`;}).join("")+`</div>`;
  }else if(x.type==="ordre"){
    /* Ordre mélangé : sinon l'énoncé donne la réponse. On retire jusqu'à obtenir
       un ordre RÉELLEMENT différent de l'original : un mélange peut retomber sur
       la solution, et l'exercice paraît alors déjà corrigé au tableau. */
    const base=(x.items||[]).slice();
    let l=base.slice();
    if(base.length>1){
      let essais=0;
      do{ for(let i=l.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); const t=l[i]; l[i]=l[j]; l[j]=t; } essais++; }
      while(essais<20&&l.every(function(v,i){return v===base[i];}));
    }
    h+=`<ul class="sc-ordre melange">`+l.map(function(it){return "<li>"+it+"</li>";}).join("")+`</ul>`;
  }else if(x.type==="calcul"){
    h+=`<div class="sc-paires">`+(x.champs||[]).map(function(c){
      return `<div>${c.lib} <span class="sc-trou">?</span>${c.unite?" "+c.unite:""}</div>`;}).join("")+`</div>`;
  }else if(x.type==="lettres"){
    h+=`<div class="sc-cases">`+String(x.mot||"").split("").map(function(){return `<span></span>`;}).join("")+`</div>`;
    if(x.aide)h+=`<div class="sc-aide"><i class="ph ph-lifebuoy"></i> ${x.aide}</div>`;
  }else if(x.type==="libre"&&x.aide){
    h+=`<div class="sc-aide"><i class="ph ph-lifebuoy"></i> ${x.aide}</div>`;
  }
  return h;
}

/* Découpe une leçon sur ses cartes : chacune porte déjà un titre et une idée. */
function seanceDepuisLecon(id){
  const lec=LECONS[id]; if(!lec)return null;
  const tmp=document.createElement("div"); tmp.innerHTML=lec.html;
  const cartes=tmp.querySelectorAll(".carte");
  const slides=[];
  if(!cartes.length){ slides.push({titre:lec.titre,html:lec.html}); }
  else cartes.forEach(function(c){
    const h3=c.querySelector("h3");
    const titre=h3?h3.textContent.trim():lec.titre;
    if(h3)h3.remove();
    slides.push({titre:titre,html:c.innerHTML});
  });
  return {titre:lec.titre,slides:slides,retour:function(){afficherLecon(id);}};
}
/* Découpe un cours interactif : le contenu d'une étape, puis ses exercices. */
function seanceDepuisCours(coursId){
  const d=COURS_DEF[coursId]; if(!d)return null;
  const av=ceCours; ceCours=coursId;                     /* pour ceDef().img */
  const slides=[];
  (d.etapes||[]).forEach(function(e,n){
    const html=String(e.html||"").replace(/__([A-Z0-9_]+)__/g,function(_,k){ return d.img[k.toLowerCase()]||""; });
    /* certaines étapes n'ont aucun contenu et ne portent que des exercices :
       leur créer un écran donnerait une page blanche au tableau */
    if(html.trim())slides.push({titre:(n+1)+". "+e.t,html:html});
    (e.ex||[]).forEach(function(x,k){
      slides.push({titre:(n+1)+". "+e.t+" · exercice "+(k+1),
                   html:seanceQuestionHTML(x), sol:seanceSolutionHTML(x)});
    });
  });
  ceCours=av;
  return {titre:d.titre,slides:slides,retour:function(){ecranCours(coursId);}};
}

function seanceLancerLecon(id){ seanceOuvrir(seanceDepuisLecon(id)); }
function seanceLancerCours(id){ seanceOuvrir(seanceDepuisCours(id)); }

function seanceOuvrir(src){
  if(!src||!src.slides||!src.slides.length){ toast("Rien à présenter ici."); return; }
  /* on reprend là où la dernière séance de ce cours s'était arrêtée */
  let dep=0; try{ dep=parseInt(localStorage.getItem("seanceDer_"+src.titre),10)||0; }catch(e){}
  if(dep<0||dep>=src.slides.length-1)dep=0;
  seance={src:src,i:dep,revele:false,t0:Date.now(),chrono:null};
  let b=document.getElementById("seanceEcran");
  if(b)b.remove();
  b=document.createElement("div");
  b.id="seanceEcran"; b.className="seance";
  b.innerHTML=`
    <div class="sc-tete">
      <div class="sc-titre" id="scTitre"></div>
      <div class="sc-outils">
        <span class="sc-horloge" id="scHorloge">0:00</span>
        <button class="sc-btn" onclick="seanceZoom(-1)" title="Réduire le texte"><i class="ph ph-minus"></i></button>
        <button class="sc-btn" onclick="seanceZoom(1)" title="Agrandir le texte"><i class="ph ph-plus"></i></button>
        <button class="sc-btn" onclick="seancePlein()" title="Plein écran"><i class="ph ph-arrows-out"></i></button>
        <button class="sc-btn" onclick="seanceQuitter()" title="Quitter la séance (Échap)"><i class="ph ph-x"></i></button>
      </div>
    </div>
    <div class="sc-corps" id="scCorps"></div>
    <div class="sc-pied">
      <button class="sc-nav" id="scPrec" onclick="seanceAller(-1)"><i class="ph ph-caret-left"></i> Précédent</button>
      <div class="sc-milieu">
        <button class="sc-reveler" id="scReveler" onclick="seanceReveler()"><i class="ph ph-eye"></i> Révéler la réponse</button>
        <div class="sc-compteur" id="scCompteur"></div>
      </div>
      <button class="sc-nav" id="scSuiv">Suivant <i class="ph ph-caret-right"></i></button>
    </div>
    <div class="sc-frise" id="scFrise" role="navigation" aria-label="Aller à une diapositive">${seanceFriseHTML(src)}</div>`;
  document.body.appendChild(b);
  document.body.classList.add("seance-ouverte");
  document.addEventListener("keydown",seanceTouche);
  seance.chrono=setInterval(seanceHorloge,1000);
  seanceRendre();
  if(dep)toast("Reprise à la diapositive "+(dep+1)+" sur "+src.slides.length+" : clique la frise en bas pour aller où tu veux.");
}
/* Frise de la séance : un segment par diapositive, regroupés par étape du cours
   (numéro en tête de chaque groupe) ; un clic va directement à la diapositive. */
function seanceFriseHTML(src){
  let prec=null;
  return src.slides.map(function(sl,k){
    const m=/^(\d+)\./.exec(String(sl.titre||"")), et=m?m[1]:"";
    const debut=et&&et!==prec; prec=et||prec;
    const lib=String(sl.titre||"").replace(/&nbsp;/g," ").replace(/<[^>]+>/g,"");
    return '<button type="button" class="sc-seg'+(debut&&k?" debut":"")+'" data-k="'+k+'" title="'+escapeHtml((k+1)+" · "+lib)+'" aria-label="'+escapeHtml("Diapositive "+(k+1)+" : "+lib)+'" onclick="seanceAllerA('+k+')">'
      +(debut?'<span class="sc-seg-n">'+et+'</span>':'')+'</button>';
  }).join("");
}
function seanceAllerA(k){
  if(!seance||k<0||k>=seance.src.slides.length)return;
  seance.i=k; seance.revele=false; seanceRendre();
}
function seanceQuitter(){
  if(!seance)return;
  const r=seance.src.retour;
  clearInterval(seance.chrono);
  document.removeEventListener("keydown",seanceTouche);
  const poseParSeance=seance.pleinPose;
  const b=document.getElementById("seanceEcran"); if(b)b.remove();
  document.body.classList.remove("seance-ouverte");
  seance=null;
  /* on ne sort du plein écran que si c'est la séance qui l'a demandé : un
     professeur qui projette toute sa session ne doit pas en être éjecté */
  try{ if(poseParSeance)sortirPleinEcran(); }catch(e){}
  if(typeof r==="function")r();
}
function seanceHorloge(){
  if(!seance)return;
  const s=Math.floor((Date.now()-seance.t0)/1000);
  const e=document.getElementById("scHorloge");
  if(e)e.textContent=Math.floor(s/60)+":"+("0"+(s%60)).slice(-2);
}
function seanceRendre(){
  if(!seance)return;
  const s=seance.src.slides[seance.i]; if(!s)return;
  /* les titres du cours contiennent des entités (&nbsp;) : innerHTML, pas textContent */
  document.getElementById("scTitre").innerHTML=s.titre||seance.src.titre;
  const c=document.getElementById("scCorps");
  c.innerHTML=`<div class="sc-page">${s.html||""}
    ${s.sol?`<div class="sc-sol" id="scSol" style="display:none">${s.sol}</div>`:""}</div>`;
  c.scrollTop=0;
  const rev=document.getElementById("scReveler");
  rev.style.visibility=s.sol?"visible":"hidden";
  rev.innerHTML=seance.revele?'<i class="ph ph-eye-slash"></i> Masquer'
                             :'<i class="ph ph-eye"></i> Révéler la réponse';
  if(s.sol&&seance.revele){ const el=document.getElementById("scSol"); if(el)el.style.display="block"; }
  document.getElementById("scCompteur").textContent=(seance.i+1)+" / "+seance.src.slides.length;
  document.getElementById("scPrec").disabled=(seance.i===0);
  /* dernière diapositive : « Suivant » devient « Terminer », qui ferme la séance */
  const suiv=document.getElementById("scSuiv"), der=(seance.i>=seance.src.slides.length-1);
  suiv.disabled=false; suiv.classList.toggle("fin",der);
  suiv.innerHTML=der?'<i class="ph-fill ph-flag-checkered"></i> Terminer':'Suivant <i class="ph ph-caret-right"></i>';
  suiv.onclick=der?function(){ seanceQuitter(); toast("Séance terminée. Bravo à tous !"); }:function(){ seanceAller(1); };
  document.querySelectorAll("#scFrise .sc-seg").forEach(function(b,k){
    b.classList.toggle("vu",k<seance.i); b.classList.toggle("ici",k===seance.i); b.setAttribute("aria-current",k===seance.i?"step":"false"); });
  try{ localStorage.setItem("seanceDer_"+seance.src.titre,seance.i); }catch(e){}
  try{ if(typeof ceMonterYT==="function")ceMonterYT(); }catch(e){}
}
function seanceAller(d){
  if(!seance)return;
  const n=seance.i+d;
  if(n<0||n>=seance.src.slides.length)return;
  seance.i=n; seance.revele=false;
  seanceRendre();
}
function seanceReveler(){
  if(!seance)return;
  const s=seance.src.slides[seance.i]; if(!s||!s.sol)return;
  seance.revele=!seance.revele;
  seanceRendre();
}
function seanceZoom(d){
  if(!seance)return;
  const b=document.getElementById("seanceEcran");
  const cur=parseFloat(b.dataset.zoom||"1");
  const z=Math.round(Math.max(.7,Math.min(1.8,cur+d*0.1))*10)/10;
  b.dataset.zoom=z; b.style.setProperty("--sc-zoom",z);
}
/* On met la PAGE en plein écran, jamais l'encart : un élément passé en plein
   écran devient la racine de l'affichage et le navigateur peint du noir derrière
   lui. L'application a déjà ses helpers, on les réutilise. */
function seancePlein(){
  try{
    if(estPleinEcran())sortirPleinEcran();
    else{ if(seance)seance.pleinPose=true; entrerPleinEcran(); }
  }catch(e){}
}
function seanceTouche(e){
  if(!seance)return;
  const k=e.key;
  if(k==="Escape"){ e.preventDefault(); seanceQuitter(); return; }
  if(k==="ArrowRight"||k==="PageDown"||k===" "){ e.preventDefault(); seanceAller(1); return; }
  if(k==="ArrowLeft"||k==="PageUp"){ e.preventDefault(); seanceAller(-1); return; }
  if(k==="r"||k==="R"){ e.preventDefault(); seanceReveler(); return; }
  if(k==="f"||k==="F"){ e.preventDefault(); seancePlein(); return; }
}
/* Bouton d'entrée, posé sur les leçons et les cours. Réservé à l'enseignant :
   il dévoile les réponses. */
function seanceBoutonHTML(quoi,id){
  if(typeof profConnecte!=="function"||!profConnecte())return "";
  const f=quoi==="cours"?`seanceLancerCours('${id}')`:`seanceLancerLecon('${id}')`;
  return `<button class="action btn-nouv seance-cta" onclick="${f}">
    <i class="ph ph-projector-screen-chart"></i> Faire la séance au tableau</button>`;
}

/* ============================================================
   L'APPLICATION VUE PAR L'ENSEIGNANT
   Un professeur connecté n'est pas un élève : il n'a ni points, ni badges, ni
   série de jours, ni défi quotidien. Tant que ces trois écrans (accueil, profil,
   classement) lui montraient la version élève, l'espace enseignant paraissait
   greffé à côté de l'application au lieu d'en faire partie.
   ============================================================ */
function profConnecte(){ const a=fbAuth(); return !!(a&&estProf(a.currentUser)); }

/* ---------- Attente d'une écriture serveur ----------
   Firestore ne résout sa promesse qu'après l'aller-retour réseau : sur une
   connexion d'établissement, cela peut prendre plusieurs secondes pendant
   lesquelles rien ne bougeait à l'écran. Le voile montre que ça travaille ET
   empêche de recliquer, ce qui créait des doublons. */
let _attN=0;
function attendre(msg){
  _attN++;
  let b=document.getElementById("attente");
  if(!b){
    b=document.createElement("div"); b.id="attente"; b.className="att-fond";
    b.innerHTML=`<div class="att-boite"><i class="ph ph-spinner-gap"></i><span id="attMsg"></span></div>`;
    document.body.appendChild(b);
  }
  const m=document.getElementById("attMsg"); if(m)m.textContent=msg||"Enregistrement…";
}
function attendreFin(){
  _attN=Math.max(0,_attN-1);
  if(_attN)return;
  const b=document.getElementById("attente"); if(b)b.remove();
}
/* Enrobe une promesse : voile pendant, retrait garanti après (succès ou échec). */
/* =====================================================================
   BOÎTES DE DIALOGUE AUX COULEURS DE LA CHARTE
   Remplacent confirm() / prompt() natifs du navigateur (gris, hors charte).
   dlgConfirmer(message,opts)       -> Promise<boolean>
   dlgSaisir(message,defaut,opts)   -> Promise<string|null>  (null = annulé)
   Le message garde l'écriture des anciens confirm() : 1re ligne = titre, le
   reste = corps, une ligne vide sépare deux paragraphes. Tout est posé en
   textContent : un nom d'élève ou de classe n'est jamais interprété en HTML.
   opts : {ok, annuler, danger (sinon deviné d'après le texte), type}
   Action destructrice : bouton rouge, et « Annuler » a le focus (Entrée annule).
   ===================================================================== */
function dlgOuvrir(message,opts,saisie,defaut){
  opts=opts||{};
  return new Promise(function(resolve){
    const txt=String(message==null?"":message);
    const lignes=txt.split("\n");
    const titre=(lignes.shift()||"").trim();
    const corps=lignes.join("\n").trim();
    const danger=(opts.danger!=null)?!!opts.danger
      :(!saisie&&/supprim|effac|définitiv|irréversible|remettre à zéro|réinitialis|clôtur/i.test(txt));
    const ov=document.createElement("div"); ov.className="dlg-voile";
    const boite=document.createElement("div"); boite.className="dlg"+(danger?" dlg-danger":"");
    boite.setAttribute("role","dialog"); boite.setAttribute("aria-modal","true");
    const ic=document.createElement("div"); ic.className="dlg-ic";
    ic.innerHTML='<i class="ph-fill '+(saisie?"ph-pencil-simple-line":(danger?"ph-warning":"ph-question"))+'"></i>';
    const h=document.createElement("h3"); h.className="dlg-titre"; h.textContent=titre;
    boite.appendChild(ic); boite.appendChild(h);
    if(corps){
      const c=document.createElement("div"); c.className="dlg-corps";
      corps.split(/\n\s*\n/).forEach(function(p){ const el=document.createElement("p"); el.textContent=p.trim(); c.appendChild(el); });
      boite.appendChild(c);
    }
    let champ=null;
    if(saisie){
      champ=document.createElement("input"); champ.className="dlg-champ"; champ.type=opts.type||"text";
      champ.value=(defaut==null?"":String(defaut)); boite.appendChild(champ);
    }
    const act=document.createElement("div"); act.className="dlg-actions";
    const non=document.createElement("button"); non.type="button"; non.className="action btn-nouv"; non.textContent=opts.annuler||"Annuler";
    const oui=document.createElement("button"); oui.type="button"; oui.className="action "+(danger?"btn-danger":"btn-corr");
    oui.textContent=opts.ok||(saisie?"Valider":(danger?"Oui, confirmer":"Confirmer"));
    act.appendChild(non); act.appendChild(oui); boite.appendChild(act); ov.appendChild(boite);
    const avant=document.activeElement;
    let fini=false;
    const clavier=function(e){
      if(e.key==="Escape"){ e.preventDefault(); e.stopPropagation(); fermer(saisie?null:false); return; }
      if(e.key==="Enter"&&(saisie?document.activeElement===champ:document.activeElement===oui)){
        e.preventDefault(); e.stopPropagation(); fermer(saisie?champ.value:true); return; }
      if(e.key==="Tab"){
        const f=[champ,non,oui].filter(Boolean), k=f.indexOf(document.activeElement);
        if(k<0){ e.preventDefault(); f[0].focus(); }
        else if(e.shiftKey&&k===0){ e.preventDefault(); f[f.length-1].focus(); }
        else if(!e.shiftKey&&k===f.length-1){ e.preventDefault(); f[0].focus(); }
        return;
      }
      e.stopPropagation();   /* rien ne passe aux raccourcis de la page tant que la boîte est ouverte */
    };
    const fermer=function(v){
      if(fini)return; fini=true;
      document.removeEventListener("keydown",clavier,true);
      ov.remove();
      try{ if(avant&&avant.focus)avant.focus(); }catch(e){}
      resolve(v);
    };
    non.onclick=function(){ fermer(saisie?null:false); };
    oui.onclick=function(){ fermer(saisie?champ.value:true); };
    ov.addEventListener("mousedown",function(e){ if(e.target===ov)fermer(saisie?null:false); });
    document.addEventListener("keydown",clavier,true);
    document.body.appendChild(ov);
    setTimeout(function(){ if(champ){ champ.focus(); champ.select(); } else (danger?non:oui).focus(); },30);
  });
}
function dlgConfirmer(message,opts){ return dlgOuvrir(message,opts,false); }
function dlgSaisir(message,defaut,opts){ return dlgOuvrir(message,opts,true,defaut); }

function pendant(msg,promesse){
  attendre(msg);
  return promesse.then(function(v){ attendreFin(); return v; },
                       function(e){ attendreFin(); throw e; });
}
/* Verrou par action : le voile empêche les clics de souris, mais il ne protège
   ni de la touche Entrée ni d'un double appel parti avant son affichage. La
   garde doit donc être dans le code, sinon on crée cinq fois la même leçon.
   Renvoie null si l'action est déjà en cours : l'appelant abandonne. */
const _occupe={};
function unSeul(cle,fabrique){
  if(_occupe[cle])return null;
  _occupe[cle]=true;
  let p;
  try{ p=fabrique(); }catch(e){ delete _occupe[cle]; throw e; }
  return p.then(function(v){ delete _occupe[cle]; return v; },
                function(e){ delete _occupe[cle]; throw e; });
}

/* Classes du professeur, mémorisées pour que les raccourcis aillent droit au but
   quand il n'y en a qu'une : c'est le cas le plus courant en cours d'année. */
let _profClasses=[];
/* ---------- Navigation enseignant ----------
   Une page par tâche (élèves, travail à donner, travaux rendus, évaluations,
   appréciations, classement), chacune avec le MÊME sélecteur de classe. Avant,
   il fallait ouvrir « Ma classe », choisir, puis naviguer dans des sous-pages :
   on s'y perdait, et trois boutons de l'accueil aboutissaient au même endroit.
   La classe choisie est mémorisée : on la sélectionne une fois pour toutes. */
let _classeProfSel=null;
function chargerClassesProf(){
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u)return Promise.resolve(_profClasses||[]);
  return s.collection("classes").where("ownerUid","==",u.uid).get().then(function(snap){
    const l=[]; snap.forEach(function(d){ l.push(Object.assign({id:d.id},d.data()||{})); });
    l.sort(function(x,y){ return String(x.nom||"").localeCompare(String(y.nom||""),"fr",{numeric:true}); });
    _profClasses=l;
    try{ invitesRecopier(l); }catch(e){}
    return l;
  }).catch(function(){ return _profClasses||[]; });
}
/* Les élèves invités avant la version du 24 sept. 2026 n'avaient pas l'invitation
   notée sur leur code : on la recopie, une seule fois par session. */
let _invitesRecopies=false;
function invitesRecopier(l){
  if(_invitesRecopies)return; _invitesRecopies=true;
  const s=fbStore(); if(!s||typeof firebase==="undefined")return;
  const FV=firebase.firestore.FieldValue;
  (l||[]).forEach(function(c){ (Array.isArray(c.membres)?c.membres:[]).forEach(function(code){
    s.collection("eleveCodes").doc(code).set({invite:FV.arrayUnion(c.id)},{merge:true}).catch(function(){});
  }); });
}
function classeProfCourante(l,demande){
  if(demande&&l.some(function(c){return c.id===demande;}))return demande;
  if(_classeProfSel&&l.some(function(c){return c.id===_classeProfSel;}))return _classeProfSel;
  return l.length?l[0].id:null;
}
/* Sélecteur posé en tête de chaque page. Masqué s'il n'y a qu'une classe :
   un menu à une seule entrée n'apporte rien. */
function selClasseHTML(fn,cid,liste){
  const l=liste||_profClasses||[];
  if(l.length<2)return "";
  let idx=0; for(let i=0;i<l.length;i++){ if(l[i].id===cid){idx=i;break;} }
  const prev=idx>0?l[idx-1].id:null, next=idx<l.length-1?l[idx+1].id:null;
  const fleche=function(id,ic,titre){ return `<button class="action btn-nouv" style="padding:8px 12px"${id?"":" disabled"} title="${titre}"${id?` onclick="${fn}('${id}')"`:""}><i class="ph ${ic}"></i></button>`; };
  return `<div style="margin-bottom:18px;display:flex;gap:8px;justify-content:center;align-items:center;flex-wrap:wrap">
    ${fleche(prev,"ph-caret-left","Classe précédente")}
    <label style="font-size:.88rem;color:var(--encre-doux)">Classe&nbsp;:
      <select onchange="${fn}(this.value)"
        style="margin-left:8px;padding:9px 12px;border:1px solid var(--ligne);border-radius:10px;
               font-family:inherit;font-size:1rem;background:var(--surface);color:var(--encre)">
        ${l.map(function(c){return `<option value="${c.id}"${c.id===cid?" selected":""}>${echapH(c.nom||"Classe")}</option>`;}).join("")}
      </select></label>
    ${fleche(next,"ph-caret-right","Classe suivante")}</div>`;
}
/* Ouvre une page enseignant sur la bonne classe, quel que soit le point d'entrée. */
function ouvrirProf(fn,classId){
  const z=document.getElementById("zone");
  if(z)z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  chargerClassesProf().then(function(l){
    const cid=classeProfCourante(l,classId);
    if(!cid){
      masquerInterfaceNormale(); majRetour(accueil,"Accueil");
      titreProf('<i class="ph ph-users-three"></i> Mes classes');
      document.getElementById("zone").innerHTML=`<div class="accueil" style="max-width:520px">
        <div class="ex" style="text-align:center">
          <h3 style="margin-top:0"><i class="ph ph-info"></i> Aucune classe</h3>
          <p>Créez d'abord une classe : c'est elle qui porte les codes de vos élèves.</p>
          <button class="rm-cta" onclick="dashboardProf()"><i class="ph-fill ph-plus"></i> Créer une classe</button>
        </div></div>`;
      return;
    }
    _classeProfSel=cid;
    try{ window[fn](cid); }catch(e){}
  });
}
/* Conservés pour les anciens points d'appel : ils passent par le même chemin. */
/* ================= Sauvegarde du professeur =================
   La donnée la plus fragile n'est PAS sur le serveur : ce sont les NOMS des
   élèves, qui ne vivent que dans le localStorage du prof (RGPD). Sans
   sauvegarde, vider le navigateur les efface pour toujours. On exporte donc
   ces noms + les préférences + une copie (sans audio) des classes, morceaux,
   leçons et notes. Rien ne part sur un serveur : c'est un fichier local. */
/* Sauvegarde manquante (jamais faite) ou vieille de 14 jours et plus : pastille
   sur la rubrique « Sauvegarde » des Paramètres (plus de bandeau sur l'accueil). */
function sauvegardeEnRetard(){
  const d=profil&&profil.derniereSauvegarde;
  return !d||Math.floor((Date.now()-d)/86400000)>=14;
}
function sauvegardeInfoHTML(){
  const d=profil&&profil.derniereSauvegarde;
  return d ? 'Dernière sauvegarde : <b>'+new Date(d).toLocaleString("fr-FR")+'</b>.'
           : '<b style="color:var(--faux)"><i class="ph-fill ph-warning-circle"></i> Vous n\'avez jamais fait de sauvegarde.</b> '
             +'Les noms de vos élèves ne sont enregistrés que sur cet appareil : pensez-y.';
}
function sauvegardeCollecter(){
  const local={};
  try{ [LABELS_KEY,STORE_KEY,CONTACTS_KEY,ROSTER_KEY,"theme"].forEach(function(k){ const v=localStorage.getItem(k); if(v!=null)local[k]=v; }); }catch(e){}
  const base={ app:"MUSEDUC", type:"sauvegarde", version:1, cree:Date.now(),
               dateLisible:new Date().toLocaleString("fr-FR"), local:local, serveur:null };
  const s=fbStore(), a=fbAuth(), u=a&&a.currentUser;
  if(!s||!u||!estProf(u))return Promise.resolve(base);   /* au minimum, les données locales */
  const uid=u.uid;
  const dump=function(ref){ return ref.get().then(function(sn){ const o=[]; sn.forEach(function(d){o.push(Object.assign({id:d.id},d.data()||{}));}); return o; }).catch(function(){ return []; }); };
  const T=s.collection("teachers").doc(uid);
  return Promise.all([
    dump(T.collection("chants")), dump(T.collection("lecons")), dump(T.collection("questions")),
    s.collection("classes").where("ownerUid","==",uid).get().catch(function(){ return {forEach:function(){}}; })
  ]).then(function(r){
    const cls=[]; r[3].forEach(function(d){ cls.push(Object.assign({id:d.id},d.data()||{})); });
    return Promise.all(cls.map(function(k){
      const C=s.collection("classes").doc(k.id);
      return Promise.all([ dump(C.collection("eleves")), dump(C.collection("evals")),
                           dump(C.collection("devoirs")), dump(C.collection("enr")) ])
        .then(function(sub){ return { classe:k, eleves:sub[0], evals:sub[1], devoirs:sub[2], enr:sub[3] }; });
    })).then(function(classes){
      base.serveur={ chants:r[0], lecons:r[1], questions:r[2], classes:classes };  /* jamais l'audio */
      return base;
    });
  }).catch(function(){ return base; });
}
function sauvegardeTelecharger(obj){
  const blob=new Blob([JSON.stringify(obj,null,2)],{type:"application/json"});
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url; a.download="museduc-sauvegarde-"+new Date().toISOString().slice(0,10)+".json";
  document.body.appendChild(a); a.click();
  setTimeout(function(){ try{URL.revokeObjectURL(url);}catch(e){} a.remove(); },1500);
}
function sauvegardeExporter(){
  const btn=document.getElementById("sauvExportBtn"); if(btn)btn.disabled=true;
  const p=unSeul("sauvExport",function(){ return sauvegardeCollecter(); });
  if(!p){ if(btn)btn.disabled=false; return; }
  toast("Préparation de la sauvegarde…");
  p.then(function(obj){
    sauvegardeTelecharger(obj);
    try{ profil.derniereSauvegarde=Date.now(); sauverProfil(profil); }catch(e){}
    const z=document.getElementById("sauvInfo"); if(z)z.innerHTML=sauvegardeInfoHTML();
    const pa=document.querySelector(".pm-nav-it.on .pm-nav-alerte"); if(pa&&!sauvegardeEnRetard())pa.remove();
    toast("Sauvegarde téléchargée.");
  }).catch(function(){ toast("La sauvegarde a échoué."); })
   .then(function(){ if(btn)btn.disabled=false; });
}
function sauvegardeChoisirFichier(){ const i=document.getElementById("sauvFichier"); if(i)i.click(); }
function sauvegardeImporter(input){
  const f=input&&input.files&&input.files[0];
  if(input)input.value="";
  if(!f)return;
  const r=new FileReader();
  r.onload=function(){
    let data; try{ data=JSON.parse(r.result); }catch(e){ toast("Fichier illisible : ce n'est pas une sauvegarde MusEduc."); return; }
    if(!data||data.app!=="MUSEDUC"||!data.local){ toast("Ce fichier n'est pas une sauvegarde MusEduc."); return; }
    sauvegardeConfirmerRestauration(data);
  };
  r.onerror=function(){ toast("Lecture du fichier impossible."); };
  r.readAsText(f);
}
function sauvegardeCompterNoms(data){
  let n=0;
  try{ const l=JSON.parse((data.local&&data.local[LABELS_KEY])||"{}");
       Object.keys(l).forEach(function(c){ n+=Object.keys(l[c]||{}).length; }); }catch(e){}
  return n;
}
function sauvegardeAppliquerLocal(data){
  const loc=data.local||{};
  /* Noms d'élèves : FUSION. On ne remplace jamais un nom déjà saisi ; on ne
     fait que compléter les manquants. Restaurer ne peut donc rien détruire. */
  try{
    const imp=JSON.parse(loc[LABELS_KEY]||"{}");
    const cur=lireLabels();
    Object.keys(imp).forEach(function(cid){
      cur[cid]=cur[cid]||{};
      Object.keys(imp[cid]||{}).forEach(function(code){
        if(!cur[cid][code] && imp[cid][code]) cur[cid][code]=imp[cid][code];
      });
    });
    ecrireLabels(cur);
  }catch(e){}
  try{
    const impC=JSON.parse(loc[CONTACTS_KEY]||"{}"); const curC=lireContacts();
    Object.keys(impC).forEach(function(cid){ curC[cid]=curC[cid]||{};
      Object.keys(impC[cid]||{}).forEach(function(code){ curC[cid][code]=curC[cid][code]||[];
        const ids={}; curC[cid][code].forEach(function(x){ if(x&&x.id)ids[x.id]=1; });
        (impC[cid][code]||[]).forEach(function(x){ if(x&&x.id&&!ids[x.id])curC[cid][code].push(x); });
      });
    });
    ecrireContacts(curC);
  }catch(e){}
  try{ if(loc[ROSTER_KEY]){ const impR=JSON.parse(loc[ROSTER_KEY]); const cur=rosterLire(); const codes=cur.codes||{}; const imp=(impR&&impR.codes)||{};
    Object.keys(imp).forEach(function(c){ if(!codes[c])codes[c]=imp[c]; });
    ecrireRoster(codes, cur.meta&&cur.meta.quand?cur.meta:{n:Object.keys(codes).length,quand:Date.now()}); } }catch(e){}
  try{ if(loc.theme){ localStorage.setItem("theme",loc.theme); if(typeof appliquerTheme==="function")appliquerTheme(loc.theme); } }catch(e){}
}
async function sauvegardeConfirmerRestauration(data){
  const n=sauvegardeCompterNoms(data);
  const quand=data.dateLisible||(data.cree?new Date(data.cree).toLocaleString("fr-FR"):"?");
  if(!await dlgConfirmer("Restaurer cette sauvegarde ?\n\n"
    +"Fichier du "+quand+"\n"
    +"Noms d'élèves dans le fichier : "+n+"\n\n"
    +"Vos noms actuels seront COMPLÉTÉS (aucun nom existant ne sera écrasé), "
    +"et vos préférences restaurées. Vos classes et notes restent, elles, "
    +"conservées en ligne."))return;
  sauvegardeAppliquerLocal(data);
  try{ if(typeof majEnteteProfil==="function")majEnteteProfil(); }catch(e){}
  toast("Sauvegarde restaurée : "+n+" nom(s) d'élève.");
}
function sauvegardeCarteHTML(){
  return '<div class="pm-panneau">'
    +'<div class="pm-p-tete"><div class="pm-p-ic"><i class="ph ph-floppy-disk"></i></div><h2>Sauvegarde</h2></div>'
    +'<p class="pm-p-aide">Les noms de vos élèves ne vivent que sur cet appareil : un fichier de sauvegarde, et vous ne perdez plus rien.</p>'
    +'<div class="sauv-bloc"><h3><i class="ph ph-download-simple"></i> Exporter mes données</h3>'
    +'<p>Téléchargez un fichier de sauvegarde. Il contient <b>les noms de vos élèves</b> (qui ne quittent jamais cet appareil), vos préférences, et une copie de vos classes, morceaux, leçons et notes.</p>'
    +'<p id="sauvInfo" style="font-size:.88rem;color:var(--encre-doux)">'+sauvegardeInfoHTML()+'</p>'
    +'<button class="rm-cta" id="sauvExportBtn" onclick="sauvegardeExporter()"><i class="ph-fill ph-download-simple"></i> Télécharger ma sauvegarde</button></div>'
    +'<div class="sauv-bloc"><h3><i class="ph ph-upload-simple"></i> Restaurer</h3>'
    +'<p>Vous changez d\'ordinateur, ou vous avez perdu les noms de vos élèves&nbsp;? Rechargez votre fichier&nbsp;: les noms et vos préférences reviennent. Vos classes et vos notes, elles, sont déjà conservées en ligne.</p>'
    +'<input type="file" id="sauvFichier" accept="application/json,.json" style="display:none" onchange="sauvegardeImporter(this)">'
    +'<button class="action btn-nouv" onclick="sauvegardeChoisirFichier()"><i class="ph ph-upload-simple"></i> Choisir un fichier de sauvegarde</button></div>'
    +'<p style="color:var(--encre-doux);font-size:.86rem;margin:4px 0 0"><i class="ph ph-identification-card"></i> Pour <b>importer les noms de vos élèves</b> (liste CSV) ou les saisir, allez dans <b>Élèves et codes</b>. Cette rubrique sauvegarde tout d\'un coup (noms compris).</p>'
    +'</div>';
}

/* ================= Outil de vote de classe =================
   Le vote vit dans Firestore (classes/{cid}/votes/{vid}), les réponses dans
   .../reponses/{codeEleve}. « Direct » = le prof projette et sonde les réponses
   toutes les 3 s (barres qui montent) ; « asynchrone » = le vote reste ouvert,
   les élèves votent quand ils veulent. Images : vignette réduite (data-URI)
   dans l'option, jamais dans Storage (payant). RGPD : seul le code de l'élève. */
let _voteClasse=null, _voteId=null, _votePoll=null, _voteBrouillon=null;
let _voteVote=null, _voteReveler=false, _voteMon=null, _voteReps=[];
function voteArreterPoll(){ if(_votePoll){ clearInterval(_votePoll); _votePoll=null; } }
function voteColRef(cid){ const s=fbStore(); return s?s.collection("classes").doc(cid).collection("votes"):null; }
function voteNewId(){ return "o"+Math.random().toString(36).slice(2,8); }
function voteImageReduire(file){
  return new Promise(function(res,rej){
    if(!file||String(file.type||"").indexOf("image/")!==0){ rej("type"); return; }
    const fr=new FileReader();
    fr.onload=function(){
      const img=new Image();
      img.onload=function(){
        let w=img.width,h=img.height; const max=480;
        if(w>=h && w>max){ h=Math.round(h*max/w); w=max; }
        else if(h>w && h>max){ w=Math.round(w*max/h); h=max; }
        try{ const c=document.createElement("canvas"); c.width=w;c.height=h;
          c.getContext("2d").drawImage(img,0,0,w,h);
          res(c.toDataURL("image/jpeg",0.72)); }catch(e){ rej(e); }
      };
      img.onerror=function(){ rej("img"); }; img.src=fr.result;
    };
    fr.onerror=function(){ rej("read"); }; fr.readAsDataURL(file);
  });
}

/* ---------- Professeur : liste des votes ---------- */
function ecranVotesProf(classId){
  voteArreterPoll();
  if(classId)_classeProfSel=classId;
  const cid=_classeProfSel;
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  titreProf('<i class="ph ph-chart-bar"></i> Votes de la classe',
    "Lancez un vote (une chanson, une pochette, un projet…). Les élèves votent, les résultats montent en direct.");
  const z=document.getElementById("zone");
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser;
  if(!s||!u||!estProf(u)||!cid){ z.innerHTML=svcIndispo("Cet espace est réservé aux professeurs connectés."); remonter(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  voteColRef(cid).get().then(function(snap){
    const l=[]; snap.forEach(function(d){ l.push(Object.assign({id:d.id},d.data()||{})); });
    l.sort(function(x,y){ return (y.cree||0)-(x.cree||0); });
    let h='<div class="accueil" style="max-width:760px">'
      +selClasseHTML("ecranVotesProf",cid)
      +'<div style="text-align:center;margin-bottom:16px"><button class="rm-cta" onclick="voteEditer(\''+cid+'\',\'\')"><i class="ph-fill ph-plus"></i> Nouveau vote</button></div>';
    if(!l.length){
      h+='<div class="ex" style="text-align:center"><h3 style="margin-top:0"><i class="ph ph-lightbulb"></i> À quoi ça sert&nbsp;?</h3>'
        +'<p>Posez une question à la classe et proposez des choix (texte et/ou image). Les élèves votent depuis leur appareil, et vous projetez les résultats qui montent en direct. Parfait pour choisir une chanson, une pochette de carnet, un projet…</p></div>';
    }
    l.forEach(function(v){
      const nbOpt=(v.options||[]).length;
      h+='<div class="vt-carte"><div class="vt-haut"><div style="flex:1;min-width:0">'
        +'<div class="vt-titre">'+echapH(v.titre||v.question||"Vote")+'</div>'
        +(v.question&&v.titre?'<div class="vt-q">'+echapH(v.question)+'</div>':'')
        +'<div class="vt-meta">'+nbOpt+' choix · <span class="'+(v.ouvert?'vt-ouvert':'vt-ferme')+'">'+(v.ouvert?'ouvert':'fermé')+'</span></div>'
        +'</div></div><div class="vt-actions">'
        +'<button class="vt-go" onclick="voteProjeter(\''+cid+'\',\''+v.id+'\')"><i class="ph ph-presentation-chart"></i> Projeter</button>'
        +'<button class="vt-btn" onclick="voteBasculer(\''+cid+'\',\''+v.id+'\','+(v.ouvert?'false':'true')+')">'+(v.ouvert?'<i class="ph ph-lock"></i> Fermer':'<i class="ph ph-lock-open"></i> Ouvrir')+'</button>'
        +'<button class="vt-btn" onclick="voteQuiTout(\''+cid+'\',\''+v.id+'\')"><i class="ph ph-users-three"></i> Qui a voté quoi</button>'
        +'<button class="vt-btn" onclick="voteEditer(\''+cid+'\',\''+v.id+'\')"><i class="ph ph-pencil-simple"></i> Modifier</button>'
        +'<button class="vt-sup" title="Supprimer" onclick="voteSupprimer(\''+cid+'\',\''+v.id+'\')"><i class="ph ph-trash"></i></button>'
        +'</div></div>';
    });
    h+='</div>'; z.innerHTML=h; remonter();
  }).catch(function(e){
    const c=String((e&&e.code)||(e&&e.message)||"");
    z.innerHTML=(c.indexOf("permission-denied")>=0 && typeof chRegles==="function")?chRegles():svcIndispo("Impossible de charger les votes.");
    remonter();
  });
}
/* Clôture : on calcule le décompte agrégé et on l'écrit SUR le vote
   (resultats + total). Les élèves lisent le vote (déjà autorisé) et voient donc
   les résultats, sans jamais accéder aux réponses individuelles. */
function voteCalculerEtFermer(cid,vid){
  return voteColRef(cid).doc(vid).collection("reponses").get().then(function(sn){
    const res={}; let total=0;
    sn.forEach(function(d){ const o=(d.data()||{}).opt; if(o){ res[o]=(res[o]||0)+1; total++; } });
    return voteColRef(cid).doc(vid).update({ouvert:false, resultats:res, total:total});
  });
}
function voteBasculer(cid,vid,ouvrir){
  const r=voteColRef(cid); if(!r)return;
  const act = ouvrir ? r.doc(vid).update({ouvert:true}) : voteCalculerEtFermer(cid,vid);
  pendant(ouvrir?"Ouverture…":"Clôture…", act)
    .then(function(){ toast(ouvrir?"Vote ouvert.":"Vote clos : les résultats sont visibles par les élèves."); ecranVotesProf(cid); })
    .catch(function(){ toast("Action impossible."); });
}
async function voteSupprimer(cid,vid){
  if(!await dlgConfirmer("Supprimer ce vote et toutes ses réponses ?\n\nCette action est définitive."))return;
  const ref=voteColRef(cid).doc(vid);
  const p=unSeul("voteSup",function(){
    return pendant("Suppression…", ref.collection("reponses").get().then(function(sn){
      return Promise.all(sn.docs.map(function(d){ return d.ref.delete().catch(function(){}); }));
    }).then(function(){ return ref.delete(); }));
  });
  if(!p)return;
  p.then(function(){ toast("Vote supprimé."); ecranVotesProf(cid); }).catch(function(){ toast("La suppression a échoué."); });
}

/* ---------- Professeur : éditeur ---------- */
function voteEditer(cid,vid){
  voteArreterPoll();
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(function(){ ecranVotesProf(cid); },"Votes");
  titreProf('<i class="ph ph-pencil-line"></i> '+(vid?"Modifier le vote":"Nouveau vote"),
    "Une question, deux choix ou plus (texte et/ou image).");
  const z=document.getElementById("zone");
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser;
  if(!s||!u||!estProf(u)){ z.innerHTML=svcIndispo(); return; }
  const rendre=function(){
    z.innerHTML='<div class="accueil" style="max-width:640px"><div class="ex">'
      +'<label class="vt-l">Titre <span style="font-weight:400;color:var(--encre-doux)">(facultatif)</span>'
      +'<input id="voteTitre" class="vt-in" maxlength="80" value="'+echapH(_voteBrouillon.titre||"")+'" placeholder="Ex. La chanson du spectacle"></label>'
      +'<label class="vt-l" style="margin-top:12px">Question posée à la classe'
      +'<input id="voteQ" class="vt-in" maxlength="160" value="'+echapH(_voteBrouillon.question||"")+'" placeholder="Ex. Quelle chanson chante-t-on&nbsp;?"></label>'
      +'<div class="vt-l" style="margin-top:16px">Les choix</div>'
      +'<div id="voteOpts"></div>'
      +'<div style="text-align:center;margin:12px 0"><button class="action btn-nouv" onclick="voteAjouterOption()"><i class="ph ph-plus"></i> Ajouter un choix</button></div>'
      +'<label class="vt-coche"><input type="checkbox" id="voteOuvert"'+(_voteBrouillon.ouvert?' checked':'')+'> Ouvrir le vote tout de suite (les élèves pourront voter)</label>'
      +'<div id="voteErr" style="color:var(--faux);font-size:.85rem;margin-top:8px;display:none"></div>'
      +'<div style="text-align:center;margin-top:16px"><button class="rm-cta" onclick="voteEnregistrer(\''+cid+'\',\''+(vid||"")+'\')"><i class="ph-fill ph-floppy-disk"></i> Enregistrer le vote</button></div>'
      +'</div></div>';
    voteOptRender(); remonter();
  };
  if(vid){
    z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
    voteColRef(cid).doc(vid).get().then(function(d){
      const v=d.data()||{};
      _voteBrouillon={titre:v.titre||"",question:v.question||"",ouvert:!!v.ouvert,
        options:(v.options||[]).map(function(o){ return {id:o.id||voteNewId(),texte:o.texte||"",img:o.img||null}; })};
      while(_voteBrouillon.options.length<2)_voteBrouillon.options.push({id:voteNewId(),texte:"",img:null});
      rendre();
    }).catch(function(){ toast("Impossible de charger ce vote."); ecranVotesProf(cid); });
  }else{
    _voteBrouillon={titre:"",question:"",ouvert:true,options:[{id:voteNewId(),texte:"",img:null},{id:voteNewId(),texte:"",img:null}]};
    rendre();
  }
}
function voteOptRender(){
  const z=document.getElementById("voteOpts"); if(!z||!_voteBrouillon)return;
  z.innerHTML=_voteBrouillon.options.map(function(o,i){
    return '<div class="vt-opt">'
      +'<div class="vt-opt-img'+(o.img?' a':'')+'" onclick="voteImageChoisir(\''+o.id+'\')" title="Ajouter ou changer l\'image">'
        +(o.img?'<img src="'+o.img+'" alt="">':'<i class="ph ph-image"></i>')+'</div>'
      +'<input class="vt-in" id="voteOptTxt-'+o.id+'" maxlength="80" value="'+echapH(o.texte||"")+'" placeholder="Choix '+(i+1)+'">'
      +(_voteBrouillon.options.length>2?'<button class="vt-opt-x" onclick="voteRetirerOption(\''+o.id+'\')" title="Retirer ce choix"><i class="ph ph-x"></i></button>':'<span style="width:34px;flex:none"></span>')
      +'<input type="file" accept="image/*" id="voteFile-'+o.id+'" style="display:none" onchange="voteImageMaj(\''+o.id+'\',this)">'
      +'</div>';
  }).join("");
}
function voteOptSync(){
  if(!_voteBrouillon)return;
  _voteBrouillon.options.forEach(function(o){ const el=document.getElementById("voteOptTxt-"+o.id); if(el)o.texte=el.value; });
  const t=document.getElementById("voteTitre"), q=document.getElementById("voteQ"), ou=document.getElementById("voteOuvert");
  if(t)_voteBrouillon.titre=t.value; if(q)_voteBrouillon.question=q.value; if(ou)_voteBrouillon.ouvert=ou.checked;
}
function voteAjouterOption(){ voteOptSync(); if(_voteBrouillon.options.length>=8){ toast("8 choix au maximum."); return; } _voteBrouillon.options.push({id:voteNewId(),texte:"",img:null}); voteOptRender(); }
function voteRetirerOption(id){ voteOptSync(); _voteBrouillon.options=_voteBrouillon.options.filter(function(o){ return o.id!==id; }); voteOptRender(); }
function voteImageChoisir(id){ const f=document.getElementById("voteFile-"+id); if(f)f.click(); }
function voteImageMaj(id,input){
  const f=input&&input.files&&input.files[0]; if(input)input.value="";
  if(!f)return;
  voteImageReduire(f).then(function(data){
    if(data.length>200000){ toast("Cette image reste trop lourde. Essayez-en une autre."); return; }
    voteOptSync();
    const o=_voteBrouillon.options.filter(function(x){ return x.id===id; })[0]; if(o)o.img=data;
    voteOptRender();
  }).catch(function(){ toast("Cette image n'a pas pu être ajoutée."); });
}
function voteEnregistrer(cid,vid){
  voteOptSync();
  const err=document.getElementById("voteErr");
  const dire=function(m){ if(err){ err.textContent=m; err.style.display="block"; } else toast(m); };
  const question=(_voteBrouillon.question||"").trim();
  if(!question){ dire("Écrivez la question posée à la classe."); return; }
  const opts=_voteBrouillon.options.map(function(o){ return {id:o.id,texte:(o.texte||"").trim(),img:o.img||null}; })
    .filter(function(o){ return o.texte || o.img; });
  if(opts.length<2){ dire("Il faut au moins deux choix (un texte ou une image par choix)."); return; }
  let taille=0; opts.forEach(function(o){ if(o.img)taille+=o.img.length; });
  if(taille>850000){ dire("Les images sont trop lourdes au total. Retirez-en ou prenez des images plus petites."); return; }
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser; if(!s||!u){ dire("Service indisponible."); return; }
  const doc={titre:(_voteBrouillon.titre||"").trim(), question:question,
    options:opts.map(function(o){ const x={id:o.id,texte:o.texte}; if(o.img)x.img=o.img; return x; }),
    ouvert:!!_voteBrouillon.ouvert, ownerUid:u.uid, maj:Date.now()};
  const col=voteColRef(cid); const ref=vid?col.doc(vid):col.doc();
  if(!vid)doc.cree=Date.now();
  const p=unSeul("voteSave",function(){ return pendant("Enregistrement…", ref.set(doc,{merge:!!vid})); });
  if(!p)return;
  p.then(function(){ toast("Vote enregistré."); ecranVotesProf(cid); }).catch(function(){ dire("Le vote n'a pas pu être enregistré."); });
}

/* ---------- Professeur : projection en direct ---------- */
function voteProjeter(cid,vid){
  voteArreterPoll(); _voteClasse=cid; _voteId=vid; _voteReveler=false;
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(function(){ ecranVotesProf(cid); },"Votes");
  titreProf('<i class="ph ph-presentation-chart"></i> Vote en direct',"");
  const z=document.getElementById("zone"); const s=fbStore();
  if(!s){ z.innerHTML=svcIndispo(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  voteColRef(cid).doc(vid).get().then(function(d){
    if(!d.exists){ toast("Vote introuvable."); ecranVotesProf(cid); return; }
    _voteVote=Object.assign({id:vid},d.data()||{});
    voteRendreBoard(); voteRafraichir();
    _votePoll=setInterval(voteRafraichir,3000);
  }).catch(function(){ toast("Impossible d'ouvrir le vote."); ecranVotesProf(cid); });
}
function voteRendreBoard(){
  const z=document.getElementById("zone"); const v=_voteVote; if(!z||!v)return;
  z.innerHTML='<div class="accueil vt-board" style="max-width:900px">'
    +'<div class="vt-board-q">'+echapH(v.question||v.titre||"Vote")+'</div>'
    +'<div id="voteBarres" class="vt-barres"></div>'
    +'<p class="vt-astuce"><i class="ph ph-hand-pointing"></i> Cliquez sur une réponse pour voir qui l\'a choisie (noms masqués tant que vous ne les affichez pas).</p>'
    +'<div class="vt-board-pied"><span id="voteTotal" class="vt-total">0 vote</span>'
    +'<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center">'
    +'<button class="vt-btn" onclick="voteToggleReveler()"><i class="ph ph-trophy"></i> <span id="voteRevLbl">Révéler le gagnant</span></button>'
    +'<button class="vt-btn" onclick="voteBasculerProjete()"><i class="ph ph-lock"></i> <span id="voteOuvLbl">'+(v.ouvert?"Fermer le vote":"Rouvrir le vote")+'</span></button>'
    +'<button class="action btn-nouv" onclick="ecranVotesProf(\''+_voteClasse+'\')"><i class="ph ph-x"></i> Quitter</button>'
    +'</div></div></div>';
  voteRendreBarres({},0);
}
function voteRafraichir(){
  if(!_voteVote||!_voteClasse)return;
  voteColRef(_voteClasse).doc(_voteVote.id).collection("reponses").get().then(function(sn){
    const compte={}; let total=0; _voteReps=[];
    sn.forEach(function(d){ const o=(d.data()||{}).opt; if(o){ compte[o]=(compte[o]||0)+1; total++; _voteReps.push({code:d.id,opt:o}); } });
    voteRendreBarres(compte,total);
  }).catch(function(){});
}
function voteRendreBarres(compte,total){
  const z=document.getElementById("voteBarres"); const v=_voteVote; if(!z||!v)return;
  let maxN=0; (v.options||[]).forEach(function(o){ const n=compte[o.id]||0; if(n>maxN)maxN=n; });
  z.innerHTML=(v.options||[]).map(function(o){
    const n=compte[o.id]||0; const pct=total?Math.round(n/total*100):0;
    const gagne=_voteReveler && n>0 && n===maxN;
    return '<div class="vt-barre vt-clic'+(gagne?' gagne':'')+'" role="button" tabindex="0" title="Voir qui a choisi cette réponse" onclick="voteQui(\''+o.id+'\')" onkeydown="if(event.key===\'Enter\')voteQui(\''+o.id+'\')">'
      +'<div class="vt-barre-tete">'
        +(o.img?'<img class="vt-barre-img" src="'+o.img+'" alt="">':'')
        +'<span class="vt-barre-lbl">'+echapH(o.texte||"")+'</span>'
        +'<span class="vt-barre-n">'+n+(_voteReveler?' · '+pct+'%':'')+'</span></div>'
      +'<div class="vt-barre-piste"><div class="vt-barre-plein" style="width:'+pct+'%"></div></div></div>';
  }).join("");
  const t=document.getElementById("voteTotal"); if(t)t.textContent=total+" vote"+(total>1?"s":"");
}
/* Qui a choisi quoi : seul le professeur ouvre cette fenêtre. Le serveur ne garde
   que les codes ; les noms viennent de la liste du professeur, sur son appareil.
   Noms floutés au départ : l'écran est souvent projeté devant la classe. */
function voteQuiHTML(v,reps,cid,optId){
  const opts=(v.options||[]).filter(function(o){ return !optId||o.id===optId; });
  const nom=function(code){ const l=labelDe(cid,code); return l?l:code; };
  const blocs=opts.map(function(o){
    const l=reps.filter(function(r){ return r.opt===o.id; }).map(function(r){ return nom(r.code); })
      .sort(function(a,b){ return a.localeCompare(b,"fr"); });
    return '<div class="vt-qui-opt"><div class="vt-qui-tete">'+(o.img?'<img src="'+o.img+'" alt="">':'')
      +'<b>'+echapH(o.texte||"(image)")+'</b><span>'+l.length+' élève'+(l.length>1?"s":"")+'</span></div>'
      +(l.length?'<ul class="vt-qui-noms">'+l.map(function(n){ return '<li>'+echapH(n)+'</li>'; }).join("")+'</ul>':'<p class="vt-qui-vide">Personne</p>')+'</div>';
  }).join("");
  return '<div class="vt-qui-boite" role="dialog" aria-modal="true" aria-label="Qui a voté quoi">'
    +'<div class="vt-qui-haut"><h3><i class="ph ph-users-three"></i> '+(optId?'Qui a choisi cette réponse':'Qui a voté quoi')+'</h3>'
    +'<button class="vt-qui-x" onclick="voteQuiFermer()" aria-label="Fermer"><i class="ph ph-x"></i></button></div>'
    +'<p class="vt-qui-prive"><i class="ph ph-eye-slash"></i> Visible par vous seul : les élèves ne voient jamais qui a voté quoi.</p>'
    +'<div class="vt-qui-corps masque" id="voteQuiCorps">'+blocs+'</div>'
    +'<div class="vt-qui-pied"><button class="vt-go" id="voteQuiVoir" onclick="voteQuiAfficher()"><i class="ph ph-eye"></i> Afficher les noms</button></div></div>';
}
function voteQuiOuvrir(html){
  voteQuiFermer();
  const f=document.createElement("div"); f.className="vt-qui-fond"; f.id="voteQuiFond";
  f.onclick=function(e){ if(e.target===f)voteQuiFermer(); };
  f.innerHTML=html; document.body.appendChild(f);
}
function voteQuiFermer(){ const f=document.getElementById("voteQuiFond"); if(f)f.remove(); }
function voteQuiAfficher(){
  const c=document.getElementById("voteQuiCorps"), b=document.getElementById("voteQuiVoir"); if(!c)return;
  const masque=!c.classList.toggle("masque");
  if(b)b.innerHTML=masque?'<i class="ph ph-eye-slash"></i> Masquer les noms':'<i class="ph ph-eye"></i> Afficher les noms';
}
function voteQui(optId){
  if(!_voteVote||!_voteClasse)return;
  voteQuiOuvrir(voteQuiHTML(_voteVote,_voteReps,_voteClasse,optId));
}
function voteQuiTout(cid,vid){
  const r=voteColRef(cid); if(!r)return;
  pendant("Chargement…", Promise.all([r.doc(vid).get(), r.doc(vid).collection("reponses").get()])).then(function(x){
    const v=x[0].data()||{}, reps=[];
    x[1].forEach(function(d){ const o=(d.data()||{}).opt; if(o)reps.push({code:d.id,opt:o}); });
    voteQuiOuvrir(voteQuiHTML(v,reps,cid,null));
  }).catch(function(){ toast("Impossible de lire les réponses."); });
}
document.addEventListener("keydown",function(e){ if(e.key==="Escape"&&document.getElementById("voteQuiFond"))voteQuiFermer(); });
function voteToggleReveler(){ _voteReveler=!_voteReveler; const l=document.getElementById("voteRevLbl"); if(l)l.textContent=_voteReveler?"Masquer le résultat":"Révéler le gagnant"; voteRafraichir(); }
function voteBasculerProjete(){
  if(!_voteVote)return; const nv=!_voteVote.ouvert;
  const act = nv ? voteColRef(_voteClasse).doc(_voteVote.id).update({ouvert:true}) : voteCalculerEtFermer(_voteClasse,_voteVote.id);
  act.then(function(){
    _voteVote.ouvert=nv; const l=document.getElementById("voteOuvLbl"); if(l)l.textContent=nv?"Fermer le vote":"Rouvrir le vote";
    toast(nv?"Vote ouvert.":"Vote clos : résultats visibles par les élèves.");
  }).catch(function(){ toast("Action impossible."); });
}

/* ---------- Élève : voter ---------- */
function ecranVotesEleve(){
  voteArreterPoll();
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  const tt=document.getElementById("titre"); if(tt){ tt.innerHTML='<i class="ph ph-chart-bar"></i> Les votes'; tt.style.display=""; }
  const it=document.getElementById("intro"); if(it){ it.textContent=""; it.style.display="none"; }
  const z=document.getElementById("zone"); const s=fbStore();
  if(!s||!profil.classeId){ z.innerHTML=svcIndispo("Rejoins d'abord ta classe avec ton code."); remonter(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  authElevePret().then(function(){ return votesEleveCharger(s); }).then(function(snap){
    const ouverts=[], clos=[];
    snap.forEach(function(d){ const v=Object.assign({id:d.id,_cid:d._cid},d.data()||{}); if(v.ouvert)ouverts.push(v); else if(v.resultats)clos.push(v); });
    ouverts.sort(function(x,y){ return (y.cree||0)-(x.cree||0); });
    clos.sort(function(x,y){ return (y.maj||y.cree||0)-(x.maj||x.cree||0); });
    let h='<div class="accueil" style="max-width:600px">';
    if(!ouverts.length && !clos.length){ h+='<div class="ex" style="text-align:center"><p style="margin:0">Aucun vote pour l\'instant. Reviens quand ton professeur en lance un&nbsp;!</p></div>'; }
    if(ouverts.length){
      h+='<h3 class="prog-titre" style="text-align:center"><i class="ph ph-hand-pointing"></i> À voter</h3>';
      ouverts.forEach(function(v){ h+=voteCarteElHTML(v,false); });
    }
    if(clos.length){
      h+='<h3 class="prog-titre" style="text-align:center'+(ouverts.length?';margin-top:18px':'')+'"><i class="ph ph-chart-bar"></i> Résultats</h3>';
      clos.forEach(function(v){ h+=voteCarteElHTML(v,true); });
    }
    h+='</div>'; z.innerHTML=h; remonter();
  }).catch(function(){ z.innerHTML=svcIndispo("Impossible de charger les votes."); remonter(); });
}
/* Votes de toutes les classes de l'élève, chaque document marqué de sa classe
   (_cid) : c'est elle qui reçoit la réponse. */
function votesEleveCharger(s){
  return chargerClassesInvite().then(function(){
    return Promise.all(classesEleve().map(function(cid){
      return s.collection("classes").doc(cid).collection("votes").get()
        .then(function(sn){ return {cid:cid,sn:sn}; }).catch(function(){ return {cid:cid,sn:null}; });
    }));
  }).then(function(lots){
    let vide=true; lots.forEach(function(x){ if(x.sn&&!x.sn.empty)vide=false; });
    return {empty:vide, forEach:function(fn){ lots.forEach(function(x){ if(x.sn)x.sn.forEach(function(d){ d._cid=x.cid; fn(d); }); }); }};
  });
}
let _voteClasseEl=null;   /* classe du vote ouvert par l'élève (la sienne ou celle où il est invité) */
function voteCarteElHTML(v,resultat){
  return '<button class="vt-carte-el" onclick="voteVoterEcran(\''+v.id+'\',\''+(v._cid||"")+'\')"><div style="min-width:0">'
    +'<div class="vt-titre">'+echapH(v.titre||v.question||"Vote")+'</div>'
    +(v.question&&v.titre?'<div class="vt-q">'+echapH(v.question)+'</div>':'')
    +'</div>'+(resultat?'<span class="vt-el-badge" style="margin-left:auto"><i class="ph-fill ph-chart-bar"></i> Résultats</span>':'')
    +'<i class="ph ph-caret-right"></i></button>';
}
function voteVoterEcran(vid,cid){
  _voteClasseEl=cid||profil.classeId;
  voteArreterPoll();
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(ecranVotesEleve,"Les votes");
  const tt=document.getElementById("titre"); if(tt){ tt.innerHTML='<i class="ph ph-chart-bar"></i> Vote'; tt.style.display=""; }
  const it=document.getElementById("intro"); if(it)it.style.display="none";
  const z=document.getElementById("zone"); const s=fbStore();
  if(!s||!profil.classeId||!profil.eleveCode){ z.innerHTML=svcIndispo("Rejoins d'abord ta classe."); remonter(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  const ref=s.collection("classes").doc(_voteClasseEl||profil.classeId).collection("votes").doc(vid);
  authElevePret().then(function(){
    return Promise.all([ ref.get(), ref.collection("reponses").doc(profil.eleveCode).get().catch(function(){ return {exists:false}; }) ]);
  }).then(function(r){
    if(!r[0].exists){ toast("Ce vote n'existe plus."); ecranVotesEleve(); return; }
    _voteVote=Object.assign({id:vid},r[0].data()||{});
    _voteMon=(r[1]&&r[1].exists)?(r[1].data()||{}).opt:null;
    voteVoterRendre();
  }).catch(function(){ z.innerHTML=svcIndispo("Impossible d'ouvrir ce vote."); remonter(); });
}
function voteVoterRendre(){
  const z=document.getElementById("zone"); const v=_voteVote; if(!z||!v)return;
  if(!v.ouvert && v.resultats){ voteResultatsRendre(); return; }
  let h='<div class="accueil" style="max-width:560px"><div class="vt-el-q">'+echapH(v.question||v.titre||"Vote")+'</div>';
  if(!v.ouvert)h+='<p style="text-align:center;color:var(--faux);font-weight:600;margin:0 0 12px"><i class="ph ph-lock"></i> Ce vote est fermé.</p>';
  h+='<div class="vt-el-opts">'+(v.options||[]).map(function(o){
    const sel=(_voteMon===o.id);
    return '<button class="vt-el-opt'+(sel?' sel':'')+'"'+(v.ouvert?' onclick="voteVoter(\''+o.id+'\')"':' disabled')+'>'
      +(o.img?'<img class="vt-el-img" src="'+o.img+'" alt="">':'<span class="vt-el-ic"><i class="ph ph-music-note"></i></span>')
      +'<span class="vt-el-txt">'+echapH(o.texte||"")+'</span>'
      +(sel?'<span class="vt-el-badge"><i class="ph-fill ph-check-circle"></i> Ton choix</span>':'')
      +'</button>';
  }).join("")+'</div>';
  if(v.ouvert)h+='<p style="text-align:center;color:var(--encre-doux);font-size:.85rem;margin-top:12px">Tu peux changer ton choix tant que le vote est ouvert.</p>';
  h+='</div>'; z.innerHTML=h; remonter();
}
/* Résultats vus par l'élève après clôture : décompte agrégé lu sur le vote. */
function voteResultatsRendre(){
  const z=document.getElementById("zone"); const v=_voteVote; if(!z||!v)return;
  const res=v.resultats||{}; const total=v.total||0;
  let maxN=0; (v.options||[]).forEach(function(o){ const n=res[o.id]||0; if(n>maxN)maxN=n; });
  let h='<div class="accueil" style="max-width:600px"><div class="vt-el-q">'+echapH(v.question||v.titre||"Vote")+'</div>'
    +'<p style="text-align:center;color:var(--encre-doux);font-size:.86rem;margin:-8px 0 16px"><i class="ph ph-flag-checkered"></i> Vote terminé · '+total+' vote'+(total>1?'s':'')+'</p>'
    +'<div class="vt-barres">'+(v.options||[]).map(function(o){
      const n=res[o.id]||0; const pct=total?Math.round(n/total*100):0; const gagne=n>0&&n===maxN; const mien=(_voteMon===o.id);
      return '<div class="vt-barre'+(gagne?' gagne':'')+'">'
        +'<div class="vt-barre-tete">'+(o.img?'<img class="vt-barre-img" src="'+o.img+'" alt="">':'')
          +'<span class="vt-barre-lbl">'+echapH(o.texte||"")+(mien?' <span class="vt-el-badge"><i class="ph-fill ph-check-circle"></i> ton choix</span>':'')+'</span>'
          +'<span class="vt-barre-n">'+n+' · '+pct+'%</span></div>'
        +'<div class="vt-barre-piste"><div class="vt-barre-plein" style="width:'+pct+'%"></div></div></div>';
    }).join("")+'</div></div>';
  z.innerHTML=h; remonter();
}
function voteVoter(optId){
  const v=_voteVote; if(!v||!v.ouvert)return;
  const s=fbStore(); if(!s||!profil.eleveCode||!profil.classeId){ toast("Vote impossible."); return; }
  _voteMon=optId; voteVoterRendre();
  s.collection("classes").doc(_voteClasseEl||profil.classeId).collection("votes").doc(v.id).collection("reponses").doc(profil.eleveCode)
    .set({code:profil.eleveCode, opt:optId, cree:Date.now()})
    .then(function(){ toast("Vote enregistré !"); })
    .catch(function(){ toast("Ton vote n'a pas pu être envoyé. Réessaie."); });
}
/* ================= Travail en classe (plan + évaluation par actions) =================
   Repris de « Gestion de classe », adapté MusEduc : élèves = CODES anonymes
   (noms en local via labelDe), tout par période ouvrable/clôturable (date de
   clôture modifiable à tout moment). La note n'est jamais stockée : elle est
   recalculée depuis les événements (note de départ + somme amortie, 0–20).
   L'élève lit SON suivi (retour direct). Collections :
   classes/{cid}/travailPlan/config, /travailPeriode/{pid}, /travailEleve/{code}. */
const TV_COMPORT_DEF=[
  {id:"part", ic:"hand-palm",     label:"Participation",       type:"pos", pts:1},
  {id:"aide", ic:"handshake",     label:"Aide un camarade",    type:"pos", pts:1},
  {id:"effort",ic:"trend-up",     label:"Bel effort",          type:"pos", pts:0.5},
  {id:"materiel",ic:"backpack",   label:"Oubli de matériel",   type:"neg", pts:-0.5},
  {id:"bavard",ic:"chat-circle",  label:"Bavardage",           type:"neg", pts:-0.5},
  {id:"perturb",ic:"warning",     label:"Perturbation",        type:"neg", pts:-1}
];
let _tv={cid:null, plan:{libre:true,places:{},tableau:"bas",rangs:0}, eleves:[], travail:{}, periode:null, periodes:[],
         comport:TV_COMPORT_DEF.slice(), base:10, mode:"noter", sel:null};
function tvCol(cid,nom){ const s=fbStore(); return s?s.collection("classes").doc(cid).collection(nom):null; }
function tvNom(code){ return labelDe(_tv.cid,code)||code; }
function tvUid(){ return "e"+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
/* Barème « amorti » : la note tend vers 20 (ou 0) sans jamais l'atteindre. */
function tvScale(total,base){
  if(total>=0){ const m=Math.max(0.5,20-base); return 20-m*Math.exp(-total/m); }
  const m=Math.max(0.5,base); return m*Math.exp(total/m);
}
function tvNoteDe(events,pid,base){
  let t=0; (events||[]).forEach(function(e){ if(!pid||e.periodeId===pid)t+=(Number(e.pts)||0); });
  return Math.max(0,Math.min(20,Math.round(tvScale(t,(typeof base==="number"?base:10))*10)/10));
}
function tvNoteEleve(code){ return tvNoteDe(_tv.travail[code], _tv.periode&&_tv.periode.id, _tv.base); }
function tvCoul(n){ if(n<8)return"var(--faux)"; if(n<10)return"#ea580c"; if(n<12)return"#d97706"; if(n<15)return"var(--juste)"; return"var(--juste)"; }
function tvDispNote(n){ return String(Math.round(n*10)/10).replace(".",","); }
function tvDispPts(p){ p=Number(p)||0; return (p>0?"+":p<0?"":"±")+String(p).replace(".",","); }
function tvDate(d){ try{ return new Date(d).toLocaleDateString("fr-FR"); }catch(e){ return ""; } }

/* ---------- Chargement de l'écran ---------- */
function ecranTravailProf(cid){
  if(cid)_classeProfSel=cid; cid=_classeProfSel;
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  titreProf('<i class="ph ph-chalkboard-simple"></i> Travail en classe',
    "Placez vos élèves, relevez ce qu'ils font en cours d'un clic. Leur note évolue, et ils en ont un retour.");
  const z=document.getElementById("zone");
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser;
  if(!s||!u||!estProf(u)||!cid){ z.innerHTML=svcIndispo("Cet espace est réservé aux professeurs connectés."); remonter(); return; }
  z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement…</p>';
  Promise.all([
    s.collection("teachers").doc(u.uid).get(),
    s.collection("eleveCodes").where("ownerUid","==",u.uid).get(),   /* la vraie liste : les codes de la classe (les progressions n'existent qu'après connexion) */
    s.collection("classes").doc(cid).collection("travailPlan").doc("config").get().catch(function(){return {exists:false};}),
    s.collection("classes").doc(cid).collection("travailPeriode").get().catch(function(){return {forEach:function(){}};}),
    s.collection("classes").doc(cid).collection("travailEleve").get().catch(function(){return {forEach:function(){}};}),
    chargerClassesProf()   /* pour le menu déroulant de changement de classe */
  ]).then(function(r){
    const tdoc=r[0].data()||{};
    _tv.comport = (Array.isArray(tdoc.comportements)&&tdoc.comportements.length)? tdoc.comportements : TV_COMPORT_DEF.slice();
    _tv.base = (typeof tdoc.travailBase==="number")? tdoc.travailBase : 10;
    _tv.cid=cid;
    const _mb=((_profClasses||[]).filter(function(x){return x.id===cid;})[0]||{}).membres||[];
    _tv.eleves=[]; r[1].forEach(function(d){ const v=d.data()||{}; if(v.classId===cid||_mb.indexOf(d.id)>=0)_tv.eleves.push(d.id); });
    _tv.eleves.sort(function(x,y){ return String(tvNom(x)).localeCompare(String(tvNom(y)),"fr",{numeric:true}); });
    const plan=r[2].exists?(r[2].data()||{}):{};
    _tv.plan=tvMigrerPlan(plan);
    _tv.periodes=[]; r[3].forEach(function(d){ _tv.periodes.push(Object.assign({id:d.id},d.data()||{})); });
    _tv.periode = _tv.periodes.filter(function(p){return !p.close;}).sort(function(x,y){return (y.debut||0)-(x.debut||0);})[0] || null;
    _tv.travail={}; _tv.att={}; r[4].forEach(function(d){ const v=d.data()||{}; _tv.travail[d.id]=v.events||[]; _tv.att[d.id]=v.att||{}; });
    _tv.mode="noter"; _tv.sel=null; _tv.appelDate=new Date().toISOString().slice(0,10);
    if(!_tv.periode){ tvNouvellePeriode(true); return; }
    tvRendre();
  }).catch(function(e){
    const c=String((e&&e.code)||"");
    z.innerHTML=(c.indexOf("permission-denied")>=0 && typeof chRegles==="function")?chRegles():svcIndispo("Impossible de charger le travail en classe.");
    remonter();
  });
}

/* ---------- Rendu principal ---------- */
function tvRendre(){
  const z=document.getElementById("zone"); if(!z)return;
  const p=_tv.periode||{};
  const nonPlaces=_tv.eleves.filter(function(c){ return !_tv.plan.places[c]; });
  let h='<div class="accueil" style="max-width:1000px">';
  h+=selClasseHTML('ecranTravailProf', _tv.cid);   /* menu déroulant : changer de classe */

  /* barre période */
  const pClos=!!p.close;
  h+='<div class="tv-periode"><div style="flex:1;min-width:0">'
    +'<div class="tv-per-nom"><i class="ph ph-flag-banner"></i> '+echapH(p.nom||"Période")+(pClos?' <span class="tv-per-clos">clôturée</span>':'')+'</div>'
    +'<div class="tv-per-date">'+(pClos?('Clôturée le <b>'+tvDate(p.clotureLe||p.fin)+'</b>'):('Clôture prévue le <b>'+(p.fin?tvDate(p.fin):"à définir")+'</b>'))+' · '+_tv.eleves.length+' élève'+(_tv.eleves.length>1?"s":"")+'</div>'
    +'</div><div class="tv-per-act">'
    +'<button class="vt-btn" onclick="tvHistorique()"><i class="ph ph-clock-counter-clockwise"></i> Périodes</button>'
    +(pClos
      ?'<button class="vt-btn" onclick="tvRouvrir(\''+p.id+'\')"><i class="ph ph-lock-open"></i> Rouvrir</button>'
      :'<button class="vt-btn" onclick="tvPeriodeModifier()"><i class="ph ph-pencil-simple"></i> Modifier</button>'
       +'<button class="vt-btn" onclick="tvCloturer()"><i class="ph ph-flag-checkered"></i> Clôturer</button>')
    +'</div></div>';

  /* barre outils */
  h+='<div class="tv-outils">'
    +'<div class="tv-modes">'
    +'<button class="tv-mode'+(_tv.mode==="noter"?" on":"")+'" onclick="tvMode(\'noter\')"><i class="ph ph-cursor-click"></i> Noter</button>'
    +'<button class="tv-mode'+(_tv.mode==="appel"?" on":"")+'" onclick="tvMode(\'appel\')"><i class="ph ph-user-check"></i> Appel</button>'
    +'<button class="tv-mode'+(_tv.mode==="placer"?" on":"")+'" onclick="tvMode(\'placer\')"><i class="ph ph-arrows-out-cardinal"></i> Placer</button>'
    +'</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +(_tv.mode==="placer"?'<button class="vt-btn" onclick="tvAutoMenu()"><i class="ph ph-magic-wand"></i> Ranger automatiquement</button>'
      +'<button class="vt-btn" onclick="tvVider()"><i class="ph ph-eraser"></i> Vider le plan</button>'
      +'<button class="vt-btn" onclick="tvInverserTableau()"><i class="ph ph-swap"></i> Tableau '+(_tv.plan.tableau==="haut"?"en haut":"en bas")+'</button>':'')
    +(_tv.mode==="appel"?'<label class="tv-datel">Jour <input type="date" value="'+(_tv.appelDate||"")+'" onchange="tvAppelDate(this.value)"></label>'
      +'<button class="vt-btn" onclick="tvAppelRecap()"><i class="ph ph-list-checks"></i> Récap présences</button>':'')
    +'<button class="vt-btn" onclick="tvComportEcran()"><i class="ph ph-sliders"></i> Comportements</button>'
    +'<button class="vt-btn" onclick="tvContacts()"><i class="ph ph-address-book"></i> Contacts familles</button>'
    +'</div></div>';

  /* plan de classe : placement libre sur un canevas */
  if(_tv.mode==="appel"){ h+='<div class="tv-legende">'+TV_ATT.map(function(a){return '<span><i style="background:'+a.coul+'"></i>'+a.k+' · '+a.label+'</span>';}).join("")+'<span><i style="background:var(--juste)"></i>P · Présent</span></div>'; }
  if(_tv.mode==="noter"){ h+='<p class="tv-hint"><i class="ph ph-hand-tap"></i> Clic = +1 · double-clic = menu · glisser vers le <b style="color:var(--juste)">haut</b> = +, vers le <b style="color:var(--faux)">bas</b> = −</p>'; }
  h+='<div class="tv-canvas" id="tvCanvas">';
  h+='<div class="tv-tableau '+(_tv.plan.tableau==="haut"?"haut":"bas")+'"><i class="ph ph-chalkboard"></i> Tableau</div>';
  _tv.eleves.forEach(function(c){ const pl=_tv.plan.places[c]; if(pl){ h+=tvTuileHTML(c,pl.x,pl.y); } });
  h+='</div>';
  if(_tv.mode==="noter"){
    h+='<div class="tv-behbar">'
      +_tv.comport.map(function(cp){ return '<button class="tv-beh '+(cp.type==="neg"?"neg":"pos")+(_tv.behSel===cp.id?" on":"")+'" onclick="tvBehSel(\''+cp.id+'\')" title="Sélectionner : chaque clic sur un élève applique ce comportement"><i class="ph ph-'+echapH(cp.ic||"circle")+'"></i> '+echapH(cp.label)+' <b>'+tvDispPts(cp.pts)+'</b></button>'; }).join("")
      +'</div>';
    if(_tv.behSel){ h+='<p class="tv-hint"><i class="ph ph-cursor-click"></i> Comportement sélectionné : cliquez les élèves concernés (reclic sur le comportement pour revenir au +1).</p>'; }
  }

  /* file des non-placés */
  if(nonPlaces.length){
    h+='<div class="tv-file"><div class="tv-file-t">'+(_tv.mode==="placer"?'À placer (cliquez pour poser sur le plan, puis glissez où vous voulez)':'Non placés')+'</div><div class="tv-file-l">'
      +nonPlaces.map(function(c){ return '<button class="tv-chip"'
        +(_tv.mode==="placer"?' onclick="tvPlacerCentre(\''+c+'\')" title="Placer sur le plan"':' onclick="tvOuvrirComport(\''+c+'\')"')+'>'
        +echapH(tvNom(c))+' <span class="tv-chip-n" style="color:'+tvCoul(tvNoteEleve(c))+'">'+tvDispNote(tvNoteEleve(c))+'</span></button>'; }).join("")
      +'</div></div>';
  }

  h+='<p style="text-align:center;color:var(--encre-doux);font-size:.83rem;margin-top:16px">'
    +'<i class="ph ph-lock"></i> Seuls les <b>codes</b> de vos élèves sont enregistrés ; les noms restent sur cet appareil. Chaque élève voit son propre suivi.</p>';
  h+='</div>';
  const _m=document.querySelector("main"); const _sy=_m?_m.scrollTop:0;
  z.innerHTML=h;
  if(_m){ _m.scrollTop=_sy; requestAnimationFrame(function(){ try{ _m.scrollTop=_sy; }catch(e){} }); }
}
function tvTuileHTML(code,x,y){
  const pos='left:'+x+'%;top:'+y+'%';
  const n=tvNoteEleve(code); const evs=_tv.travail[code]||[];
  const dernier=evs[evs.length-1];
  if(_tv.mode==="appel"){
    const st=(_tv.att[code]||{})[_tv.appelDate]; const info=tvAttInfo(st);
    return '<div class="tv-tuile tv-appel" style="'+pos+'" onclick="tvAppelCycle(\''+code+'\')" title="Présent → absent → retard → exclu → dispensé">'
      +'<div class="tv-tuile-nom">'+echapH(tvNom(code))+'</div>'
      +'<div class="tv-appel-st" style="color:'+(info?info.coul:"var(--juste)")+'">'+(info?info.k:"P")+'</div>'
      +'<div class="tv-appel-lbl">'+(info?info.label:"Présent")+'</div></div>';
  }
  if(_tv.mode==="placer"){
    return '<div class="tv-tuile tv-placer" style="'+pos+'" data-code="'+code+'" onpointerdown="tvDragDebut(event,\''+code+'\')" title="Glissez pour déplacer">'
      +'<button class="tv-tuile-x" title="Retirer du plan" onpointerdown="event.stopPropagation()" onclick="event.stopPropagation();tvRetirer(\''+code+'\')"><i class="ph ph-x"></i></button>'
      +'<div class="tv-tuile-nom">'+echapH(tvNom(code))+'</div>'
      +'<div class="tv-tuile-note" style="color:'+tvCoul(n)+'">'+tvDispNote(n)+'</div></div>';
  }
  return '<div class="tv-tuile tv-noter" style="'+pos+'" data-code="'+code+'" onpointerdown="tvNoteDebut(event,\''+code+'\')" title="Clic : +1 · Double-clic : menu · Glisser vers le haut = +, vers le bas = −">'
    +'<div class="tv-tuile-nom">'+echapH(tvNom(code))+'</div>'
    +'<div class="tv-tuile-note" style="color:'+tvCoul(n)+'">'+tvDispNote(n)+'</div>'
    +(dernier?'<div class="tv-tuile-dern"><i class="ph '+(dernier.type==="neg"?"ph-arrow-down":"ph-arrow-up")+'"></i> '+echapH(dernier.label||"")+'</div>':'')
    +'</div>';
}

/* ---------- Placement ---------- */
function tvMode(m){ _tv.mode=m; _tv.sel=null; _tv.behSel=null; tvRendre(); }
/* Notation à la « Gestion de classe » : clic = +1, double-clic = menu,
   glisser vers le haut = point positif, vers le bas = négatif. Le barème est
   amorti (tvScale) : plus on approche de 20, plus un point rapporte peu. */
let _tvTap=null, _tvSingleTimer=null, _tvLastTap={code:null,at:0};
function tvNoteDebut(e,code){
  if(_tv.mode!=="noter")return;
  _tvTap={code:code, x:e.clientX, y:e.clientY};
  const tile=e.currentTarget;
  try{ tile.setPointerCapture(e.pointerId); }catch(_){}
  tile.addEventListener("pointermove",tvNoteMove);
  tile.addEventListener("pointerup",tvNoteFin);
  tile.addEventListener("pointercancel",tvNoteAnnule);
}
function tvNoteMove(e){
  if(!_tvTap)return;
  const dy=e.clientY-_tvTap.y, dx=e.clientX-_tvTap.x, tile=e.currentTarget;
  if(Math.abs(dy)>=40 && Math.abs(dy)>Math.abs(dx)){ tile.classList.remove("tv-swup","tv-swdown"); tile.classList.add(dy<0?"tv-swup":"tv-swdown"); }
  else { tile.classList.remove("tv-swup","tv-swdown"); }
}
function tvNoteRetirerEcouteurs(tile){ if(!tile)return; tile.removeEventListener("pointermove",tvNoteMove); tile.removeEventListener("pointerup",tvNoteFin); tile.removeEventListener("pointercancel",tvNoteAnnule); tile.classList.remove("tv-swup","tv-swdown"); }
function tvNoteAnnule(e){ tvNoteRetirerEcouteurs(e.currentTarget); _tvTap=null; }
function tvNoteFin(e){
  const tile=e.currentTarget; tvNoteRetirerEcouteurs(tile);
  if(!_tvTap)return;
  const dy=e.clientY-_tvTap.y, dx=e.clientX-_tvTap.x, code=_tvTap.code; _tvTap=null;
  if(Math.abs(dy)>=40 && Math.abs(dy)>Math.abs(dx)){ tvNoteRapide(code, dy<0?1:-1); return; }
  if(Math.abs(dx)>12||Math.abs(dy)>12)return;   /* petit déplacement : ni tap ni swipe */
  const now=Date.now();
  if(_tvLastTap.code===code && (now-_tvLastTap.at)<300){
    _tvLastTap={code:null,at:0};
    if(_tvSingleTimer){ clearTimeout(_tvSingleTimer); _tvSingleTimer=null; }
    tvOuvrirComport(code);                        /* double-clic : menu complet */
  } else {
    _tvLastTap={code:code, at:now};
    if(_tvSingleTimer)clearTimeout(_tvSingleTimer);
    _tvSingleTimer=setTimeout(function(){ _tvSingleTimer=null; _tvLastTap={code:null,at:0}; tvNoteApplique(code); },300);
  }
}
/* Défaut du swipe : haut = Participation (1er positif), bas = Bavardages (1er négatif). */
function tvBehDefaut(sens){
  const pref=sens>0?/particip/i:/bavard/i, typ=sens>0?"pos":"neg";
  return _tv.comport.filter(function(b){return b.type===typ&&pref.test(b.label);})[0]
      || _tv.comport.filter(function(b){return b.type===typ;})[0];
}
function tvFlash(code,sens){
  setTimeout(function(){ const t=document.querySelector('#tvCanvas .tv-tuile[data-code="'+code+'"]'); if(t){ t.classList.add(sens>0?"tv-flash-pos":"tv-flash-neg"); setTimeout(function(){ try{t.classList.remove("tv-flash-pos","tv-flash-neg");}catch(_){}} ,650); } },40);
}
function tvNoteRapide(code,sens){
  const beh=tvBehDefaut(sens);
  if(!beh){ toast("Aucun comportement "+(sens>0?"positif":"négatif")+" dans le barème (voir Comportements)."); return; }
  tvAjouterEvent(code,{label:beh.label, ic:beh.ic, type:beh.type, pts:beh.pts}); tvFlash(code,sens);
}
/* Clic simple : applique le comportement sélectionné dans la barre du bas,
   sinon un +1 par défaut. */
function tvNoteApplique(code){
  if(_tv.behSel){ const cp=_tv.comport.filter(function(b){return b.id===_tv.behSel;})[0]; if(cp){ tvAjouterEvent(code,{label:cp.label,ic:cp.ic,type:cp.type,pts:cp.pts}); tvFlash(code,cp.type==="neg"?-1:1); return; } }
  tvNoteRapide(code,1);
}
function tvBehSel(id){ _tv.behSel=(_tv.behSel===id?null:id); tvRendre(); }
const TV_ATT=[{k:"A",label:"Absent",coul:"var(--faux)"},{k:"R",label:"Retard",coul:"#d97706"},{k:"E",label:"Exclu",coul:"#9333ea"},{k:"D",label:"Dispensé",coul:"var(--encre-doux)"}];
function tvAttInfo(k){ return TV_ATT.filter(function(x){return x.k===k;})[0]||null; }
const TV_CONTACT_TYPES=[{k:"appel",label:"Appel téléphonique",ic:"phone"},{k:"carnet",label:"Mot dans le carnet",ic:"notebook"},{k:"mail",label:"E-mail",ic:"envelope"},{k:"rdv",label:"Rendez-vous",ic:"users-three"},{k:"autre",label:"Autre",ic:"chat-dots"}];
function tvContactType(k){ return TV_CONTACT_TYPES.filter(function(t){return t.k===k;})[0]||null; }
function tvContactDate(ts){ if(!ts)return ""; try{ return new Date(ts).toLocaleDateString("fr-FR",{day:"2-digit",month:"short",year:"numeric"}); }catch(_){ return ""; } }
function tvContacts(){
  if(!_tv.cid){ toast("Ouvrez d'abord une classe."); return; }
  const b=document.createElement("div"); b.id="tvPop"; b.className="voc-pop-fond";
  b.onclick=function(ev){ if(ev.target===b)tvFermerPop(); };
  b.innerHTML='<div class="voc-pop" style="max-width:640px;position:relative">'
    +'<button class="ch-croix" onclick="tvFermerPop()" aria-label="Fermer"><i class="ph ph-x"></i></button>'
    +'<h3 style="margin:0 0 4px;padding-right:36px"><i class="ph ph-address-book"></i> Contacts familles</h3>'
    +'<p style="margin:0 0 12px;color:var(--encre-doux);font-size:.86rem">Journal privé, conservé uniquement sur cet appareil et inclus dans vos sauvegardes. Aucun envoi sur le serveur.</p>'
    +'<div id="tvContactCorps"></div></div>';
  document.body.appendChild(b); tvContactsRendre();
}
function tvContactsRendre(){
  const z=document.getElementById("tvContactCorps"); if(!z)return;
  const eleves=_tv.eleves.slice().sort(function(a,b){ return tvNom(a).localeCompare(tvNom(b)); });
  const opts=eleves.map(function(c){ return '<option value="'+c+'">'+echapH(tvNom(c))+'</option>'; }).join("");
  const typeOpts=TV_CONTACT_TYPES.map(function(t){ return '<option value="'+t.k+'">'+t.label+'</option>'; }).join("");
  const auj=new Date().toISOString().slice(0,10);
  const form='<div class="tv-ct-form">'
    +'<div class="tv-ct-row"><select id="tvCtEleve" class="tv-ct-in">'+opts+'</select>'
    +'<select id="tvCtType" class="tv-ct-in">'+typeOpts+'</select>'
    +'<input id="tvCtDate" type="date" class="tv-ct-in" value="'+auj+'"></div>'
    +'<input id="tvCtObjet" class="tv-ct-in" placeholder="Objet (ex. absences répétées)" maxlength="80">'
    +'<textarea id="tvCtNote" class="tv-ct-in" rows="2" placeholder="Note (facultatif)"></textarea>'
    +'<button class="rm-cta" style="justify-content:center" onclick="tvContactAjouter()"><i class="ph ph-plus"></i> Enregistrer le contact</button></div>';
  const cont=lireContacts()[_tv.cid]||{}; const items=[];
  Object.keys(cont).forEach(function(code){ (cont[code]||[]).forEach(function(x){ items.push(Object.assign({code:code},x)); }); });
  items.sort(function(a,b){ return (b.date||0)-(a.date||0); });
  let liste;
  if(items.length){
    liste='<div class="tv-ct-liste">'+items.map(function(x){
      const t=tvContactType(x.type);
      return '<div class="tv-ct-l"><div class="tv-ct-ic"><i class="ph ph-'+(t?t.ic:"chat-dots")+'"></i></div>'
        +'<div style="flex:1;min-width:0"><div class="tv-ct-tete"><b>'+echapH(tvNom(x.code))+'</b> <span style="color:var(--encre-doux);font-size:.8rem">'+(t?t.label:"")+' · '+tvContactDate(x.date)+'</span></div>'
        +(x.objet?'<div style="font-weight:600;font-size:.9rem">'+echapH(x.objet)+'</div>':'')
        +(x.note?'<div style="font-size:.86rem;color:var(--encre-doux);white-space:pre-wrap">'+echapH(x.note)+'</div>':'')
        +'</div><button class="tv-ct-suppr" title="Supprimer" onclick="tvContactSupprimer(\''+x.code+'\',\''+x.id+'\')"><i class="ph ph-trash"></i></button></div>';
    }).join("")+'</div>';
  } else { liste='<p style="color:var(--encre-doux);margin-top:14px">Aucun contact enregistré pour cette classe.</p>'; }
  z.innerHTML=form+'<h4 style="margin:16px 0 8px">Historique</h4>'+liste;
}
function tvContactAjouter(){
  const code=(document.getElementById("tvCtEleve")||{}).value;
  const type=(document.getElementById("tvCtType")||{}).value;
  const dv=(document.getElementById("tvCtDate")||{}).value;
  const objet=(((document.getElementById("tvCtObjet")||{}).value)||"").trim();
  const note=(((document.getElementById("tvCtNote")||{}).value)||"").trim();
  if(!code){ toast("Choisissez un élève."); return; }
  if(!objet && !note){ toast("Ajoutez au moins un objet ou une note."); return; }
  const ts=dv?new Date(dv+"T12:00:00").getTime():Date.now();
  const all=lireContacts(); all[_tv.cid]=all[_tv.cid]||{}; all[_tv.cid][code]=all[_tv.cid][code]||[];
  all[_tv.cid][code].push({ id:"ct"+Date.now()+"_"+Math.floor(Math.random()*10000), date:ts, type:type||"autre", objet:objet.slice(0,80), note:note.slice(0,600) });
  ecrireContacts(all); toast("Contact enregistré."); tvContactsRendre();
}
async function tvContactSupprimer(code,id){
  if(!await dlgConfirmer("Supprimer ce contact ?"))return;
  const all=lireContacts(); const arr=(all[_tv.cid]&&all[_tv.cid][code])||[];
  const i=arr.map(function(x){return x.id;}).indexOf(id);
  if(i>=0){ arr.splice(i,1); ecrireContacts(all); tvContactsRendre(); }
}
function tvAppelDate(v){ if(v){ _tv.appelDate=v; tvRendre(); } }
function tvAppelCycle(code){
  const ordre=["A","R","E","D"];
  _tv.att[code]=_tv.att[code]||{};
  const cur=_tv.att[code][_tv.appelDate]; const i=ordre.indexOf(cur);
  const next=(i<0)?"A":(i>=ordre.length-1?null:ordre[i+1]);
  if(next)_tv.att[code][_tv.appelDate]=next; else delete _tv.att[code][_tv.appelDate];
  tvSauverAtt(code,_tv.appelDate,next); tvRendre();
}
function tvSauverAtt(code,date,val){
  const c=tvCol(_tv.cid,"travailEleve"); if(!c)return;
  const FV=(typeof firebase!=="undefined")?firebase.firestore.FieldValue:null;
  if(val){ const o={}; o[date]=val; c.doc(code).set({code:code,att:o},{merge:true}).catch(function(){}); }
  else if(FV){ const u={}; u["att."+date]=FV.delete(); c.doc(code).update(u).catch(function(){}); }
}
function tvAppelRecap(){
  const b=document.createElement("div"); b.id="tvPop"; b.className="voc-pop-fond";
  b.onclick=function(ev){ if(ev.target===b)tvFermerPop(); };
  const lignes=_tv.eleves.map(function(c){
    const a=_tv.att[c]||{}; let nA=0,nR=0,nE=0,nD=0;
    Object.keys(a).forEach(function(d){ const v=a[d]; if(v==="A")nA++; else if(v==="R")nR++; else if(v==="E")nE++; else if(v==="D")nD++; });
    return {c:c,nA:nA,nR:nR,nE:nE,nD:nD,tot:nA+nR+nE+nD};
  }).filter(function(x){return x.tot>0;}).sort(function(x,y){return (y.nA-x.nA)||(y.tot-x.tot);});
  b.innerHTML='<div class="voc-pop" style="max-width:520px;position:relative">'
    +'<button class="ch-croix" onclick="tvFermerPop()" aria-label="Fermer"><i class="ph ph-x"></i></button>'
    +'<h3 style="margin:0 0 12px;padding-right:36px">Récap des présences</h3>'
    +(lignes.length?'<div class="tv-recap">'+lignes.map(function(r){
        return '<div class="tv-recap-l"><b>'+echapH(tvNom(r.c))+'</b><span>'
          +(r.nA?'<span style="color:var(--faux)">'+r.nA+' abs.</span> ':'')
          +(r.nR?'<span style="color:#d97706">'+r.nR+' ret.</span> ':'')
          +(r.nE?'<span style="color:#9333ea">'+r.nE+' excl.</span> ':'')
          +(r.nD?'<span style="color:var(--encre-doux)">'+r.nD+' disp.</span>':'')
          +'</span></div>';
      }).join("")+'</div>':'<p style="color:var(--encre-doux)">Aucune absence ni retard relevé pour l\'instant.</p>')
    +'</div>';
  document.body.appendChild(b);
}
function tvRetirer(code){ delete _tv.plan.places[code]; tvSauverPlan(); tvRendre(); }
async function tvVider(){ if(!await dlgConfirmer("Retirer tous les élèves du plan ? (le suivi et les notes sont conservés)"))return; _tv.plan.places={}; tvSauverPlan(); tvRendre(); }
function tvSauverPlan(){
  const c=tvCol(_tv.cid,"travailPlan"); if(!c)return;
  c.doc("config").set({libre:true, places:_tv.plan.places, tableau:_tv.plan.tableau||"bas", rangs:_tv.plan.rangs||0},{merge:false}).catch(function(){});
}
function tvMigrerPlan(plan){
  plan=plan||{}; const places=plan.places||{};
  if(plan.libre){ return {libre:true, places:places, tableau:plan.tableau||"bas", rangs:plan.rangs||0}; }
  /* ancien format grille -> coordonnées en pourcentage */
  const cols=plan.cols||6, rows=plan.rows||5, np={};
  Object.keys(places).forEach(function(c){ const pl=places[c]; if(!pl)return;
    const x = cols>1 ? 8+84*((pl.x||0)/(cols-1)) : 50;
    const y = rows>1 ? 20+72*((pl.y||0)/(rows-1)) : 50;
    np[c]={x:Math.round(x*10)/10, y:Math.round(y*10)/10};
  });
  return {libre:true, places:np, tableau:plan.tableau||"bas", rangs:plan.rangs||0};
}
function tvOccupe(x,y,code){ return _tv.eleves.some(function(c){ if(c===code)return false; const pl=_tv.plan.places[c]; return pl&&Math.abs(pl.x-x)<9&&Math.abs(pl.y-y)<9; }); }
function tvPlacerCentre(code){
  let x=50,y=48,t=0;
  while(tvOccupe(x,y,code)&&t<50){ x=24+Math.random()*52; y=26+Math.random()*58; t++; }
  _tv.plan.places[code]={x:Math.round(x*10)/10, y:Math.round(y*10)/10}; tvSauverPlan(); tvRendre();
}
function tvDragDebut(e,code){
  if(_tv.mode!=="placer")return;
  if(e&&e.preventDefault)e.preventDefault();
  const canvas=document.getElementById("tvCanvas"); const tile=e.currentTarget; if(!canvas||!tile)return;
  tile.classList.add("drag"); tile.style.zIndex="60";
  try{ tile.setPointerCapture(e.pointerId); }catch(_){}
  function move(ev){
    const r=canvas.getBoundingClientRect(); if(!r.width||!r.height)return;
    let x=(ev.clientX-r.left)/r.width*100, y=(ev.clientY-r.top)/r.height*100;
    x=Math.max(4,Math.min(96,x)); y=Math.max(9,Math.min(96,y));
    tile.style.left=x+"%"; tile.style.top=y+"%"; tile._x=x; tile._y=y;
  }
  function fin(){
    try{ tile.releasePointerCapture(e.pointerId); }catch(_){}
    tile.removeEventListener("pointermove",move); tile.removeEventListener("pointerup",fin); tile.removeEventListener("pointercancel",fin);
    tile.classList.remove("drag"); tile.style.zIndex="";
    if(tile._x!=null){ _tv.plan.places[code]={x:Math.round(tile._x*10)/10, y:Math.round(tile._y*10)/10}; tvSauverPlan(); }
  }
  tile.addEventListener("pointermove",move); tile.addEventListener("pointerup",fin); tile.addEventListener("pointercancel",fin);
}
function tvAutoMenu(){
  const b=document.createElement("div"); b.id="tvPop"; b.className="voc-pop-fond";
  b.onclick=function(ev){ if(ev.target===b)tvFermerPop(); };
  const opts=[
    {k:"alpha",ic:"sort-ascending",label:"Alphabétique",desc:"En rangs, par ordre des noms"},
    {k:"alea",ic:"shuffle",label:"Aléatoire",desc:"Places tirées au hasard"},
    {k:"u",ic:"square",label:"En U",desc:"Autour de la salle, ouvert vers le tableau"},
    {k:"ilot",ic:"squares-four",label:"En îlots",desc:"Par groupes de 4"},
    {k:"arc",ic:"rainbow",label:"En arc de cercle",desc:"Rangs courbés face au tableau"},
    {k:"binome",ic:"users",label:"Par binômes",desc:"Tables de 2"}
  ];
  b.innerHTML='<div class="voc-pop" style="max-width:460px;position:relative">'
    +'<button class="ch-croix" onclick="tvFermerPop()" aria-label="Fermer"><i class="ph ph-x"></i></button>'
    +'<h3 style="margin:0 0 4px;padding-right:36px">Ranger automatiquement</h3>'
    +'<p style="margin:0 0 10px;color:var(--encre-doux);font-size:.86rem">Choisissez une disposition. Vous pourrez ensuite ajuster chaque élève à la main.</p>'
    +'<label class="tv-rangs-l"><i class="ph ph-rows"></i> Nombre de rangs <input id="tvRangs" type="number" min="0" max="12" value="'+(_tv.plan.rangs||"")+'" placeholder="auto"> <span style="font-size:.78rem">(0 = automatique)</span></label>'
    +'<div class="tv-formes">'+opts.map(function(o){
      return '<button class="tv-forme" onclick="tvArranger(\''+o.k+'\')"><i class="ph ph-'+o.ic+'"></i><span><b>'+o.label+'</b><small>'+o.desc+'</small></span></button>';
    }).join("")+'</div></div>';
  document.body.appendChild(b);
}
function tvInverserTableau(){
  _tv.plan.tableau=(_tv.plan.tableau==="haut")?"bas":"haut";
  Object.keys(_tv.plan.places).forEach(function(c){ const p=_tv.plan.places[c]; if(p)p.y=Math.round((100-p.y)*10)/10; });
  tvSauverPlan(); tvRendre(); toast("Tableau "+(_tv.plan.tableau==="haut"?"en haut":"en bas")+".");
}
/* Placement automatique porté de « Gestion de classe.html » : rangées, îlots, U
   et demi-cercle (arcs concentriques centrés sur l'enseignant, trigonométrie).
   planY gère le tableau en bas (défaut) ou en haut ; rien à retourner ensuite. */
function tvPlanAuto(kind,N,R,boardPos){
  const out=[]; if(N<=0)return out;
  const bas=(boardPos!=="haut");
  const clamp=function(v,a,b){ return Math.max(a,Math.min(b,v)); };
  const planY=function(t){ const near=20,far=92; return bas ? far-(far-near)*t : near+(far-near)*t; };
  const ASPECT_X=1.5, ASPECT_Y=1, ARC_FOCUS=0.05;
  function splitRows(n,r,weights){
    r=Math.max(1,Math.min(r,n));
    const w=weights||Array.from({length:r},function(){return 1;});
    const tot=w.reduce(function(a,b){return a+b;},0)||1;
    const counts=w.map(function(x){return Math.floor(n*x/tot);});
    let rest=n-counts.reduce(function(a,b){return a+b;},0);
    for(let k=0;rest>0;k=(k+1)%r){counts[k]++;rest--;}
    return counts.filter(function(c){return c>0;});
  }
  let i=0;
  if(kind==="alpha"||kind==="alea"||kind==="rows"){
    const counts=splitRows(N,R);
    counts.forEach(function(n,r){
      const t=counts.length<=1?0.35:r/(counts.length-1);
      const y=planY(t);
      const span=Math.min(90,Math.max(28,n*13));
      for(let c=0;c<n;c++,i++){
        const x=n===1?50:50+(c-(n-1)/2)*(span/(n-1));
        out.push({x:clamp(x,4,96),y:clamp(y,5,95)});
      }
    });
  } else if(kind==="ilot"||kind==="binome"){
    const per=(kind==="binome")?2:4;
    const groups=Math.max(1,Math.ceil(N/per));
    const rowsOfGroups=Math.min(R,groups);
    const perRow=splitRows(groups,rowsOfGroups);
    const rowGap=perRow.length<=1?30:72/(perRow.length-1);
    const dyIsl=Math.min(9,rowGap*0.30);
    perRow.forEach(function(ng,r){
      const t=perRow.length<=1?0.45:r/(perRow.length-1);
      const cy=planY(t);
      const slot=88/ng, dxIsl=Math.min(9,slot*0.30);
      for(let k=0;k<ng;k++){
        const cx=6+slot*(k+0.5);
        for(let j=0;j<per&&i<N;j++,i++){
          out.push({x:clamp(cx+(j%2?dxIsl:-dxIsl),4,96),y:clamp(cy+(j>1?dyIsl:-dyIsl),5,95)});
        }
      }
    });
    while(i<N){ out.push({x:clamp(8+(i%8)*11,4,96),y:clamp(planY(0.95),5,95)}); i++; }
  } else if(kind==="u"){
    const rings=[];
    for(let k=0;k<R;k++){
      const xL=7+k*12, xR=93-k*12, tNear=0.04+k*0.10, tFar=0.94-k*0.17;
      if(xR-xL<14||tFar-tNear<0.1) break;
      const side=(tFar-tNear)*72*ASPECT_Y, back=(xR-xL)*ASPECT_X;
      rings.push({xL:xL,xR:xR,tNear:tNear,tFar:tFar,side:side,back:back,per:2*side+back});
    }
    if(!rings.length)rings.push({xL:7,xR:93,tNear:0.04,tFar:0.94,side:64.8,back:129,per:258.6});
    const counts=splitRows(N,rings.length,rings.map(function(r){return r.per||1;}));
    counts.forEach(function(n,k){
      const g=rings[k]||rings[rings.length-1];
      for(let j=0;j<n;j++,i++){
        const d=(n===1?0.5:j/(n-1))*g.per;
        let x,t;
        if(d<=g.side){ x=g.xL; t=g.tNear+(g.side?(d/g.side):0)*(g.tFar-g.tNear); }
        else if(d<=g.side+g.back){ t=g.tFar; x=g.xL+((d-g.side)/g.back)*(g.xR-g.xL); }
        else { x=g.xR; t=g.tFar-((d-g.side-g.back)/g.side)*(g.tFar-g.tNear); }
        out.push({x:clamp(x,4,96),y:clamp(planY(t),5,95)});
      }
    });
    while(i<N){ out.push({x:50,y:clamp(planY(0.5),5,95)}); i++; }
  } else { /* arc / demi-cercle */
    const R2=Math.min(R,N);
    const TH=78*Math.PI/180;
    const dx=R2>1?Math.min(12,(46-15)/(R2-1)):0;
    const dt=R2>1?Math.min(0.21,(0.93-0.26)/(R2-1)):0;
    const rings=[];
    for(let k=0;k<R2;k++) rings.push({rx:46-(R2-1-k)*dx, rt:0.93-(R2-1-k)*dt});
    const counts=splitRows(N,R2,rings.map(function(g){return g.rx;}));
    counts.forEach(function(n,k){
      const g=rings[k];
      for(let j=0;j<n;j++,i++){
        const a=(n===1?0:(j/(n-1))*2-1)*TH;
        out.push({x:clamp(50+Math.sin(a)*g.rx,4,96), y:clamp(planY(ARC_FOCUS+Math.cos(a)*g.rt),5,95)});
      }
    });
  }
  return out;
}
function tvArranger(kind){
  const rows=Math.max(0,Math.min(8, parseInt((document.getElementById("tvRangs")||{}).value,10)||0));
  _tv.plan.rangs=rows;
  tvFermerPop();
  let order=_tv.eleves.slice();
  if(kind==="alea"){ for(let i=order.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); const t=order[i];order[i]=order[j];order[j]=t; } }
  else order.sort(function(a,b){ return String(tvNom(a)).localeCompare(String(tvNom(b)),"fr",{numeric:true}); });
  const R=Math.max(1,Math.min(8, rows>0?rows:3));
  const pos=tvPlanAuto(kind, order.length, R, _tv.plan.tableau||"bas");
  const places={}; order.forEach(function(c,i){ if(pos[i])places[c]=pos[i]; });
  _tv.plan.places=places; tvSauverPlan(); tvRendre(); toast("Plan rangé.");
}
