          +'<div style="font-size:.78rem;color:var(--encre-doux)">'+(p.close?("clôturée le "+tvDate(p.clotureLe||p.fin)):("clôture prévue le "+(p.fin?tvDate(p.fin):"à définir")))+'</div></div>'
          +'<div style="display:flex;gap:6px;flex:none">'
          +(actif?'<span class="vt-el-badge">vue actuelle</span>':'<button class="vt-btn" onclick="tvVoirPeriode(\''+p.id+'\')">Voir</button>')
          +(p.close?'<button class="vt-btn" onclick="tvRouvrir(\''+p.id+'\')"><i class="ph ph-lock-open"></i> Rouvrir</button>':'')
          +'</div></div>';
