    +(( _tv.travail[code]||[]).length?'<div class="tv-histo"><div class="tv-histo-t">Derniers relevés</div>'
        + (_tv.travail[code]||[]).slice(-5).reverse().map(function(e){ return '<div class="tv-histo-l"><span><i class="ph '+(e.type==="neg"?"ph-arrow-down":"ph-arrow-up")+'"></i> '+echapH(e.label||"")+'</span><b>'+tvDispPts(e.pts)+'</b></div>'; }).join("")
        +'</div>':'')
