function tvFermerPop(){ const b=document.getElementById("tvPop"); if(b)b.remove(); }
function tvEvent(code,compId){
  const cp=_tv.comport.filter(function(x){return x.id===compId;})[0]; if(!cp)return;
  tvAjouterEvent(code,{label:cp.label, ic:cp.ic, type:cp.type, pts:cp.pts});
}
async function tvEventLibre(code){
  const desc=await dlgSaisir("Que s'est-il passé ?"); if(desc==null)return;
  const t=(desc||"").trim(); if(!t)return;
  let p=await dlgSaisir("Points ? (ex. +1, -0,5)","-0,5"); if(p==null)return;
  p=parseFloat(String(p).replace(",",".")); if(isNaN(p))p=0; p=Math.max(-5,Math.min(5,p));
  tvAjouterEvent(code,{label:t.slice(0,80), ic:(p<0?"minus-circle":p>0?"plus-circle":"circle"), type:(p<0?"neg":p>0?"pos":"neu"), pts:p});
}
function tvAjouterEvent(code,base){
  if(!_tv.periode){ toast("Ouvrez d'abord une période."); return; }
  if(_tv.periode.close){ toast("Cette période est clôturée. Rouvrez-la pour noter."); tvFermerPop(); return; }
  const ev=Object.assign({id:tvUid(), periodeId:_tv.periode.id, date:Date.now()}, base);
  _tv.travail[code]=(_tv.travail[code]||[]).concat([ev]);
  const c=tvCol(_tv.cid,"travailEleve"); if(!c)return;
  const FV=(typeof firebase!=="undefined")?firebase.firestore.FieldValue:null;
  const maj = FV ? {code:code, events:FV.arrayUnion(ev)} : {code:code, events:_tv.travail[code]};
  c.doc(code).set(maj,{merge:true})
    .then(function(){ toast(tvNom(code)+" · "+base.label+" ("+tvDispPts(base.pts)+") · note "+tvDispNote(tvNoteEleve(code))); })
    .catch(function(){ toast("Le relevé n'a pas pu être enregistré."); });
  tvFermerPop(); tvRendre();
}

/* ---------- Période ---------- */
function tvNouvellePeriode(silencieux){
  const c=tvCol(_tv.cid,"travailPeriode"); if(!c)return;
  const fin=new Date(); fin.setMonth(fin.getMonth()+3);
  const doc={nom:"Période "+(_tv.periodes.length+1), debut:Date.now(), fin:fin.getTime(), close:false, base:_tv.base};
  const ref=c.doc();
  ref.set(doc).then(function(){
    _tv.periode=Object.assign({id:ref.id},doc); _tv.periodes.push(_tv.periode);
    if(!silencieux)toast("Nouvelle période ouverte.");
    tvRendre();
  }).catch(function(){ toast("Impossible de créer la période."); });
}
function tvPeriodeModifier(){
  const p=_tv.periode; if(!p)return;
  const z=document.getElementById("zone");
  const b=document.createElement("div"); b.id="tvPop"; b.className="voc-pop-fond";
  b.onclick=function(ev){ if(ev.target===b)tvFermerPop(); };
  const dISO=p.fin?new Date(p.fin).toISOString().slice(0,10):"";
  b.innerHTML='<div class="voc-pop" style="max-width:420px;position:relative">'
    +'<button class="ch-croix" onclick="tvFermerPop()" aria-label="Fermer"><i class="ph ph-x"></i></button>'
    +'<h3 style="margin:0 0 12px;padding-right:36px">Modifier la période</h3>'
    +'<label class="vt-l">Nom<input id="tvPerNom" class="vt-in" maxlength="60" value="'+echapH(p.nom||"")+'"></label>'
    +'<label class="vt-l" style="margin-top:12px">Date de clôture prévue <span style="font-weight:400;color:var(--encre-doux)">(modifiable à tout moment)</span>'
    +'<input id="tvPerFin" class="vt-in" type="date" value="'+dISO+'"></label>'
    +'<div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap">'
    +'<button class="rm-cta" onclick="tvPeriodeSauver()"><i class="ph-fill ph-floppy-disk"></i> Enregistrer</button>'
    +'<button class="action btn-nouv" onclick="tvFermerPop();tvNouvellePeriode()"><i class="ph ph-plus"></i> Nouvelle période</button>'
    +'</div></div>';
  document.body.appendChild(b);
}
function tvPeriodeSauver(){
  const p=_tv.periode; if(!p)return;
  const nom=(((document.getElementById("tvPerNom")||{}).value)||"").trim()||p.nom||"Période";
  const finV=((document.getElementById("tvPerFin")||{}).value)||"";
  const fin=finV?new Date(finV+"T18:00:00").getTime():p.fin||null;
  tvCol(_tv.cid,"travailPeriode").doc(p.id).set({nom:nom,fin:fin},{merge:true}).then(function(){
    p.nom=nom; p.fin=fin; tvFermerPop(); toast("Période mise à jour."); tvRendre();
  }).catch(function(){ toast("Enregistrement impossible."); });
}
async function tvCloturer(){
  const p=_tv.periode; if(!p)return;
  if(!await dlgConfirmer("Clôturer « "+(p.nom||"la période")+" » ?\n\nLes notes de cette période seront figées (vous pourrez en ouvrir une nouvelle). Vous pourrez toujours rouvrir cette période plus tard."))return;
  tvCol(_tv.cid,"travailPeriode").doc(p.id).set({close:true, clotureLe:Date.now()},{merge:true}).then(function(){
    p.close=true; _tv.periode=null; toast("Période clôturée."); ecranTravailProf(_tv.cid);
  }).catch(function(){ toast("Clôture impossible."); });
}

