  Object.keys(devMeta).forEach(function(id){ const m=devMeta[id], t=m.ouvre||0;
    if(t===0||(t>=b.deb&&t<=b.fin))colFor("d:"+id,m.nom,m.coef,m.bonus,t,"d"); });
