let _gbTri={key:"nom",sens:1};
function evGbTrier(key){
  if(_gbTri.key===key)_gbTri.sens=-_gbTri.sens;
  else _gbTri={key:key,sens:(key==="nom")?1:-1};   /* noms A→Z, chiffres du plus haut d'abord */
  if(typeof evalsRendre==="function")evalsRendre();
}
/* Un tableau du carnet : colonnes passées en paramètre, colonne finale = moyenne
   (évaluations demandées) ou note bonus (évaluations libres). */
function gbTableHTML(classId,g,cols,type){
  const bonusT=(type==="bonus");
  let rows=g.rows.slice();
  if(_gbNom.trim()){
    const q=norm(_gbNom);
    rows=rows.filter(function(r){ return norm(r.nom||"").indexOf(q)>=0 || norm(r.code||"").indexOf(q)>=0; });
  }
  const tri=_gbTri, cleValide=(tri.key==="nom"||tri.key==="moy"||tri.key==="bonus"||cols.some(function(c){return c.key===tri.key;}));
  const key=cleValide?tri.key:"nom", sens=cleValide?tri.sens:1;
  rows.sort(function(a,b){
    if(key==="nom")return String(a.nom||"￿").toLowerCase().localeCompare(String(b.nom||"￿").toLowerCase(),"fr",{numeric:true})*sens;
    let va,vb;
    if(key==="moy"){va=a.moy;vb=b.moy;} else if(key==="bonus"){va=a.bonus;vb=b.bonus;}
    else {va=(a.cells[key]||{}).count;vb=(b.cells[key]||{}).count;}
    if(va==null&&vb==null)return 0; if(va==null)return 1; if(vb==null)return -1;
    return (va-vb)*sens;
  });
  const fleche=function(k){ return _gbTri.key===k?(_gbTri.sens>0?" ▲":" ▼"):""; };
  const actif=function(k){ return _gbTri.key===k?" gb-actif":""; };
  const cleFin=bonusT?"bonus":"moy";
  const libFin=bonusT?"Note bonus":"Moy.";
  /* la moyenne générale ne s'affiche qu'au carnet des évaluations demandées,
     et seulement si le professeur donne un poids à la note bonus */
  const avecGen=!bonusT&&g.reg.coefBonus>0;
  const nb1=function(x){ return String(Math.round(x*100)/100).replace(".",","); };
  const titreFin=bonusT
    ? "NOTE BONUS sur 20, à saisir dans un devoir Pronote à part : socle des "+g.reg.socle+" meilleures évaluations libres (à "+String(g.reg.seuil).replace(".",",")+"/20 ou plus) + "+String(g.reg.pas).replace(".",",")+" point par évaluation réussie en plus"
    : "Moyenne des évaluations demandées (coefficients compris)";
  let h='<div class="gb-wrap"><table class="gradebook"><thead><tr>'
    +'<th class="gb-nom'+actif("nom")+'" onclick="evGbTrier(\'nom\')" title="Trier par nom">Nom'+fleche("nom")+'</th>'
    +'<th class="gb-'+(bonusT?"bonus":"moy")+actif(cleFin)+'" onclick="evGbTrier(\''+cleFin+'\')" title="'+titreFin+' · clique pour trier">'+libFin+fleche(cleFin)+'</th>'
    + cols.map(function(c,ci){ const edit=(c.src==="m"||c.src==="d"||c.src==="L"||c.src==="P");
        const sous=[evColDate(c),(c.coef&&c.coef!=1)?"×"+c.coef:""].filter(Boolean).join(" · ");
        const nm=echapH(c.nom)+(sous?'<span class="gb-col-sous">'+sous+'</span>':'');
        const ctx=edit?' oncontextmenu="event.preventDefault();evColEditer(\''+classId+'\',\''+c.key+'\');return false"':'';
        return '<th class="gb-eval'+(ci%2?" gb-b":"")+actif(c.key)+'" onclick="evGbTrier(\''+c.key+'\')"'+ctx+' title="'+echapH(c.nom)+(c.coef&&c.coef!=1?" · coef "+c.coef:"")+' · clic gauche = trier'+(edit?", clic droit = modifier"+(c.src==="m"?"":" ou voir les questions ratées"):"")+'">'
          +'<div class="gb-rot"><span>'+nm+fleche(c.key)+'</span></div></th>'; }).join("")
    +(avecGen?'<th class="gb-gen'+actif("generale")+'" onclick="evGbTrier(\'generale\')" title="MOYENNE GÉNÉRALE : évaluations demandées (coefficient '+nb1(g.reg.coefOff)+') et note bonus (coefficient '+nb1(g.reg.coefBonus)+'), réglables dans Paramètres → Règles de la classe · clique pour trier">Générale'+fleche("generale")+'</th>':'')
    +'</tr></thead><tbody>';
  rows.forEach(function(r){
    const val=bonusT?r.bonus:r.moy;
    const coul=val==null?"var(--encre-doux)":(bonusT?"var(--or-texte)":(val>=14?"var(--juste)":(val>=10?"var(--or-texte)":"var(--faux)")));
    const coulNom=(bonusT?r.bonus:r.moy)==null?"var(--encre-doux)":coul;
    h+='<tr><td class="gb-nom" style="cursor:pointer" onclick="ecranEvalEleve(\''+classId+'\',\''+r.code+'\')" title="Voir le détail"><b style="color:'+coulNom+'">'+(r.nom?echapH(r.nom):'<span style="color:var(--encre-doux)">'+r.code+'</span>')+'</b></td>'
      +'<td class="gb-'+(bonusT?"bonus":"moy")+'"'+((bonusT&&r.bonusInfo)?' title="'+evBonusDetail(r.bonusInfo)+(r.generaleInfo&&!r.generaleInfo.compte?" · ne fait pas monter la moyenne, elle n\'est donc pas comptée":"")+'"':'')+'>'
      +(val==null?'<b style="color:'+coul+';font-size:1.05rem;background:transparent">-</b>'
        :(bonusT&&r.generaleInfo&&!r.generaleInfo.compte
          ? '<b class="gb-inutile" style="font-size:1.05rem">('+String(val).replace(".",",")+'/20)</b>'
          : '<b style="color:'+coul+';font-size:1.05rem;background:'+evMoyFond(val)+'">'+String(val).replace(".",",")+'/20</b>'))+'</td>'
      + cols.map(function(c,ci){ const cell=r.cells[c.key]||{}; const old=(r.hist&&r.hist[c.key])||[];
          const bcls=ci%2?" gb-b":"";
          const disp=(cell.txt==null?'<span style="color:var(--ligne)">·</span>':(cell.count==null?'<span style="color:var(--faux)" title="Ne compte pas">'+cell.txt+'</span>':cell.txt));
          let dv=""; if(cell.raw!=null&&cell.raw!==""){ dv=(typeof cell.raw==="number")?String(Math.round(cell.raw*10)/10).replace(".",","):String(cell.raw); }
          let inner;
          if(c.src==="L"){ const nb=old.length; inner=disp+(nb>1?' <span style="color:var(--encre-doux);font-size:.78em" title="'+nb+' passages">('+nb+')</span>':''); }
          else { const oldTxt=old.map(function(o){ return '<span style="color:var(--encre-doux);text-decoration:line-through;font-size:.82em" title="Note précédente">'+String(Math.round(o*10)/10).replace(".",",")+'</span>'; }).join(" "); inner=(oldTxt?oldTxt+" ":"")+disp; }
          const ctx=' oncontextmenu="return evCellMenu(event,\''+classId+'\',\''+c.key+'\',\''+r.code+'\')"';
          return '<td class="gb-eval-c'+bcls+' gb-cell" tabindex="0" data-cl="'+classId+'" data-k="'+c.key+'" data-c="'+r.code+'" data-v="'+echapH(dv)+'"'
            +' onclick="gbStartEdit(this)"'+ctx+' title="Clic = saisir (nombre, ou A/n/w/r) · flèches = se déplacer · clic droit = '+(c.src==="L"?"historique":"refaire / effacer")+'">'+inner+'</td>'; }).join("")
      +(avecGen?'<td class="gb-gen"'+(r.generaleInfo?' title="'+echapH(evGeneraleDetail(r.generaleInfo))+'"':'')+'>'
        +(r.generale!=null?'<b>'+String(r.generale).replace(".",",")+'/20</b>'
          +'<span class="gb-gen-d">'+(r.bonus==null?'sans bonus'
            :(r.generaleInfo&&r.generaleInfo.compte
               ? String(r.moy).replace(".",",")+' · bonus '+String(r.bonus).replace(".",",")
               : String(r.moy).replace(".",",")+' <span class="gb-inutile">(bonus '+String(r.bonus).replace(".",",")+')</span>'))+'</span>'
          :'<span style="color:var(--encre-doux)">-</span>')+'</td>':'')
      +'</tr>';
  });
  const moyCl=bonusT?g.classBonus:g.classMoy;
  h+='<tr class="gb-classe"><td class="gb-nom">Moyenne de classe</td>'
    +'<td class="gb-'+(bonusT?"bonus":"moy")+'">'+(moyCl==null?"-":String(moyCl).replace(".",",")+"/20")+'</td>'
    + cols.map(function(c,ci){return '<td class="'+(ci%2?"gb-b":"")+'"></td>';}).join("")
    +(avecGen?'<td class="gb-gen">'+(g.classGen==null?"-":'<b>'+String(g.classGen).replace(".",",")+'/20</b>')+'</td>':'')
    +'</tr></tbody></table></div>';
  return h;
}
/* ---------- Carnet éditable : saisie inline + navigation clavier (façon tableur) ---------- */
let _gbFocus=null;
function gbStartEdit(td){
  if(!td||td.querySelector("input"))return;
  const cur=(td.getAttribute("data-v")||"").replace(/"/g,"&quot;");
  td.setAttribute("data-prev",td.innerHTML);
  td.innerHTML='<input class="gb-in" type="text" inputmode="decimal" value="'+cur+'">';
  const inp=td.querySelector("input"); if(!inp)return; inp.focus(); inp.select();
  let done=false;
  inp.addEventListener("keydown",function(ev){
    if(ev.key==="Enter"){ ev.preventDefault(); done=true; gbCommit(td,inp.value,"down"); }
    else if(ev.key==="Escape"){ ev.preventDefault(); done=true; td.innerHTML=td.getAttribute("data-prev")||""; td.focus(); }
    else if(ev.key==="Tab"){ ev.preventDefault(); done=true; gbCommit(td,inp.value,ev.shiftKey?"left":"right"); }
  });
  inp.addEventListener("blur",function(){ if(done)return; done=true; gbCommit(td,inp.value,null); });
}
function gbCommit(td,val,move){ evSetNote(td.getAttribute("data-cl"),td.getAttribute("data-k"),td.getAttribute("data-c"),val,move); }
function gbMove(td,dir){
  if(!td)return; const tr=td.parentNode, tb=tr.parentNode, ci=td.cellIndex; let target=null;
  if(dir==="ArrowLeft"||dir==="ArrowRight"){ let n=td, step=(dir==="ArrowRight")?"nextElementSibling":"previousElementSibling";
    while((n=n[step])){ if(n.classList&&n.classList.contains("gb-cell")){target=n;break;} } }
  else { const rows=[].slice.call(tb.querySelectorAll("tr")), ri=rows.indexOf(tr), dr=(dir==="ArrowDown")?1:-1;
    for(let r=ri+dr;r>=0&&r<rows.length;r+=dr){ const cell=rows[r].cells[ci]; if(cell&&cell.classList&&cell.classList.contains("gb-cell")){target=cell;break;} } }
  if(target)target.focus();
}
function evSetNote(classId,key,code,val,move){
  /* Valeur = nombre 0-20, code A/n/w/r, ou vide (efface). Stockée sur le doc élève
     dans `carnet[colKey]` (couche « saisie prof » par-dessus les notes dérivées :
     copies en ligne, évals manuelles, meilleure note libre). */
  /* Vide = "" : c'est une SAISIE EXPLICITE « pas de note ici », qui EFFACE la note
     dérivée (copie en ligne, éval manuelle…) et persiste. On n'utilise plus
     FieldValue.delete pour effacer (ça faisait revenir la note dérivée) : delete est
     réservé à « Rétablir la note de l'élève » (evResetNote). */
  const t=String(val==null?"":val).trim(); let store="";
  if(t!==""){ const low=t.toLowerCase();
    if(low==="a")store="A"; else if(low==="n")store="n"; else if(low==="w")store="w";
    else if(low==="r"||low==="nr")store="r"; else if(low==="r*"||low==="nr*")store="z";
    else { const num=parseFloat(t.replace(",",".")); if(isNaN(num)||num<0||num>20){ toast("Note entre 0 et 20, ou un code : A (absent), n (non noté), w (compte 0), NR (non rendu, ne compte pas), NR* (non rendu, compte 0)."); if(typeof evalsRendre==="function")evalsRendre(); return; } store=Math.round(num*100)/100; }
  }
  const s=fbStore(); if(!s){svcIndispo();return;}
  const o={}; o[key]=store;
  s.collection("classes").doc(classId).collection("eleves").doc(code).set({carnet:o},{merge:true})
    .catch(function(){toast("Échec de l'enregistrement : vérifie que tes règles Firestore autorisent le professeur (à republier si besoin).");});
  _evEleves[classId]=_evEleves[classId]||{}; const el=(_evEleves[classId][code]=_evEleves[classId][code]||{});
  el.carnet=el.carnet||{}; el.carnet[key]=store;
  _gbFocus={key:key,code:code,move:move};
  if(typeof evalsRendre==="function")evalsRendre();
  setTimeout(function(){ const f=_gbFocus; _gbFocus=null; if(!f)return;
    const esc=(window.CSS&&CSS.escape)?CSS.escape:function(x){return x;};
    const td=document.querySelector('td.gb-cell[data-k="'+esc(f.key)+'"][data-c="'+esc(f.code)+'"]'); if(!td)return;
    td.focus(); if(f.move)gbMove(td,f.move==="down"?"ArrowDown":(f.move==="right"?"ArrowRight":"ArrowLeft")); },0);
}
/* Rétablir la note DÉRIVÉE de l'élève : on retire l'override du carnet (delete),
   la case réaffiche alors la note d'origine (copie en ligne, éval manuelle…). */
function evResetNote(classId,key,code){
  const s=fbStore(); if(!s){svcIndispo();return;}
  s.collection("classes").doc(classId).collection("eleves").doc(code)
    .set({carnet:{[key]:firebase.firestore.FieldValue.delete()}},{merge:true})
    .catch(function(){toast("Échec : vérifie que tes règles Firestore autorisent le professeur.");});
  const el=((_evEleves[classId]||{})[code]); if(el&&el.carnet)delete el.carnet[key];
  toast("Note de l'élève rétablie.");
  if(typeof evalsRendre==="function")evalsRendre();
}
if(!window._gbKb){ window._gbKb=true; document.addEventListener("keydown",function(ev){
  const td=ev.target&&ev.target.closest&&ev.target.closest("td.gb-cell"); if(!td)return;
  if(td.querySelector("input"))return;   /* en cours d'édition : géré par l'input */
  const k=ev.key;
  if(k==="ArrowRight"||k==="ArrowLeft"||k==="ArrowUp"||k==="ArrowDown"){ ev.preventDefault(); gbMove(td,k); }
  else if(k==="Enter"||k==="F2"){ ev.preventDefault(); gbStartEdit(td); }
  else if(k==="Delete"||k==="Backspace"){ ev.preventDefault(); gbCommit(td,"",null); }
  else if(k.length===1&&/[0-9.,a-zA-Z]/.test(k)){ ev.preventDefault(); gbStartEdit(td); const inp=td.querySelector("input"); if(inp){ inp.value=(k===","?".":k); try{inp.setSelectionRange(inp.value.length,inp.value.length);}catch(e){} } }
}); }
/* Bandeau d'indicateurs (moyenne, réussite, évalués, évaluations données),
   centré, façon « Option A » de la refonte. */
/* Bandeau générique : cartes {l:libellé, v:valeur (HTML), c:couleur?, or:bool?}. */
function evKpiBandeau(cards){
  return '<div class="ev-kpis">'+cards.map(function(k){
    return '<div class="ev-kpi'+(k.or?" or":"")+'"><div class="ev-kpi-l">'+k.l+'</div>'
      +'<div class="ev-kpi-v"'+(k.c?' style="color:'+k.c+'"':'')+'>'+k.v+'</div></div>';
  }).join("")+'</div>';
}
/* Couleur d'une moyenne /20 selon le seuil (vert / or / rouge). */
function evMoyFond(m,seuilVert){ if(m==null)return "transparent"; const sv=seuilVert||14;
  return m>=sv?"rgba(26,156,107,.14)":(m>=10?"rgba(242,201,76,.24)":"rgba(198,40,40,.10)"); }
function evMoyCoul(m,seuilVert){ if(m==null)return "var(--encre)"; const sv=seuilVert||14;
  return m>=sv?"var(--juste)":(m>=10?"var(--or-texte)":"var(--faux)"); }
/* Les trois moyennes de la classe tiennent dans UNE carte : trois vignettes
   séparées prenaient toute la largeur pour trois nombres. */
function evKpiHTML(g){
  const nb=function(x){ return x==null?'<i>-</i>':String(x).replace(".",",")+'<span>/20</span>'; };
  const bloc=function(lib,val,coul,or){
    return '<div class="ev-moy3-i'+(or?" or":"")+'"><span>'+lib+'</span>'
      +'<b'+(coul?' style="color:'+coul+'"':'')+'>'+val+'</b></div>'; };
  let h='<div class="ev-moy3"><div class="ev-moy3-t">Moyennes<br>de la classe</div>'
    +bloc("Évaluations demandées",nb(g.classMoy),evMoyCoul(g.classMoy))
    +bloc("Note bonus",nb(g.classBonus),"var(--or-texte)",true);
  if(g.reg&&g.reg.coefBonus>0)h+=bloc("Moyenne générale",nb(g.classGen),evMoyCoul(g.classGen));
  return h+'</div>'+evAlertesHTML(g);
}
/* Ce qu'il reste à faire, sur une seule ligne : rien d'affiché s'il n'y a rien. */
function evAlertesHTML(g){
  const classId=_evClasse, rows=g.rows||[];
  const puces=[];
  const aNoter=(typeof _evANoter!=="undefined"&&_evANoter[classId])||0;
  if(aNoter)puces.push('<button class="gb-alerte rouge" onclick="evVue(\'chant\')">'
    +'<b>'+aNoter+'</b> copie'+(aNoter>1?"s":"")+' de chant à écouter</button>');
  let vig=0;
  try{ const l=_evalsCache[classId]||[], b=evBornesPeriode(evPeriodeCourante(classId),classId);
    vig=l.filter(function(e){ return evEstEpreuve(e)&&(e.fait||0)>=b.deb&&(e.fait||0)<=b.fin&&suspicionEval(e,{cid:classId,liste:l}).niveau>=1; }).length; }catch(e){}
  if(vig)puces.push('<button class="gb-alerte or" onclick="evVue(\'vigil\')">'
    +'<b>'+vig+'</b> épreuve'+(vig>1?"s":"")+' à vérifier</button>');
  /* rien à signaler : pas de ligne du tout, la place revient au carnet */
  return puces.length?'<div class="gb-alertes">'+puces.join("")+'</div>':"";
}
let _gbBonusOuvert=false;   /* le carnet bonus reste replié tant qu'on ne l'ouvre pas */
let _gbOffOuvert=false;     /* le carnet des évaluations demandées s'ouvre à la demande, lui aussi */
/* ---------- Fusion de colonnes du carnet ---------- */
function carnetFusionsDe(classId){ const cl=(_profClasses||[]).filter(function(c){ return c.id===classId; })[0]; return (cl&&cl.carnetFusions)||{}; }
function evFusionBarreHTML(classId,colsOff){
  const fus=carnetFusionsDe(classId), simples=colsOff.filter(function(c){ return c.src!=="F"; });
  const faites=colsOff.filter(function(c){ return c.src==="F"; });
  if(simples.length<2&&!faites.length)return "";
  return '<div class="gbf-barre">'
    +(simples.length>=2?'<button type="button" class="action btn-nouv gbf-btn" onclick="evFusionOuvrir(\''+classId+'\')"><i class="ph ph-arrows-merge"></i> Fusionner des colonnes</button>':'')
    +faites.map(function(c){ const fid=c.key.slice(2);
      return '<span class="gbf-chip" title="'+escapeHtml(c.membres.map(function(k){ return k; }).length+" colonnes réunies")+'"><i class="ph-fill ph-arrows-merge"></i> '+echapH(c.nom)+' <small>('+c.membres.length+' colonnes)</small>'
        +'<button type="button" title="Séparer à nouveau" aria-label="Séparer" onclick="evFusionDefaire(\''+classId+'\',\''+fid+'\')"><i class="ph ph-x"></i></button></span>'; }).join("")
    +'</div>';
}
function evFusionOuvrir(classId){
  const g=evGradebookData(classId,true), l=g.cols.filter(function(c){ return !c.bonus&&c.src!=="F"; });
  evFusionFermer();
  const d=document.createElement("div"); d.className="gbf-fond"; d.id="gbfFond";
  d.innerHTML='<div class="gbf-boite" role="dialog" aria-modal="true" aria-label="Fusionner des colonnes">'
    +'<h3><i class="ph ph-arrows-merge"></i> Fusionner des colonnes</h3>'
    +'<p>Cochez les colonnes qui correspondent à <b>la même évaluation</b> donnée à des groupes d\u2019élèves différents. Elles deviendront une seule colonne&nbsp;: chaque élève y garde sa note (la meilleure s\u2019il en a plusieurs). Vous pourrez les séparer à nouveau.</p>'
    +'<div class="gbf-liste">'+l.map(function(c){
      const nb=g.rows.filter(function(r){ const x=r.cells[c.key]; return x&&x.raw!==""&&x.raw!=null; }).length;
      return '<label><input type="checkbox" value="'+escapeHtml(c.key)+'" onchange="evFusionMajNom()" data-nom="'+escapeHtml(c.nom)+'"> <span><b>'+echapH(c.nom)+'</b><small>'+nb+' note'+(nb>1?"s":"")+'</small></span></label>'; }).join("")+'</div>'
    +'<label class="gbf-nom">Nom de la colonne fusionnée<input id="gbfNom" type="text" maxlength="60" placeholder="Ex : Évaluation La répétition" oninput="this.dataset.touche=1"></label>'
    +'<p id="gbfErr" class="gbf-err" hidden></p>'
    +'<div class="gbf-actions"><button type="button" class="action" onclick="evFusionFermer()">Annuler</button>'
    +'<button type="button" class="rm-cta" onclick="evFusionValider(\''+classId+'\')"><i class="ph-fill ph-arrows-merge"></i> Fusionner</button></div></div>';
  d.addEventListener("click",function(e){ if(e.target===d)evFusionFermer(); });
  document.body.appendChild(d);
}
function evFusionFermer(){ const d=document.getElementById("gbfFond"); if(d)d.remove(); }
function evFusionMajNom(){
  const n=document.getElementById("gbfNom"); if(!n||n.dataset.touche)return;
  const c=document.querySelector("#gbfFond .gbf-liste input:checked"); n.value=c?c.getAttribute("data-nom"):"";
}
function evFusionValider(classId){
  const cles=[].map.call(document.querySelectorAll("#gbfFond .gbf-liste input:checked"),function(x){ return x.value; });
  const err=document.getElementById("gbfErr");
  if(cles.length<2){ if(err){ err.hidden=false; err.textContent="Cochez au moins deux colonnes."; } return; }
  const nom=((document.getElementById("gbfNom")||{}).value||"").trim()||"Évaluation fusionnée";
  const fid="f"+Date.now().toString(36);
  const cl=(_profClasses||[]).filter(function(c){ return c.id===classId; })[0];
  if(cl){ cl.carnetFusions=Object.assign({},cl.carnetFusions||{}); cl.carnetFusions[fid]={nom:nom,cles:cles}; }
  const st=fbStore(); const o={}; o[fid]={nom:nom,cles:cles};
  if(st)st.collection("classes").doc(classId).set({carnetFusions:o},{merge:true}).catch(function(){ toast("La fusion n\u2019a pas pu être enregistrée : vérifie ta connexion."); });
  evFusionFermer(); toast("Colonnes fusionnées."); if(typeof evalsRendre==="function")evalsRendre();
}
async function evFusionDefaire(classId,fid){
  if(!await dlgConfirmer("Séparer à nouveau ces colonnes ?\n\nChaque évaluation retrouve sa propre colonne ; aucune note n'est perdue."))return;
  const cl=(_profClasses||[]).filter(function(c){ return c.id===classId; })[0];
  if(cl&&cl.carnetFusions){ cl.carnetFusions=Object.assign({},cl.carnetFusions); delete cl.carnetFusions[fid]; }
  const st=fbStore(), u={}; u["carnetFusions."+fid]=firebase.firestore.FieldValue.delete();
  if(st)st.collection("classes").doc(classId).update(u).catch(function(){ toast("La séparation n\u2019a pas pu être enregistrée."); });
  toast("Colonnes séparées."); if(typeof evalsRendre==="function")evalsRendre();
}
function evGbTablesHTML(classId){
  const g=evGradebookData(classId,true);
  const colsOff=g.cols.filter(function(c){ return !c.bonus; });
  const colsLib=g.cols.filter(function(c){ return c.bonus; });
  const aBonus=g.rows.some(function(r){ return r.bonus!=null; });
  let h="";
  /* Aucun nom connu sur cet appareil : le carnet n'affiche que des codes. */
  if(g.rows.length&&g.rows.every(function(r){ return !r.nom; }))
    h+='<p class="gb-avis">Les <b>noms ne sont pas sur cet appareil</b> : le carnet affiche les codes. '
      +'<a href="#" onclick="rosterClasse(\''+classId+'\');return false">Importer ma liste de classe</a></p>';
  /* Carnet des évaluations demandées : repliable lui aussi, pour atteindre le
     bonus sans faire défiler toute la classe. */
  const sansRien=g.rows.filter(function(r){ return r.moy==null&&r.bonus==null; }).length;
  const resumeOff=(colsOff.length?colsOff.length+' évaluation'+(colsOff.length>1?"s":""):'aucune évaluation')
    +' · '+g.rows.length+' élève'+(g.rows.length>1?"s":"")
    +(sansRien?' · <b class="gb-rouge">'+sansRien+'</b> sans aucune note':'');
  h+='<details class="gb-bloc"'+(_gbOffOuvert?" open":"")+' ontoggle="_gbOffOuvert=this.open">'
    +'<summary><i class="ph-fill ph-seal-check"></i> Évaluations demandées <span>'+resumeOff+'</span>'
    +'<span class="gb-sp"></span>'+evExportBtnHTML(classId,"tout")+'</summary>'
    +'<div class="gb-bloc-c">'
    +evChipsManuelles(classId,"cours")
    +evFusionBarreHTML(classId,colsOff)
    +((colsOff.length||g.rows.length)?gbTableHTML(classId,g,colsOff,"moy"):"")
    +(colsOff.length?"":'<p class="badge-vide">Aucune évaluation demandée sur cette période. '
      +'Assignez-en une dans <b>Donner du travail</b>, ou saisissez une note papier avec <b>Ajouter une évaluation</b>.</p>')
    +'</div></details>';
  /* Carnet bonus : replié, car on le consulte moins souvent que la moyenne. */
  const nbB=g.rows.filter(function(r){ return r.bonus!=null; }).length;
  const resume=(colsLib.length?colsLib.length+' leçon'+(colsLib.length>1?"s":""):'aucune leçon')
    +(g.classBonus!=null?' · moyenne '+String(g.classBonus).replace(".",",")+'/20':'')
    +(nbB?' · '+nbB+' élève'+(nbB>1?"s":"")+' concerné'+(nbB>1?"s":""):'');
  h+='<details class="gb-bloc"'+(_gbBonusOuvert?" open":"")+' ontoggle="_gbBonusOuvert=this.open">'
    +'<summary><i class="ph-fill ph-gift"></i> Évaluations bonus <span>'+resume+'</span>'
    +'<span class="gb-sp"></span>'+evExportBtnHTML(classId,"bonus")+'</summary>'
    +'<div class="gb-bloc-c">'
    +((colsLib.length||aBonus)?gbTableHTML(classId,g,colsLib,"bonus")
       :'<p class="badge-vide">Aucune évaluation passée librement sur cette période.</p>')
    +evBonusSyntheseHTML(g)+'</div></details>';
  return h;
}
/* Une phrase sur l'élève que le bonus fait le plus monter : c'est là que se voit
   le travail en autonomie, qu'aucune autre colonne ne montre. */
function evBonusSyntheseHTML(g){
  let best=null;
  (g.rows||[]).forEach(function(r){
    if(r.moy==null||r.bonus==null)return;
    const ecart=r.bonus-r.moy;
    if(ecart>2&&(!best||ecart>best.ecart))best={r:r,ecart:ecart};
  });
  if(!best)return "";
  const n=function(x){ return String(x).replace(".",","); };
  const q=best.r.nom?echapH(best.r.nom):best.r.code;
  return '<p style="color:var(--encre-doux);font-size:.85rem;margin:10px 2px 0">'
    +'<i class="ph ph-lightbulb" style="color:var(--or-texte)"></i> '
    +'<b>'+q+'</b> a '+n(best.r.moy)+'/20 de moyenne mais <b>'+n(best.r.bonus)+'/20</b> de note bonus : '
    +'beaucoup de travail en autonomie.</p>';
}
function evGradebookHTML(classId){
  const g=evGradebookData(classId,true);
  const aBonus=g.rows.some(function(r){ return r.bonus!=null; });
  if(!g.cols.length && !aBonus && !g.rows.length){
    return evKpiHTML(g)+'<p class="badge-vide">Aucun élève et aucune évaluation sur cette période. '
      +'Créez des codes dans « Élèves et codes », ou ajoutez une évaluation hors ligne.</p>';
  }
  return evKpiHTML(g)
    +'<div id="gbZone">'+evGbTablesHTML(classId)+'</div>'
    +evAideCarnetHTML(classId);
}
/* Le mode d'emploi et la règle de calcul : présents, mais repliés. */
function evAideCarnetHTML(classId){
  const r=bonusLibreDe(classId);
  const n=function(x){ return String(Math.round(x*100)/100).replace(".",","); };
  return '<details class="gb-bloc gb-aide"><summary><i class="ph ph-question"></i> Aide <span>saisie des notes et calcul du bonus</span></summary>'
    +'<div class="gb-bloc-c">'
    +'<p><b>Saisir une note</b> : cliquez une case, même vide. Les <b>flèches</b> déplacent la sélection, le <b>clic droit</b> efface, fait refaire ou montre l\'historique. '
    +'Codes acceptés : <b>A</b> absent, <b>n</b> non noté, <b>w</b> compte 0, <b>r</b> non rendu. Sur un en-tête : clic pour trier, clic droit pour renommer.</p>'
    +'<p><b>Note bonus</b> : moyenne des <b>'+r.socle+'</b> meilleures évaluations que l\'élève passe de lui-même (divisée par '+r.socle+' même s\'il en a moins), puis <b>+'+n(r.pas)+'</b> par évaluation réussie de plus. En dessous de <b>'+n(r.seuil)+'/20</b>, une évaluation est ignorée.</p>'
    +(r.coefBonus>0
      ? '<p><b>Moyenne générale</b> : demandées <b>×'+n(r.coefOff)+'</b> et note bonus <b>×'+n(r.coefBonus)+'</b>, mais seulement si le bonus <b>fait monter</b> l\'élève : sinon il s\'affiche en gris entre parenthèses et la générale reste la moyenne.</p>'
      : '<p><b>Moyenne générale</b> : désactivée (coefficient du bonus à 0).</p>')
    +'<p><a href="#" onclick="ecranParametres();return false">Modifier ces règles dans Paramètres → Règles de la classe</a></p>'
    +'</div></details>';
}
/* Historique complet des passages LIBRES d'un élève sur un thème (seule la meilleure compte). */
function evLibreHistorique(classId,tk,code){
  const lab=labelDe(classId,code)||code;
  const arr=(_evalsCache[classId]||[]).filter(function(e){ return e.code===code && !e._chant && !e._travail && !e._manuel && !e.dev && ((e.domaine||e.theme||"")===tk); })
    .sort(function(a,b){return (b.fait||0)-(a.fait||0);});
  const nomT=arr.length?(arr[0].theme||tk):tk;
  const diffN=function(d){return d===1?"Facile":(d===3?"Difficile":"Intermédiaire");};
  let bestV=-1; arr.forEach(function(e){ const v=(e.note||0)/(e.sur||20)*20; if(v>bestV)bestV=v; });
  const lignes=arr.map(function(e){ const v=(e.note||0)/(e.sur||20)*20; const estBest=(Math.abs(v-bestV)<1e-6);
    return '<tr'+(estBest?' style="background:var(--juste-fond)"':'')+'><td>'+(e.fait?fmtDateHeure(e.fait):"-")+'</td>'
      +'<td style="text-align:center"><b>'+String(Math.round(v*10)/10).replace(".",",")+'</b>'+(estBest?' <i class="ph-fill ph-star" style="color:var(--or-texte)" title="Meilleure note (retenue)"></i>':'')+'</td>'
      +'<td style="text-align:center">'+diffN(e.diff||2)+'</td>'
      +'<td style="text-align:center">'+(e.dureeMin||"-")+' min</td>'
      +'<td style="text-align:center"'+((e.sorties||0)>0?' style="color:var(--faux)"':'')+'>'+(e.sorties||0)+'</td>'
      +'<td style="text-align:center">'+(e.tpsEntrain!=null?fmtTemps(e.tpsEntrain):"-")+'</td></tr>'; }).join("")
    ||'<tr><td colspan="6" style="color:var(--encre-doux)">Aucun passage.</td></tr>';
  let b=document.getElementById("evHistPop"); if(b)b.remove();
  b=document.createElement("div"); b.id="evHistPop"; b.className="voc-pop-fond";
  b.innerHTML='<div class="voc-pop" style="max-width:580px;text-align:left"><h3 style="margin:0 0 4px"><i class="ph ph-clock-counter-clockwise"></i> '+echapH(lab)+' · '+echapH(nomT)+'</h3>'
    +'<p style="font-size:.85rem;color:var(--encre-doux);margin:0 0 10px">'+arr.length+' passage'+(arr.length>1?"s":"")+' · évaluation libre : <b>seule la meilleure note compte</b> (en bonus).</p>'
    +'<div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Date</th><th>Note</th><th>Difficulté</th><th>Durée</th><th>Sorties</th><th title="Temps d\'entraînement cumulé sur ce thème">Entraînement</th></tr></thead><tbody>'+lignes+'</tbody></table></div>'
    +'<div style="text-align:center;margin-top:12px"><button class="action btn-nouv" onclick="(function(){var x=document.getElementById(\'evHistPop\');if(x)x.remove();})()">Fermer</button></div></div>';
  document.body.appendChild(b);
  b.addEventListener("click",function(ev){ if(ev.target===b)b.remove(); });
}
/* Clic sur un en-tête de colonne : modifier nom / coefficient / bonus, ou supprimer. */
function evColEditer(classId,key){
  const src=key.charAt(0), id=key.slice(2);
  let nom="",coef=1,bonus=false;
  if(src==="m"){ const m=(_evManuel[classId]||[]).filter(function(x){return x.id===id;})[0]||{}; nom=m.titre||"Évaluation"; coef=(m.coef!=null?+m.coef:1); bonus=!!m.bonus; }
  else if(src==="d"){ const d=(_evDevoirs[classId]||[]).filter(function(x){return x.id===id;})[0]||{}; const v=(d.volets||[]).filter(function(x){return x.t==="eval";})[0]||{};
    nom=d.evalNom||d.titre||v.nom||((typeof nomCat==="function"&&v.cible)?nomCat(v.cible):v.cible)||"Évaluation"; coef=(d.coef!=null?+d.coef:1); bonus=!!d.bonus; }
  else if(src==="L"||src==="P"){ evLibreEditer(classId,key); return; }
  else { toast("Cette évaluation est héritée (ancienne) : non modifiable ici."); return; }
  let b=document.getElementById("evColPop"); if(b)b.remove();
  b=document.createElement("div"); b.id="evColPop"; b.className="voc-pop-fond";
  b.innerHTML=`<div class="voc-pop" style="max-width:440px;text-align:left">
      <h3 style="margin:0 0 10px"><i class="ph ph-pencil-simple"></i> Modifier l'évaluation</h3>
      <label style="display:block;font-size:.85rem;color:var(--encre-doux)">Nom
        <input id="ecNom" type="text" value="${echapH(nom)}" maxlength="60" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:8px;font-family:inherit;background:var(--surface);color:var(--encre)"></label>
      <label style="display:block;font-size:.85rem;color:var(--encre-doux);margin-top:10px">Coefficient
        <input id="ecCoef" type="number" min="0" max="10" step="0.5" value="${coef}" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:8px;font-family:inherit;background:var(--surface);color:var(--encre)"></label>
      <label class="chk" style="display:flex;align-items:center;gap:8px;margin-top:12px;cursor:pointer;background:var(--or-fond,rgba(242,201,76,.16));border:1px solid var(--or);border-radius:8px;padding:9px 11px">
        <input id="ecBonus" type="checkbox" ${bonus?"checked":""}> <span>Évaluation <b>bonus</b> : hors moyenne, elle compte comme une évaluation libre dans la colonne « Note bonus ».</span></label>
      ${src==="d"?`<button class="action btn-nouv eq-btn" onclick="evQuestionsEcran('${classId}','${key}')"><i class="ph ph-chart-bar-horizontal"></i> Questions ratées</button>`:""}
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px;align-items:center">
        <button class="action btn-corr" onclick="evColSauver('${classId}','${key}')"><i class="ph ph-check"></i> Enregistrer</button>
        <button class="action btn-nouv" onclick="(function(){var x=document.getElementById('evColPop');if(x)x.remove();})()">Annuler</button>
        <button class="action btn-nouv" style="border-color:var(--faux);color:var(--faux);margin-left:auto" onclick="evColSupprimer('${classId}','${key}')"><i class="ph ph-trash"></i> Supprimer</button>
      </div></div>`;
  document.body.appendChild(b);
  b.addEventListener("click",function(ev){ if(ev.target===b)b.remove(); });
}
/* ---------- Questions ratées (analyse d'une colonne du carnet) ---------- */
/* Les copies d'une colonne : évaluation demandée (d:<devoir>) ou libre (L:<thème>).
   On garde la dernière copie de chaque élève, celle que montre le carnet. */
function evQuestionsDossiers(classId,key){
  const src=key.charAt(0), id=key.slice(2);
  const par={};
  (_evalsCache[classId]||[]).forEach(function(e){
    if(e._manuel||e._chant||e._travail||!Array.isArray(e.detail)||!e.detail.length)return;
    const dansCol=(src==="d")?(e.dev===id):(src==="L"||src==="P")?(!e.dev&&(e.domaine||e.theme||"")===id):false;
    if(!dansCol)return;
    const k=e.code||"?";
    if(!par[k]||(e.fait||0)>(par[k].fait||0))par[k]=e;
  });
  return Object.keys(par).map(function(k){ return par[k]; });
}
/* Texte d'un énoncé sans balises, portées ni images : sert de clé de regroupement.
   La copie vient du navigateur de l'élève : on la lit avec DOMParser, qui
   n'exécute rien et ne charge aucune image (un innerHTML, lui, le ferait). */
function evQTexte(h){
  const src=String(h||"").replace(/<svg[\s\S]*?<\/svg>/gi," ");
  if(src.indexOf("<")<0)return src.replace(/\s+/g," ").trim();
  let t="";
  try{ t=new DOMParser().parseFromString(src,"text/html").body.textContent||""; }catch(e){ t=src.replace(/<[^>]*>/g," "); }
  return t.replace(/\s+/g," ").trim();
}
function evQuestionsAnalyse(dossiers){
  const g={};
  dossiers.forEach(function(e){ e.detail.forEach(function(d){
    const txt=evQTexte(d.q); if(!txt)return;
    const cle=txt.toLowerCase().slice(0,160);
    const x=g[cle]||(g[cle]={txt:txt.slice(0,200),n:0,ok:0,fautes:{}});
    x.n++; if(d.ok){ x.ok++; return; }
    const r=evQTexte(d.rep)||"(sans réponse)", sol=evQTexte(d.sol).replace(/^\s*R[ée]ponse\s*:\s*/i,"").replace(/\.\s*$/,"");
    const fk=r.toLowerCase()+"→"+sol.toLowerCase();
    const f=x.fautes[fk]||(x.fautes[fk]={rep:r.slice(0,80),sol:sol.slice(0,120),n:0}); f.n++;
  }); });
  return Object.keys(g).map(function(k){ const x=g[k];
    x.taux=Math.round(100*x.ok/x.n);
    x.top=Object.keys(x.fautes).map(function(f){ return x.fautes[f]; }).sort(function(a,b){ return b.n-a.n; }).slice(0,2);
    return x; }).sort(function(a,b){ return (a.taux-b.taux)||(b.n-a.n); });
}
function evQuestionsEcran(classId,key){
  const x0=document.getElementById("evColPop"); if(x0)x0.remove();
  const doss=evQuestionsDossiers(classId,key);
  const col=((evGradebookData(classId,true).cols||[]).filter(function(c){ return c.key===key; })[0]||{});
  const lignes=evQuestionsAnalyse(doss);
  const b=document.createElement("div"); b.id="evColPop"; b.className="voc-pop-fond";
  let h='<div class="voc-pop eq-pop" role="dialog" aria-label="Questions ratées"><button class="ch-croix" aria-label="Fermer" onclick="document.getElementById(\'evColPop\').remove()"><i class="ph ph-x"></i></button>'
    +'<h3 style="margin:0 0 4px;padding-right:36px"><i class="ph ph-chart-bar-horizontal"></i> Questions ratées</h3>'
    +'<p class="eq-sous">'+echapH(col.nom||"Évaluation")+' · '+doss.length+' copie'+(doss.length>1?"s":"")+' · de la plus ratée à la mieux réussie. '
    +'Les questions tirées au sort d\'un même type sont regroupées.</p>';
  if(!lignes.length)h+='<p class="badge-vide">Aucun détail de réponses pour cette évaluation (copies anciennes, ou saisies à la main).</p>';
  else h+='<div class="eq-liste">'+lignes.map(function(x){
      const coul=x.taux>=70?"var(--juste)":(x.taux>=40?"var(--or-texte)":"var(--faux)");
      return '<div class="eq-l"><div class="eq-tete"><span class="eq-pct" style="color:'+coul+'">'+x.taux+'%</span>'
        +'<span class="eq-txt">'+echapH(x.txt)+'</span><span class="eq-n">'+x.ok+'/'+x.n+'</span></div>'
        +'<div class="eq-barre"><span style="width:'+x.taux+'%;background:'+coul+'"></span></div>'
        +(x.top.length?'<div class="eq-fautes">'+x.top.map(function(f){
            return '<span><b>'+f.n+'×</b> « '+echapH(f.rep)+' »'+(f.sol?' au lieu de « '+echapH(f.sol)+' »':'')+'</span>'; }).join("")+'</div>':'')
        +'</div>'; }).join("")+'</div>';
  b.innerHTML=h+'</div>';
  document.body.appendChild(b);
  b.addEventListener("click",function(ev){ if(ev.target===b)b.remove(); });
}
/* Colonne d'une évaluation LIBRE (L:) ou libre passée en DEMANDÉE (P:) : nom affiché,
   et case « évaluation demandée » (compte dans la moyenne, avec un coefficient). */
function evLibreEditer(classId,key){
  const src=key.charAt(0), tk=key.slice(2);
  const cl=(_profClasses||[]).filter(function(x){return x.id===classId;})[0]||{};
  const p=(cl.libresDemandees||{})[tk]||null;
  const nomL=(cl.libreNoms||{})[tk]||"", nom=p?(p.titre||""):nomL, coef=(p&&p.coef!=null)?+p.coef:1;
  let b=document.getElementById("evColPop"); if(b)b.remove();
  b=document.createElement("div"); b.id="evColPop"; b.className="voc-pop-fond";
  b.innerHTML=`<div class="voc-pop" style="max-width:460px;text-align:left">
      <h3 style="margin:0 0 8px"><i class="ph ph-pencil-simple"></i> ${p?"Évaluation demandée (passée par les élèves seuls)":"Évaluation libre"}</h3>
      <p style="font-size:.82rem;color:var(--encre-doux);margin:0 0 10px">Les élèves l'ont passée <b>d'eux-mêmes</b> après les entraînements. ${p?"Elle compte dans la <b>moyenne</b> : pour chaque élève, sa <b>meilleure</b> note.":"Pour l'instant, elle compte dans la <b>note bonus</b>."}</p>
      <label style="display:block;font-size:.85rem;color:var(--encre-doux)">Nom affiché
        <input id="ecNomL" type="text" value="${echapH(nom)}" maxlength="60" placeholder="(nom du thème)" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:8px;font-family:inherit;background:var(--surface);color:var(--encre)"></label>
      <label class="chk" style="display:flex;align-items:flex-start;gap:8px;margin-top:12px;cursor:pointer;background:var(--or-fond,rgba(242,201,76,.16));border:1px solid var(--or);border-radius:8px;padding:9px 11px">
        <input id="ecDemandee" type="checkbox" ${p?"checked":""} onchange="document.getElementById('ecCoefWrap').style.display=this.checked?'block':'none'" style="margin-top:3px"> <span><b>Évaluation demandée</b> : elle compte dans la moyenne, comme une évaluation donnée en travail, et sort de la note bonus.</span></label>
      <label id="ecCoefWrap" style="display:${p?"block":"none"};font-size:.85rem;color:var(--encre-doux);margin-top:10px">Coefficient
        <input id="ecCoefL" type="number" min="0.5" max="10" step="0.5" value="${coef}" style="width:100%;margin-top:4px;padding:9px 10px;border:1px solid var(--ligne);border-radius:8px;font-family:inherit;background:var(--surface);color:var(--encre)"></label>
      <p style="font-size:.8rem;color:var(--encre-doux);margin:10px 0 0"><i class="ph ph-info"></i> Pour que les autres élèves la passent aussi, donne-la en <b>Travail à faire</b> (évaluation, même thème) : leurs notes arriveront dans la même colonne, et ceux qui l'ont déjà passée seront comptés comme l'ayant rendue.</p>
      <button class="action btn-nouv eq-btn" onclick="evQuestionsEcran('${classId}','${key}')"><i class="ph ph-chart-bar-horizontal"></i> Questions ratées</button>
      <div style="display:flex;gap:8px;margin-top:16px">
        <button class="action btn-corr" onclick="evLibreEnregistrer('${classId}','${tk}')"><i class="ph ph-check"></i> Enregistrer</button>
        <button class="action btn-nouv" onclick="(function(){var x=document.getElementById('evColPop');if(x)x.remove();})()">Annuler</button>
      </div></div>`;
  document.body.appendChild(b); b.addEventListener("click",function(ev){ if(ev.target===b)b.remove(); });
}
function evLibreEnregistrer(classId,tk){
  const s=fbStore(); if(!s){svcIndispo();return;}
  const nom=((document.getElementById("ecNomL")||{}).value||"").trim();
  const dem=!!((document.getElementById("ecDemandee")||{}).checked);
  let coef=parseFloat((document.getElementById("ecCoefL")||{}).value); if(isNaN(coef)||coef<=0)coef=1; coef=Math.min(10,coef);
  const cl=(_profClasses||[]).filter(function(x){return x.id===classId;})[0]||{};
  const FV=firebase.firestore.FieldValue, maj={}, P={};
  if(dem){
    /* nom du thème tel que l'élève l'enregistre : sert à reconnaître ses notes */
    const ex=(_evalsCache[classId]||[]).filter(function(e){ return (e.domaine||e.theme||"")===tk&&e.theme; })[0];
    const avant=(cl.libresDemandees||{})[tk]||{};
    P[tk]={nom:(ex&&ex.theme)||((typeof nomCat==="function")?nomCat(tk):tk),titre:nom,coef:coef,t:avant.t||Date.now()};
    maj.libresDemandees=P;
  } else {
    P[tk]=FV.delete(); maj.libresDemandees=P;
    const o={}; o[tk]=(nom?nom:FV.delete()); maj.libreNoms=o;
  }
  s.collection("classes").doc(classId).set(maj,{merge:true}).then(function(){
    cl.libresDemandees=cl.libresDemandees||{};
    if(dem)cl.libresDemandees[tk]=P[tk]; else { delete cl.libresDemandees[tk]; cl.libreNoms=cl.libreNoms||{}; if(nom)cl.libreNoms[tk]=nom; else delete cl.libreNoms[tk]; }
    const x=document.getElementById("evColPop"); if(x)x.remove();
    toast(dem?"Évaluation passée en demandée : elle compte dans la moyenne.":"Évaluation remise en libre (note bonus).");
    if(typeof evalsRendre==="function")evalsRendre();
  }).catch(function(){ toast("Échec de l'enregistrement : vérifie ta connexion."); });
}
function evLibreRenommer(classId,tk){
  const nom=((document.getElementById("ecNomL")||{}).value||"").trim();
  const s=fbStore(); if(!s){svcIndispo();return;}
  const o={}; o[tk]=(nom?nom:firebase.firestore.FieldValue.delete());
  s.collection("classes").doc(classId).set({libreNoms:o},{merge:true}).then(function(){
    const cl=(_profClasses||[]).filter(function(x){return x.id===classId;})[0];
    if(cl){ cl.libreNoms=cl.libreNoms||{}; if(nom)cl.libreNoms[tk]=nom; else delete cl.libreNoms[tk]; }
    const x=document.getElementById("evColPop"); if(x)x.remove();
    toast("Nom mis à jour."); if(typeof evalsRendre==="function")evalsRendre();
  }).catch(function(){ toast("Échec : vérifie tes règles Firestore."); });
}
function evColSauver(classId,key){
  const src=key.charAt(0), id=key.slice(2);
  const nom=((document.getElementById("ecNom")||{}).value||"").trim();
  let coef=parseFloat((document.getElementById("ecCoef")||{}).value); if(isNaN(coef)||coef<0)coef=1; coef=Math.min(10,coef);
  const bonus=!!((document.getElementById("ecBonus")||{}).checked);
  const s=fbStore(); if(!s){svcIndispo();return;}
  let ref,data={coef:coef,bonus:bonus};
  if(src==="m"){ ref=s.collection("classes").doc(classId).collection("notesManuelles").doc(id); if(nom)data.titre=nom; }
  else if(src==="d"){ ref=s.collection("classes").doc(classId).collection("devoirs").doc(id); if(nom)data.evalNom=nom; }
  else { return; }
  pendant("Enregistrement…",ref.set(data,{merge:true})).then(function(){
    const x=document.getElementById("evColPop"); if(x)x.remove();
    toast("Évaluation mise à jour."); delete _evalsCache[classId]; evalsClasse(classId);
  }).catch(function(){ toast("Échec : vérifie que tes règles Firestore sont publiées."); });
}
async function evColSupprimer(classId,key){
  const src=key.charAt(0), id=key.slice(2);
  if(!await dlgConfirmer("Supprimer définitivement cette évaluation et toutes les notes associées ?\n\nCette action est irréversible."))return;
  const s=fbStore(); if(!s){svcIndispo();return;}
  const fini=function(){ const x=document.getElementById("evColPop"); if(x)x.remove(); toast("Évaluation supprimée."); delete _evalsCache[classId]; evalsClasse(classId); };
  if(src==="m"){
    pendant("Suppression…",s.collection("classes").doc(classId).collection("notesManuelles").doc(id).delete()).then(fini).catch(function(){toast("Suppression impossible.");});
  } else if(src==="d"){
    pendant("Suppression…",
      s.collection("classes").doc(classId).collection("evals").get().then(function(snap){
        const del=[]; snap.forEach(function(d){ if((d.data()||{}).dev===id)del.push(d.ref); });
        return Promise.all(del.map(function(rf){return rf.delete().catch(function(){});}))
          .then(function(){ return s.collection("classes").doc(classId).collection("devoirs").doc(id).delete().catch(function(){}); });
      })
    ).then(fini).catch(function(){toast("Suppression impossible.");});
  } else { toast("Évaluation héritée : non supprimable ici."); }
}
/* « Faire refaire » : on pose un jeton sur le doc élève ; à sa prochaine connexion,
   l'évaluation (volet eval du devoir) se rouvre, même hors créneau, et sa nouvelle
   note remplace l'ancienne (le carnet prend la plus récente). */
async function evFaireRefaire(classId,code,devId){
  if(!devId){ toast("Cette évaluation ne peut pas être rouverte (évaluation héritée)."); return; }
  const lab=labelDe(classId,code)||code;
  if(!await dlgConfirmer("Faire REFAIRE cette évaluation à « "+lab+" » ?\n\nElle se rouvrira pour lui à sa prochaine connexion (même hors créneau), et sa nouvelle note remplacera l'ancienne."))return;
  const s=fbStore(); if(!s){svcIndispo();return;}
  const token=devId+"|"+Date.now();
  s.collection("classes").doc(classId).collection("eleves").doc(code)
    .set({refaire:firebase.firestore.FieldValue.arrayUnion(token)},{merge:true})
    .then(function(){ toast("« "+lab+" » pourra refaire l'évaluation à sa prochaine connexion."); })
    .catch(function(){ toast("Échec : vérifie tes règles Firestore."); });
}
/* Clic droit sur une note du carnet : menu « saisir une note / faire refaire » (façon Pronote). */
function evCellMenu(ev,classId,key,code){
  if(ev&&ev.preventDefault)ev.preventDefault();
  const src=key.charAt(0), id=key.slice(2); const lab=labelDe(classId,code)||code;
  const ferm="(function(){var x=document.getElementById('evCellPop');if(x)x.remove();})()";
  const btns=[];
  btns.push('<button class="action btn-nouv" onclick="'+ferm+';evSaisirNote(\''+classId+'\',\''+key+'\',\''+code+'\')"><i class="ph ph-pencil-simple"></i> Saisir / modifier la note</button>');
  btns.push('<button class="action btn-nouv" style="border-color:var(--faux);color:var(--faux)" onclick="'+ferm+';evSetNote(\''+classId+'\',\''+key+'\',\''+code+'\',\'\',null)"><i class="ph ph-eraser"></i> Effacer la note (laisser vide)</button>');
  /* si une note dérivée existe sous cet override, proposer de la rétablir */
  if((((_evEleves[classId]||{})[code]||{}).carnet||{})[key]!==undefined)
    btns.push('<button class="action btn-nouv" onclick="'+ferm+';evResetNote(\''+classId+'\',\''+key+'\',\''+code+'\')"><i class="ph ph-arrow-u-up-left"></i> Rétablir la note de l\'élève</button>');
  if(src==="d")
    btns.push('<button class="action btn-nouv" onclick="'+ferm+';evFaireRefaire(\''+classId+'\',\''+code+'\',\''+id+'\')"><i class="ph ph-arrow-counter-clockwise"></i> Faire refaire (en ligne)</button>');
  if(src==="L")
    btns.push('<button class="action btn-nouv" onclick="'+ferm+';evLibreHistorique(\''+classId+'\',\''+id+'\',\''+code+'\')"><i class="ph ph-clock-counter-clockwise"></i> Historique des passages</button>');
  let b=document.getElementById("evCellPop"); if(b)b.remove();
  b=document.createElement("div"); b.id="evCellPop"; b.className="voc-pop-fond";
  b.innerHTML='<div class="voc-pop" style="max-width:360px;text-align:left"><h3 style="margin:0 0 10px"><i class="ph ph-list-dashes"></i> '+echapH(lab)+'</h3>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'+btns.join("")
    +'<button class="action btn-nouv" onclick="'+ferm+'">Annuler</button></div></div>';
  document.body.appendChild(b);
  b.addEventListener("click",function(e2){ if(e2.target===b)b.remove(); });
  return false;
}
/* Note saisie à la main par le prof pour une éval EN LIGNE (élève sans appareil, copie papier). */
async function evSaisirNote(classId,key,code){
  const lab=labelDe(classId,code)||code;
  const v=await dlgSaisir("Note de « "+lab+" » sur 20, ou un code : A (absent), n (non noté), w (compte 0), r (non rendu). Laisse vide pour effacer :","");
  if(v===null)return;
  evSetNote(classId,key,code,v,null);
}
function evParEleve(classId){
  const tous=_evalsCache[classId]||[];
  const _b=evBornesPeriode(evPeriodeCourante(classId),classId);
  const par={};
  tous.forEach(function(e){
    if(e._travail||e._chant)return;
    if((e.fait||0)<_b.deb||(e.fait||0)>_b.fin)return;   /* comportement et chant ont leur propre onglet */
    const c=e.code||"?";
    const b=par[c]||(par[c]={code:c,nom:labelDe(classId,c),notes:[],raw:[],sorties:0,nb:0,der:0,
                              graves:0,signalees:0});
    const sur20=(e.note||0)/(e.sur||20)*20;
    b.notes.push(sur20); b.raw.push(e); b.nb++;
    b.sorties+=(e.sorties||0);
    if(e.fait>b.der)b.der=e.fait;
    const sp=suspicionEval(e);
    if(sp.niveau>=2)b.graves++;
    else if(sp.niveau===1)b.signalees++;
  });
  return Object.keys(par).map(function(c){
    const b=par[c];
    const _mo=evMoyDossiers(b.raw,classId,false);   /* seules les demandées comptent */
    b.moy=_mo?_mo.moy:null;
    const _nb=evNoteBonusDossiers(b.raw,classId);   /* note bonus : évaluations libres */
    b.bonusNote=_nb?_nb.note:null; b.bonusInfo=_nb;
    b.mini=b.nb?Math.round(Math.min.apply(null,b.notes)*10)/10:null;
    b.maxi=b.nb?Math.round(Math.max.apply(null,b.notes)*10)/10:null;
    const sortiesMoy=b.nb?b.sorties/b.nb:0;
    b.motifs=[];
    /* une seule épreuve très douteuse suffit à monter au niveau 2 */
    if(b.graves)b.motifs.push(b.graves+" épreuve"+(b.graves>1?"s":"")+" très douteuse"+(b.graves>1?"s":""));
    if(b.signalees)b.motifs.push(b.signalees+" épreuve"+(b.signalees>1?"s":"")+" à vérifier");
    if(sortiesMoy>2)b.motifs.push(String(Math.round(sortiesMoy*10)/10).replace(".",",")
      +" sorties de page en moyenne par évaluation");
    b.vig=b.graves?2:(b.signalees||sortiesMoy>2?1:0);
    return b;
  });
}
/* Date courte d'une colonne du carnet (« 12 sept. »), vide si on ne l'a pas. */
function evColDate(c){
  const t=c&&c.order;
  if(!t||t<=0||t>=9e14)return "";
  try{ return new Date(t).toLocaleDateString("fr-FR",{day:"numeric",month:"short"}); }catch(e){ return ""; }
}
/* Détail de la moyenne générale, en une phrase (infobulle du carnet). */
function evGeneraleDetail(g){
  if(!g)return "";
  const n=function(x){ return String(Math.round(x*10)/10).replace(".",","); };
  const c=function(x){ return String(Math.round(x*100)/100).replace(".",","); };
  if(g.bonus==null)return "Moyenne des évaluations demandées : "+n(g.moy)+"/20 (aucune note bonus).";
  if(!g.compte)return "Note bonus "+n(g.bonus)+"/20 : elle ne dépasse pas la moyenne des évaluations demandées ("
    +n(g.moy)+"/20), un bonus ne pouvant que faire monter, elle n'est pas comptée.";
  return "Moyenne des demandées "+n(g.moy)+"/20 (coefficient "+c(g.coefOff)+") et note bonus "
    +n(g.bonus)+"/20 (coefficient "+c(g.coefBonus)+") : elle fait monter l'élève à "+n(g.gen)+"/20.";
}
/* Détail d'une note bonus, en une phrase (infobulle du carnet). */
function evBonusDetail(b){
  if(!b)return "";
  const n=function(x){ return String(Math.round(x*10)/10).replace(".",","); };
  let t=b.nb+" évaluation"+(b.nb>1?"s":"")+" libre"+(b.nb>1?"s":"")+" réussie"+(b.nb>1?"s":"")
    +" · socle (les "+b.regles.socle+" meilleures ÷ "+b.regles.socle+") = "+n(b.socle);
  if(b.sup)t+=" · endurance "+b.sup+" × "+n(b.regles.pas)+" = +"+n(b.pts);
  if(b.manque)t+=" · il manque "+b.manque+" évaluation"+(b.manque>1?"s":"")+" pour un socle complet";
  if(b.ignorees)t+=" · "+b.ignorees+" sous "+n(b.regles.seuil)+"/20 ignorée"+(b.ignorees>1?"s":"");
  if(b.brut>20)t+=" · total réel "+n(b.brut)+", ramené à 20";
  return echapH(t);
}
/* Lignes « Nom<tab>Moyenne<tab>Note bonus », prêtes à coller dans Pronote :
   la moyenne des évaluations demandées et la note bonus sont deux colonnes
   distinctes, à saisir dans deux devoirs Pronote différents. */
function evElLignes(classId,quoi){
  /* on part du CARNET : tous les élèves de la classe y figurent, même sans note */
  const g=evGradebookData(classId,true);
  const n=function(x){ return x==null?"":String(x).replace(".",","); };
  return g.rows.slice().sort(function(a,b){
    return String(a.nom||"￿").localeCompare(String(b.nom||"￿"),"fr",{numeric:true});
  }).map(function(e){
    /* la note bonus se saisit dans un devoir Pronote à part : on l'exporte seule */
    if(quoi==="bonus")return (e.nom||e.code)+"\t"+n(e.bonus);
    return (e.nom||e.code)+"\t"+n(e.moy)+"\t"+n(e.bonus)+"\t"+n(e.generale);
  }).join("\n");
}
/* Une ligne par élève de la classe : le carnet (moyenne, note bonus) complété par
   les repères de la vue par élève (plus basse, plus haute, à vérifier). */
function evElLignesData(classId){
  const g=evGradebookData(classId,true);
  const par={}; evParEleve(classId).forEach(function(e){ par[e.code]=e; });
  return g.rows.slice().sort(function(a,b){
    return String(a.nom||"￿").localeCompare(String(b.nom||"￿"),"fr",{numeric:true});
  }).map(function(r){
    const e=par[r.code]||{nb:0,mini:null,maxi:null,motifs:[]};
    return {code:r.code, nom:r.nom, moy:r.moy, bonusNote:r.bonus, generale:r.generale, nb:e.nb||0,
            mini:e.mini, maxi:e.maxi, motifs:e.motifs||[]};
  });
}
/* Les notes seules, sans ligne de titres : à coller directement dans la colonne
   d'un devoir Pronote, sans avoir à ignorer la première ligne. */
function evElCopierBrut(classId,quoi){
  appPresse(evElLignes(classId,quoi));
  toast(quoi==="bonus"
    ? "Copié sans titres : une ligne par élève (nom, note bonus). Collez dans la grille de notes avec Ctrl+V."
    : "Copié sans titres : une ligne par élève (nom, moyenne, note bonus, générale). Collez dans la grille de notes avec Ctrl+V.");
}
function evElCopier(classId,quoi){
  if(quoi==="bonus"){
    appPresse("Nom\tNote bonus\n"+evElLignes(classId,"bonus"));
    toast("Note bonus copiée (nom, note). Dans Pronote : ouvrez le devoir de bonus, cliquez dans la première case puis Ctrl+V. La 1re ligne est un titre, à ignorer à l'import.");
    return;
  }
  appPresse("Nom\tMoyenne (évaluations demandées)\tNote bonus\tMoyenne générale\n"+evElLignes(classId));
  /* Pronote accepte le collage depuis le presse-papier : on rappelle la manipulation,
     et la ligne de titres se saute avec « ne pas importer les premières lignes ». */
  toast("Copié (nom, moyenne, note bonus, générale). Dans Pronote : ouvrez le devoir, cliquez dans la première case puis Ctrl+V. La 1re ligne est un titre, à ignorer à l'import.");
}
function evElExporter(classId,quoi){
  const l=evElLignesData(classId);
  if(quoi==="bonus"){
    const lb=[["Nom","Code","Note bonus (évaluations libres)"]].concat(l.map(function(e){
      return [e.nom||"", e.code, e.bonusNote==null?"":String(e.bonusNote).replace(".",",")]; }));
    csvTelecharger("museduc_note_bonus.csv", lb.map(function(x){
      return x.map(function(v){ return '"'+String(v).replace(/"/g,'""')+'"'; }).join(";"); }).join("\r\n"));
    toast("Notes bonus enregistrées (encodage Windows, lisible tel quel par Pronote et Excel).");
    return;
  }
  const lignes=[["Nom","Code","Évaluations","Moyenne (demandées)","Note bonus (libres)","Moyenne générale","Plus basse","Plus haute","À vérifier"]]
    .concat(l.map(function(e){
      return [e.nom||"", e.code, e.nb,
              e.moy==null?"":String(e.moy).replace(".",","),
              e.bonusNote==null?"":String(e.bonusNote).replace(".",","),
              e.generale==null?"":String(e.generale).replace(".",","),
              e.mini==null?"":String(e.mini).replace(".",","),
              e.maxi==null?"":String(e.maxi).replace(".",","),
              e.motifs.join(" ; ")];
    }));
  const csv=lignes.map(function(x){
    return x.map(function(v){ return '"'+String(v).replace(/"/g,'""')+'"'; }).join(";"); }).join("\r\n");
  csvTelecharger("museduc_moyennes.csv",csv);
  toast("Liste enregistrée (encodage Windows, lisible tel quel par Pronote et Excel).");
}
function evElImprimer(classId,quoi){
  const l=evElLignesData(classId);
  const cl=(_profClasses||[]).filter(function(c){return c.id===classId;})[0];
  if(quoi==="bonus"){
    let cb='<h1>Notes bonus : '+echapH((cl&&cl.nom)||"classe")+'</h1>'
      +'<div class="mini">'+l.length+' élève(s) · au '+new Date().toLocaleDateString("fr-FR")+'</div>'
      +'<table><tr><th>Nom</th><th>Note bonus</th></tr>';
    l.forEach(function(e){ cb+='<tr><td>'+echapH(e.nom||e.code)+'</td>'
      +'<td><b>'+(e.bonusNote==null?"-":String(e.bonusNote).replace(".",",")+"/20")+'</b></td></tr>'; });
    ouvrirImpression("Notes bonus de la classe", cb+'</table>');
    return;
  }
  let corps='<h1>Moyennes : '+echapH((cl&&cl.nom)||"classe")+'</h1>'
    +'<div class="mini">'+l.length+' élève(s) · au '+new Date().toLocaleDateString("fr-FR")+'</div>'
    +'<table><tr><th>Nom</th><th>Évaluations</th><th>Moyenne</th><th>Note bonus</th><th>Générale</th><th>Plus basse</th><th>Plus haute</th><th>À vérifier</th></tr>';
  l.forEach(function(e){
    corps+='<tr><td>'+echapH(e.nom||e.code)+'</td><td>'+e.nb+'</td>'
      +'<td><b>'+(e.moy==null?"-":String(e.moy).replace(".",",")+"/20")+'</b></td>'
      +'<td>'+(e.bonusNote==null?"-":String(e.bonusNote).replace(".",",")+"/20")+'</td>'
      +'<td><b>'+(e.generale==null?"-":String(e.generale).replace(".",",")+"/20")+'</b></td>'
      +'<td>'+(e.mini==null?"-":String(e.mini).replace(".",","))+'</td>'
      +'<td>'+(e.maxi==null?"-":String(e.maxi).replace(".",","))+'</td>'
      +'<td class="mini">'+echapH(e.motifs.join(" ; "))+'</td></tr>';
  });
  corps+='</table><p class="mini">« À vérifier » : score de risque d\x27au moins 25 sur 100 (détail dans l\x27onglet Vigilance). Ce n\'est pas une preuve.</p>';
  ouvrirImpression("Moyennes de la classe",corps);
}

/* ===================== Onglets Comportement + Bilan (Évaluations et notes) =====================
   Les « trimestres » sont les PÉRIODES de Travail en classe (mêmes bornes de dates).
   Tout est calculé en lecture ; rien de nouveau n'est écrit sur le serveur. */
/* Les TRIMESTRES sont des plages de dates réglées par le prof (profil.trimestres),
   valables pour toutes ses classes. Ils décident quelles évaluations sont prises en
   compte. « Toute l'année » = pas de filtre. Réglage dans les Paramètres. */
const EV_ALL={id:"__all__", nom:"Toute l'année", debut:null, fin:null};
function evTrimestres(){
  if(typeof profil==="undefined"||periodeType()==="annee")return [];
  /* une période sans aucune date ne découpe rien : sans date, on reste « à l'année » */
  return (profil.trimestres||[]).filter(function(t){ return t&&(t.debut!=null||t.fin!=null); })
    .sort(function(a,b){return (a.debut||0)-(b.debut||0);});
}
/* Découpage choisi par le prof : "annee", "trimestre" ou "semestre" (déduit des anciennes données sinon). */
function periodeType(){
  const t=profil&&profil.periodeType;
  if(t==="annee"||t==="trimestre"||t==="semestre")return t;
  const n=((profil&&profil.trimestres)||[]).length;
  return n===2?"semestre":(n?"trimestre":"annee");
}
function evPeriodesDe(classId){ return evTrimestres(); }
function evPeriodeCourante(classId){
  const ts=evTrimestres();
  if(_evPeriode==="__all__")return EV_ALL;
  if(_evPeriode){ const f=ts.filter(function(t){return t.id===_evPeriode;})[0]; if(f)return f; }
  if(!ts.length)return EV_ALL;
  const now=Date.now();
  const cur=ts.filter(function(t){ return (t.debut==null||now>=t.debut) && (t.fin==null||now<=t.fin); })[0];
  return cur || ts[ts.length-1] || EV_ALL;
}
function evChoisirPeriode(id){ _evPeriode=id; evalsRendre(); }
/* Bornes de dates d'une période, CONTIGUËS sur toute l'année : la 1re période
   attrape tout ce qui la précède (deb=0), chaque période va jusqu'au début de la
   suivante (ou +infini pour l'ouverte). Ainsi aucune évaluation n'est orpheline
   parce qu'elle a été passée avant la date de début de la période. */
function evBornesPeriode(p,classId){
  if(!p||p.id==="__all__")return {deb:0, fin:Number.MAX_SAFE_INTEGER};
  return {deb:(p.debut!=null?p.debut:0), fin:(p.fin!=null?p.fin:Number.MAX_SAFE_INTEGER)};
}
/* TOUS les élèves de la classe, même ceux qui n'ont rien rendu : le carnet se lit
   comme celui de Pronote, on voit d'un coup d'œil qui a fait quoi (et qui n'a rien
   fait). Les codes viennent de la liste de la classe (eleveCodes + invités), puis
   on ajoute ceux qui ont déposé une note sans y figurer. */
function evTousLesCodes(classId){
  const set={};
  (_evCodes[classId]||[]).forEach(function(c){ if(c)set[c]=1; });
  (_evalsCache[classId]||[]).forEach(function(e){ if(e.code&&!e._travail)set[e.code]=1; });
  const td=(_evTravail[classId]||{}).eleves||{}; Object.keys(td).forEach(function(c){ set[c]=1; });
  return Object.keys(set).sort(function(a,b){ return String(labelDe(classId,a)||a).localeCompare(String(labelDe(classId,b)||b),"fr",{numeric:true}); });
}
/* Comportement d'un élève sur une période (note + relevés + assiduité). */
function evComportInfo(classId,code,p){
  const data=(_evTravail[classId]||{}).eleves||{}; const v=data[code]||{events:[],att:{}};
  const b=evBornesPeriode(p,classId);
  const evs=(v.events||[]).filter(function(e){ const dt=e.date||0; return dt>=b.deb && dt<=b.fin; });
  const base=(typeof profil!=="undefined"&&typeof profil.travailBase==="number")?profil.travailBase:10;
  const note=evs.length?tvNoteDe(evs,null,base):null;
  let pos=0,neg=0; evs.forEach(function(e){ if(e.type==="neg")neg++; else pos++; });
  const att=v.att||{}; let a=0,r=0; const attF={};
  Object.keys(att).forEach(function(d){ let dt; try{ dt=new Date(d+"T12:00:00").getTime(); }catch(_){ dt=0; } if(dt<b.deb||dt>b.fin)return; attF[d]=att[d]; if(att[d]==="A")a++; else if(att[d]==="R")r++; });
  return {note:note, nb:evs.length, pos:pos, neg:neg, abs:a, retards:r, events:evs, att:attF};
}
/* Appréciation générale : évaluations + engagement (temps/exercices) + comportement + évolution. */
/* Faits COMPLETS d'un élève sur un trimestre : cours + chant + comportement +
   engagement + évolution. Sert de socle unique aux appréciations et aux bulletins. */
function evFaitsAcad(classId,code,p){
  const b=evBornesPeriode(p,classId);
  const evs=(_evalsCache[classId]||[]).filter(function(e){ return e.code===code && !e._travail && (e.fait||0)>=b.deb && (e.fait||0)<=b.fin; });
  if(!evs.length)return null;
  const mo=evMoyDossiers(evs,classId,true);   /* cours (demandées) + chant, libres en bonus */
  return mo?mo.moy:null;
}
function evFaitsComplets(classId,code,p){
  const b=evBornesPeriode(p,classId);
  const evs=(_evalsCache[classId]||[]).filter(function(e){ return e.code===code && !e._travail && (e.fait||0)>=b.deb && (e.fait||0)<=b.fin; });
  const cours=evs.filter(function(e){return !e._chant;});
  const chant=evs.filter(function(e){return e._chant;});
  const moyDe=function(a){ if(!a.length)return null; return a.reduce(function(s,e){return s+(e.note||0)/(e.sur||20)*20;},0)/a.length; };
  /* cours : demandées comptées, libres en bonus ; chant : toujours compté */
  const _mc=evMoyDossiers(cours,classId,false); const coursMoy=_mc?_mc.moy:null;
  const _nb=evNoteBonusDossiers(cours,classId); const bonusNote=_nb?_nb.note:null;
  const chantMoy=moyDe(chant);
  const acad=cours.concat(chant); const _ma=evMoyDossiers(acad,classId,true); const acadMoy=_ma?_ma.moy:null;
  const temps=cours.reduce(function(t,e){return t+(e.dureeMin||0);},0);
  const co=evComportInfo(classId,code,p);
  const cptP={},cptN={}; (co.events||[]).forEach(function(e){ if(e.type==="neg")cptN[e.label]=(cptN[e.label]||0)+1; else cptP[e.label]=(cptP[e.label]||0)+1; });
  const topN=function(o,k){ return Object.keys(o).sort(function(a,b){return o[b]-o[a];}).slice(0,k); };
  const prevs=evPeriodesDe(classId).filter(function(q){ return (q.debut||0)<(p.debut||0); });
  let tendance=0;
  if(prevs.length && acadMoy!=null){
    const pm=[]; prevs.forEach(function(q){ const f2=evFaitsAcad(classId,code,q); if(f2!=null)pm.push(f2); });
    if(pm.length){ const prevMoy=pm.reduce(function(a,b){return a+b;},0)/pm.length; if(acadMoy-prevMoy>=1.5)tendance=1; else if(prevMoy-acadMoy>=1.5)tendance=-1; }
  }
  const notesChrono=acad.slice().sort(function(a,b){return (a.fait||0)-(b.fait||0);}).map(function(e){return {note:e.note,sur:e.sur||20};});
  return {
    moy:acadMoy, nbNotes:acad.length,
    coursMoy:coursMoy, coursNb:cours.length, bonusNote:bonusNote, chantMoy:chantMoy, chantNb:chant.length,
    series:cours.length, serie:0, temps:temps, points:0, niveau:1, badges:0,
    devoirs:0, devoirsRendus:0,
    comportement:co.note, compNb:co.nb, abs:co.abs, retards:co.retards,
    forts:topN(cptP,3), faibles:topN(cptN,3),
    tendance:tendance, _notes:notesChrono
  };
}
/* Prépare _appDonnees pour réutiliser le moteur d'appréciation et les bulletins A4. */
function evBilanCharger(classId,p){
  const key=classId+"|"+((p&&p.id)||"");
  if(_appClasse!==classId || window._appPerKey!==key)_appEdits={};
  _appClasse=classId; window._appPerKey=key; _appNotes={};
  _appDonnees=evTousLesCodes(classId).map(function(c){
    const f=evFaitsComplets(classId,c,p); _appNotes[c]=f._notes||[];
    return {code:c, nom:labelDe(classId,c), faits:f};
  });
}
/* ----- Onglet Comportement ----- */
function evComportRendre(classId){
  const p=evPeriodeCourante(classId);
  let h="";
  if(!p){ return h+'<p class="badge-vide">Ouvrez une période dans « Travail en classe » pour suivre le comportement par trimestre.</p>'; }
  const lignes=evTousLesCodes(classId).map(function(c){ return Object.assign({code:c,nom:labelDe(classId,c)||""}, evComportInfo(classId,c,p)); })
                  .filter(function(x){ return x.nb>0 || x.abs || x.retards; });
  if(!lignes.length)return h+'<p class="badge-vide">Aucun relevé de comportement sur ce trimestre.</p>';
  (function(){ const notes=lignes.filter(function(x){return x.note!=null;});
    const moyCl=notes.length?Math.round(notes.reduce(function(a,x){return a+x.note;},0)/notes.length*10)/10:null;
    let pos=0,neg=0; lignes.forEach(function(x){ pos+=(x.pos||0); neg+=(x.neg||0); });
    h+=evKpiBandeau([
      {l:"Note moyenne de classe",v:(moyCl==null?"-":tvDispNote(moyCl)+'<span>/20</span>'),c:evMoyCoul(moyCl,13)},
      {l:"Élèves suivis",v:String(lignes.length)},
      {l:"Relevés positifs",v:String(pos),c:"var(--juste)"},
      {l:"Relevés négatifs",v:String(neg),c:"var(--faux)"}
    ]);
  })();
  h+='<p style="color:var(--encre-doux);font-size:.88rem;text-align:center">Cliquez sur un élève pour le détail des relevés.</p>';
  h+='<div style="overflow-x:auto"><table class="dash-table" style="width:100%;margin-top:6px"><thead><tr><th>Nom (privé)</th><th>Note /20</th><th>Positifs</th><th>Négatifs</th><th>Abs. / Ret.</th><th></th></tr></thead><tbody>';
  lignes.forEach(function(x){
    const coul=x.note==null?"var(--encre-doux)":(x.note>=13?"var(--juste)":(x.note>=10?"var(--or-texte)":"var(--faux)"));
    h+='<tr style="cursor:pointer" onclick="ecranComportEleve(\''+classId+'\',\''+x.code+'\')" title="Détail des relevés">'
      +'<td><b>'+(x.nom?echapH(x.nom):'<span style="color:var(--encre-doux)">(sans nom)</span>')+'</b></td>'
      +'<td><b style="color:'+coul+';font-size:1.05rem">'+(x.note==null?"-":tvDispNote(x.note))+'</b></td>'
      +'<td style="text-align:center;color:var(--juste)">'+x.pos+'</td>'
      +'<td style="text-align:center;color:var(--faux)">'+x.neg+'</td>'
      +'<td style="text-align:center">'+(x.abs||0)+' / '+(x.retards||0)+'</td>'
      +'<td style="text-align:right"><i class="ph ph-caret-right" style="color:var(--encre-doux)"></i></td></tr>';
  });
  h+='</tbody></table></div>';
  return h;
}
function ecranComportEleve(classId,code){
  const p=evPeriodeCourante(classId); if(!p){ toast("Aucune période."); return; }
  masquerInterfaceNormale(); majRetour(function(){ _evVue="comport"; evalsClasse(classId); },"Comportement");
  const nom=labelDe(classId,code)||"(élève non nommé)";
  titreProf('<i class="ph ph-chalkboard-simple"></i> '+echapH(nom), "Travail en classe · "+echapH(p.nom||""));
  const info=evComportInfo(classId,code,p);
  const evs=info.events.slice().sort(function(a,b){ return (b.date||0)-(a.date||0); });
  const coul=info.note==null?"var(--encre-doux)":(info.note>=13?"var(--juste)":(info.note>=10?"var(--or-texte)":"var(--faux)"));
  let h='<div class="accueil" style="max-width:760px">';
  h+='<div class="ex" style="margin-bottom:14px"><p style="margin:0">Note de comportement : <b style="color:'+coul+';font-size:1.2rem">'+(info.note==null?"-":tvDispNote(info.note)+" / 20")+'</b>'
    +((info.abs||info.retards)?' · <span style="color:var(--encre-doux)">'+(info.abs?info.abs+" absence"+(info.abs>1?"s":""):"")+((info.abs&&info.retards)?", ":"")+(info.retards?info.retards+" retard"+(info.retards>1?"s":""):"")+'</span>':'')+'</p></div>';
  if(evs.length){
    h+='<div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Date</th><th>Relevé</th><th>Type</th><th>Points</th></tr></thead><tbody>';
    evs.forEach(function(e){
      h+='<tr><td style="white-space:nowrap">'+fmtDateHeure(e.date)+'</td><td>'+echapH(e.label||"")+'</td>'
        +'<td>'+(e.type==="neg"?'<span style="color:var(--faux)">Négatif</span>':'<span style="color:var(--juste)">Positif</span>')+'</td>'
        +'<td>'+tvDispPts(e.pts!=null?e.pts:(e.type==="neg"?-1:1))+'</td></tr>';
    });
    h+='</tbody></table></div>';
  } else { h+='<p class="badge-vide">Aucun relevé de comportement sur ce trimestre.</p>'; }
  const jours=Object.keys(info.att||{}).sort().reverse();
  if(jours.length){
    h+='<h4 style="margin:18px 0 8px"><i class="ph ph-user-check"></i> Présences</h4><div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Jour</th><th>Statut</th></tr></thead><tbody>';
    jours.forEach(function(d){ const st=tvAttInfo(info.att[d]); h+='<tr><td>'+echapH(d)+'</td><td style="color:'+(st?st.coul:"")+';font-weight:600">'+(st?st.label:echapH(info.att[d]))+'</td></tr>'; });
    h+='</tbody></table></div>';
  }
  h+='</div>'; document.getElementById("zone").innerHTML=h; if(typeof remonter==="function")remonter();
}
/* ----- Détail d'un élève dans l'onglet Évaluations ----- */
function ecranEvalEleve(classId,code){
  const nom=labelDe(classId,code)||"(élève non nommé)";
  masquerInterfaceNormale(); majRetour(function(){ _evVue="eleves"; evalsClasse(classId); },"Évaluations");
  titreProf('<i class="ph ph-exam"></i> '+echapH(nom), "Détail des évaluations sur le logiciel");
  const _b=evBornesPeriode(evPeriodeCourante(classId),classId);
  const evs=(_evalsCache[classId]||[]).filter(function(e){ return e.code===code && !e._travail && !e._chant && (e.fait||0)>=_b.deb && (e.fait||0)<=_b.fin; }).sort(function(a,b){ return (b.fait||0)-(a.fait||0); });
  /* deux chiffres bien distincts : la moyenne (évaluations demandées) et la note
     bonus (évaluations que l'élève a passées de lui-même). */
  const _mo=evMoyDossiers(evs,classId,false); const moy=_mo?_mo.moy:null;
  const _nbo=evNoteBonusDossiers(evs,classId);
  let h='<div class="accueil" style="max-width:900px">';
  h+='<div class="ex" style="margin-bottom:14px"><p style="margin:0">Moyenne des évaluations demandées : '
    +'<b style="color:var(--laiton);font-size:1.2rem">'+(moy==null?"-":String(moy).replace(".",",")+"/20")+'</b>'
    +' · Note bonus : <b style="color:var(--or-texte);font-size:1.2rem"'+(_nbo?' title="'+evBonusDetail(_nbo)+'"':'')+'>'
    +(_nbo?String(_nbo.note).replace(".",",")+"/20":"-")+'</b>'
    +' · '+evs.length+' évaluation'+(evs.length>1?"s":"")+' au total</p></div>';
  if(evs.length){
    h+='<div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Date</th><th>Sujet</th><th>Note</th><th>Durée</th><th>Sorties de page</th><th></th></tr></thead><tbody>';
    evs.forEach(function(e){
      const cell = e._chant
        ? '<td style="color:var(--encre-doux)">Chant</td><td>-</td><td><button class="btn-son mini" title="Écouter" onclick="ecranChantRendus(\''+classId+'\',\''+e.chantId+'\')"><i class="ph ph-headphones"></i></button></td>'
        : e._manuel
        ? '<td style="color:var(--encre-doux)">Manuelle</td><td>-</td><td><button class="btn-son mini" title="Modifier l\'évaluation" onclick="evManuelEditer(\''+classId+'\',\'cours\',\''+e.manuelId+'\')"><i class="ph ph-pencil-simple"></i></button></td>'
        : '<td>'+(e.dureeMin||"-")+' min</td><td'+((e.sorties||0)>2?' style="color:var(--faux);font-weight:700"':'')+' style="text-align:center">'+(e.sorties||0)+'</td><td><button class="btn-son mini" title="Détail des réponses" onclick="ecranFicheEval(\''+classId+'\',\''+e.id+'\')"><i class="ph ph-magnifying-glass"></i></button>'+(e.dev?'<button class="btn-son mini" title="Faire refaire cette évaluation à l\'élève" onclick="evFaireRefaire(\''+classId+'\',\''+code+'\',\''+e.dev+'\')"><i class="ph ph-arrow-counter-clockwise" style="color:var(--laiton)"></i></button>':'')+'</td>';
      h+='<tr><td style="white-space:nowrap">'+fmtDateHeure(e.fait)+'</td><td>'+echapH(e.theme||"")+'</td>'
        +'<td><b>'+e.note+'/'+(e.sur||20)+'</b>'+(e.bonus>0?' <span style="color:var(--or-texte);font-size:.8rem" title="Bonus d\'évaluation dépensé par l\'élève">(dont +'+e.bonus+')</span>':'')+'</td>'+cell+'</tr>';
    });
    h+='</tbody></table></div>';
  } else { h+='<p class="badge-vide">Aucune évaluation pour cet élève.</p>'; }
  h+='</div>'; document.getElementById("zone").innerHTML=h; if(typeof remonter==="function")remonter();
}
/* ----- Onglet Bilan : appréciation complète (moteur appTexte) + export Pronote ----- */
/* ----- Évaluations « hors ligne » : le prof saisit une note par élève (colonne).
   Stockées dans classes/{cid}/notesManuelles (prof-écrivable ; le prof ne peut pas
   écrire dans evals, réservé à l'élève). Agrégées comme cours (ou chant). ----- */
function evManuelEditer(classId,cat,id){
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser;
  if(!s||!u){ toast("Connectez-vous à votre espace enseignant."); return; }
  cat=(cat==="chant")?"chant":"cours";
  masquerInterfaceNormale(); majRetour(function(){ _evVue=(cat==="chant")?"chant":"eleves"; evalsClasse(classId); },"Notes & bulletins");
  titreProf('<i class="ph ph-exam"></i> '+(id?"Modifier une":"Nouvelle")+' évaluation '+(cat==="chant"?"de chant":"de cours"),
            "Une note par élève, saisie en colonne. Elles rejoignent les moyennes, le bilan et l'export Pronote.");
  const z=document.getElementById("zone"); z.innerHTML='<p style="color:var(--encre-doux)"><i class="ph ph-spinner-gap"></i> Chargement de la classe…</p>';
  const existant=(_evManuel[classId]||[]).filter(function(x){return x.id===id;})[0];
  s.collection("eleveCodes").where("ownerUid","==",u.uid).get().then(function(el){
    const _mb=((_profClasses||[]).filter(function(x){return x.id===classId;})[0]||{}).membres||[];
    const codes=[]; el.forEach(function(d){ const v=d.data()||{}; if(v.classId===classId||_mb.indexOf(d.id)>=0)codes.push(d.id); });
    codes.sort(function(x,y){ return String(labelDe(classId,x)||"￿").localeCompare(String(labelDe(classId,y)||"￿"),"fr",{numeric:true}); });
    const notes=(existant&&existant.notes)||{};
    const titre=(existant&&existant.titre)||"";
    const sur=(existant&&existant.sur)||20;
    const dateISO=(existant&&existant.date)?new Date(existant.date).toISOString().slice(0,10):new Date().toISOString().slice(0,10);
    let h='<div class="accueil" style="max-width:680px">';
    h+='<div class="ex"><div style="display:grid;grid-template-columns:1fr 84px 150px;gap:10px;align-items:end">'
      +'<label style="font-size:.85rem;color:var(--encre-doux)">Titre ou thème<input id="emTitre" class="tv-ct-in" maxlength="60" value="'+echapH(titre)+'" placeholder="'+(cat==="chant"?"Chant en direct":"Contrôle écrit")+'"></label>'
      +'<label style="font-size:.85rem;color:var(--encre-doux)">Barème<input id="emSur" class="tv-ct-in" type="number" min="1" max="100" step="1" value="'+sur+'"></label>'
      +'<label style="font-size:.85rem;color:var(--encre-doux)">Date<input id="emDate" class="tv-ct-in" type="date" value="'+dateISO+'"></label>'
      +'</div></div>';
    if(!codes.length){
      h+='<p class="badge-vide">Cette classe n\'a pas encore d\'élèves (codes). Créez-les depuis « Élèves et codes ».</p></div>';
      z.innerHTML=h; if(typeof remonter==="function")remonter(); return;
    }
    h+='<div class="ex" style="padding-top:6px"><div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Nom (privé)</th><th style="width:130px">Note</th></tr></thead><tbody>';
    codes.forEach(function(c){
      const v=(notes[c]!=null?notes[c]:"");
      const nom=labelDe(classId,c);
      h+='<tr><td><b>'+(nom?echapH(nom):'<span style="color:var(--encre-doux)">'+echapH(c)+'</span>')+'</b></td>'
        +'<td><input class="em-note tv-ct-in" data-code="'+c+'" type="text" inputmode="decimal" autocomplete="off" value="'+v+'" placeholder="/'+sur+'" style="width:110px;text-align:center"></td></tr>';
    });
    h+='</tbody></table></div>'
      +'<p style="font-size:.8rem;color:var(--encre-doux);margin:8px 0 0">Laissez vide un élève non noté (absent, dispensé). Les notes sont ramenées sur 20 dans les moyennes.</p></div>';
    h+='<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:8px">'
      +'<button class="rm-cta" onclick="evManuelSauver(\''+classId+'\',\''+cat+'\',\''+(id||"")+'\')"><i class="ph-fill ph-floppy-disk"></i> Enregistrer</button>'
      +(id?'<button class="action" onclick="evManuelSupprimer(\''+classId+'\',\''+id+'\')"><i class="ph ph-trash"></i> Supprimer</button>':'')
      +'</div></div>';
    z.innerHTML=h; if(typeof remonter==="function")remonter();
  }).catch(function(){ z.innerHTML=svcIndispo("Impossible de charger la liste de la classe."); });
}
function evManuelSauver(classId,cat,id){
  const s=fbStore(),a=fbAuth(),u=a&&a.currentUser; if(!s||!u)return;
  cat=(cat==="chant")?"chant":"cours";
  const titre=(((document.getElementById("emTitre")||{}).value)||"").trim()||(cat==="chant"?"Chant":"Évaluation");
  const sur=Math.max(1,Math.min(100, parseFloat((document.getElementById("emSur")||{}).value)||20));
  const dv=(document.getElementById("emDate")||{}).value;
  const date=dv?new Date(dv+"T12:00:00").getTime():Date.now();
  const notes={}; let n=0;
  [].slice.call(document.querySelectorAll(".em-note")).forEach(function(inp){
    const val=String(inp.value||"").trim().replace(",",".");
    if(val==="")return;
    let num=parseFloat(val); if(isNaN(num))return; num=Math.max(0,Math.min(sur,Math.round(num*100)/100));
    notes[inp.dataset.code]=num; n++;
  });
  if(!n){ toast("Saisissez au moins une note."); return; }
  const docId=id||("nm"+Date.now()+"_"+Math.floor(Math.random()*10000));
  const data={ titre:titre, cat:cat, sur:sur, date:date, ownerUid:u.uid, maj:Date.now(), notes:notes };
  if(!id)data.cree=Date.now();
  s.collection("classes").doc(classId).collection("notesManuelles").doc(docId).set(data,{merge:false})
    .then(function(){ toast(n+" note(s) enregistrée(s)."); delete _evalsCache[classId]; _evVue=(cat==="chant")?"chant":"eleves"; evalsClasse(classId); })
    .catch(function(e){ const code=String((e&&e.code)||""); const z=document.getElementById("zone");
      if(code.indexOf("permission-denied")>=0&&typeof chRegles==="function"&&z){ z.innerHTML=chRegles(); }
      else toast("Enregistrement impossible."); });
}
async function evManuelSupprimer(classId,id){
  if(!await dlgConfirmer("Supprimer cette évaluation et toutes ses notes ?"))return;
  const s=fbStore(); if(!s)return;
  s.collection("classes").doc(classId).collection("notesManuelles").doc(id).delete()
    .then(function(){ toast("Évaluation supprimée."); delete _evalsCache[classId]; evalsClasse(classId); })
    .catch(function(){ toast("Suppression impossible."); });
}
/* ----- Onglet Chant : notes de chant par élève ----- */
function evChantRendre(classId){
  const _b=evBornesPeriode(evPeriodeCourante(classId),classId);
  const tete=evToolbarHTML(classId,"chant","Notes de chant");
  const tous=(_evalsCache[classId]||[]).filter(function(e){return e._chant && (e.fait||0)>=_b.deb && (e.fait||0)<=_b.fin;});
  if(!tous.length)return tete+'<p class="badge-vide">Aucun chant noté. Notez des enregistrements depuis « Chant », ou ajoutez un chant évalué en direct ci-dessus.</p>';
  const par={};
  tous.forEach(function(e){ const c=e.code||"?"; (par[c]||(par[c]={code:c,notes:[],nb:0,der:0})); par[c].notes.push((e.note||0)/(e.sur||20)*20); par[c].nb++; if((e.fait||0)>par[c].der)par[c].der=e.fait; });
  const lignes=Object.keys(par).map(function(c){ const b=par[c]; b.nom=labelDe(classId,c)||""; b.moy=Math.round(b.notes.reduce(function(x,y){return x+y;},0)/b.nb*10)/10; return b; })
    .sort(function(x,y){ return String(x.nom||"￿").localeCompare(String(y.nom||"￿"),"fr",{numeric:true}); });
  const moyCl=Math.round(lignes.reduce(function(a,b){return a+b.moy;},0)/lignes.length*10)/10;
  const reussite=lignes.length?Math.round(100*lignes.filter(function(b){return b.moy>=10;}).length/lignes.length):null;
  const totChants=lignes.reduce(function(a,b){return a+(b.nb||0);},0);
  let h=evKpiBandeau([
    {l:"Moyenne de classe",v:(moyCl==null?"-":String(moyCl).replace(".",",")+'<span>/20</span>'),c:evMoyCoul(moyCl)},
    {l:"Taux de réussite",v:(reussite==null?"-":reussite+'<span>%</span>'),c:"var(--juste)"},
    {l:"Élèves notés",v:String(lignes.length)},
    {l:"Chants notés",v:String(totChants),or:true}
  ]);
  h+='<p style="color:var(--encre-doux);font-size:.88rem;text-align:center">Cliquez sur un élève pour le détail de ses chants.</p>';
  h+='<div style="overflow-x:auto"><table class="dash-table" style="width:100%;margin-top:6px"><thead><tr><th>Nom (privé)</th><th>Chants</th><th>Moyenne</th><th>Dernier</th><th></th></tr></thead><tbody>';
  lignes.forEach(function(b){
    const coul=b.moy>=14?"var(--juste)":(b.moy>=10?"var(--or-texte)":"var(--faux)");
    h+='<tr style="cursor:pointer" onclick="ecranChantElevesProf(\''+classId+'\',\''+b.code+'\')" title="Détail des chants">'
      +'<td><b>'+(b.nom?echapH(b.nom):'<span style="color:var(--encre-doux)">(sans nom)</span>')+'</b></td>'
      +'<td style="text-align:center">'+b.nb+'</td>'
      +'<td><b style="color:'+coul+';font-size:1.05rem">'+String(b.moy).replace(".",",")+'/20</b></td>'
      +'<td style="white-space:nowrap;color:var(--encre-doux)">'+(b.der?fmtDateHeure(b.der):"-")+'</td>'
      +'<td style="text-align:right"><i class="ph ph-caret-right" style="color:var(--encre-doux)"></i></td></tr>';
  });
  h+='</tbody></table></div>';
  return tete+h;
}
/* Vue PROF : les chants notés d'un élève. Nom distinct de ecranChantEleve(chantId),
   qui est l'écran ÉLÈVE d'un chant (sinon la définition la plus tardive l'écrase). */
function ecranChantElevesProf(classId,code){
  const nom=labelDe(classId,code)||"(élève non nommé)";
  masquerInterfaceNormale(); majRetour(function(){ _evVue="chant"; evalsClasse(classId); },"Chant");
  titreProf('<i class="ph ph-microphone-stage"></i> '+echapH(nom), "Chants notés");
  const _b=evBornesPeriode(evPeriodeCourante(classId),classId);
  const evs=(_evalsCache[classId]||[]).filter(function(e){ return e.code===code && e._chant && (e.fait||0)>=_b.deb && (e.fait||0)<=_b.fin; }).sort(function(a,b){ return (b.fait||0)-(a.fait||0); });
  const notes=evs.map(function(e){ return (e.note||0)/(e.sur||20)*20; });
  const moy=notes.length?Math.round(notes.reduce(function(x,y){return x+y;},0)/notes.length*10)/10:null;
  let h='<div class="accueil" style="max-width:820px">';
  h+='<div class="ex" style="margin-bottom:14px"><p style="margin:0">Moyenne chant : <b style="color:var(--laiton);font-size:1.2rem">'+(moy==null?"-":String(moy).replace(".",",")+"/20")+'</b> · '+evs.length+' chant'+(evs.length>1?"s":"")+'</p></div>';
  if(evs.length){
    h+='<div style="overflow-x:auto"><table class="dash-table" style="width:100%"><thead><tr><th>Date</th><th>Morceau</th><th>Note</th><th></th></tr></thead><tbody>';
    evs.forEach(function(e){
      h+='<tr><td style="white-space:nowrap">'+fmtDateHeure(e.fait)+'</td><td>'+echapH(e.theme||"Chant")+'</td>'
        +'<td><b>'+e.note+'/'+(e.sur||20)+'</b></td>'
        +'<td><button class="btn-son mini" title="Écouter la classe" onclick="ecranChantRendus(\''+classId+'\',\''+e.chantId+'\')"><i class="ph ph-headphones"></i></button></td></tr>';
    });
    h+='</tbody></table></div>';
  } else { h+='<p class="badge-vide">Aucun chant noté pour cet élève.</p>'; }
  h+='</div>'; document.getElementById("zone").innerHTML=h; if(typeof remonter==="function")remonter();
}
function evBilanRendre(classId){
  const p=evPeriodeCourante(classId);
  let h="";
  if(!p){ return h+'<p class="badge-vide">Ouvrez une période dans « Travail en classe » : elle définit le trimestre du bilan et des appréciations.</p>'; }
  evBilanCharger(classId,p);
  if(!_appDonnees.length)return h+'<p class="badge-vide">Aucun élève avec des données sur ce trimestre.</p>';
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:10px">'
    +'<button class="action btn-corr" onclick="evExportPronote(\''+classId+'\')"><i class="ph ph-table"></i> Copier pour Pronote (colonnes)</button>'
    +'<button class="action btn-nouv" onclick="evExportPronoteCSV(\''+classId+'\')"><i class="ph ph-file-csv"></i> Export Pronote (CSV)</button>'
    +'</div>';
  return h+lsuBlocHTML(classId,p)+appBlocHTML();
}

/* ================= Diplômes des meilleurs élèves =================
   Modèle « Palmarès Stickers ». Les lauréats sont calculés sur la classe et la
   période choisies dans le ruban des notes. Les noms viennent de la liste locale
   du professeur : rien ne part sur le serveur, l'impression se fait sur l'appareil. */
const IMG_FELICITATION="images/maestro-felicitation.webp";
const DIP_CATS=[
  {k:"moyenne", titre:"Meilleure moyenne", phrase:"pour la meilleure moyenne de la classe", lib:"Moyenne",
   d:"M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3 6.4 20.2l1.1-6.2L3 9.6l6.2-.9z", periode:true},
  {k:"points", titre:"Le plus de points", phrase:"pour le plus grand nombre de points de la classe", lib:"Points",
   d:"M13 2L4 14h7l-1 8 9-12h-7z"},
  {k:"temps", titre:"Le plus d'entraînement", phrase:"pour le plus de temps passé à s'entraîner", lib:"Entraînement",
   d:"M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18zM12 7v5l3 2"},
  {k:"badges", titre:"Le plus de badges", phrase:"pour le plus grand nombre de badges gagnés", lib:"Badges",
   d:"M8 3l2 5M16 3l-2 5M12 8a6 6 0 1 0 0 12a6 6 0 1 0 0-12zM12 11l1.2 2.4 2.6.4-1.9 1.8.5 2.6-2.4-1.3-2.4 1.3.5-2.6-1.9-1.8 2.6-.4z"},
  {k:"evaluations", titre:"Le plus d'évaluations réussies", phrase:"pour le plus grand nombre d'évaluations réussies", lib:"Évaluations",
   d:"M9 11l3 3 8-8M20 12v7a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h9", periode:true},
  {k:"maitrise", titre:"Le plus de leçons maîtrisées", phrase:"pour le plus de leçons maîtrisées, trois niveaux validés", lib:"Leçons maîtrisées",
   d:"M7 4h10v5a5 5 0 0 1-10 0zM7 6H4a3 3 0 0 0 3 4M17 6h3a3 3 0 0 1-3 4M12 14v4M8 21h8M9 18h6"}
];
function dipReglages(){ const d=(profil&&profil.diplome)||{}; return {prof:d.prof||"", college:d.college||"", ville:d.ville||"", style:d.style||"rond", encre:d.encre||"#2b55a8"}; }
function dipValTxt(k,v){
  if(k==="moyenne")return String(Math.round(v*10)/10).replace(".",",")+" / 20";
  if(k==="points")return Math.round(v).toLocaleString("fr-FR")+" pts";
  if(k==="temps")return fmtTemps(v);
  if(k==="evaluations")return v+" réussie"+(v>1?"s":"");
  return String(v);
}
/* lauréats (ex aequo compris) et suivants, par catégorie ; V = {code:{moyenne,points,…}} */
function dipLaureatsDe(V){
  const codes=Object.keys(V);
  return DIP_CATS.map(function(cat){
    const l=codes.map(function(code){ return {code:code, v:V[code][cat.k]}; })
      .filter(function(x){ return x.v!=null && x.v>0; })
      .sort(function(a,b){ return b.v-a.v; });
    const top=l.length?l[0].v:null;
    const egal=function(a,b2){ return cat.k==="moyenne"?Math.round(a*10)===Math.round(b2*10):a===b2; };
    const gagnants=top==null?[]:l.filter(function(x){ return egal(x.v,top); });
    const suivants=l.filter(function(x){ return !egal(x.v,top); }).slice(0,2);
    return {cat:cat, gagnants:gagnants, suivants:suivants};
  });
}
function dipAnneeScolaire(p){
  const t=(p&&p.debut)||Date.now(), d=new Date(t), y=d.getMonth()>=7?d.getFullYear():d.getFullYear()-1;
  return y+"-"+(y+1);
}
/* ---- le tampon (SVG), partagé par le diplôme et l'aperçu des réglages ---- */
/* Tampons des diplômes (05/10/2026) : six styles et cinq encres, choisis dans
   Paramètres > Diplômes. Tout est dessiné à la couleur "#2b55a8", remplacée à la fin. */
const DIP_STYLES=[["rond","Rond classique"],["sceau","Sceau dentelé"],["etoiles","Couronne d'étoiles"],["note","Note de musique"],["ovale","Ovale"],["cadre","Cadre officiel"]];
const DIP_ENCRES=[["#2b55a8","Bleu"],["#b3261e","Rouge"],["#1f7a4d","Vert"],["#6b3fa0","Violet"],["#2a2f38","Noir"]];
function dipTamponSVG(R,taille,encre){
  R=R||{};
  const style=R.style||"rond", E=encre||R.encre||"#2b55a8", C="#2b55a8";
  const maj=function(x){ return String(x||"").toUpperCase(); };
  const haut=maj(R.college||"COLLÈGE"), bas=maj(R.ville?R.ville+" · ÉDUCATION MUSICALE":"ÉDUCATION MUSICALE"), prof=maj(R.prof||"LE PROFESSEUR");
  const fs=function(t,max){ return Math.max(6.5,Math.min(max,200/(t.length*0.8))).toFixed(1); };
  const fp=Math.max(9,Math.min(15,120/(prof.length*0.62))).toFixed(1);
  const id="tp"+Math.floor(Math.random()*1e6);
  const T=taille||178;
  const arcs='<path id="'+id+'h" d="M 23 89 A 66 66 0 0 1 155 89" fill="none"/><path id="'+id+'b" d="M 23 89 A 66 66 0 0 0 155 89" fill="none"/>'
    +'<text fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fs(haut,11.5)+'" font-weight="700" letter-spacing="1.1"><textPath href="#'+id+'h" startOffset="50%" text-anchor="middle">'+echapH(haut)+'</textPath></text>'
    +'<text fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fs(bas,9)+'" font-weight="700" letter-spacing=".6"><textPath href="#'+id+'b" startOffset="50%" text-anchor="middle">'+echapH(bas)+'</textPath></text>';
  const centre=function(y){ return '<text x="89" y="'+(y-18)+'" fill="'+C+'" font-family="Inter, sans-serif" font-size="8.5" font-weight="700" letter-spacing="1.5" text-anchor="middle">LE PROFESSEUR</text>'
    +'<text x="89" y="'+y+'" fill="'+C+'" font-family="\'Baloo 2\', sans-serif" font-size="'+fp+'" font-weight="800" text-anchor="middle">'+echapH(prof)+'</text>'
    +'<path d="M 62 '+(y+9)+' L 116 '+(y+9)+'" stroke="'+C+'" stroke-width="1.2"/>'; };
  const etoile=function(x,y,r){ let d=""; for(let i=0;i<10;i++){ const a=-Math.PI/2+i*Math.PI/5, rr=i%2?r*0.45:r; d+=(i?"L":"M")+(x+rr*Math.cos(a)).toFixed(1)+" "+(y+rr*Math.sin(a)).toFixed(1); } return '<path d="'+d+'Z" fill="'+C+'"/>'; };
  const note='<path d="M82 68 v-15 l14 -3 v14" fill="none" stroke="'+C+'" stroke-width="2.2"/><circle cx="79.2" cy="68" r="3.4" fill="'+C+'"/><circle cx="93.2" cy="64" r="3.4" fill="'+C+'"/>';
  let corps="";
  if(style==="sceau"){
    let d=""; const n=36; for(let i=0;i<=n*2;i++){ const a=i*Math.PI/n, r=i%2?80:87; d+=(i?"L":"M")+(89+r*Math.cos(a)).toFixed(1)+" "+(89+r*Math.sin(a)).toFixed(1); }
    corps='<path d="'+d+'Z" fill="none" stroke="'+C+'" stroke-width="2.4" stroke-linejoin="round"/>'
      +'<circle cx="89" cy="89" r="73" fill="none" stroke="'+C+'" stroke-width="1.2"/><circle cx="89" cy="89" r="47" fill="none" stroke="'+C+'" stroke-width="1.6" stroke-dasharray="3 2.5"/>'
      +arcs+centre(97);
  }else if(style==="etoiles"){
    let st=""; for(let i=0;i<12;i++){ const a=i*Math.PI/6; if(i===0||i===6)continue; st+=etoile(89+57*Math.cos(a),89+57*Math.sin(a),3.6); }
    corps='<circle cx="89" cy="89" r="85" fill="none" stroke="'+C+'" stroke-width="3.5"/><circle cx="89" cy="89" r="79" fill="none" stroke="'+C+'" stroke-width="1.2"/>'
      +'<circle cx="89" cy="89" r="47" fill="none" stroke="'+C+'" stroke-width="1.6"/>'+arcs+etoile(14,89,4)+etoile(164,89,4)+etoile(89,62,6.5)+centre(100);
  }else if(style==="note"){
    corps='<circle cx="89" cy="89" r="85" fill="none" stroke="'+C+'" stroke-width="2"/><circle cx="89" cy="89" r="81" fill="none" stroke="'+C+'" stroke-width="2" stroke-dasharray="1 4" stroke-linecap="round"/>'
      +'<circle cx="89" cy="89" r="47" fill="none" stroke="'+C+'" stroke-width="2.4"/>'+arcs+note+centre(104);
  }else if(style==="ovale"){
    const fo=Math.max(6,Math.min(11,132/(haut.length*0.72))).toFixed(1), fb=Math.max(5.5,Math.min(9,120/(bas.length*0.68))).toFixed(1);
    corps='<ellipse cx="89" cy="89" rx="86" ry="58" fill="none" stroke="'+C+'" stroke-width="3.5"/><ellipse cx="89" cy="89" rx="80" ry="52" fill="none" stroke="'+C+'" stroke-width="1.2"/>'
      +'<text x="89" y="62" fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fo+'" font-weight="700" letter-spacing="1" text-anchor="middle">'+echapH(haut)+'</text>'
      +'<path d="M 34 70 L 144 70 M 34 112 L 144 112" stroke="'+C+'" stroke-width="1"/>'
      +'<text x="89" y="86" fill="'+C+'" font-family="Inter, sans-serif" font-size="8" font-weight="700" letter-spacing="1.5" text-anchor="middle">LE PROFESSEUR</text>'
      +'<text x="89" y="103" fill="'+C+'" font-family="\'Baloo 2\', sans-serif" font-size="'+fp+'" font-weight="800" text-anchor="middle">'+echapH(prof)+'</text>'
      +'<text x="89" y="123" fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fb+'" font-weight="700" letter-spacing=".4" text-anchor="middle">'+echapH(bas)+'</text>';
  }else if(style==="cadre"){
    const fo=Math.max(6.5,Math.min(10.5,118/(haut.length*0.72))).toFixed(1), fb=Math.max(6.5,Math.min(9,140/(bas.length*0.75))).toFixed(1);
    corps='<rect x="8" y="34" width="162" height="110" rx="8" fill="none" stroke="'+C+'" stroke-width="3.5"/><rect x="14" y="40" width="150" height="98" rx="5" fill="none" stroke="'+C+'" stroke-width="1.2"/>'
      +'<text x="89" y="60" fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fo+'" font-weight="800" letter-spacing="1" text-anchor="middle">'+echapH(haut)+'</text>'
      +etoile(24,57,3.4)+etoile(154,57,3.4)
      +'<text x="89" y="82" fill="'+C+'" font-family="Inter, sans-serif" font-size="8" font-weight="700" letter-spacing="1.5" text-anchor="middle">LE PROFESSEUR</text>'
      +'<text x="89" y="100" fill="'+C+'" font-family="\'Baloo 2\', sans-serif" font-size="'+fp+'" font-weight="800" text-anchor="middle">'+echapH(prof)+'</text>'
      +'<path d="M 40 110 L 138 110" stroke="'+C+'" stroke-width="1"/>'
      +'<text x="89" y="126" fill="'+C+'" font-family="Inter, sans-serif" font-size="'+fb+'" font-weight="700" letter-spacing=".6" text-anchor="middle">'+echapH(bas)+'</text>';
  }else{
    corps='<circle cx="89" cy="89" r="85" fill="none" stroke="'+C+'" stroke-width="3.5"/><circle cx="89" cy="89" r="79" fill="none" stroke="'+C+'" stroke-width="1.2"/>'
      +'<circle cx="89" cy="89" r="47" fill="none" stroke="'+C+'" stroke-width="1.6"/>'+arcs
      +'<path d="M 14 89 l 3 -3 l 3 3 l -3 3 z M 158 89 l 3 -3 l 3 3 l -3 3 z" fill="'+C+'"/>'+centre(97);
  }
  const svg='<svg width="'+T+'" height="'+T+'" viewBox="0 0 178 178" class="dip-tamp" aria-hidden="true">'+corps+'</svg>';
  return E===C?svg:svg.split(C).join(E);
}
