/* Registre des évaluations de cours : id -> banque + nom lisible + module natif. */
const EVALCOURS_DEF={
 orch:{coursId:"orch", bank:BANK_ORCH, nom:"Évaluation : L'orchestre et les instruments"},
 enr:{coursId:"enr", bank:BANK_ENR, nom:"Évaluation : L'histoire de l'enregistrement"},
 aud:{coursId:"aud", bank:BANK_AUD, nom:"Évaluation : L'enquête auditive"},
 recre:{coursId:"recre", bank:BANK_RECRE, nom:"Évaluation : La recréation musicale"},
 rep:{coursId:"rep", bank:BANK_REP, nom:"Évaluation : La répétition"}
};
/* Chaque évaluation de cours est aussi un THÈME d'entraînement : GEN["evalcours-<id>"]
   tire des questions de la banque, exactement comme une leçon du professeur. */
Object.keys(EVALCOURS_DEF).forEach(function(k){
  const key="evalcours-"+k, d=EVALCOURS_DEF[k];
  /* Même règle que les leçons du professeur : facile = questions faciles ;
     intermédiaire = faciles + moyennes ; difficile = moyennes + difficiles.
     Si un niveau manque de questions, on reprend toute la banque. */
  GEN[key]=function(){ const b=d.bank||[]; if(!b.length)return [];
    const pool=b.filter(function(x){ const q=x.diff||2;
      return difficulte===1?q===1:(difficulte===2?q<=2:q>=2); });
    const l=pool.length>=5?pool:b;
    return mapEx(Math.min(nbQuestions,l.length),function(){ return qProfEx(l[Math.floor(Math.random()*l.length)]); }); };
});

/* Registre des cours interactifs disponibles dans l'application. */
const COURS_DEF={
 orch:{titre:"L'orchestre et les instruments", ic:"music-notes", etapes:COURS_ORCH, indices:ORCH_INDICES, img:IMG_ORCH,
      intro:"Cours interactif de 6ᵉ : découvre l'orchestre, ses familles et comment un geste devient un son.",
      module:"instruments", evalId:"evalcours-orch",
      finTxt:"Tu connais maintenant les <b>quatre familles</b> de l'orchestre, le rôle du <b>chef</b>, et le secret commun à toute musique : le <b>geste transforme la matière en vibration</b>."},
 enr:{titre:"L'histoire de l'enregistrement", ic:"cassette-tape", etapes:COURS_ENR, indices:ENR_INDICES, img:IMG_ENR,
      intro:"Cours interactif de 3ᵉ : écoute, joue, et corrige-toi au fur et à mesure.",
      module:"histoire-son", evalId:"evalcours-enr",
      finTxt:"Tu as traversé <b>160 ans d'histoire</b> : du phonautographe muet de 1860 jusqu'au studio-instrument de Queen."},
 aud:{titre:"L'enquête auditive", ic:"ear", etapes:COURS_AUD, indices:AUD_INDICES, img:IMG_AUD,
      intro:"Cours interactif de 4ᵉ : mène l'enquête sur le son et protège ton audition.",
      module:"ouie", evalId:"evalcours-aud",
      finTxt:"Tu as mené l'enquête de bout en bout : de la <b>loudness war</b> jusqu'aux <b>cellules ciliées</b>. Tu sais désormais protéger ton capital auditif : et celui des autres."},
 recre:{titre:"La recréation musicale", ic:"vinyl-record", etapes:COURS_RECRE, indices:RECRE_INDICES, img:IMG_RECRE,
      intro:"Jeu de rôle : deviens David Bowie puis Shigeru Miyamoto, et recrée une musique à partir d'une autre dans le studio.",
      evalId:"evalcours-recre",
      finTxt:"Tu as vécu deux <b>recréations</b> de l'intérieur : de <i>Comme d'habitude</i> à <i>Life on Mars?</i>, et de la <b>Berceuse de Zelda</b> à <b>Ballad of the Goddess</b>, jouée à l'envers. Adapter, transformer, recréer : c'est aussi ça, composer."},
 rep:{titre:"La répétition", ic:"repeat", etapes:COURS_REP, indices:REP_INDICES, img:IMG_REP,
      intro:"Ostinato, accumulation, motif thématique, basse obstinée : découvre comment la répétition construit une œuvre.",
      evalId:"evalcours-rep",
      finTxt:"Tu sais maintenant reconnaître un <b>ostinato</b>, une <b>structure par accumulation</b> (<i>North Star</i>), un <b>motif thématique</b> (<i>Batman</i>) et une <b>basse obstinée</b> (Lully). Répéter, c'est aussi composer."}
};

/* ---------- État & progression ---------- */
let ceEtape=0, ceRep={};        // ceRep["e-x"] = état des réponses de l'exercice x de l'étape e
let ceEssais={};                // "etape_ex" -> nb d'essais ratés (1er = diagnostic, 2e = correction)

/* Registre des cours interactifs : chacun a ses étapes, ses indices et ses images. */
let ceCours="enr";
function ceDef(){ return COURS_DEF[ceCours]||COURS_DEF.enr; }
function ceProfil(){
  if(!profil.cours||typeof profil.cours!=="object")profil.cours={};
  /* reprise de l'ancien format (cours « enregistrement » seul) */
  if(profil.coursEnr&&!profil.cours.enr){ profil.cours.enr=profil.coursEnr; delete profil.coursEnr; }
  const c=profil.cours;
  if(!c[ceCours]||typeof c[ceCours]!=="object")c[ceCours]={faits:[],max:0,ex:{}};
  if(!Array.isArray(c[ceCours].faits))c[ceCours].faits=[];
  if(!c[ceCours].ex||typeof c[ceCours].ex!=="object")c[ceCours].ex={};
  return c[ceCours];
}
function ceFait(i){ return ceProfil().faits.indexOf(i)>=0; }
function ceMarquer(i){
  const p=ceProfil();
  if(p.faits.indexOf(i)<0){ p.faits.push(i); p.dates=p.dates||{}; if(!p.dates[i])p.dates[i]=Date.now(); p.maj=Date.now(); sauverProfil(profil); }
  if((p.max||0)<i+1){ p.max=i+1; sauverProfil(profil); }
  /* toutes les étapes faites : le cours vaut travail rendu */
  try{
    const n=ceDef().etapes.length;
    let tout=true; for(let k=0;k<n;k++){ if(!ceEtapeComplete(k)){tout=false;break;} }
    if(tout&&typeof devoirFait==="function")devoirFait("cours:"+ceCours,"cours",null);
  }catch(e){}
}
/* ---- Verrouillage : l'élève doit FAIRE les exercices avant de passer à la suite ----
   (le professeur, lui, circule librement dans tout le cours) */
function ceProf(){ try{ return typeof arbToutOuvert==="function" && arbToutOuvert(); }catch(e){ return false; } }
/* un exercice est « fait » quand il a été résolu ou corrigé (pas au 1er essai raté) */
function ceMarquerEx(etape,i){
  const p=ceProfil(), k=String(etape);
  if(!Array.isArray(p.ex[k]))p.ex[k]=[];
  if(p.ex[k].indexOf(i)<0){ p.ex[k].push(i); p.maj=Date.now(); if(!p.debut)p.debut=Date.now(); sauverProfil(profil); }
  if(ceEtapeComplete(etape))ceMarquer(etape);
}
function ceExFait(etape,i){
  const l=ceProfil().ex[String(etape)];
  return Array.isArray(l)&&l.indexOf(i)>=0;
}
function ceRestants(etape){
  const e=ceDef().etapes[etape]; if(!e||!e.ex)return 0;
  let n=0; e.ex.forEach(function(_,i){ if(!ceExFait(etape,i))n++; });
  return n;
}
/* Une étape validée (bouton « Suivant ») compte comme complète : le bouton n'est
   actif que lorsque tous ses exercices sont faits. Les tout premiers élèves du
   cours « enregistrement » n'avaient que cette trace (pas le détail des
   exercices) : sans cette règle, leur cours n'était jamais « terminé ». */
function ceEtapeComplete(etape){ return ceFait(etape)||ceRestants(etape)===0; }
/* étape accessible ? prof = tout ; élève = la 1re, celles déjà faites, et la suivante immédiate */
/* Limite fixée par le professeur pour la classe : nombre d'étapes ouvertes (0 = toutes). */
function ceLimiteProf(id){ if(ceProf())return 0; const n=+((_coursEtapes||{})[id||ceCours]||0); return n>0?n:0; }
function ceFermeeParProf(etape){ const L=ceLimiteProf(); return L>0&&etape>=L; }
function ceOuverte(etape){
  if(ceProf())return true;
  if(ceFermeeParProf(etape))return false;
  if(etape===0)return true;
  for(let k=0;k<etape;k++){ if(!ceEtapeComplete(k))return false; }
  return true;
}

/* ---------- Écran principal ---------- */
/* Ouvre un cours donné (id du registre) à l'étape voulue. */
function ecranCours(id,etape){
  if(COURS_DEF[id]&&id!==ceCours){ ceCours=id; ceEtape=0; ceEssais={}; }
  ecranCoursEnr(typeof etape==="number"?etape:cePremiereIncomplete());
}
/* Reprise : première étape dont les exercices ne sont pas tous faits (0 si on n'a rien commencé). */
function cePremiereIncomplete(){
  const n=ceDef().etapes.length;
  for(let i=0;i<n;i++){ if(!ceEtapeComplete(i))return i; }
  return 0;
}
function ecranCoursEnr(etape){
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  if(typeof etape==="number"){
    let cible=Math.max(0,Math.min(ceDef().etapes.length-1,etape));
    /* un élève ne peut pas sauter une étape dont les exercices ne sont pas faits */
    if(!ceOuverte(cible)){ while(cible>0&&!ceOuverte(cible))cible--; }
    ceEtape=cible;
  }
  const e=ceDef().etapes[ceEtape], n=ceDef().etapes.length;
  const reste=ceFait(ceEtape)?0:ceRestants(ceEtape), libre=ceProf(), bloque=(!libre&&reste>0);
  document.getElementById("titre").innerHTML='<i class="ph ph-'+ceDef().ic+'"></i> '+ceDef().titre;
  document.getElementById("intro").textContent=ceDef().intro;
  const pct=Math.round((ceEtape)/(n-1)*100);
  let html=e.html||"";
  /* jetons __CLE__ remplacés par l'image correspondante du cours */
  html=html.replace(/__([A-Z0-9_]+)__/g,function(_,k){ return ceDef().img[k.toLowerCase()]||""; });
  const exs=(e.ex||[]).map(function(x,i){return ceExHTML(x,i);}).join("");
  document.getElementById("zone").innerHTML=`
   <div class="accueil ce-cours">
     <div class="ce-fixe" role="status" aria-label="Étape ${ceEtape+1} sur ${n}">
       <span class="ce-fixe-num"><small>Étape</small><b>${ceEtape+1}</b><small>sur ${n}</small></span>
       <span class="ce-fixe-mil">
         <span class="ce-fixe-t">${e.t}</span>
         <span class="ce-fixe-jauge"><i style="width:${Math.round((ceEtape+(reste?0:1))/n*100)}%"></i></span>
       </span>
       <span class="ce-fixe-reste" id="ceFixeReste">${ceFixeResteHTML(reste)}</span>
     </div>
     <div class="ce-fil">
       ${ceDef().etapes.map(function(s,i){
         const ouv=ceOuverte(i), lib=escapeHtml(s.t.replace(/&nbsp;/g," "));
         return `<button class="ce-pas${i===ceEtape?" on":""}${ceEtapeComplete(i)&&ceFait(i)?" fait":""}${ouv?"":" verrou"}${ceFermeeParProf(i)?" prof":""}"
           title="${ouv?lib:(ceFermeeParProf(i)?"Ton professeur ouvrira cette étape plus tard":"Termine d'abord les exercices des étapes précédentes")}" ${ouv?"":"disabled"}
           onclick="${ouv?("ecranCoursEnr("+i+")"):""}">${ouv?(i+1):"<i class='ph-fill ph-lock-simple'></i>"}</button>`;}).join("")}
     </div>
     <div class="ce-jauge"><i style="width:${pct}%"></i></div>
     <div class="ce-tete">
       <h2>${e.ic||""} ${e.t}</h2>
     </div>
     ${(ceLimiteProf()&&ceEtape===ceLimiteProf()-1&&ceEtape<n-1)?`<div class="ce-note ce-pause-prof"><i class="ph ph-hourglass-medium"></i> <span>C'est la <b>dernière étape ouverte</b> pour l'instant. Termine-la bien : ton professeur ouvrira la suite au prochain cours.</span></div>`:""}
     <div class="ce-corps">${html}</div>
     ${exs}
     ${bloque?`<div class="ce-verrou"><i class="ph-fill ph-lock-simple"></i>
       <span>Il te reste <b>${reste} exercice${reste>1?"s":""}</b> à faire sur cette étape avant de pouvoir continuer.</span></div>`:""}
     <div class="ce-nav">
       <button class="action" ${ceEtape===0?"disabled style='opacity:.4'":""} onclick="ecranCoursEnr(${ceEtape-1})"><i class="ph ph-arrow-left"></i> Précédent</button>
       ${ceEtape<n-1&&ceFermeeParProf(ceEtape+1)
         ? `<button class="action btn-corr" disabled title="Ton professeur ouvrira la suite plus tard"><i class="ph-fill ph-lock-simple"></i> La suite sera ouverte par ton professeur</button>`
         : ceEtape<n-1
         ? `<button class="action btn-corr" ${bloque?"disabled":""} onclick="ceMarquer(${ceEtape});ecranCoursEnr(${ceEtape+1})">Suivant <i class="ph ph-arrow-right"></i></button>`
         : `<button class="action btn-corr" ${bloque?"disabled":""} onclick="ceMarquer(${ceEtape});ceFinal()"><i class="ph ph-flag-checkered"></i> Terminer le cours</button>`}
     </div>
   </div>`;
  ceMonterYT(); ceMonterPistes(); stuMonter(); repMonter();
  if(typeof remonter==="function")remonter();
}

/* ---------- Images des cours interactifs : zoom au clic ----------
   Au survol, l'image se soulève (CSS) ; au clic, elle s'ouvre en grand dans une
   fenêtre. On ferme avec la croix, la touche Échap ou un clic à côté.
   Les petits portraits ronds des jeux de rôle (.recre-role) ne sont pas concernés. */
function ceZoomImage(img){
  ceZoomFermer();
  const fig=img.closest("figure"), cap=fig&&fig.querySelector("figcaption");
  const leg=(cap&&cap.textContent.trim())||img.getAttribute("alt")||"";
  const d=document.createElement("div");
  d.className="ce-zoom"; d.id="ceZoom"; d.setAttribute("role","dialog"); d.setAttribute("aria-modal","true");
  d.setAttribute("aria-label",leg||"Image agrandie");
  d.innerHTML='<button type="button" class="ce-zoom-x" aria-label="Fermer" onclick="ceZoomFermer()"><i class="ph ph-x"></i></button>'
    +'<figure><img src="'+img.currentSrc.replace(/"/g,"&quot;")+'" alt="'+escapeHtml(leg)+'">'+(leg?'<figcaption>'+escapeHtml(leg)+'</figcaption>':'')+'</figure>';
  d.addEventListener("click",function(e){ if(e.target===d||e.target.tagName==="FIGURE")ceZoomFermer(); });
  /* en plein écran (séance au tableau), seul l'élément affiché en plein écran
     est visible : la fenêtre de zoom doit s'y loger */
  const fs=document.fullscreenElement;
  (fs&&fs!==document.documentElement&&fs!==document.body?fs:document.body).appendChild(d);
  /* une petite image (partition, schéma) est agrandie pour occuper l'écran, jusqu'à 4 fois sa taille */
  const g=d.querySelector("img"), nw=img.naturalWidth||img.width, nh=img.naturalHeight||img.height;
  if(g&&nw&&nh){
    const k=Math.min(4,Math.min(window.innerWidth*0.94,1400)/nw,(window.innerHeight-120)/nh);
    if(k>1){ g.style.width=Math.round(nw*k)+"px"; g.style.maxHeight="none"; }
  }
  requestAnimationFrame(function(){ d.classList.add("on"); });
  const x=d.querySelector(".ce-zoom-x"); if(x)x.focus();
}
function ceZoomFermer(){ const d=document.getElementById("ceZoom"); if(d)d.remove(); }
document.addEventListener("click",function(e){
  const img=e.target&&e.target.closest&&e.target.closest(".ce-corps img, .ce-ex img, .sc-page img, .cbio-fig img");
  if(!img||img.closest(".recre-role")||img.closest("button,a"))return;
  ceZoomImage(img);
});
/* Échap ferme d'abord le zoom, sans quitter la séance au tableau (écouteur en phase de capture) */
document.addEventListener("keydown",function(e){
  if(!document.getElementById("ceZoom"))return;
  if(e.key==="Escape"){ ceZoomFermer(); e.preventDefault(); e.stopImmediatePropagation(); }
  else if(/^(Arrow|Page| $)/.test(e.key)){ e.stopImmediatePropagation(); }   /* pas de changement de diapositive sous le zoom */
},true);

/* ---------- Lecteurs YouTube (chargés au clic, pour ne pas ralentir la page) ---------- */
/* Un lecteur YouTube intégré refuse de démarrer si la page est ouverte
   directement depuis le disque (adresse en file://) : l'origine est alors
   « nulle » et YouTube bloque la lecture. Dans ce cas on n'affiche pas de
   lecteur mais un bouton qui ouvre la vidéo sur YouTube. En ligne, on garde
   le lecteur intégré, avec un lien de secours si l'établissement filtre
   l'affichage des vidéos. */
function ceYTlocal(){ return location.protocol==="file:"; }
function ceMonterYT(){
  const local=ceYTlocal();
  document.querySelectorAll(".ce-yt").forEach(function(d){
    const id=d.getAttribute("data-yt"), lib=d.getAttribute("data-lib")||"";
    d.innerHTML=`<button class="ce-yt-btn" onclick="ceLireYT(this,'${id}')">
      <span class="ce-yt-play"><i class="ph-fill ph-${local?"arrow-square-out":"play"}"></i></span>
      <span class="ce-yt-lib">${escapeHtml(lib)}</span>
      <span class="ce-yt-src">${local?"Ouvrir sur YouTube":"YouTube"}</span></button>`;
  });
}
/* ---------- Laboratoire du son 8 bits (leçon « La musique de jeux vidéo ») ----------
   1) les formes d'onde, à voir et à entendre (hauteur réglable, largeur du créneau) ;
   2) les 4 canaux de la NES sur « Korobeiniki » (l'air de Tetris, chanson populaire),
      que l'élève coupe et rallume pour entendre ce que joue chacun.
   Tout est synthétisé en direct (Web Audio), aucun fichier son. */
const O8_ONDES=[
  {k:"sine",nom:"Sinusoïde",coul:"#7fd3ff",txt:"Le son le plus <b>pur</b> : doux et lisse, comme un diapason ou un sifflement. La NES ne sait pas le jouer&nbsp;!"},
  {k:"square",nom:"Carrée",coul:"#F2C94C",txt:"Elle saute d'un coup du haut au bas. Timbre <b>creux et nasillard</b>, riche en harmoniques : c'est <b>le son des jeux 8 bits</b>. La NES en a deux, pour la mélodie et l'accompagnement."},
  {k:"triangle",nom:"Triangulaire",coul:"#7ee0a4",txt:"Elle monte et descend en ligne droite. Timbre <b>doux et rond</b>, un peu comme une flûte. Sur la NES, elle joue <b>la basse</b>."},
  {k:"sawtooth",nom:"Dents de scie",coul:"#ff9f7a",txt:"Elle monte doucement puis retombe d'un coup. Timbre <b>brillant et cuivré</b>, celui des synthétiseurs et des consoles plus récentes (pas de la NES)."},
  {k:"noise",nom:"Bruit",coul:"#c9b6ff",txt:"Le signal change <b>au hasard</b> : plus de note précise, juste un souffle «&nbsp;chhh&nbsp;». Très court, il imite une <b>caisse claire</b>, une <b>cymbale</b> ou une <b>explosion</b>."}
];
let _o8={onde:"square",duty:.5,midi:64,son:null,t0:0,anim:0,jeu:null};
function o8Pulse(ctx,d){
  const N=64,re=new Float32Array(N),im=new Float32Array(N);
  for(let n=1;n<N;n++){ re[n]=2/(n*Math.PI)*Math.sin(2*Math.PI*n*d); im[n]=2/(n*Math.PI)*(1-Math.cos(2*Math.PI*n*d)); }
  return ctx.createPeriodicWave(re,im);
}
function o8BruitBuffer(ctx){
  if(ctx._o8b)return ctx._o8b;
  const b=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate),d=b.getChannelData(0);
  let v=0; for(let i=0;i<d.length;i++){ if(i%4===0)v=Math.random()<.5?-1:1; d[i]=v; }
  return (ctx._o8b=b);
}
function o8Icone(k){
  const p={sine:"M2 12 C6 2,10 2,14 12 S22 22,26 12",square:"M2 17 V7 H14 V17 H26 V7",triangle:"M2 17 L8 7 L14 17 L20 7 L26 17",
    sawtooth:"M2 17 L14 7 V17 L26 7 V17",noise:"M2 12 L4 7 L6 15 L8 9 L10 18 L12 6 L14 13 L16 8 L18 16 L20 10 L22 17 L24 7 L26 12"}[k];
  return '<svg viewBox="0 0 28 24" aria-hidden="true"><path d="'+p+'" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/></svg>';
}
function onde8Monter(){
  const box=document.getElementById("onde8"); if(!box)return;
  o8Arreter(); o8JeuArreter();
  box.innerHTML=
   '<div class="o8-t"><i class="ph ph-wave-square"></i> Le laboratoire du son 8 bits</div>'+
   '<div class="o8-part"><div class="o8-st">1. Les formes d\'onde : regarde et écoute</div>'+
   '<p class="o8-aide">Un son est une <b>vibration</b>. Sa <b>forme d\'onde</b> donne son <b>timbre</b> (sa couleur). Clique sur une forme pour l\'entendre.</p>'+
   '<div class="o8-ondes">'+O8_ONDES.map(function(o){return '<button class="o8-onde" data-k="'+o.k+'" style="--c:'+o.coul+'" onclick="o8Choisir(\''+o.k+'\')">'+o8Icone(o.k)+'<span>'+o.nom+'</span></button>';}).join("")+'</div>'+
   '<div class="o8-ecran"><canvas id="o8Scope"></canvas><span class="o8-etat" id="o8Etat"></span></div>'+
   '<p class="o8-desc" id="o8Desc"></p>'+
   '<div class="o8-regl"><label>Hauteur <span>grave</span><input type="range" min="45" max="81" value="'+_o8.midi+'" oninput="o8Hauteur(this.value)"><span>aigu</span></label>'+
   '<div class="o8-duty" id="o8Duty">Largeur du créneau '+[.5,.25,.125].map(function(d){return '<button data-d="'+d+'" onclick="o8Duty('+d+')">'+String(d*100).replace(".",",")+' %</button>';}).join("")+'</div></div>'+
   '<p class="o8-aide">Plus l\'onde se répète vite, plus le son est <b>aigu</b> : bouge le curseur et regarde les vagues se resserrer.</p></div>'+
   '<div class="o8-part"><div class="o8-st">2. La NES en action : 4 canaux</div>'+
   '<p class="o8-aide">Voici «&nbsp;Korobeiniki&nbsp;», l\'air de Tetris, joué comme par une console 8 bits. Lance la musique, puis <b>coupe et rallume les canaux</b> pour entendre ce que joue chacun. (Le 5ᵉ canal de la NES, pour de courts sons enregistrés, n\'est pas utilisé ici.)</p>'+
   '<button class="o8-jouer" id="o8Jouer" onclick="o8JeuBasculer()"><i class="ph-fill ph-play"></i> Lancer la musique</button>'+
   '<div class="o8-canaux">'+O8_CANAUX.map(function(c,i){return '<button class="o8-canal on" id="o8C'+i+'" style="--c:'+c.coul+'" onclick="o8Canal('+i+')"><span class="o8-haut"><span class="o8-cn">Canal '+(i+1)+'</span><span class="o8-onoff"></span></span><span class="o8-type">'+c.onde+'</span><b>'+c.role+'</b><canvas id="o8S'+i+'"></canvas></button>';}).join("")+'</div></div>';
  o8MajUI();
}
function o8MajUI(){
  document.querySelectorAll(".o8-onde").forEach(function(b){b.classList.toggle("on",b.dataset.k===_o8.onde);});
  const o=O8_ONDES.find(function(x){return x.k===_o8.onde;});
  const d=document.getElementById("o8Desc"); if(d)d.innerHTML="<b>"+o.nom+"</b> : "+o.txt;
  const du=document.getElementById("o8Duty"); if(du){ du.hidden=_o8.onde!=="square"; du.querySelectorAll("button").forEach(function(b){b.classList.toggle("on",+b.dataset.d===_o8.duty);}); }
  const e=document.getElementById("o8Etat"); if(e)e.textContent=_o8.son?"♪ en cours":"clique sur une forme pour l'entendre";
  o8Dessiner();
}
function o8Freq(){ return 440*Math.pow(2,(_o8.midi-69)/12); }
function o8Choisir(k){
  const meme=_o8.onde===k&&_o8.son; _o8.onde=k; o8Arreter();
  if(!meme)o8Lancer();
  o8MajUI();
}
function o8Lancer(){
  o8JeuArreter();
  const ctx=audio(); if(ctx.state==="suspended")ctx.resume();
  const g=ctx.createGain(), t=ctx.currentTime, vol={sine:.25,square:.09,triangle:.25,sawtooth:.1,noise:.08}[_o8.onde];
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(vol,t+.02);
  g.gain.setValueAtTime(vol,t+3.6); g.gain.linearRampToValueAtTime(0,t+4);
  let src;
  if(_o8.onde==="noise"){ src=ctx.createBufferSource(); src.buffer=o8BruitBuffer(ctx); src.loop=true; src.playbackRate.value=o8Freq()/330; }
  else { src=ctx.createOscillator(); if(_o8.onde==="square")src.setPeriodicWave(o8Pulse(ctx,_o8.duty)); else src.type=_o8.onde; src.frequency.value=o8Freq(); }
  src.connect(g); g.connect(ctx.destination); src.start(t); src.stop(t+4.05);
  const son={src:src,g:g}; _o8.son=son;
  src.onended=function(){ if(_o8.son===son){_o8.son=null; o8MajUI();} };
}
function o8Arreter(){
  const s=_o8.son; if(!s)return; _o8.son=null;
  try{ const t=audio().currentTime; s.g.gain.cancelScheduledValues(t); s.g.gain.setValueAtTime(s.g.gain.value,t); s.g.gain.linearRampToValueAtTime(0,t+.03); s.src.stop(t+.05); }catch(e){}
}
function o8Hauteur(v){
  _o8.midi=+v; const s=_o8.son; if(!s){ o8Dessiner(); return; }
  const t=audio().currentTime;
  if(s.src.frequency)s.src.frequency.setTargetAtTime(o8Freq(),t,.02); else s.src.playbackRate.setTargetAtTime(o8Freq()/330,t,.02);
}
function o8Duty(d){ _o8.duty=d; if(_o8.son&&_o8.onde==="square"){ o8Arreter(); o8Lancer(); } o8MajUI(); }
function o8Forme(k,p,d){
  if(k==="sine")return Math.sin(2*Math.PI*p);
  if(k==="square")return p<d?1:-1;
  if(k==="triangle")return p<.5?4*p-1:3-4*p;
  if(k==="sawtooth")return 2*p-1;
  return 0;
}
function o8Toile(c){
  const r=window.devicePixelRatio||1, w=c.clientWidth, h=c.clientHeight;
  if(c.width!==Math.round(w*r)||c.height!==Math.round(h*r)){ c.width=Math.round(w*r); c.height=Math.round(h*r); }
  const x=c.getContext("2d"); x.setTransform(r,0,0,r,0,0); x.clearRect(0,0,w,h); return {x:x,w:w,h:h};
}
function o8Dessiner(){
  cancelAnimationFrame(_o8.anim);
  const c=document.getElementById("o8Scope"); if(!c){ o8Arreter(); o8JeuArreter(); return; }
  const T=o8Toile(c), x=T.x, w=T.w, h=T.h, o=O8_ONDES.find(function(z){return z.k===_o8.onde;});
  x.strokeStyle="rgba(255,255,255,.12)"; x.lineWidth=1; x.beginPath(); x.moveTo(0,h/2); x.lineTo(w,h/2); x.stroke();
  const per=2*Math.pow(2,(_o8.midi-57)/12), dec=_o8.son?(performance.now()/1000)*.6:0, amp=h*.36;
  x.strokeStyle=o.coul; x.lineWidth=2.5; x.shadowColor=o.coul; x.shadowBlur=_o8.son?10:0; x.beginPath();
  if(_o8.onde==="noise"){
    const pas=Math.max(3,9-per); let y=0;
    for(let i=0;i<=w;i+=pas){ const ny=h/2-(Math.random()*2-1)*amp; if(i===0)x.moveTo(0,ny); else { x.lineTo(i,y); x.lineTo(i,ny); } y=ny; }
  } else {
    for(let i=0;i<=w;i++){ let p=(i/w*per+dec)%1; const y=h/2-o8Forme(_o8.onde,p,_o8.duty)*amp; if(i===0)x.moveTo(i,y); else x.lineTo(i,y); }
  }
  x.stroke(); x.shadowBlur=0;
  o8DessinerCanaux();
  if(_o8.son||_o8.jeu)_o8.anim=requestAnimationFrame(o8Dessiner);
}

/* --- Partie 2 : les 4 canaux de la NES --- */
const O8_CANAUX=[
  {onde:"onde carrée",role:"la mélodie",coul:"#F2C94C"},
  {onde:"onde carrée",role:"l'accompagnement",coul:"#ffc38a"},
  {onde:"onde triangulaire",role:"la basse",coul:"#7ee0a4"},
  {onde:"bruit",role:"les percussions",coul:"#c9b6ff"}
];
// Korobeiniki (chanson populaire russe) : [midi ou null, durée en croches]
const O8_MEL=[[76,2],[71,1],[72,1],[74,2],[72,1],[71,1], [69,2],[69,1],[72,1],[76,2],[74,1],[72,1],
  [71,3],[72,1],[74,2],[76,2], [72,2],[69,2],[69,2],[null,2],
  [null,1],[74,2],[77,1],[81,2],[79,1],[77,1], [76,3],[72,1],[76,2],[74,1],[72,1],
  [71,2],[71,1],[72,1],[74,2],[76,2], [72,2],[69,2],[69,2],[null,2]];
const O8_ACC={E:[56,59],Am:[60,64],Dm:[53,57],C:[52,55]};
const O8_GRILLE=[["E","E"],["Am","Am"],["E","E"],["Am","Am"],["Dm","Dm"],["C","C"],["E","E"],["Am","Am"]];
const O8_BASSE=[[52,52],[57,57],[56,52],[57,57],[50,50],[48,48],[47,52],[57,57]];
function o8Partition(){
  const ev=[[],[],[],[]]; let t=0;
  O8_MEL.forEach(function(n){ if(n[0])ev[0].push([t,n[1],n[0]]); t+=n[1]; });
  for(let m=0;m<8;m++)for(let h=0;h<2;h++){
    const b=m*8+h*4, acc=O8_ACC[O8_GRILLE[m][h]], r=O8_BASSE[m][h];
    ev[1].push([b+1,.6,acc[0]]); ev[1].push([b+3,.6,acc[1]]);
    for(let k=0;k<4;k++)ev[2].push([b+k,.9,k%2?r+12:r]);
    for(let k=0;k<4;k++)ev[3].push([b+k,k===2?1:.3,k===0?"boum":k===2?"tchak":"tss"]);
  }
  return ev;
}
const O8_CROCHE=.2, O8_BOUCLE=64;
function o8JeuBasculer(){ if(_o8.jeu)o8JeuArreter(); else o8JeuLancer(); }
function o8JeuLancer(){
  const ctx=audio(); if(ctx.state==="suspended")ctx.resume();
  o8Arreter();
  const maitre=ctx.createGain(); maitre.gain.value=.55; maitre.connect(ctx.destination);
  const canaux=O8_CANAUX.map(function(c,i){
    const g=ctx.createGain(), an=ctx.createAnalyser(); an.fftSize=1024;
    const on=document.getElementById("o8C"+i); g.gain.value=on&&!on.classList.contains("on")?0:1;
    g.connect(an); an.connect(maitre); return {g:g,an:an};
  });
  const j={maitre:maitre,canaux:canaux,ev:o8Partition(),debut:ctx.currentTime+.1,prochain:0,sources:[],p1:o8Pulse(ctx,.25),p2:o8Pulse(ctx,.5)};
  _o8.jeu=j;
  j.minuteur=setInterval(o8JeuPlanifier,25); o8JeuPlanifier();
  const b=document.getElementById("o8Jouer"); if(b)b.innerHTML='<i class="ph-fill ph-stop"></i> Arrêter';
  o8Dessiner();
}
function o8JeuPlanifier(){
  const j=_o8.jeu; if(!j)return;
  if(!document.getElementById("onde8")){ o8JeuArreter(); return; }
  const ctx=audio(), limite=ctx.currentTime+.15;
  while(j.debut+j.prochain*O8_CROCHE<limite){
    const pas=j.prochain%O8_BOUCLE, t0=j.debut+j.prochain*O8_CROCHE;
    j.ev.forEach(function(liste,c){ liste.forEach(function(e){ if(e[0]===pas)o8Note(j,c,t0,e[1]*O8_CROCHE,e[2]); }); });
    j.prochain++;
  }
  j.sources=j.sources.filter(function(s){return s.fin>ctx.currentTime;});
}
function o8Note(j,c,t,dur,h){
  const ctx=audio(), g=ctx.createGain(); let src, vol;
  if(c===3){
    src=ctx.createBufferSource(); src.buffer=o8BruitBuffer(ctx); src.loop=true;
    const f=ctx.createBiquadFilter();
    if(h==="boum"){ f.type="lowpass"; f.frequency.value=260; vol=.9; dur=.12; src.playbackRate.value=.25; }
    else if(h==="tchak"){ f.type="bandpass"; f.frequency.value=1800; vol=.45; dur=.14; }
    else { f.type="highpass"; f.frequency.value=6000; vol=.18; dur=.035; }
    src.connect(f); f.connect(g);
    g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(.001,t+dur);
  } else {
    src=ctx.createOscillator(); src.frequency.value=440*Math.pow(2,(h-69)/12);
    if(c===2)src.type="triangle"; else src.setPeriodicWave(c===0?j.p1:j.p2);
    vol=c===0?.16:c===1?.08:.45;
    src.connect(g);
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(vol,t+.005);
    g.gain.setValueAtTime(vol,Math.max(t+.006,t+dur-.03)); g.gain.linearRampToValueAtTime(0,t+dur);
  }
  g.connect(j.canaux[c].g); src.start(t); src.stop(t+dur+.02);
  j.sources.push({src:src,fin:t+dur+.02});
}
function o8JeuArreter(){
  const j=_o8.jeu; if(!j)return; _o8.jeu=null; clearInterval(j.minuteur);
  try{ const t=audio().currentTime; j.maitre.gain.setTargetAtTime(0,t,.02); j.sources.forEach(function(s){try{s.src.stop(t+.08);}catch(e){}}); setTimeout(function(){try{j.maitre.disconnect();}catch(e){}},300); }catch(e){}
  const b=document.getElementById("o8Jouer"); if(b)b.innerHTML='<i class="ph-fill ph-play"></i> Lancer la musique';
  o8DessinerCanaux();
}
function o8Canal(i){
  const b=document.getElementById("o8C"+i); if(!b)return;
  const on=!b.classList.contains("on"); b.classList.toggle("on",on);
  if(_o8.jeu)_o8.jeu.canaux[i].g.gain.setTargetAtTime(on?1:0,audio().currentTime,.015);
}
function o8DessinerCanaux(){
  const j=_o8.jeu, buf=new Float32Array(1024);
  O8_CANAUX.forEach(function(c,i){
    const cv=document.getElementById("o8S"+i); if(!cv)return;
    const T=o8Toile(cv), x=T.x, w=T.w, h=T.h;
    x.strokeStyle=c.coul; x.lineWidth=2; x.beginPath();
    if(!j){ x.globalAlpha=.35; x.moveTo(0,h/2); x.lineTo(w,h/2); x.stroke(); x.globalAlpha=1; return; }
    j.canaux[i].an.getFloatTimeDomainData(buf);
    let d=0; for(let k=1;k<512;k++){ if(buf[k-1]<0&&buf[k]>=0){ d=k; break; } }
    const n=i===2?300:180;
    for(let k=0;k<n;k++){ const y=h/2-Math.max(-1,Math.min(1,buf[d+k]*2.2))*h*.42; const px=k/(n-1)*w; if(k===0)x.moveTo(px,y); else x.lineTo(px,y); }
    x.stroke();
  });
}

/* Un lecteur peut être bloqué selon le réseau (mode restreint de YouTube imposé par
   l'établissement, filtre, compte Google d'élève mineur, maison de disques). Le lecteur
   intégré le signale par un message « onError » (API JS de YouTube, enablejsapi=1) :
   on passe alors à la version de secours (data-yt2="id1,id2") ou on explique le blocage. */
function ceLireYT(btn,id){
  const box=btn.parentElement;
  if(ceYTlocal()){ window.open("https://www.youtube.com/watch?v="+id,"_blank","noopener"); return; }
  box._ytListe=[id].concat((box.getAttribute("data-yt2")||"").split(",").map(function(x){return x.trim();}).filter(Boolean));
  box._ytI=0;
  ceYTCharger(box);
}
function ceYTCharger(box){
  const id=box._ytListe[box._ytI], lien="https://www.youtube.com/watch?v="+id;
  box.innerHTML=`<div class="ce-yt-cadre"><iframe src="https://www.youtube-nocookie.com/embed/${id}?rel=0&autoplay=1&enablejsapi=1&origin=${encodeURIComponent(location.origin)}"
      title="Extrait musical" frameborder="0" allow="accelerometer;autoplay;encrypted-media;picture-in-picture" allowfullscreen></iframe></div>
    <a class="ce-yt-secours" href="${lien}" target="_blank" rel="noopener noreferrer">
      <i class="ph ph-arrow-square-out"></i> La vidéo ne s'affiche pas ? L'ouvrir sur YouTube</a>`;
  const f=box.querySelector("iframe");
  /* on demande au lecteur de nous prévenir de ses événements (dont les erreurs) */
  const ecouter=function(){ try{ f.contentWindow.postMessage(JSON.stringify({event:"listening",id:"ceyt",channel:"widget"}),"*"); }catch(e){} };
  f.addEventListener("load",function(){ ecouter(); setTimeout(ecouter,700); setTimeout(ecouter,2000); });
}
window.addEventListener("message",function(ev){
  let h=""; try{ h=new URL(ev.origin).hostname; }catch(e){ return; }
  if(!/(^|\.)youtube(-nocookie)?\.com$/.test(h))return;
  let d=ev.data; if(typeof d==="string"){ try{ d=JSON.parse(d); }catch(e){ return; } }
  if(!d||d.event!=="onError")return;
  const box=[].slice.call(document.querySelectorAll(".ce-yt")).find(function(b){ const f=b.querySelector("iframe"); return f&&f.contentWindow===ev.source; });
  if(!box||!box._ytListe)return;
  if(box._ytI<box._ytListe.length-1){ box._ytI++; ceYTCharger(box); return; }
  const lien="https://www.youtube.com/watch?v="+box._ytListe[0];
  box.innerHTML='<div class="ce-yt-bloque"><i class="ph-fill ph-prohibit"></i><span><b>Cette vidéo est bloquée sur cet appareil ou ce réseau</b> (mode restreint de YouTube ou filtre de l\'établissement). Demande à ton professeur de la projeter au tableau, ou <a href="'+lien+'" target="_blank" rel="noopener noreferrer">essaie de l\'ouvrir sur YouTube</a>.</span></div>';
});

/* ---------- Schéma des pistes (Bouncing) ---------- */
function ceMonterPistes(){
  const d=document.getElementById("cePistes"); if(!d)return;
  const av=[["1","Batterie"],["2","Piano"],["3","Voix A"],["4","Voix B"],["5","Voix C"],["6","(libre)"]];
  const ap=[["1","Batterie"],["2","Piano"],["3","(libre)"],["4","(libre)"],["5","(libre)"],["6","Voix A+B+C"]];
  const bloc=function(titre,l){return `<div class="ce-magneto"><div class="cm-t">${titre}</div>`+
    l.map(function(p){return `<div class="cm-p${p[1].indexOf("libre")>=0?" libre":""}"><span>${p[0]}</span>${p[1]}</div>`;}).join("")+`</div>`;};
  d.innerHTML=bloc("AVANT le Bouncing",av)+`<div class="ce-fleche"><i class="ph ph-arrow-right"></i></div>`+bloc("APRÈS le Bouncing",ap);
}

/* ---------- Rendu des exercices ---------- */
function ceExHTML(x,i){
  const cle="ex"+ceEtape+"_"+i;
  let corps="";
  if(x.type==="qcm"||x.type==="sondage"){
    corps=`<div class="ce-opts" id="${cle}">`+x.opts.map(function(o,k){
      return `<button class="ce-opt" data-k="${k}" onclick="ceChoisir(this)">${o}</button>`;}).join("")+`</div>`;
  } else if(x.type==="lettres"){
    /* on groupe les cases PAR MOT : un mot ne doit jamais être coupé en fin de ligne */
    let k=-1;
    corps=`<div class="ce-lettres" id="${cle}">`+x.mot.split(" ").map(function(mot,mi){
      if(mi>0)k++;                                   // on saute l'espace séparateur
      return `<span class="ce-mot">`+mot.split("").map(function(){
        k++;
        return `<input class="ce-lettre" data-i="${k}" maxlength="1" inputmode="text" autocomplete="off"
          oninput="ceLettreSuiv(this)" onkeydown="ceLettreRet(event,this)">`;}).join("")+`</span>`;
    }).join("")+`</div>`;
  } else if(x.type==="grille"){
    corps=`<table class="ce-grille" id="${cle}"><thead><tr><th></th>`+
      x.cols.map(function(c){return "<th>"+c+"</th>";}).join("")+`</tr></thead><tbody>`+
      x.rows.map(function(r,ri){return `<tr data-r="${ri}"><td class="cg-lib">${r.t}</td>`+
        x.cols.map(function(_,ci){return `<td class="cg-case" data-c="${ci}" onclick="ceCocher(this)"><i class="ph ph-check"></i></td>`;}).join("")+`</tr>`;}).join("")+
      `</tbody></table>`;
  } else if(x.type==="etiquettes"){
    corps=`<div class="ce-etiq" id="${cle}">
      <div class="ce-banque" ondragover="ceDragSurv(event,this)" ondrop="ceRendreBanque(event,this)">`+melangerVoc(x.mots.slice()).map(function(m){
        return `<button class="ce-et" draggable="true" data-m="${escapeHtml(m)}" onclick="cePrendre(this)"
          ondragstart="ceDragDebut(event,this)" ondragend="ceDragFin(this)">${m}</button>`;}).join("")+`</div>
      <div class="ce-cases">`+(x.melangerCases?melangerVoc(x.cases.map(function(c,ci){return {c:c,ci:ci};})):x.cases.map(function(c,ci){return {c:c,ci:ci};})).map(function(o){
        return `<div class="ce-case" data-i="${o.ci}" onclick="cePoser(this)"
          ondragover="ceDragSurv(event,this)" ondragleave="this.classList.remove('survol')" ondrop="ceDeposer(event,this)"
          ><span class="cc-lib">${o.c.lib}</span><span class="cc-slot">glisse ici</span></div>`;}).join("")+`</div></div>`;
  } else if(x.type==="ordre"){
    corps=`<div class="ce-ordre" id="${cle}">`+melangerVoc(x.items.map(function(t,k){return {t:t,k:k};})).map(function(o){
      return `<button class="ce-item" data-k="${o.k}" onclick="ceOrdonner(this)"><span class="ci-n"></span><span class="ci-t">${o.t}</span></button>`;}).join("")+`</div>`;
  } else if(x.type==="calcul"){
    corps=`<div class="ce-calc" id="${cle}">`+x.champs.map(function(c,ci){
      return `<label class="ce-ch"><span>${c.lib}</span><span class="ce-in"><input type="number" data-i="${ci}" inputmode="numeric"><em>${c.unite||""}</em></span></label>`;}).join("")+`</div>`;
  } else if(x.type==="libre"){
    corps=`<div class="ce-libre" id="${cle}"><textarea rows="4" placeholder="Écris ta réponse ici…"></textarea></div>`;
  } else if(x.type==="studio"){
    corps=`<div class="stu" id="${cle}" data-e="${ceEtape}" data-i="${i}"></div>`;
  }
  const q=x.q?`<p class="ce-q">${x.q}</p>`:"";
  const cons=x.consigne?`<p class="ce-consigne">${x.consigne}</p>`:"";
  const aide=x.aide?`<div class="ce-aide"><i class="ph ph-lightbulb"></i> ${x.aide}</div>`:"";
  const btn=x.type==="studio" ? "" : x.type==="libre"
    ? `<button class="action btn-nouv" onclick="ceVoirModele(${i})"><i class="ph ph-eye"></i> Voir une réponse possible</button>`
    : x.type==="sondage"
    ? `<button class="action btn-corr" onclick="ceSondage(${i})"><i class="ph ph-paper-plane-tilt"></i> Valider mon ressenti</button>`
    : `<button class="action btn-corr" onclick="ceVerifier(${i})"><i class="ph ph-check-circle"></i> Vérifier</button>
       <button class="action ce-btn-corr-dir" onclick="ceVerifier(${i},true)" title="Essaie d'abord par toi-même : on retient bien mieux ce qu'on a cherché !"><i class="ph ph-eye"></i> Voir la correction</button>`;
  return `<div class="ce-ex" data-ex="${i}">
    <div class="ce-ex-tete"><i class="ph-fill ph-game-controller"></i> Exercice ${i+1}</div>
    ${q}${cons}${aide}${corps}
    <div class="ce-actions">${btn}</div>
    <div class="ce-corr" id="corr${ceEtape}_${i}"></div>
  </div>`;
}

/* ---------- Interactions ---------- */
function ceChoisir(b){
  const p=b.parentElement;
  p.querySelectorAll(".ce-opt").forEach(function(o){o.classList.remove("sel");});
  b.classList.add("sel");
}
function ceCocher(td){
  const tr=td.parentElement;
  tr.querySelectorAll(".cg-case").forEach(function(c){c.classList.remove("sel");});
  td.classList.add("sel");
}
let ceEtiq=null;
/* ---- Glisser-déposer (souris) ; le clic reste actif comme repli tactile ---- */
function ceDragDebut(ev,b){
  if(b.classList.contains("place")){ ev.preventDefault(); return; }
  ceEtiq=b; b.classList.add("prise");
  try{ ev.dataTransfer.setData("text/plain",b.getAttribute("data-m")); ev.dataTransfer.effectAllowed="move"; }catch(e){}
}
function ceDragFin(b){ b.classList.remove("prise"); document.querySelectorAll(".ce-case.survol").forEach(function(c){c.classList.remove("survol");}); }
function ceDragSurv(ev,el){
  if(!ceEtiq)return;
  ev.preventDefault();
  try{ ev.dataTransfer.dropEffect="move"; }catch(e){}
  if(el.classList.contains("ce-case"))el.classList.add("survol");
}
function ceDeposer(ev,c){
  ev.preventDefault(); c.classList.remove("survol");
  if(!ceEtiq)return;
  cePoser(c,true);
}
/* on ramène une étiquette dans la réserve en la relâchant sur celle-ci */
function ceRendreBanque(ev,banque){
  ev.preventDefault();
  if(!ceEtiq)return;
  const m=ceEtiq.getAttribute("data-m");
  const c=banque.parentElement.querySelector('.ce-case[data-m="'+CSS.escape(m)+'"]');
  if(c){ c.classList.remove("plein"); c.removeAttribute("data-m"); c.querySelector(".cc-slot").innerHTML="glisse ici"; }
  ceEtiq.classList.remove("place","prise"); ceEtiq=null;
}
function cePrendre(b){
  if(b.classList.contains("place"))return;
  const box=b.closest(".ce-etiq");
  box.querySelectorAll(".ce-et").forEach(function(e){e.classList.remove("prise");});
  b.classList.add("prise"); ceEtiq=b;
}
function cePoser(c){
  const box=c.closest(".ce-etiq");
  /* si la case est déjà remplie : on rend l'étiquette à la banque */
  if(c.classList.contains("plein")){
    const m=c.getAttribute("data-m");
    const et=box.querySelector('.ce-et[data-m="'+CSS.escape(m)+'"]');
    if(et){et.classList.remove("place","prise");}
    c.classList.remove("plein"); c.removeAttribute("data-m");
    c.querySelector(".cc-slot").innerHTML="glisse ici";
    if(!ceEtiq)return;
  }
  if(!ceEtiq||!box.contains(ceEtiq))return;
  const m=ceEtiq.getAttribute("data-m");
  c.classList.add("plein"); c.setAttribute("data-m",m);
  c.querySelector(".cc-slot").innerHTML=ceEtiq.innerHTML;
  ceEtiq.classList.add("place"); ceEtiq.classList.remove("prise"); ceEtiq=null;
}
function ceOrdonner(b){
  const box=b.parentElement;
  if(b.classList.contains("fige"))return;              // rang déjà validé : on n'y touche plus
  if(b.classList.contains("num")){                     // on retire ce choix
    b.classList.remove("num","arevoir"); b.querySelector(".ci-n").textContent="";
    return;
  }
  /* on attribue le plus petit rang encore libre (les rangs déjà justes sont conservés) */
  const pris={}; box.querySelectorAll(".ce-item.num").forEach(function(it){pris[+it.querySelector(".ci-n").textContent]=1;});
  let n=1; while(pris[n])n++;
  b.classList.add("num"); b.classList.remove("arevoir"); b.querySelector(".ci-n").textContent=n;
}

/* ---------- Correction ---------- */
/* Saisie lettre par lettre : on avance/recule tout seul entre les cases. */
/* navigation d'une case à l'autre, y compris d'un mot au suivant */
function ceVoisine(inp,pas){
  const l=[...inp.closest(".ce-lettres").querySelectorAll(".ce-lettre")];
  return l[l.indexOf(inp)+pas]||null;
}
function ceLettreSuiv(inp){
  inp.value=(inp.value||"").toUpperCase();
  inp.classList.remove("arevoir","juste","faux");
  if(inp.value){ const n=ceVoisine(inp,1); if(n)n.focus(); }
}
function ceLettreRet(ev,inp){
  if(ev.key==="Backspace"&&!inp.value){ const p=ceVoisine(inp,-1); if(p){p.focus();p.value="";} }
}
/* Sondage : aucune mauvaise réponse, on recueille le ressenti puis on commente. */
function ceSondage(i){
  const x=ceDef().etapes[ceEtape].ex[i], box=document.getElementById("ex"+ceEtape+"_"+i);
  const corr=document.getElementById("corr"+ceEtape+"_"+i);
  const sel=box.querySelector(".ce-opt.sel");
  if(!sel){ corr.className="ce-corr manque"; corr.innerHTML=`<i class="ph ph-warning-circle"></i> Choisis d'abord une réponse.`; return; }
  box.querySelectorAll(".ce-opt").forEach(function(o){ o.disabled=true; if(o!==sel)o.classList.add("estompe"); });
  corr.className="ce-corr gagne";
  corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-chat-teardrop-text"></i> Merci pour ta réponse&nbsp;!</div>
    <div class="cc-expl">${x.expl}</div>`;
  const z=document.querySelector('.ce-ex[data-ex="'+i+'"] .ce-actions');
  if(z)z.innerHTML="";
  try{jouerEffet("valider");}catch(e){}
  ceMarquerEx(ceEtape,i); ceMajVerrou();
}
/* Analyse les réponses SANS rien modifier à l'écran.
   Renvoie {repondu, bon, total, faux:[…]} où `faux` liste les éléments à revoir. */
function ceAnalyser(x,box){
  let bon=0,total=0,repondu=true;const faux=[];
  if(x.type==="qcm"){
    total=1;const sel=box.querySelector(".ce-opt.sel");
    if(!sel)repondu=false;
    else if(+sel.getAttribute("data-k")===x.r)bon=1;
    else faux.push(sel);
  } else if(x.type==="grille"){
    total=x.rows.length;
    box.querySelectorAll("tbody tr").forEach(function(tr){
      const ri=+tr.getAttribute("data-r"),sel=tr.querySelector(".cg-case.sel");
      if(!sel){repondu=false;return;}
      if(+sel.getAttribute("data-c")===x.rows[ri].r)bon++; else faux.push(sel);
    });
  } else if(x.type==="etiquettes"){
    total=x.cases.length;
    box.querySelectorAll(".ce-case").forEach(function(c){
      const ci=+c.getAttribute("data-i"),m=c.getAttribute("data-m");
      if(!m){repondu=false;return;}
      if(norm(m)===norm(x.cases[ci].r))bon++; else faux.push(c);
    });
  } else if(x.type==="ordre"){
    total=x.items.length;
    const its=[...box.querySelectorAll(".ce-item.num")];
    if(its.length<total)repondu=false;
    else its.forEach(function(it){
      if(+it.querySelector(".ci-n").textContent===(+it.getAttribute("data-k"))+1)bon++; else faux.push(it);
    });
  } else if(x.type==="calcul"){
    total=x.champs.length;
    box.querySelectorAll("input").forEach(function(inp){
      const ci=+inp.getAttribute("data-i"),v=inp.value.trim();
      if(v===""){repondu=false;return;}
      if(parseFloat(v.replace(",","."))===x.champs[ci].r)bon++; else faux.push(inp);
    });
  } else if(x.type==="lettres"){
    total=x.mot.replace(/ /g,"").length;
    box.querySelectorAll(".ce-lettre").forEach(function(inp){
      const k=+inp.getAttribute("data-i"),v=(inp.value||"").trim();
      if(v===""){repondu=false;return;}
      if(norm(v)===norm(x.mot[k]))bon++; else faux.push(inp);
    });
  }
  return {repondu:repondu,bon:bon,total:total,faux:faux};
}
/* Indice par défaut selon le type de jeu, quand l'exercice n'en fournit pas. */
function ceIndiceAuto(x,n){
  const p=(n>1);
  switch(x.type){
    case "qcm": return "Relis la question mot à mot, puis <b>élimine</b> les réponses impossibles avant de choisir.";
    case "grille": return p?("<b>"+n+" lignes</b> sont à revoir (surlignées en orange). Reprends-les une par une."):
                            "<b>1 ligne</b> est à revoir (surlignée en orange).";
    case "etiquettes": return p?("<b>"+n+" étiquettes</b> ne sont pas à leur place : elles sont revenues dans la réserve. Commence par celles dont tu es sûr."):
                                "<b>1 étiquette</b> n'est pas à sa place : elle est revenue dans la réserve.";
    case "ordre": return p?("<b>"+n+" étapes</b> sont mal placées. Demande-toi ce qui doit <b>logiquement</b> arriver en premier."):
                           "<b>1 étape</b> est mal placée. Relis l'ordre logique des opérations.";
    case "calcul": return p?("<b>"+n+" résultats</b> sont à revoir. Vérifie ton opération et l'unité demandée."):
                            "<b>1 résultat</b> est à revoir. Vérifie ton opération et l'unité demandée.";
    case "lettres": return p?("<b>"+n+" lettres</b> sont à corriger (cases orange). Épelle le mot syllabe par syllabe."):
                             "<b>1 lettre</b> est à corriger. Relis le mot lettre à lettre.";
  }
  return "Reprends les éléments surlignés en orange.";
}
/* Étape 1 : on montre CE QUI ne va pas (sans donner la réponse) et on invite à retenter. */
function ceDiagnostic(x,r,box){
  r.faux.forEach(function(el){
    if(x.type==="qcm"){ el.classList.remove("sel"); el.classList.add("arevoir"); }
    else if(x.type==="grille"){ el.classList.remove("sel"); el.classList.add("arevoir"); }
    else if(x.type==="etiquettes"){
      const m=el.getAttribute("data-m");
      const et=box.querySelector('.ce-et[data-m="'+CSS.escape(m)+'"]');
      if(et)et.classList.remove("place","prise");          // l'étiquette repart dans la réserve
      el.classList.remove("plein"); el.removeAttribute("data-m");
      el.querySelector(".cc-slot").innerHTML="glisse ici";
      el.classList.add("arevoir");
    }
    else if(x.type==="ordre"){ el.classList.remove("num"); el.querySelector(".ci-n").textContent=""; el.classList.add("arevoir"); }
    else if(x.type==="calcul"||x.type==="lettres"){ el.value=""; el.classList.add("arevoir"); }
  });
  /* ce qui est juste est verrouillé : l'élève ne refait que ce qui coince */
  if(x.type==="etiquettes"){
    box.querySelectorAll(".ce-case.plein").forEach(function(c){c.classList.add("ok-fige");c.onclick=null;});
  } else if(x.type==="ordre"){
    box.querySelectorAll(".ce-item.num").forEach(function(it){it.classList.add("fige");});
  } else if(x.type==="calcul"||x.type==="lettres"){
    box.querySelectorAll("input").forEach(function(inp){ if(!inp.classList.contains("arevoir"))inp.disabled=true; });
    const p=box.querySelector("input.arevoir"); if(p)p.focus();
  } else if(x.type==="grille"){
    box.querySelectorAll("tbody tr").forEach(function(tr){ if(tr.querySelector(".cg-case.sel"))tr.classList.add("fige"); });
  }
}
/* Étape 2 (ou correction demandée) : on révèle les bonnes réponses. */
function ceReveler(x,box){
  if(x.type==="qcm"){
    box.querySelectorAll(".ce-opt").forEach(function(o){
      const k=+o.getAttribute("data-k");
      if(k===x.r)o.classList.add("juste");
      else if(o.classList.contains("sel")||o.classList.contains("arevoir"))o.classList.add("faux");
      o.classList.remove("arevoir");
    });
  } else if(x.type==="grille"){
    box.querySelectorAll("tbody tr").forEach(function(tr){
      const ri=+tr.getAttribute("data-r"),sel=tr.querySelector(".cg-case.sel")||tr.querySelector(".cg-case.arevoir");
      tr.querySelectorAll(".cg-case").forEach(function(td){
        const ci=+td.getAttribute("data-c");
        td.classList.remove("arevoir");
        if(ci===x.rows[ri].r)td.classList.add("juste");
        else if(td===sel)td.classList.add("faux");
      });
    });
  } else if(x.type==="etiquettes"){
    box.querySelectorAll(".ce-case").forEach(function(c){
      const ci=+c.getAttribute("data-i"),m=c.getAttribute("data-m");
      c.classList.remove("arevoir");
      const ok=(m&&norm(m)===norm(x.cases[ci].r));
      c.classList.add(ok?"juste":"faux");
      if(!ok)c.querySelector(".cc-slot").innerHTML=(m?`<s>${m}</s> `:"")+`<b>→ ${x.cases[ci].r}</b>`;
    });
  } else if(x.type==="ordre"){
    box.querySelectorAll(".ce-item").forEach(function(it){
      const k=+it.getAttribute("data-k"),n=it.querySelector(".ci-n"),pos=n.textContent?+n.textContent:null;
      it.classList.remove("arevoir");
      const ok=(pos===k+1);
      it.classList.add(ok?"juste":"faux");
      if(!ok)n.innerHTML=(pos||"?")+"<b>→"+(k+1)+"</b>";
    });
  } else if(x.type==="calcul"){
    box.querySelectorAll("input").forEach(function(inp){
      const ci=+inp.getAttribute("data-i"),v=inp.value.trim();
      inp.classList.remove("arevoir");
      const ok=(v!==""&&parseFloat(v.replace(",","."))===x.champs[ci].r);
      inp.classList.add(ok?"juste":"faux"); inp.disabled=true;
      if(!ok&&!inp.parentElement.querySelector(".ce-vrai"))
        inp.parentElement.insertAdjacentHTML("beforeend",`<b class="ce-vrai">${x.champs[ci].r}</b>`);
    });
  } else if(x.type==="lettres"){
    box.querySelectorAll(".ce-lettre").forEach(function(inp){
      const k=+inp.getAttribute("data-i"),v=(inp.value||"").trim();
      inp.classList.remove("arevoir");
      const ok=(v!==""&&norm(v)===norm(x.mot[k]));
      inp.classList.add(ok?"juste":"faux"); inp.disabled=true;
      if(!ok)inp.value=x.mot[k];      // on écrit la bonne lettre à la place
    });
  }
}
/* Correction en DEUX TEMPS :
   1er essai raté  → on montre ce qui ne va pas + un indice, et l'élève retente ;
   2e essai raté   → correction complète.
   `forcer` = l'élève a cliqué « Voir la correction » (déconseillé, mais disponible). */
function ceVerifier(i,forcer){
  const x=ceDef().etapes[ceEtape].ex[i], cle="ex"+ceEtape+"_"+i, box=document.getElementById(cle);
  const corr=document.getElementById("corr"+ceEtape+"_"+i);
  const kEss=ceEtape+"_"+i;
  const r=ceAnalyser(x,box);
  if(!r.repondu&&!forcer){
    corr.className="ce-corr manque";
    corr.innerHTML=`<i class="ph ph-warning-circle"></i> Réponds à <b>tout</b> l'exercice avant de vérifier.`;
    return;
  }
  const zoneBtn=document.querySelector('.ce-ex[data-ex="'+i+'"] .ce-actions');
  /* --- tout juste --- */
  if(r.bon===r.total&&!forcer){
    ceReveler(x,box);
    const premier=!ceEssais[kEss];
    corr.className="ce-corr gagne";
    corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-seal-check"></i> Bravo, tout est juste&nbsp;!${premier?"":" (après correction)"}</div>
      ${x.expl?`<div class="cc-expl">${x.expl}</div>`:""}`;
    if(zoneBtn)zoneBtn.innerHTML=`<button class="action" onclick="ecranCoursEnr(${ceEtape})"><i class="ph ph-arrow-counter-clockwise"></i> Refaire cet exercice</button>`;
    try{jouerEffet("bon");}catch(e){}
    if(premier){ try{ajouterPoints(3);}catch(e){} }
    delete ceEssais[kEss];
    ceMarquerEx(ceEtape,i); ceMajVerrou();
    return;
  }
  /* --- correction demandée explicitement (bouton « Voir la correction ») --- */
  if(forcer){
    ceReveler(x,box);
    corr.className="ce-corr partiel";
    corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-info"></i> Voici la correction</div>
      ${x.expl?`<div class="cc-expl">${x.expl}</div>`:""}`;
    if(zoneBtn)zoneBtn.innerHTML=`<button class="action" onclick="ecranCoursEnr(${ceEtape})"><i class="ph ph-arrow-counter-clockwise"></i> Refaire cet exercice</button>`;
    try{jouerEffet("mauvais");}catch(e){}
    delete ceEssais[kEss];
    ceMarquerEx(ceEtape,i); ceMajVerrou();
    return;
  }
  const essai=(ceEssais[kEss]||0)+1;
  ceEssais[kEss]=essai;
  /* --- Tableau à cocher (grille) : la réponse est binaire, révéler la correction
     ne sert à rien (« si ce n'est pas à droite, c'est à gauche »). On ne marque PAS
     les lignes fausses et on ne révèle JAMAIS : on donne seulement le nombre de
     bonnes réponses et on encourage. L'élève doit valider tout seul (tout juste). --- */
  if(x.type==="grille"){
    corr.className="ce-corr diagnostic";
    corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-list-checks"></i> ${r.bon} / ${r.total} bonnes réponses</div>
      <div class="cc-relance"><i class="ph ph-arrow-counter-clockwise"></i> Reprends les lignes et réessaie : tu vas y arriver&nbsp;! Le tableau se validera quand tout sera juste.</div>`;
    if(zoneBtn)zoneBtn.innerHTML=`<button class="action btn-corr" onclick="ceVerifier(${i})"><i class="ph ph-check-circle"></i> Vérifier à nouveau</button>`;
    try{jouerEffet("mauvais");}catch(e){}
    return;
  }
  /* --- Essai raté : diagnostic + indice, on NE donne PAS la réponse. La correction
     ne se débloque qu'au 2e essai raté (l'élève a vu l'indice et réessayé). --- */
  ceDiagnostic(x,r,box);
  const indice=(ceDef().indices[kEss]||ceIndiceAuto(x,r.faux.length));
  const peutCorr=(essai>=2);
  corr.className="ce-corr diagnostic";
  corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-lightbulb"></i> Presque&nbsp;! ${r.bon} / ${r.total} : reprends ce qui est en orange</div>
    <div class="cc-expl"><b>Ce qui ne va pas encore :</b> ${indice}</div>
    <div class="cc-relance"><i class="ph ph-arrow-counter-clockwise"></i> Corrige, puis re-clique sur <b>Vérifier</b>. Ce qui était juste est déjà validé&nbsp;!${peutCorr?" Si tu bloques, tu peux maintenant voir la correction." :""}</div>`;
  if(zoneBtn)zoneBtn.innerHTML=
    `<button class="action btn-corr" onclick="ceVerifier(${i})"><i class="ph ph-check-circle"></i> Vérifier à nouveau</button>`
    +(peutCorr
       ? `<button class="action ce-btn-corr-dir" onclick="ceVerifier(${i},true)" title="Essaie d'abord de trouver par toi-même : tu retiendras bien mieux !"><i class="ph ph-eye"></i> Voir la correction</button>`
       : `<button class="action ce-btn-corr-dir" disabled title="Réessaie d'abord avec l'indice : la correction s'activera si tu n'y arrives pas."><i class="ph ph-lock-simple"></i> Voir la correction</button>`);
  try{jouerEffet("mauvais");}catch(e){}
}
/* Met à jour le verrou de navigation sans re-dessiner la page (on garde les corrections à l'écran). */
/* Pastille de droite du bandeau d'étape : ce qu'il reste à faire sur l'étape. */
function ceFixeResteHTML(reste){
  return reste?'<i class="ph-fill ph-pencil-simple-line"></i> '+reste+' exercice'+(reste>1?"s":"")+' à faire'
              :'<i class="ph-fill ph-check-circle"></i> Étape terminée';
}
function ceMajVerrou(){
  const reste=ceFait(ceEtape)?0:ceRestants(ceEtape), bloque=(!ceProf()&&reste>0);
  const fx=document.getElementById("ceFixeReste");
  if(fx){ fx.innerHTML=ceFixeResteHTML(reste); fx.classList.toggle("ok",!reste); }
  const nav=document.querySelector(".ce-nav .btn-corr");
  if(nav)nav.disabled=bloque;
  const av=document.querySelector(".ce-verrou");
  if(bloque){
    if(av)av.querySelector("span").innerHTML=`Il te reste <b>${reste} exercice${reste>1?"s":""}</b> à faire sur cette étape avant de pouvoir continuer.`;
  } else if(av){
    av.className="ce-verrou ouvert";
    av.innerHTML=`<i class="ph-fill ph-lock-simple-open"></i><span>Étape terminée&nbsp;! Tu peux passer à la suite.</span>`;
  }
  /* la pastille de l'étape passe en « fait » dès que tout est terminé */
  const pas=document.querySelectorAll(".ce-fil .ce-pas")[ceEtape];
  if(pas&&reste===0)pas.classList.add("fait");
}
function ceVoirModele(i){
  const x=ceDef().etapes[ceEtape].ex[i];
  const corr=document.getElementById("corr"+ceEtape+"_"+i);
  const ta=document.querySelector("#ex"+ceEtape+"_"+i+" textarea");
  /* on n'ouvre la réponse type que si l'élève a VRAIMENT rédigé quelque chose */
  const ecrit=(ta?ta.value.trim():"" ).replace(/\s+/g," ");
  if(!ceProf()&&ecrit.length<20){
    corr.className="ce-corr manque";
    corr.innerHTML=`<i class="ph ph-warning-circle"></i> Rédige d'abord <b>ta propre réponse</b> (une phrase complète au minimum), puis tu pourras comparer.`;
    if(ta)ta.focus();
    return;
  }
  corr.className="ce-corr gagne";
  corr.innerHTML=`<div class="cc-score"><i class="ph-fill ph-chat-teardrop-text"></i> Une réponse possible</div>
    <div class="cc-expl">${x.modele}</div>
    <div class="cc-relance"><i class="ph ph-scales"></i> Compare avec ce que tu as écrit : as-tu pensé aux mêmes idées&nbsp;?</div>`;
  try{jouerEffet("valider");}catch(e){}
  ceMarquerEx(ceEtape,i); ceMajVerrou();
}

/* ---------- Écran de fin ---------- */
/* « Tu as débloqué… » : dit à l'élève OÙ retrouver l'entraînement et l'évaluation
   du cours qu'il vient de terminer (Leçons › Évaluations des cours de collège).
   Sur l'accueil, la carte n'apparaît qu'une fois par cours (profil.cours[id].annonceVue). */
function ceDebloqueHTML(id){ const surAccueil=false;
  const d=COURS_DEF[id]; if(!d)return "";
  return '<div class="ce-debloque'+(surAccueil?' accueil-carte':'')+'" data-cours="'+id+'">'
    +(surAccueil?'<button type="button" class="ce-debloque-x" aria-label="J\u2019ai compris" title="J\u2019ai compris" onclick="coursAnnonceVue(\''+id+'\')"><i class="ph ph-x"></i></button>':'')
    +'<div class="ce-debloque-ic"><i class="ph-fill ph-lock-key-open"></i></div>'
    +'<div class="ce-debloque-t"><b>Débloqué&nbsp;: entraînement et évaluation'+(surAccueil?' de « '+d.titre+' »':'')+'&nbsp;!</b>'
    +'<p>Tu les retrouveras à tout moment dans <b><i class="ph ph-graduation-cap"></i> Leçons</b>, rubrique <b>Évaluations des cours de collège</b>. '
    +'Commence par <b>t\u2019entraîner</b> (à gauche), puis passe l\u2019<b>évaluation</b> (à droite) quand tu te sens prêt.</p>'
    +'<button type="button" class="action btn-corr" onclick="'+(surAccueil?'coursAnnonceVue(\''+id+'\',true);':'')+'ouvrir(\'evalcours-'+id+'\')"><i class="ph ph-barbell"></i> Y aller maintenant</button></div></div>';
}
function coursAnnonceVue(id){
  try{ if(profil.cours&&profil.cours[id]){ profil.cours[id].annonceVue=true; sauverProfil(profil); } }catch(e){}
}
function ceFinal(){
  try{ const pf=ceProfil(); if(!pf.fini)pf.fini=Date.now(); pf.annonceVue=true; sauverProfil(profil); }catch(e){}
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  document.getElementById("titre").innerHTML='<i class="ph ph-flag-checkered"></i> Cours terminé';
  document.getElementById("intro").textContent="";
  const p=ceProfil();
  document.getElementById("zone").innerHTML=`
   <div class="accueil" style="max-width:620px">
     <div class="ex" style="text-align:center">
       <div style="font-size:3rem;line-height:1"><i class="ph-fill ph-trophy" style="color:var(--or-texte)"></i></div>
       <h3 style="margin:8px 0">Tu as terminé le parcours&nbsp;!</h3>
       <p style="color:var(--encre-doux)">${ceDef().finTxt}</p>
       <p style="color:var(--encre-doux);font-size:.9rem">${p.faits.length} étape${p.faits.length>1?"s":""} sur ${ceDef().etapes.length} parcourue${p.faits.length>1?"s":""}.</p>
     </div>
     ${ceDef().evalId?ceDebloqueHTML(ceCours):""}
     ${ceDef().module?`<button class="action ${ceDef().evalId?"btn-nouv":"btn-corr"}" onclick="ouvrir('${ceDef().module}')"><i class="ph ph-barbell"></i> S'entraîner sur le thème</button>`:""}
     <button class="action btn-nouv" onclick="ecranCoursEnr(0)"><i class="ph ph-arrow-counter-clockwise"></i> Revoir le cours</button>
     <button class="action" onclick="accueil()"><i class="ph ph-house"></i> Retour à l'accueil</button>
   </div>`;
  try{jouerEffet("victoire");}catch(e){}
  if(typeof remonter==="function")remonter();
}

/* =====================================================================
   STUDIO DE MONTAGE (type d'exercice « studio » des cours interactifs)
   Un petit Audacity : pistes superposées avec leur forme d'onde, bouton
   Muet, volume, sélection d'un passage, Effets ▸ Changer le tempo (sans
   changer la hauteur, par WSOLA) et Effets ▸ Inverser le sens, Annuler.
   Les MISSIONS de l'exercice se valident toutes seules, dans l'ordre.
   Le projet (pistes et effets) est gardé d'une étape à l'autre du cours ;
   `depart` le reconstitue si l'élève arrive directement sur une étape.
   ===================================================================== */
const STU_SONS={
  cf_voix:{nom:"Claude François voix",url:"sons/recre-cf-voix.mp3",js:"sons/recre-cf-voix.js",coul:"#ff9f7a"},
  cf_instru:{nom:"Comme d'habitude instrumentale",url:"sons/recre-cf-instru.mp3",js:"sons/recre-cf-instru.js",coul:"#F2C94C"},
  piano_lom:{nom:"Piano Life on Mars",url:"sons/recre-piano-lom.mp3",js:"sons/recre-piano-lom.js",coul:"#7fd3ff"},
  bowie_voix:{nom:"David Bowie voix",url:"sons/recre-bowie-voix.mp3",js:"sons/recre-bowie-voix.js",coul:"#c9b6ff"},
  ballad:{nom:"Ballad of the Goddess",url:"sons/recre-ballad.mp3",js:"sons/recre-ballad.js",coul:"#7ee0a4"},
  berceuse:{nom:"Zelda's Lullaby (Berceuse de Zelda)",url:"sons/recre-berceuse.mp3",js:"sons/recre-berceuse.js",coul:"#ffc38a"},
  harpe:{nom:"Berceuse de Zelda, harpe celtique",url:"sons/recre-berceuse-harpe.mp3",js:"sons/recre-berceuse-harpe.js",coul:"#f5a3c7"},
  ss:{nom:"Berceuse de Zelda, version Skyward Sword",url:"sons/recre-berceuse-ss.mp3",js:"sons/recre-berceuse-ss.js",coul:"#9fe3e0"},
  faint:{nom:"Tania Meets Klebb (Bons baisers de Russie)",url:"sons/recre-faint-sample.mp3",js:"sons/recre-faint-sample.js",coul:"#ff7a9c"}
};
let _stuProj={}, _stuBufs={}, _stu=null;

/* Page ouverte depuis le disque (file://) : le navigateur interdit fetch() sur les
   fichiers voisins. On charge alors le même son encodé dans un petit script
   (sons/recre-*.js), seule façon qui marche aussi hors serveur. En ligne, on lit
   le MP3 directement et le script ne sert que de secours. */
function stuSonScript(id){
  return new Promise(function(ok,ko){
    const deja=window.STU_B64&&window.STU_B64[id]; if(deja){ ok(deja); return; }
    const sc=document.createElement("script"); sc.src=STU_SONS[id].js;
    sc.onload=function(){ const b=window.STU_B64&&window.STU_B64[id]; if(b)ok(b); else ko(new Error("vide")); };
    sc.onerror=function(){ ko(new Error("script absent")); };
    document.head.appendChild(sc);
  }).then(function(b64){
    const bin=atob(b64), u=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    try{ delete window.STU_B64[id]; }catch(e){}
    return u.buffer;
  });
}
function stuCharger(id){
  if(_stuBufs[id])return _stuBufs[id];
  const ctx=audio();
  const direct=location.protocol==="file:"?Promise.reject(new Error("file"))
    :fetch(STU_SONS[id].url).then(function(r){ if(!r.ok)throw new Error("HTTP "+r.status); return r.arrayBuffer(); });
  _stuBufs[id]=direct.catch(function(){ return stuSonScript(id); })
    .then(function(ab){ return new Promise(function(ok,ko){ ctx.decodeAudioData(ab,ok,ko); }); })
    .then(function(b){
      if(b.numberOfChannels===1)return b;
      const m=ctx.createBuffer(1,b.length,b.sampleRate), d=m.getChannelData(0), nc=b.numberOfChannels;
      for(let c=0;c<nc;c++){ const s=b.getChannelData(c); for(let k=0;k<d.length;k++)d[k]+=s[k]/nc; }
      return m;
    });
  _stuBufs[id].catch(function(e){ delete _stuBufs[id]; try{ console.warn("Studio : son non chargé", id, e); }catch(_){} });
  return _stuBufs[id];
}
/* message d'erreur qui dit la vraie cause (et non « vérifie ta connexion » à tort) */
function stuErreurSon(){
  toast(location.protocol==="file:"
    ?"Ce son n'a pas pu être chargé : le dossier « Sons » doit rester à côté de museduc7.html."
    :(navigator.onLine===false?"Pas de connexion Internet : impossible de charger ce son."
      :"Ce son est introuvable sur le serveur : le site a-t-il bien été republié (dossier sons compris) ?"));
}
function stuProjet(nom){ return _stuProj[nom]||(_stuProj[nom]={pistes:[],a:null,b:null,tete:0,hist:[],charge:"",enCours:{}}); }
/* Ajoute une piste au projet UNE seule fois, même si le studio est redessiné pendant le
   chargement (sinon deux chargements parallèles donnaient deux « Ballad of the Goddess »).
   Renvoie {p, neuve}. */
function stuAjouter(P,id,regler){
  const ex=stuPiste(P,id); if(ex)return Promise.resolve({p:ex,neuve:false});
  if(!P.enCours)P.enCours={};
  if(P.enCours[id])return P.enCours[id];
  P.charge=STU_SONS[id].nom;
  const pr=stuCharger(id).then(function(b){
    let p=stuPiste(P,id); if(p)return {p:p,neuve:false};
    p=stuNouvelle(id,b); if(regler)regler(p,b); P.pistes.push(p);
    return {p:p,neuve:true};
  });
  P.enCours[id]=pr;
  const fin=function(){ delete P.enCours[id]; P.charge=Object.keys(P.enCours).length?P.charge:""; };
  pr.then(fin,fin);
  return pr;
}
function stuPiste(P,id){ return P.pistes.find(function(p){return p.id===id;})||null; }
function stuNouvelle(id,buf){ return {id:id,buf:buf,muet:false,vol:1,choisie:false,bpm:null,inv:[],pk:null,dt:0,edl:[{a:0,b:buf.duration,r:false}]}; }
/* ---- Carte de montage (EDL) : de quelle partie du fichier source vient chaque morceau
   de la piste. {a,b} = secondes dans le SOURCE, r = lu à l'envers. Elle suit toutes les
   manipulations (supprimer, inverser, copier-coller), ce qui permet de vérifier un montage
   quel que soit l'ordre des gestes. Un changement de tempo la rend inconnue (null). ---- */
function edlDuree(e){ return e.reduce(function(n,s){return n+(s.b-s.a);},0); }
function edlTranche(e,t0,t1){
  const out=[]; let t=0;
  e.forEach(function(s){ const L=s.b-s.a, x0=Math.max(t0,t), x1=Math.min(t1,t+L);
    if(x1>x0){ const u0=x0-t, u1=x1-t; out.push(s.r?{a:s.b-u1,b:s.b-u0,r:true}:{a:s.a+u0,b:s.a+u1,r:false}); }
    t+=L; });
  return out;
}
function edlNorm(e){
  const o=[];
  e.forEach(function(s){ if(s.b-s.a<0.005)return; const p=o[o.length-1];
    if(p&&p.r===s.r&&(s.r?Math.abs(p.a-s.b)<0.003:Math.abs(p.b-s.a)<0.003)){ if(s.r)p.a=s.a; else p.b=s.b; }
    else o.push({a:s.a,b:s.b,r:s.r}); });
  return o;
}
function edlCouper(e,t0,t1){ return edlNorm(edlTranche(e,0,t0).concat(edlTranche(e,t1,1e9))); }
function edlInverser(e,t0,t1){ return edlNorm(edlTranche(e,0,t0).concat(edlTranche(e,t0,t1).reverse().map(function(s){return {a:s.a,b:s.b,r:!s.r};}),edlTranche(e,t1,1e9))); }
function edlInserer(e,t,clip){ return edlNorm(edlTranche(e,0,t).concat(clip.map(function(s){return {a:s.a,b:s.b,r:s.r};}),edlTranche(e,t,1e9))); }
/* ---- Morceaux de son ---- */
function stuMorceau(buf,t0,t1){ const sr=buf.sampleRate, d=buf.getChannelData(0); return d.slice(Math.max(0,Math.floor(t0*sr)),Math.min(d.length,Math.floor(t1*sr))); }
function stuAssembler(parts,sr){
  const L=parts.reduce(function(n,p){return n+p.length;},0), b=audio().createBuffer(1,Math.max(1,L),sr), d=b.getChannelData(0);
  let o=0; parts.forEach(function(p){ d.set(p,o); o+=p.length; }); return b;
}
/* Hauteur sans changer la durée : étirement (WSOLA) puis rééchantillonnage. */
function stuTransposer(buf,n){
  const r=Math.pow(2,n/12), st=stuEtirer(buf,1/r).getChannelData(0), L=buf.length;
  const out=audio().createBuffer(1,L,buf.sampleRate), d=out.getChannelData(0);
  for(let i=0;i<L;i++){ const x=i*r, k=Math.floor(x), f=x-k; d[i]=(st[k]||0)*(1-f)+(st[k+1]||0)*f; }
  return out;
}
function stuInstant(p){ return {t:"etat",p:p,buf:p.buf,bpm:p.bpm,inv:p.inv.slice(),edl:p.edl,dt:p.dt||0}; }
function stuDuree(){ let d=8; if(_stu)_stu.P.pistes.forEach(function(p){ d=Math.max(d,p.buf.duration); }); return d; }
function stuT(t){ t=Math.max(0,t); const m=Math.floor(t/60), s=t-m*60; return m+":"+(s<10?"0":"")+s.toFixed(1); }

/* ---- Étirement temporel sans changer la hauteur (WSOLA) ---- */
function stuEtirer(buf,ratio){
  const x=buf.getChannelData(0), sr=buf.sampleRate, N=2048, Hs=1024, Ha=Hs*ratio, tol=512;
  const L=Math.max(1,Math.floor(x.length/ratio)), y=new Float32Array(L+N), ws=new Float32Array(L+N), w=new Float32Array(N);
  for(let j=0;j<N;j++)w[j]=0.5-0.5*Math.cos(2*Math.PI*j/N);
  let prev=0;
  for(let k=0;k*Hs<L;k++){
    const cible=Math.round(k*Ha); let pos=Math.min(Math.max(0,cible),Math.max(0,x.length-N));
    if(k>0){
      const nat=prev+Hs; let meil=-Infinity, bd=0;
      const tester=function(d){ const q=cible+d; if(q<0||q+N>x.length||nat+N>x.length)return;
        let c=0; for(let j=0;j<N/2;j+=4)c+=x[nat+j]*x[q+j]; if(c>meil){meil=c;bd=d;} };
      for(let d=-tol;d<=tol;d+=8)tester(d);
      const g=bd; for(let d=g-7;d<=g+7;d++)tester(d);
      if(meil>-Infinity)pos=cible+bd;
    }
    const o=k*Hs;
    for(let j=0;j<N;j++){ const v=x[pos+j]||0; y[o+j]+=v*w[j]; ws[o+j]+=w[j]; }
    prev=pos;
  }
  const out=audio().createBuffer(1,L,sr), d=out.getChannelData(0);
  for(let i=0;i<L;i++)d[i]=ws[i]>1e-3?y[i]/ws[i]:y[i];
  return out;
}
function stuCopie(buf){ const b=audio().createBuffer(1,buf.length,buf.sampleRate); b.getChannelData(0).set(buf.getChannelData(0)); return b; }

/* ---- Montage de l'exercice ---- */
function stuMonter(){
  const box=document.querySelector(".stu[data-e]"); if(!box)return;
  const e=+box.dataset.e, i=+box.dataset.i, x=ceDef().etapes[e].ex[i];
  stuDemarrer(box,x,{mode:"cours",fini:ceExFait(e,i),e:e,i:i,surReussi:function(){
    const corr=document.getElementById("corr"+e+"_"+i);
    if(corr){ corr.className="ce-corr gagne";
      corr.innerHTML='<div class="cc-score"><i class="ph-fill ph-seal-check"></i> Montage réussi&nbsp;!</div>'+(x.expl?'<div class="cc-expl">'+x.expl+'</div>':''); }
    try{ jouerEffet("bon"); }catch(err){}
    if(!ceExFait(e,i)){ try{ ajouterPoints(3); }catch(err){} }
    ceMarquerEx(e,i); ceMajVerrou();
  }});
}
/* Ouvre le studio dans `box` pour l'exercice `x`. Modes : "cours" et "entrain" (missions
   cochées au fur et à mesure), "eval" (consignes numérotées, rien n'est coché : la note
   est calculée à la fin de l'évaluation par stuNoter). */
function stuDemarrer(box,x,o){
  o=o||{};
  stuStop(false);
  const P=stuProjet(x.projet), fini=!!o.fini;
  /* une étape ne montre que SES fichiers : une piste importée ailleurs (ex. la harpe
     de l'étape 12) ne doit pas réapparaître dans une autre étape */
  if(x.biblio){ const ok=x.biblio.concat((x.depart||[]).map(function(d){return d.p;}));
    P.pistes=P.pistes.filter(function(p){ return ok.indexOf(p.id)>=0; }); }
  _stu={box:box,x:x,e:o.e,i:o.i,mode:o.mode||"cours",surReussi:o.surReussi||null,P:P,lect:null,anim:0,fini:fini,faits:x.missions.map(function(){return fini;}),cumul:{}};
  box.innerHTML=(x.modele?`<div class="stu-modele"><span><i class="ph-fill ph-headphones"></i> <b>Le résultat à obtenir</b> : écoute-le avant de commencer, puis compare avec ton montage.</span><audio controls preload="none" src="${x.modele}"></audio></div>`:"")+`<div class="stu-app">
    <div class="stu-menus">
      <span class="stu-logo"><i class="ph-fill ph-waveform"></i> Studio</span>
      <button class="stu-menu" onclick="stuMenu('fichier',this)">Fichier <i class="ph ph-caret-down"></i></button>
      <button class="stu-menu" onclick="stuMenu('edition',this)">Édition <i class="ph ph-caret-down"></i></button>
      <button class="stu-menu" onclick="stuMenu('effets',this)">Effets <i class="ph ph-caret-down"></i></button>
      <button class="stu-menu" onclick="stuAnnuler()" title="Annuler la dernière action"><i class="ph ph-arrow-u-up-left"></i> Annuler</button>
      <span class="stu-sp"></span>
      <button class="stu-menu" onclick="stuToutChoisir()"><i class="ph ph-selection-all"></i> Tout sélectionner</button>
    </div>
    <div class="stu-transport">
      <button class="stu-tb play" id="stuPlay" onclick="stuLecture()" title="Lecture / pause"><i class="ph-fill ph-play"></i></button>
      <button class="stu-tb" onclick="stuStop(true)" title="Stop"><i class="ph-fill ph-stop"></i></button>
      <button class="stu-tb" onclick="stuDebut()" title="Revenir au début"><i class="ph-fill ph-skip-back"></i></button>
      <span class="stu-temps" id="stuTemps">0:00.0</span>
      <span class="stu-info" id="stuInfo"></span>
    </div>
    <div class="stu-zone" id="stuZone"></div>
    <div class="stu-bas"><span><i class="ph ph-brackets-square"></i> Sélection</span>
      <label>début <input id="stuA" class="stu-temps-in" type="text" inputmode="decimal" autocomplete="off" oninput="stuSaisieSel()"> s</label>
      <label>fin <input id="stuB" class="stu-temps-in" type="text" inputmode="decimal" autocomplete="off" oninput="stuSaisieSel()"> s</label>
      <button class="stu-fin" onclick="stuSelFin()" title="Étend la sélection jusqu'au bout de la piste"><i class="ph ph-arrow-line-right"></i> jusqu'à la fin</button>
      <button class="stu-lien" onclick="stuEffacerSel()">effacer</button></div>
    <div class="stu-pop" id="stuPop" hidden></div>
  </div>
  <div class="stu-missions" id="stuMissions"></div>`;
  stuRendre(); stuMissionsMaj();
  stuDepart(x).then(function(){ if(_stu&&_stu.box===box){ stuRendre(); stuVerifier(); } });
}
function stuDepart(x){
  const P=stuProjet(x.projet); let ch=Promise.resolve();
  (x.depart||[]).forEach(function(d){
    ch=ch.then(function(){
      if(stuPiste(P,d.p))return;
      const pr=stuAjouter(P,d.p,function(p,b){
        if(d.bpm){ p.buf=stuEtirer(b,d.bpm/(x.tempoDe||86)); p.bpm=d.bpm; }
        if(d.muet)p.muet=true;
      });
      if(_stu&&_stu.P===P)stuRendre();
      return pr;
    });
  });
  return ch.catch(function(){ stuErreurSon(); }).then(function(){ P.charge=""; });
}

/* ---- Rendu ---- */
function stuRendre(){
  const z=document.getElementById("stuZone"); if(!z||!_stu)return;
  const P=_stu.P;
  let h="";
  if(!P.pistes.length&&!P.charge)
    h='<div class="stu-vide"><i class="ph ph-tray-arrow-down"></i> Aucune piste pour l\'instant.<br>Ouvre le menu <b>Fichier ▸ Importer ▸ Audio</b>.</div>';
  else {
    h='<div class="stu-regle"><div class="stu-coin"></div><div class="stu-onde"><canvas id="stuRegle"></canvas></div></div>';
    h+=P.pistes.map(function(p,k){
      const s=STU_SONS[p.id];
      return `<div class="stu-piste${p.choisie?" choisie":""}${p.muet?" muette":""}" style="--c:${s.coul}">
        <div class="stu-tete" onclick="stuChoisir(${k})" title="Clique pour sélectionner la piste">
          <div class="stu-nom">${escapeHtml(s.nom)}</div>
          <div class="stu-badges">${p.bpm?'<span><i class="ph ph-metronome"></i> '+p.bpm+' BPM</span>':''}${(p.inv.length||(p.edl&&p.edl.some(function(z){return z.r;})))?'<span><i class="ph ph-arrows-left-right"></i> inversé</span>':''}${p.dt?'<span><i class="ph ph-music-notes"></i> '+(p.dt>0?"+":"")+p.dt+' demi-ton'+(Math.abs(p.dt)>1?"s":"")+'</span>':''}</div>
          <div class="stu-ctrl" onclick="event.stopPropagation()">
            <button class="stu-m${p.muet?" on":""}" onclick="stuMuet(${k})">${p.muet?'<i class="ph-fill ph-speaker-slash"></i> Muet':'<i class="ph-fill ph-speaker-high"></i> Son'}</button>
            <input type="range" min="0" max="1" step="0.05" value="${p.vol}" oninput="stuVol(${k},this.value)" title="Volume" aria-label="Volume">
            <button class="stu-x" onclick="stuRetirer(${k})" title="Retirer la piste"><i class="ph ph-x"></i></button>
          </div>
        </div>
        <div class="stu-onde" data-k="${k}"><canvas></canvas></div></div>`;
    }).join("");
    if(P.charge)h+='<div class="stu-charge"><i class="ph ph-circle-notch"></i> Importation de « '+escapeHtml(P.charge)+' »…</div>';
    h+='<div class="stu-tl" id="stuTL"></div>';
  }
  z.innerHTML=h;
  z.querySelectorAll(".stu-piste .stu-onde").forEach(function(o){ stuBrancher(o,+o.dataset.k); });
  const rg=document.getElementById("stuRegle"); if(rg)rg.parentElement.onclick=function(ev){ stuAller(stuTempsX(ev,rg.parentElement)); };
  stuDessiner(); stuMajSelInputs();
}
function stuToile(c){
  const r=window.devicePixelRatio||1, w=c.clientWidth, h=c.clientHeight;
  if(c.width!==Math.round(w*r)||c.height!==Math.round(h*r)){ c.width=Math.round(w*r); c.height=Math.round(h*r); }
  const x=c.getContext("2d"); x.setTransform(r,0,0,r,0,0); x.clearRect(0,0,w,h); return {x:x,w:w,h:h};
}
function stuDessiner(){
  if(!_stu)return;
  const P=_stu.P, dur=stuDuree();
  const rg=document.getElementById("stuRegle");
  if(rg){ const T=stuToile(rg), x=T.x, pas=T.w/dur<14?10:(T.w/dur<40?5:1);
    x.fillStyle="rgba(255,255,255,.55)"; x.font="11px Inter,sans-serif"; x.textBaseline="top";
    for(let s=0;s<=dur;s++){ const px=s/dur*T.w, grand=s%pas===0;
      x.fillRect(px,T.h-(grand?9:4),1,grand?9:4);
      if(grand&&px<T.w-20)x.fillText(stuT(s).replace(/\.0$/,""),px+3,1); } }
  document.querySelectorAll("#stuZone .stu-piste").forEach(function(row,k){
    const p=P.pistes[k]; if(!p)return;
    const c=row.querySelector("canvas"), T=stuToile(c), x=T.x, w=T.w, h=T.h, coul=STU_SONS[p.id].coul;
    const larg=Math.max(1,Math.round(p.buf.duration/dur*w));
    if(!p.pk||p.pk.length!==larg){
      const d=p.buf.getChannelData(0), pas=d.length/larg, pk=new Float32Array(larg*2);
      for(let i=0;i<larg;i++){ let mn=0,mx=0; const a=Math.floor(i*pas), b=Math.min(d.length,Math.floor((i+1)*pas));
        for(let j=a;j<b;j+=2){ const v=d[j]; if(v<mn)mn=v; else if(v>mx)mx=v; } pk[i*2]=mn; pk[i*2+1]=mx; }
      p.pk=pk;
    }
    p.inv.forEach(function(r){ const a=r[0]/dur*w, b=r[1]/dur*w;
      x.fillStyle="rgba(201,182,255,.16)"; x.fillRect(a,0,b-a,h);
      x.fillStyle="rgba(201,182,255,.9)"; x.fillRect(a,0,b-a,3); });
    x.globalAlpha=p.muet?.3:1; x.fillStyle=coul;
    for(let i=0;i<larg;i++){ const mn=p.pk[i*2], mx=p.pk[i*2+1]; const y1=h/2-mx*h*.46, y2=h/2-mn*h*.46; x.fillRect(i,y1,1,Math.max(1,y2-y1)); }
    x.globalAlpha=1;
    if(p.choisie&&P.a!=null&&P.b!=null&&P.b>P.a){ const a=P.a/dur*w, b=P.b/dur*w;
      x.fillStyle="rgba(255,255,255,.22)"; x.fillRect(a,0,b-a,h); x.fillStyle="#fff"; x.fillRect(a,0,1,h); x.fillRect(b-1,0,1,h); }
  });
  stuDessinerTete();
}
function stuDessinerTete(pos){
  const tl=document.getElementById("stuTL"), z=document.getElementById("stuZone"); if(!_stu)return;
  if(pos==null)pos=stuPos();
  const tt=document.getElementById("stuTemps"); if(tt)tt.textContent=stuT(pos)+" / "+stuT(stuDuree());
  if(!tl||!z)return;
  const o=z.querySelector(".stu-regle .stu-onde"); if(!o)return;
  tl.style.left=(o.offsetLeft+pos/stuDuree()*o.clientWidth)+"px";
}
function stuTempsX(ev,el){ const r=el.getBoundingClientRect(); return Math.max(0,Math.min(1,(ev.clientX-r.left)/r.width))*stuDuree(); }
/* glisser sur une forme d'onde = sélectionner un passage (un simple clic place la tête de lecture) */
function stuBrancher(o,k){
  o.onpointerdown=function(ev){
    if(!_stu)return; ev.preventDefault();
    const P=_stu.P, t0=stuTempsX(ev,o);
    if(!ev.shiftKey&&!ev.ctrlKey&&!ev.metaKey)P.pistes.forEach(function(p,j){ p.choisie=(j===k); }); else P.pistes[k].choisie=true;
    P.a=t0; P.b=t0;
    try{ o.setPointerCapture(ev.pointerId); }catch(e){}
    o.onpointermove=function(e2){ const t=stuTempsX(e2,o); P.a=Math.min(t0,t); P.b=Math.max(t0,t); stuDessiner(); stuMajSelInputs(); };
    o.onpointerup=function(e2){ o.onpointermove=null; o.onpointerup=null;
      if(P.b-P.a<0.15){ P.a=null; P.b=null; stuAller(t0); }
      stuRendre(); stuVerifier(); };
  };
}
function stuMajSelInputs(){
  const P=_stu&&_stu.P, a=document.getElementById("stuA"), b=document.getElementById("stuB"); if(!P||!a)return;
  const ok=P.a!=null&&P.b!=null&&P.b>P.a;
  const v=function(t){ return String(Math.round(t*100)/100).replace(".",","); };
  if(document.activeElement!==a)a.value=ok?v(P.a):""; if(document.activeElement!==b)b.value=ok?v(P.b):"";
}
function stuSaisieSel(){
  const P=_stu.P, a=parseFloat(String(document.getElementById("stuA").value).replace(",",".")), b=parseFloat(String(document.getElementById("stuB").value).replace(",","."));
  if(isFinite(a)&&isFinite(b)&&b>a){ P.a=Math.max(0,a); P.b=Math.min(stuDuree(),b);
    if(!P.pistes.some(function(p){return p.choisie;})&&P.pistes.length){
      const aud=P.pistes.filter(function(p){return !p.muet;});
      (aud.length===1?aud[0]:P.pistes[0]).choisie=true; } }
  stuRendre(); stuVerifier();
}
/* bouton « jusqu'à la fin » : la fin de la sélection = le bout de la piste */
function stuSelFin(){
  const P=_stu.P; if(!P.pistes.length)return;
  let ch=stuChoisies(); if(!ch.length){ const aud=P.pistes.filter(function(p){return !p.muet;}); ch=[aud.length===1?aud[0]:P.pistes[0]]; ch[0].choisie=true; }
  const fin=Math.max.apply(null,ch.map(function(p){return p.buf.duration;}));
  const a=document.getElementById("stuA"), b=document.getElementById("stuB");
  if(!String(a.value).trim())a.value="0";
  b.value=String(Math.round(fin*100)/100).replace(".",",");
  stuSaisieSel();
}
function stuEffacerSel(){ _stu.P.a=null; _stu.P.b=null; stuDessiner(); stuMajSelInputs(); }
function stuChoisir(k){ const p=_stu.P.pistes[k]; if(!p)return; p.choisie=!p.choisie; stuRendre(); stuVerifier(); }
function stuToutChoisir(){ const P=_stu.P; P.pistes.forEach(function(p){p.choisie=true;}); P.a=0; P.b=stuDuree(); stuRendre(); stuVerifier(); }

/* ---- Lecture ---- */
function stuPos(){ if(!_stu)return 0; const L=_stu.lect; return L?L.tete0+Math.max(0,audio().currentTime-L.t0):_stu.P.tete; }
function stuLecture(){
  if(!_stu)return;
  if(_stu.lect){ stuPause(); return; }
  const P=_stu.P; if(!P.pistes.length){ stuInfo("Importe d'abord une piste (Fichier ▸ Importer)."); return; }
  const ctx=audio(); if(ctx.state==="suspended")ctx.resume();
  if(P.tete>=stuDuree()-0.1)P.tete=0;
  const m=ctx.createGain(); m.gain.value=.9; m.connect(ctx.destination);
  const t0=ctx.currentTime+.06;
  const pl=P.pistes.map(function(p){ const g=ctx.createGain(); g.gain.value=p.muet?0:p.vol; g.connect(m);
    let s=null; if(P.tete<p.buf.duration){ s=ctx.createBufferSource(); s.buffer=p.buf; s.connect(g); s.start(t0,P.tete); }
    return {p:p,g:g,s:s}; });
  _stu.lect={t0:t0,tete0:P.tete,pl:pl,m:m,der:performance.now()};
  const b=document.getElementById("stuPlay"); if(b)b.innerHTML='<i class="ph-fill ph-pause"></i>';
  stuBoucle();
}
function stuCouper(L){ L.pl.forEach(function(o){ try{ o.s&&o.s.stop(); }catch(e){} }); try{ L.m.disconnect(); }catch(e){} }
function stuPause(){ if(!_stu||!_stu.lect)return; _stu.P.tete=stuPos(); stuCouper(_stu.lect); _stu.lect=null;
  const b=document.getElementById("stuPlay"); if(b)b.innerHTML='<i class="ph-fill ph-play"></i>'; stuDessinerTete(); }
function stuStop(debut){
  if(!_stu)return;
  cancelAnimationFrame(_stu.anim);
  if(_stu.lect){ stuCouper(_stu.lect); _stu.lect=null; }
  if(debut)_stu.P.tete=0;
  const b=document.getElementById("stuPlay"); if(b)b.innerHTML='<i class="ph-fill ph-play"></i>';
  stuDessinerTete();
}
function stuDebut(){ const j=!!(_stu&&_stu.lect); stuStop(true); if(j)stuLecture(); }
function stuAller(t){ const j=!!_stu.lect; if(j)stuPause(); _stu.P.tete=Math.max(0,Math.min(t,stuDuree())); stuDessinerTete(); if(j)stuLecture(); }
function stuBoucle(){
  if(!_stu)return;
  cancelAnimationFrame(_stu.anim);
  const L=_stu.lect;
  if(!document.body.contains(_stu.box)){ if(L)stuCouper(L); _stu.lect=null; return; }
  if(!L)return;
  const now=performance.now(), dt=Math.min(.25,(now-L.der)/1000); L.der=now;
  const pos=stuPos();
  if(pos>=stuDuree()){ stuStop(true); return; }
  if(audio().currentTime>=L.t0)stuCumuler(pos,dt);
  stuDessinerTete(pos);
  _stu.anim=requestAnimationFrame(stuBoucle);
}
function stuMuet(k){ const p=_stu.P.pistes[k]; p.muet=!p.muet; stuGainLive(p); stuRendre(); stuVerifier(); }
function stuVol(k,v){ const p=_stu.P.pistes[k]; p.vol=+v; stuGainLive(p); }
function stuGainLive(p){ const L=_stu.lect; if(!L)return; L.pl.forEach(function(o){ if(o.p===p)o.g.gain.setTargetAtTime(p.muet?0:p.vol,audio().currentTime,.02); }); }

/* ---- Menus, import, effets, annuler ---- */
function stuInfo(t){ const i=document.getElementById("stuInfo"); if(!i)return; i.textContent=t; clearTimeout(i._t); i._t=setTimeout(function(){ i.textContent=""; },4000); }
function stuPopFermer(){ const p=document.getElementById("stuPop"); if(p){ p.hidden=true; p.innerHTML=""; } }
function stuMenu(quoi,btn){
  const pop=document.getElementById("stuPop"); if(!pop)return;
  if(!pop.hidden&&pop.dataset.q===quoi){ stuPopFermer(); return; }
  pop.dataset.q=quoi;
  if(quoi==="fichier"){
    pop.innerHTML='<div class="stu-pop-t">Fichier ▸ Importer ▸ Audio…</div>'+(_stu.x.biblio||[]).map(function(id){
      const deja=!!stuPiste(_stu.P,id)||!!(_stu.P.enCours&&_stu.P.enCours[id]);
      return '<button class="stu-fich" '+(deja?"disabled":"")+' onclick="stuImporter(\''+id+'\')"><i class="ph ph-file-audio" style="color:'+STU_SONS[id].coul+'"></i> '+escapeHtml(STU_SONS[id].nom)+'.mp3'+(deja?' <em>déjà importé</em>':'')+'</button>';
    }).join("");
  } else if(quoi==="edition"){
    pop.innerHTML='<div class="stu-pop-t">Édition</div>'
      +'<button class="stu-fich" onclick="stuSupprimer()"><i class="ph ph-scissors"></i> Supprimer la sélection</button>'
      +'<button class="stu-fich" onclick="stuCopier()"><i class="ph ph-copy"></i> Copier</button>'
      +'<button class="stu-fich" onclick="stuColler()"><i class="ph ph-clipboard"></i> Coller'+(_stuPresse?' <em>'+String(_stuPresse.d.toFixed(1)).replace(".",",")+' s en mémoire</em>':'')+'</button>';
  } else {
    pop.innerHTML='<div class="stu-pop-t">Effets</div>'
      +'<button class="stu-fich" onclick="stuTempoDlg()"><i class="ph ph-metronome"></i> Changer le tempo…</button>'
      +'<button class="stu-fich" onclick="stuHauteurDlg()"><i class="ph ph-music-notes"></i> Changer la hauteur…</button>'
      +'<button class="stu-fich" onclick="stuInverser()"><i class="ph ph-arrows-left-right"></i> Inverser le sens</button>';
  }
  pop.style.left=Math.max(0,btn.offsetLeft)+"px"; pop.style.top=(btn.offsetTop+btn.offsetHeight+4)+"px";
  pop.hidden=false;
}
function stuImporter(id){
  stuPopFermer();
  const P=_stu.P; if(stuPiste(P,id)||(P.enCours&&P.enCours[id]))return;
  stuPause();
  const pr=stuAjouter(P,id); stuRendre();
  pr.then(function(r){ if(r.neuve)P.hist.push({t:"import",p:r.p}); }).catch(function(){ stuErreurSon(); })
  .then(function(){ P.charge=""; if(_stu&&_stu.P===P){ stuRendre(); stuVerifier(); } });
}
function stuRetirer(k){
  const P=_stu.P, p=P.pistes[k]; if(!p)return;
  stuPause(); P.pistes.splice(k,1); P.hist.push({t:"retrait",p:p,k:k}); stuRendre(); stuVerifier();
}
function stuChoisies(){ return _stu.P.pistes.filter(function(p){return p.choisie;}); }
function stuTempoDlg(){
  const pop=document.getElementById("stuPop"), ch=stuChoisies();
  if(!ch.length){ pop.innerHTML='<div class="stu-pop-t">Changer le tempo</div><p class="stu-pop-p"><i class="ph ph-warning-circle"></i> Sélectionne d\'abord une ou plusieurs pistes : clique sur leur nom (ou « Tout sélectionner »).</p>'; return; }
  const de=ch[0].bpm||_stu.x.tempoDe||86;
  pop.dataset.q="tempo";
  pop.innerHTML='<div class="stu-pop-t">Changer le tempo</div><p class="stu-pop-p">Accélère ou ralentit '+(ch.length>1?"les "+ch.length+" pistes sélectionnées":"la piste sélectionnée")+' sans changer la hauteur des notes.</p>'
    +'<label class="stu-champ">Tempo de départ <input id="stuBpmDe" type="number" value="'+de+'" min="30" max="250"> BPM</label>'
    +'<label class="stu-champ">Nouveau tempo <input id="stuBpmA" type="number" min="30" max="250" placeholder="?"> BPM</label>'
    +'<div class="stu-pop-btns"><button class="stu-ok" onclick="stuTempoAppliquer()">Appliquer</button><button class="stu-lien" onclick="stuPopFermer()">Annuler</button></div>';
  setTimeout(function(){ const i=document.getElementById("stuBpmA"); if(i)i.focus(); },30);
}
function stuTempoAppliquer(){
  const de=+document.getElementById("stuBpmDe").value, a=+document.getElementById("stuBpmA").value;
  if(!(de>=30&&de<=250&&a>=30&&a<=250)){ stuInfo("Indique deux tempos entre 30 et 250 BPM."); return; }
  const ch=stuChoisies(); if(!ch.length)return;
  stuPopFermer(); stuPause(); stuInfo("Calcul en cours…");
  setTimeout(function(){
    const P=_stu.P;
    ch.forEach(function(p){
      const base=p.bpm||de, r=a/base; if(Math.abs(r-1)<1e-3)return;
      P.hist.push(stuInstant(p));
      p.buf=stuEtirer(p.buf,r); p.bpm=a; p.edl=null; p.inv=p.inv.map(function(z){return [z[0]/r,z[1]/r];}); p.pk=null;
    });
    stuInfo("Tempo changé : "+a+" BPM"); stuRendre(); stuVerifier();
  },40);
}
function stuInverser(){
  stuPopFermer();
  const P=_stu.P, ch=stuChoisies();
  if(!ch.length){ _stu.conseil="Aucune piste n'est sélectionnée : clique sur le <b>nom</b> de la piste à inverser (elle s'entoure d'or), ou glisse directement sur sa forme d'onde."; stuMissionsMaj(); return; }
  if(!(P.a!=null&&P.b!=null&&P.b>P.a)){
    _stu.conseil="Aucun passage n'est sélectionné : <b>glisse</b> sur la forme d'onde de la piste pour choisir un passage (ou tape le début et la fin sous le studio), puis Effets ▸ Inverser le sens."+stuIndiceTheme(false);
    stuMissionsMaj(); return;
  }
  stuPause();
  const faites=[];
  ch.forEach(function(p){
    const d0=p.buf.duration, a=(P.a!=null&&P.b>P.a)?Math.min(P.a,d0):0, b=(P.a!=null&&P.b>P.a)?Math.min(P.b,d0):d0;
    if(b-a<0.05)return;
    P.hist.push(stuInstant(p));
    if(p.edl)p.edl=edlInverser(p.edl,a,b);
    const nb=stuCopie(p.buf), d=nb.getChannelData(0), sr=nb.sampleRate;
    let i=Math.floor(a*sr), j=Math.min(d.length,Math.floor(b*sr))-1;
    while(i<j){ const t=d[i]; d[i]=d[j]; d[j]=t; i++; j--; }
    p.buf=nb; p.pk=null;
    const deja=p.inv.findIndex(function(z){ return Math.abs(z[0]-a)<.05&&Math.abs(z[1]-b)<.05; });
    if(deja>=0)p.inv.splice(deja,1); else p.inv.push([a,b]);
    faites.push({p:p,z:[a,b]});
  });
  if(faites.length)P.tete=faites[0].z[0];
  _stu.conseil=faites.length?stuConseilInverse(faites)
    :"Rien n'a été inversé : la sélection est en dehors de la piste « "+STU_SONS[ch[0].id].nom+" » (elle est plus courte). Vérifie que tu as choisi la <b>bonne piste</b>, puis sélectionne un passage à l'intérieur.";
  stuInfo(faites.length?"Passage inversé : la tête de lecture est placée à son début, clique sur Lecture.":"");
  stuRendre(); stuVerifier();
}
/* ---- Édition : Supprimer, Copier, Coller (comme dans Audacity) ---- */
let _stuPresse=null;   // presse-papiers du studio {data, sr, edl, d}
function stuSelOk(){ const P=_stu.P; return P.a!=null&&P.b!=null&&P.b-P.a>0.02; }
function stuCibles(){
  const ch=stuChoisies(); if(ch.length)return ch;
  return _stu.P.pistes.length===1?[_stu.P.pistes[0]]:[];
}
function stuSansCible(){ _stu.conseil="Aucune piste n'est sélectionnée : clique sur le <b>nom</b> de la piste (elle s'entoure d'or), ou glisse sur sa forme d'onde."; stuMissionsMaj(); }
function stuSansSel(){ _stu.conseil="Aucun passage n'est sélectionné : <b>glisse</b> sur la forme d'onde, ou tape le début et la fin sous le studio."; stuMissionsMaj(); }
function stuSupprimer(){
  stuPopFermer();
  const P=_stu.P, ch=stuCibles(); if(!ch.length){ stuSansCible(); return; } if(!stuSelOk()){ stuSansSel(); return; }
  stuPause(); let n=0;
  ch.forEach(function(p){
    const d0=p.buf.duration, a=Math.min(P.a,d0), b=Math.min(P.b,d0); if(b-a<0.02)return;
    P.hist.push(stuInstant(p));
    p.buf=stuAssembler([stuMorceau(p.buf,0,a),stuMorceau(p.buf,b,d0)],p.buf.sampleRate);
    if(p.edl)p.edl=edlCouper(p.edl,a,b);
    p.inv=[]; p.pk=null; n++;
  });
  const a=P.a; P.a=null; P.b=null; P.tete=Math.min(a,stuDuree());
  _stu.conseil=""; stuInfo(n?"Passage supprimé.":"Rien à supprimer à cet endroit."); stuRendre(); stuVerifier();
}
function stuCopier(){
  stuPopFermer();
  const P=_stu.P, ch=stuCibles(); if(!ch.length){ stuSansCible(); return; } if(!stuSelOk()){ stuSansSel(); return; }
  const p=ch[0], d0=p.buf.duration, a=Math.min(P.a,d0), b=Math.min(P.b,d0);
  if(b-a<0.02){ stuInfo("La sélection est en dehors de la piste."); return; }
  _stuPresse={data:stuMorceau(p.buf,a,b),sr:p.buf.sampleRate,edl:p.edl?edlTranche(p.edl,a,b):null,d:b-a};
  _stu.conseil=""; stuMissionsMaj();
  stuInfo("Copié : "+String((b-a).toFixed(2)).replace(".",",")+" s. Utilise Édition ▸ Coller.");
}
/* Coller : insère le presse-papiers à la fin de la sélection (ou à la tête de lecture). */
function stuColler(){
  stuPopFermer();
  const P=_stu.P;
  if(!_stuPresse){ _stu.conseil="Le presse-papiers est vide : sélectionne d'abord un passage, puis Édition ▸ <b>Copier</b>."; stuMissionsMaj(); return; }
  const ch=stuCibles(); if(!ch.length){ stuSansCible(); return; }
  stuPause();
  const t=stuSelOk()?P.b:P.tete;
  ch.forEach(function(p){
    const d0=p.buf.duration, x=Math.max(0,Math.min(t,d0));
    P.hist.push(stuInstant(p));
    p.buf=stuAssembler([stuMorceau(p.buf,0,x),_stuPresse.data,stuMorceau(p.buf,x,d0)],p.buf.sampleRate);
    p.edl=(p.edl&&_stuPresse.edl)?edlInserer(p.edl,x,_stuPresse.edl):null;
    p.inv=[]; p.pk=null;
  });
  _stu.conseil=""; stuInfo("Collé ("+String(_stuPresse.d.toFixed(2)).replace(".",",")+" s)."); stuRendre(); stuVerifier();
}
function stuHauteurDlg(){
  const pop=document.getElementById("stuPop"), ch=stuCibles();
  if(!ch.length){ pop.innerHTML='<div class="stu-pop-t">Changer la hauteur</div><p class="stu-pop-p"><i class="ph ph-warning-circle"></i> Sélectionne d\'abord une piste : clique sur son nom (ou « Tout sélectionner »).</p>'; return; }
  pop.dataset.q="hauteur";
  pop.innerHTML='<div class="stu-pop-t">Changer la hauteur</div><p class="stu-pop-p">Rend le son plus aigu (+) ou plus grave (−) sans changer sa durée. Un <b>demi-ton</b> est le plus petit écart entre deux notes, comme entre deux touches voisines du piano.</p>'
    +'<label class="stu-champ">Demi-tons <input id="stuDemi" type="number" min="-12" max="12" step="1" placeholder="?"></label>'
    +'<div class="stu-pop-btns"><button class="stu-ok" onclick="stuHauteurAppliquer()">Appliquer</button><button class="stu-lien" onclick="stuPopFermer()">Annuler</button></div>';
  setTimeout(function(){ const i=document.getElementById("stuDemi"); if(i)i.focus(); },30);
}
function stuHauteurAppliquer(){
  const n=Math.round(+document.getElementById("stuDemi").value);
  if(!n||Math.abs(n)>12){ stuInfo("Indique un nombre de demi-tons entre -12 et +12 (0 ne change rien)."); return; }
  const ch=stuCibles(); if(!ch.length)return;
  stuPopFermer(); stuPause(); stuInfo("Calcul en cours…");
  setTimeout(function(){
    ch.forEach(function(p){ _stu.P.hist.push(stuInstant(p)); p.buf=stuTransposer(p.buf,n); p.dt=(p.dt||0)+n; p.pk=null; });
    stuInfo("Hauteur changée : "+(n>0?"+":"")+n+" demi-ton"+(Math.abs(n)>1?"s":"")+"."); stuRendre(); stuVerifier();
  },40);
}
function stuAnnuler(){
  const P=_stu.P, h=P.hist.pop(); if(!h){ stuInfo("Rien à annuler."); return; }
  stuPause();
  if(h.t==="import"){ const k=P.pistes.indexOf(h.p); if(k>=0)P.pistes.splice(k,1); }
  else if(h.t==="retrait"){ P.pistes.splice(Math.min(h.k,P.pistes.length),0,h.p); }
  else { h.p.buf=h.buf; h.p.bpm=h.bpm; h.p.inv=h.inv; h.p.edl=h.edl; h.p.dt=h.dt||0; h.p.pk=null; }
  _stu.conseil=""; stuInfo("Action annulée."); stuRendre(); stuVerifier();
}

/* ---- Missions ---- */
function stuAudibles(){ return _stu.P.pistes.filter(function(p){return !p.muet&&p.vol>0;}).map(function(p){return p.id;}).sort(); }
function stuMemes(a,b){ a=a.slice().sort(); b=b.slice().sort(); return a.length===b.length&&a.every(function(v,i){return v===b[i];}); }
/* missions d'état (vérifiées à chaque action) */
/* Épreuve « le sample de Faint » : on vérifie la carte de montage de la piste, à ±0,35 s près.
   Solution : garder 12,1-17,6 s du source, inverser, coller 3 fois la fin (4,7-5,5 s,
   soit 12,1-12,9 s du source à l'envers), recoller 1,2 s-fin, puis +2 demi-tons. */
const STU_TESTS=(function(){
  const pres=function(x,y){ return Math.abs(x-y)<=0.35; };
  const boucle=function(z){ return z&&z.r&&pres(z.a,12.1)&&pres(z.b,12.9); };
  const coupe=function(p){ const e=p&&p.edl; return !!e&&e.length>0&&pres(e[0].a,12.1)&&pres(e[0].b,17.6); };
  const inverse=function(p){ return coupe(p)&&p.edl[0].r; };
  const trois=function(p){ const e=p.edl; return inverse(p)&&boucle(e[1])&&boucle(e[2])&&boucle(e[3])&&!boucle(e[4]); };
  const reprise=function(p){ const e=p.edl; return trois(p)&&e.length===8&&e[4].r&&pres(e[4].a,12.1)&&pres(e[4].b,16.4)&&boucle(e[5])&&boucle(e[6])&&boucle(e[7]); };
  return {
    faintCoupe:coupe, faintInverse:inverse, faintBoucle:trois, faintReprise:reprise,
    faintHauteur:function(p){ return !!p&&p.dt===2; }
  };
})();
function stuEtatOk(m,P){
  P=P||_stu.P; const pi=function(id){return stuPiste(P,id);};
  if(m.t==="fn")return !!STU_TESTS[m.f](pi(m.p));
  if(m.t==="importe")return !!pi(m.p);
  if(m.t==="importeUn")return m.p.some(function(id){return !!pi(id);});
  if(m.t==="muet"){ const p=pi(m.p); return !!p&&p.muet; }
  if(m.t==="choisies")return m.p.every(function(id){ const p=pi(id); return p&&p.choisie; });
  if(m.t==="tempo")return m.p.every(function(id){ const p=pi(id); return p&&p.bpm===m.bpm; });
  if(m.t==="inverse"){ const p=pi(m.p); return !!p&&p.inv.some(function(z){ return stuInvOk(m,z); }); }
  if(m.t==="inverseUn")return m.p.some(function(id){ const p=pi(id); return p&&p.inv.length; });
  return null;   // mission d'écoute
}
function stuInvOk(m,z){
  if(m.couvre)return z[0]<=m.couvre[0]&&z[1]>=m.couvre[1]&&z[1]-z[0]<=m.max;
  return z[1]-z[0]<=m.max&&(Math.min(z[1],m.zone[1])-Math.max(z[0],m.zone[0]))>=m.min;
}
/* Après une inversion ratée, on explique POURQUOI (message qui reste affiché sous les missions). */
/* Indice sur l'emplacement du thème, de plus en plus précis à chaque essai raté
   (données de la mission : indices:[…]). compter=false : on rappelle l'indice sans l'avancer. */
function stuIndiceTheme(compter){
  const k=_stu.faits.indexOf(false), m=k>=0?_stu.x.missions[k]:null;
  if(!m||m.t!=="inverse"||!m.indices)return "";
  if(compter)_stu.echecs=(_stu.echecs||0)+1;
  const n=Math.max(0,Math.min(m.indices.length-1,(_stu.echecs||1)-1));
  return '<br><b><i class="ph ph-lightbulb-filament"></i> Indice'+(m.indices.length>1?" "+(n+1)+"/"+m.indices.length:"")+' :</b> '+m.indices[n];
}
/* Après une inversion ratée, on explique ce qui ne va pas et on donne un indice sur le thème. */
function stuConseilInverse(faites){
  const k=_stu.faits.indexOf(false), m=k>=0?_stu.x.missions[k]:null;
  if(!m||m.t!=="inverse"||stuEtatOk(m))return "";
  const nom=STU_SONS[m.p].nom;
  if(!faites.some(function(o){return o.p.id===m.p;}))
    return "Ce n'est pas la bonne piste : c'est « "+nom+" » qu'il faut inverser. Clique sur <b>Annuler</b>, puis sélectionne le passage sur cette piste.";
  const z=faites.filter(function(o){return o.p.id===m.p;})[0].z, f=function(t){return stuT(t).replace(/\.0$/,"");};
  return "Tu as inversé le passage de "+f(z[0])+" à "+f(z[1])+", mais ce n'est pas le premier thème. Clique sur <b>Annuler</b> et réessaie."+stuIndiceTheme(true);
}
/* missions d'écoute : le temps s'accumule pendant la lecture si les conditions sont remplies */
function stuCumuler(pos,dt){
  const k=_stu.faits.indexOf(false); if(k<0)return;
  const m=_stu.x.missions[k]; if(stuEtatOk(m)!==null)return;
  const aud=stuAudibles(); let ok=false;
  if(m.t==="ecoute")ok=stuMemes(aud,m.p);
  else if(m.t==="ecouteZone")ok=stuMemes(aud,m.p)&&pos>=m.zone[0]&&pos<=m.zone[1]&&stuPiste(_stu.P,m.p[0]).inv.length>0;
  else if(m.t==="ecouteInv")ok=_stu.P.pistes.some(function(p){ return m.p.indexOf(p.id)>=0&&!p.muet&&p.vol>0&&p.inv.some(function(z){return pos>=z[0]&&pos<=z[1];}); });
  if(!ok)return;
  _stu.cumul[k]=(_stu.cumul[k]||0)+dt;
  if(_stu.cumul[k]>=m.s)stuVerifier();
  else if(Math.floor(_stu.cumul[k])!==_stu.sec){ _stu.sec=Math.floor(_stu.cumul[k]); stuMissionsMaj(); }
}
function stuVerifier(){
  if(!_stu)return;
  if(_stu.mode==="eval"){ stuMissionsMaj(); return; }
  const ms=_stu.x.missions; let chg=false;
  for(let k=0;k<ms.length;k++){
    if(_stu.faits[k])continue;
    const e=stuEtatOk(ms[k]);
    const ok=(e===null)?((_stu.cumul[k]||0)>=ms[k].s):e;
    if(!ok)break;
    _stu.faits[k]=true; chg=true;
  }
  stuMissionsMaj();
  if(chg){ _stu.conseil=""; stuMissionsMaj(); try{ jouerEffet("valider"); }catch(e){} }
  if(!_stu.fini&&_stu.faits.every(Boolean))stuReussi();
}
function stuMissionsMaj(){
  const z=document.getElementById("stuMissions"); if(!z||!_stu)return;
  if(_stu.mode==="eval"){
    z.innerHTML='<div class="stu-mt"><i class="ph-fill ph-clipboard-text"></i> Consignes</div>'
      +_stu.x.missions.map(function(m,k){ return '<div class="stu-mi eval"><b>'+(k+1)+'.</b><span>'+m.txt+'</span></div>'; }).join("")
      +(_stu.conseil?'<div class="stu-conseil"><i class="ph-fill ph-info"></i><span>'+_stu.conseil+'</span></div>':"");
    return;
  }
  const ms=_stu.x.missions, cour=_stu.faits.indexOf(false);
  z.innerHTML='<div class="stu-mt"><i class="ph-fill ph-clipboard-text"></i> Missions <span>'+_stu.faits.filter(Boolean).length+' / '+ms.length+'</span></div>'
    +ms.map(function(m,k){
      const fait=_stu.faits[k], ec=(k===cour);
      const prog=(ec&&m.s&&stuEtatOk(m)===null)?' <em>'+Math.min(m.s,Math.floor(_stu.cumul[k]||0))+' s / '+m.s+' s</em>':'';
      return '<div class="stu-mi'+(fait?" fait":"")+(ec?" cour":"")+'"><i class="ph'+(fait?"-fill ph-check-circle":(ec?" ph-arrow-circle-right":" ph-circle"))+'"></i><span>'+m.txt+prog+'</span></div>';
    }).join("")
    +((_stu.conseil&&cour>=0)?'<div class="stu-conseil"><i class="ph-fill ph-lightbulb"></i><span>'+_stu.conseil+'</span></div>':"");
}
function stuReussi(){
  _stu.fini=true;
  if(_stu.surReussi)_stu.surReussi();
}
/* Note de l'épreuve de studio (fin d'évaluation) : une ligne par manipulation. */
function stuNoter(x){
  const P=_stuProj[x.projet]||{pistes:[]};
  return x.missions.map(function(m){
    let ok=false; try{ ok=!!stuEtatOk(m,P); }catch(e){}
    return {q:"Studio : "+String(m.court||m.txt).replace(/<[^>]+>/g,""), rep:ok?"réussi":"non réussi", sol:"", ok:ok};
  });
}
document.addEventListener("keydown",function(e){
  if(!_stu||!_stu.box||!document.body.contains(_stu.box))return;
  const t=e.target, temps=t&&t.classList&&t.classList.contains("stu-temps-in");
  const saisie=t&&(t.tagName==="INPUT"||t.tagName==="TEXTAREA"||t.tagName==="SELECT"||t.isContentEditable)&&!temps&&t.type!=="range";
  if(saisie)return;                       /* on ne vole jamais la frappe d'un vrai champ de texte */
  if(temps&&e.key==="Enter"){ e.preventDefault(); t.blur(); return; }
  if(e.key===" "||e.code==="Space"){ e.preventDefault(); stuLecture(); return; }
  /* Suppr : dans les cases de temps aussi (on y efface avec la touche ← retour arrière) */
  if(e.key==="Delete"||(e.key==="Backspace"&&!temps)){ e.preventDefault(); stuSupprimer(); }
});
window.addEventListener("resize",function(){ if(_stu&&document.body.contains(_stu.box)){ _stu.P.pistes.forEach(function(p){p.pk=null;}); stuDessiner(); } });
document.addEventListener("click",function(ev){ const pop=document.getElementById("stuPop"); if(!pop||pop.hidden)return;
  const chemin=ev.composedPath?ev.composedPath():[ev.target];
  if(!chemin.some(function(n){ return n.classList&&(n.classList.contains("stu-pop")||n.classList.contains("stu-menu")); }))stuPopFermer(); });

/* Épreuves de studio ajoutées à la FIN d'une évaluation de cours (une manipulation = un point). */
/* Jeu de rôle et savoirs communs à l'atelier et à l'épreuve « Faint ». Source vérifiée
   (Wikipédia « Faint (song) », Linkinpedia) : l'intro est un sample JOUÉ À L'ENVERS de
   « Tania Meets Klebb » (John Barry, Bons baisers de Russie, 1963), découvert en 2025. */
const FAINT_ROLE=`<div class="recre-bulle"><span class="rb-av"><i class="ph-fill ph-vinyl-record"></i></span><div>«&nbsp;Salut&nbsp;! C'est <b>Mr. Hahn</b>, le DJ de Linkin Park : dans le groupe, je m'occupe des platines et des <b>samples</b>. L'introduction de notre morceau <b>Faint</b> (2003) vient d'un extrait de musique de James Bond que nous avons transformé… mais j'ai perdu mon projet et je ne me souviens plus des réglages&nbsp;! J'ai seulement gardé le résultat. Écoute-le, puis aide-moi à le refabriquer, étape par étape.&nbsp;»<span>Mr. Hahn (Joe Hahn), DJ de Linkin Park</span></div></div>
 <div class="ce-note"><i class="ph ph-book-open"></i> <b>Un sample</b> («&nbsp;échantillon&nbsp;» en anglais) est un <b>court extrait d'un enregistrement existant</b>, réutilisé pour créer un nouveau morceau. On le transforme souvent : on le <b>coupe</b>, on le met en <b>boucle</b>, on l'<b>inverse</b>, on change sa <b>vitesse</b> ou sa <b>hauteur</b>. C'est l'une des bases du rap, de l'électro… et du rock de Linkin Park.</div>
 <div class="ce-note"><i class="ph ph-film-slate"></i> <b>D'où vient l'extrait&nbsp;?</b> De «&nbsp;<b>Tania Meets Klebb</b>&nbsp;», une musique composée par <b>John Barry</b> pour le 2ᵉ film de James Bond, <b>Bons baisers de Russie</b> (1963). Linkin Park l'a joué <b>à l'envers</b> et l'a transformé jusqu'à en faire les violons nerveux du début de <i>Faint</i>. Le secret était si bien caché que les fans ne l'ont découvert qu'en <b>2025</b>, plus de vingt ans après la sortie du morceau&nbsp;!</div>`;
const FAINT_MISSIONS=[
  {t:"importe",p:"faint",court:"Importer l'extrait de James Bond",
   txt:"<b>Importer l'extrait de James Bond</b><ol><li>Clique sur le menu <b>Fichier</b>.</li><li>Clique sur «&nbsp;Tania Meets Klebb&nbsp;». La piste apparaît dans le studio.</li></ol>"},
  {t:"fn",f:"faintCoupe",p:"faint",court:"Garder seulement le passage de 12,1 s à 17,6 s",
   txt:"<b>Ne garder que le passage de 12,1 s à 17,6 s</b><ol><li>Dans la case <b>début</b> (sous le studio), tape <b>17,6</b>, puis clique sur <b>jusqu'à la fin</b>.</li><li>Appuie sur la touche <b>Suppr</b> du clavier (ou Édition ▸ Supprimer la sélection).</li><li>Tape <b>0</b> dans la case <b>début</b> et <b>12,1</b> dans la case <b>fin</b>.</li><li>Appuie encore sur <b>Suppr</b>. La piste ne dure plus que 5,5 s.</li></ol>"},
  {t:"fn",f:"faintInverse",p:"faint",court:"Inverser le passage",
   txt:"<b>Jouer le passage à l'envers</b><ol><li>Clique sur <b>Tout sélectionner</b> (en haut à droite du studio).</li><li>Effets ▸ <b>Inverser le sens</b>. Écoute (touche <b>Espace</b>) : les notes «&nbsp;montent&nbsp;» au lieu de frapper.</li></ol>"},
  {t:"fn",f:"faintBoucle",p:"faint",court:"Mettre la fin en boucle (coller 3 fois)",
   txt:"<b>Faire une boucle avec la fin</b><ol><li>Tape <b>4,7</b> dans la case <b>début</b>, puis clique sur <b>jusqu'à la fin</b>.</li><li>Édition ▸ <b>Copier</b>.</li><li>Édition ▸ <b>Coller</b>, <b>trois fois</b> de suite. La piste dure alors 7,9 s.</li></ol>"},
  {t:"fn",f:"faintReprise",p:"faint",court:"Recopier le tout à la suite (coller 1 fois)",
   txt:"<b>Rejouer le tout une deuxième fois</b><ol><li>Tape <b>1,2</b> dans la case <b>début</b>, puis clique sur <b>jusqu'à la fin</b>.</li><li>Édition ▸ <b>Copier</b>.</li><li>Édition ▸ <b>Coller</b>, <b>une seule fois</b>. La piste dure alors 14,6 s.</li></ol>"},
  {t:"fn",f:"faintHauteur",p:"faint",court:"Monter la hauteur de 2 demi-tons",
   txt:"<b>Rendre le son un peu plus aigu</b><ol><li>Clique sur <b>Tout sélectionner</b>.</li><li>Effets ▸ <b>Changer la hauteur</b>.</li><li>Tape <b>2</b> (demi-tons), puis clique sur <b>Appliquer</b>. Compare avec le résultat de Mr. Hahn&nbsp;!</li></ol>"}
];
/* Épreuves de studio ajoutées à la FIN d'une évaluation de cours (une manipulation = un point). */
const STU_EVAL={
  "evalcours-recre":{projet:"faint-eval",biblio:["faint"],minutes:8,modele:"sons/recre-faint-modele.mp3",
    titre:"Aide Mr. Hahn à refabriquer le sample de « Faint »",
    consigne:FAINT_ROLE+`<p style="margin:10px 0 0"><b>Dernière épreuve : le studio.</b> Suis les étapes dans l'ordre. Chaque étape réussie rapporte <b>un point</b>. Si tu te trompes, clique sur <b>Annuler</b>. Raccourcis : <b>Espace</b> = lecture / pause, <b>Suppr</b> = supprimer la sélection.</p>`,
    missions:FAINT_MISSIONS,
    /* questions posées APRÈS le studio, avec l'écoute de « Faint » (vidéo officielle) */
    apres:{yt:"LYU-8IFcDPw",lib:"Linkin Park, Faint (2003) : écoute surtout le début",questions:[
      {id:"f1",q:"Écoute le début de « Faint ». Qu'entends-tu dans l'introduction&nbsp;?",r:"le sample que tu viens de fabriquer",o:["le sample que tu viens de fabriquer","un solo de guitare électrique","un piano qui joue seul","une chorale qui chante a cappella"],expl:"Les violons nerveux du début sont le sample : l'extrait de James Bond joué à l'envers et transformé."},
      {id:"f2",q:"Quel est le lien entre « Faint » et le film <i>Bons baisers de Russie</i>&nbsp;?",r:"son début reprend un extrait de la musique du film",o:["son début reprend un extrait de la musique du film","le chanteur de Linkin Park joue dans le film","le film utilise « Faint » pour son générique","il n'y a aucun lien entre les deux"],expl:"L'introduction de <i>Faint</i> est un sample de « Tania Meets Klebb », la musique de John Barry pour <i>Bons baisers de Russie</i> (1963)."},
      {id:"f3",q:"Quel caractère le sample donne-t-il au début de « Faint »&nbsp;?",r:"nerveux et tendu",o:["nerveux et tendu","calme et reposant","joyeux et dansant","lent et endormi"],expl:"Joué à l'envers, en boucle et plus aigu, l'extrait devient nerveux et tendu : il lance l'énergie du morceau."}]}}
};
/* Atelier d'entraînement : la même épreuve, missions cochées au fur et à mesure. */
function ecranStudioAtelier(id){
  const ep=STU_EVAL[id]; if(!ep)return;
  masquerInterfaceNormale();
  majRetour(function(){ afficherLeconCours(id); },"Entraînement et évaluation");
  const ti=document.getElementById("titre"), it=document.getElementById("intro");
  ti.style.display=""; it.style.display="";
  ti.innerHTML='<i class="ph ph-waveform"></i> Atelier studio'; it.textContent=ep.titre;
  const x=Object.assign({},ep,{projet:"faint-atelier",missions:ep.missions.concat([{t:"ecoute",p:["faint"],s:8,txt:"Écoute le sample que tu as fabriqué (8 secondes)."}])});
  document.getElementById("zone").innerHTML='<div class="accueil" style="max-width:920px"><div class="ex">'
    +FAINT_ROLE
    +'<p style="margin:10px 0 12px;color:var(--encre-doux);font-size:.9rem"><i class="ph ph-info"></i> Dans l\'évaluation, la même épreuve arrive <b>après les questions</b>, mais rien n\'y est coché : entraîne-toi ici jusqu\'à réussir tout le montage. Raccourcis : <b>Espace</b> = lecture / pause, <b>Suppr</b> = supprimer la sélection.</p>'
    +'<div class="stu" id="stuAtelier"></div><div class="ce-corr" id="stuAtelierCorr"></div>'
    +'<div style="text-align:center;margin-top:12px"><button class="action btn-nouv" onclick="delete _stuProj[\'faint-atelier\'];_stuPresse=null;ecranStudioAtelier(\''+id+'\')"><i class="ph ph-arrow-counter-clockwise"></i> Recommencer à zéro</button></div>'
    +'</div></div>';
  stuDemarrer(document.getElementById("stuAtelier"),x,{mode:"entrain",surReussi:function(){
    const c=document.getElementById("stuAtelierCorr");
    if(c){ c.className="ce-corr gagne"; c.innerHTML='<div class="cc-score"><i class="ph-fill ph-seal-check"></i> Bravo, ton sample est prêt&nbsp;!</div><div class="cc-expl">Mr. Hahn te remercie&nbsp;! Tu as refait le travail de Linkin Park : un court passage de «&nbsp;Tania Meets Klebb&nbsp;» (Bons baisers de Russie), <b>coupé</b>, <b>inversé</b>, <b>mis en boucle</b> et rendu plus <b>aigu</b>, devient l\'introduction d\'un morceau de rock. C\'est ça, un <b>sample</b>. Tu es prêt pour l\'épreuve de l\'évaluation.</div>'; }
    try{ jouerEffet("victoire"); }catch(e){}
    const j=new Date().toISOString().slice(0,10); profil.atelierLe=profil.atelierLe||{};
    if(profil.atelierLe[id]!==j){ profil.atelierLe[id]=j; try{ ajouterPoints(5); sauverProfil(profil); }catch(e){} }
  }});
  if(typeof remonter==="function")remonter();
}

/* =====================================================================
   SOUTENIR MusEduc : page de dons (PayPal, Buy Me a Coffee)
   Les liens sont de simples boutons maison aux couleurs de l'app : pas de
   script externe à charger, donc rien qui ralentisse ou piste l'élève.
   ===================================================================== */
const DON_PAYPAL="https://www.paypal.com/donate/?hosted_button_id=GR922MLA973NW";
const DON_BMC="";   /* ← colle ici ton lien Buy Me a Coffee (https://www.buymeacoffee.com/tonpseudo) ;
                       tant qu'il est vide, le bouton correspondant reste masqué. */

/* Page « Soutenir » (05/10/2026) : honnête et motivante. Ce que l'on finance,
   ce qui existe déjà (chiffres réels tirés de l'application), des montants
   indicatifs, et les façons d'aider sans payer. Vouvoiement pour les adultes
   (professeur, élève en solo), tutoiement pour les élèves. */
function soutienChiffres(){
  let lecons=0, compos=0, mots=0, cours=0;
  try{ lecons=CATEGORIES.filter(function(g){ return !g.special; }).reduce(function(n,g){ return n+g.items.length; },0); }catch(e){}
  try{ compos=Object.keys(QUIZ_COMPO).length; }catch(e){}
  try{ mots=Object.keys(VOC_INDEX).length; }catch(e){}
  try{ cours=Object.keys(COURS_DEF).length; }catch(e){}
  return {lecons:lecons,compos:compos,mots:mots,cours:cours};
}
/* =====================================================================
   STOCKAGE DU NAVIGATEUR : diagnostic (05/10/2026). Quand le navigateur
   refuse d'enregistrer, on montre pourquoi (plein ou bloqué), ce qui prend
   la place, et on propose de libérer ce qui peut l'être sans rien perdre.
   ===================================================================== */
const STOCK_CLES={"educmus_profil_v1":["Progression et réglages","garder"],
  "educmus_labels_v1":["Noms de vos élèves (uniquement sur cet appareil)","garder"],
  "educmus_roster_v1":["Liste de classe importée","garder"],
  "educmus_contacts_v1":["Contacts des familles","garder"],
  "museduc_entete_bulletin_v1":["En-tête des bulletins","garder"],
  "museduc-role":["Rôle du compte (se recharge seul)","libre"],
  "museduc-mae-lus":["Messages de Maestro déjà lus","libre"],
  "theme":["Thème clair ou sombre","libre"]};
function stockageInfo(k){
  if(STOCK_CLES[k])return STOCK_CLES[k];
  if(/^firebase:/.test(k))return ["Session de connexion (Firebase)","garder"];
  if(/^seanceDer_|^ccx/.test(k))return ["Mémo d'affichage","libre"];
  return ["Donnée inconnue (ancienne version ou autre site)","inconnu"];
}
function stockageAlerte(){
  if(document.getElementById("stockAlerte"))return;
  const b=document.createElement("div"); b.id="stockAlerte"; b.className="stock-alerte";
  b.innerHTML='<i class="ph-fill ph-warning"></i><span><b>Ce navigateur n\u2019enregistre pas MusEduc.</b> Vos réglages seront perdus en fermant la page.</span>'
    +'<button onclick="ecranStockage()">Voir pourquoi</button><button class="x" onclick="this.parentNode.remove()" aria-label="Fermer"><i class="ph ph-x"></i></button>';
  document.body.appendChild(b);
}
function stockageTest(){
  try{ localStorage.setItem("__museduc_test","x"); localStorage.removeItem("__museduc_test"); return "ok"; }
  catch(e){ return String((e&&e.name)||"erreur"); }
}
function ecranStockage(){
  const al=document.getElementById("stockAlerte"); if(al)al.remove();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  document.getElementById("titre").innerHTML='<i class="ph ph-hard-drives"></i> Stockage de ce navigateur';
  document.getElementById("intro").textContent="";
  const test=stockageTest();
  let cles=[], total=0;
  try{ for(let i=0;i<localStorage.length;i++){ const k=localStorage.key(i), v=localStorage.getItem(k)||""; const n=(k.length+v.length)*2; total+=n; cles.push({k:k,n:n}); } }catch(e){}
  cles.sort(function(a,b){ return b.n-a.n; });
  const ko=function(n){ return n<1024?n+" o":(n<1048576?Math.round(n/1024)+" Ko":(Math.round(n/104857.6)/10)+" Mo"); };
  const diag=test==="ok"?'<div class="stock-etat ok"><i class="ph-fill ph-check-circle"></i> Le navigateur enregistre normalement.</div>'
    :(/Quota/i.test(test)?'<div class="stock-etat ko"><i class="ph-fill ph-warning"></i> <b>Stockage plein.</b> Libérez de la place ci-dessous : les lignes « libre » ou « inconnu » peuvent être supprimées.</div>'
      :'<div class="stock-etat ko"><i class="ph-fill ph-warning"></i> <b>Stockage bloqué</b> ('+echapH(test)+'). C\u2019est souvent la <b>navigation privée</b> ou un réglage du navigateur qui interdit les données de sites (cookies et données de sites bloqués pour museduc.fr). Ouvrez MusEduc dans une fenêtre normale ou autorisez les données de ce site.</div>');
  const lignes=cles.map(function(c){
    const inf=stockageInfo(c.k);
    return '<div class="stock-l '+inf[1]+'"><span class="stock-k"><b>'+echapH(inf[0])+'</b><small>'+echapH(c.k)+'</small></span><span class="stock-n">'+ko(c.n)+'</span>'
      +(inf[1]==="garder"?'<span class="stock-tag">à garder</span>':'<button class="stock-sup" onclick="stockageSupprimer(\''+c.k.replace(/'/g,"\\'")+'\')"><i class="ph ph-trash"></i></button>')+'</div>';
  }).join("")||'<p class="badge-vide">Rien d\u2019enregistré.</p>';
  document.getElementById("zone").innerHTML='<div class="accueil" style="max-width:760px">'+diag
    +'<div class="ex"><h3 style="margin-top:0"><i class="ph ph-database"></i> Ce que MusEduc garde ici <span class="stock-total">'+ko(total)+' au total</span></h3>'+lignes+'</div>'
    +'<p class="stock-aide"><i class="ph ph-info"></i> Vos classes, notes, périodes et tampon des diplômes sont aussi dans votre compte : seuls les <b>noms des élèves</b> ne vivent que sur cet appareil (pensez à la Sauvegarde dans les Paramètres).</p></div>';
  if(navigator.storage&&navigator.storage.estimate)navigator.storage.estimate().then(function(e){
    const h=document.querySelector(".stock-total"); if(h&&e&&e.quota)h.textContent+=" · navigateur : "+ko(e.usage||0)+" utilisés sur "+ko(e.quota); }).catch(function(){});
}
async function stockageSupprimer(k){
  if(!await dlgConfirmer("Supprimer « "+k+" » de ce navigateur ?"))return;
  try{ localStorage.removeItem(k); }catch(e){}
  if(stockageTest()==="ok"){ window._stockageKO=false; try{ sauverProfil(profil); }catch(e){} toast("Place libérée : MusEduc peut de nouveau enregistrer."); }
  ecranStockage();
}
function ecranSoutien(){
  if(typeof fermerMenu==="function")fermerMenu();
  masquerInterfaceNormale(); majRetour(accueil,"Accueil");
  const t=etatCompte().type, vous=(t==="prof"||t==="apprenant");
  const V=function(a,b){ return vous?a:b; };
  document.getElementById("titre").innerHTML='<i class="ph-fill ph-hand-heart"></i> Soutenir MusEduc';
  document.getElementById("intro").textContent="";
  const c=soutienChiffres();
  /* « + de » toujours vrai : seuil arrondi à la dizaine en dessous (ou n-1 pour les petits nombres),
     il suit tout seul quand du contenu est ajouté */
  const plusDe=function(n){ return n<=1?n:(n>=20?Math.floor((n-1)/10)*10:n-1); };
  const chiffre=function(n,lib,ic){ return '<div class="so-chiffre"><i class="ph-fill ph-'+ic+'"></i><b><small>+ de</small> '+plusDe(n)+'</b><span>'+lib+'</span></div>'; };
  const finance=function(ic,teinte,titre,txt){ return '<div class="so-fin" style="--d:'+teinte+'"><span><i class="ph-fill ph-'+ic+'"></i></span><b>'+titre+'</b><small>'+txt+'</small></div>'; };
  const montant=function(v,lib,ic){ return '<a class="so-montant" href="'+DON_PAYPAL+'" target="_blank" rel="noopener noreferrer"><i class="ph-fill ph-'+ic+'"></i><b>'+v+'</b><small>'+lib+'</small></a>'; };
  document.getElementById("zone").innerHTML=`
   <div class="accueil so" style="max-width:900px">
     <div class="so-hero">
       <img src="${IMG_FELICITE}" alt="Maestro" class="so-maestro">
       <div class="so-hero-txt">
         <div class="so-eyebrow"><i class="ph-fill ph-heart"></i> Fait par un prof, pour les élèves</div>
         <h2>MusEduc grandit grâce à ${V("vous","toi")}</h2>
         <p>Pas de publicité, pas de revente de données, pas d'investisseur&nbsp;: juste un professeur de musique qui, le soir, crée des leçons et des jeux pour que chacun prenne plaisir à apprendre la musique.</p>
         <div class="so-ctas">
           <a class="so-cta" href="${DON_PAYPAL}" target="_blank" rel="noopener noreferrer"><i class="ph-fill ph-heart"></i> Faire un don</a>
           ${DON_BMC?`<a class="so-cta sec" href="${DON_BMC}" target="_blank" rel="noopener noreferrer"><i class="ph-fill ph-coffee"></i> Offrir un café</a>`:""}
         </div>
       </div>
     </div>

     <div class="so-chiffres">
       ${chiffre(c.lecons,"leçons","graduation-cap")}${chiffre(c.cours,"cours de collège","chalkboard-simple")}
       ${chiffre(c.compos,"compositeurs","music-notes")}${chiffre(c.mots,"mots de vocabulaire","cards")}
     </div>
     <p class="so-sous">Déjà disponibles, gratuitement, pour tout le monde.</p>

     <h3 class="so-h3">Ce que ${V("votre","ton")} soutien finance</h3>
     <div class="so-fins">
       ${finance("cloud-check","var(--dom-lire)","Les serveurs","Pour que les comptes, les notes et les jeux en direct marchent chaque jour.")}
       ${finance("music-notes-plus","var(--dom-theorie)","De nouvelles leçons","Styles, compositeurs, cours interactifs, exercices sonores.")}
       ${finance("game-controller","var(--dom-rythme)","De nouveaux jeux","Pour que réviser reste un plaisir, seul, à deux ou en classe.")}
       ${finance("clock","var(--dom-culture)","Du temps","Corriger les bugs, écouter les idées, améliorer chaque détail.")}
     </div>

     <h3 class="so-h3">Un coup de pouce, à ${V("votre","ton")} rythme</h3>
     <div class="so-montants">
       ${montant("3 €","un café pour le développeur","coffee")}
       ${montant("10 €","aide à créer une nouvelle leçon","music-note")}
       ${montant("25 €","un vrai coup d'accélérateur","rocket-launch")}
       ${montant("Libre","le montant que "+V("vous voulez","tu veux"),"hand-heart")}
     </div>
     <p class="so-confiance"><i class="ph-fill ph-shield-check"></i> Paiement sur le site sécurisé de PayPal (carte bancaire possible, sans compte). MusEduc ne voit aucune donnée bancaire. Montants indicatifs, rien n'est jamais bloqué si ${V("vous ne donnez","tu ne donnes")} pas.</p>

     <h3 class="so-h3">Aider sans dépenser un centime</h3>
     <div class="so-gratuit">
       <button class="so-g" onclick="partagerMusEduc()"><span><i class="ph-fill ph-share-network"></i></span><b>Partager</b><small>${V("à un collègue, à un ami","à tes amis, à ton prof")}</small></button>
       <a class="so-g" href="mailto:contact@museduc.fr?subject=Un%20bug%20dans%20MusEduc"><span><i class="ph-fill ph-bug"></i></span><b>Signaler un bug</b><small>une faute, un souci</small></a>
       <a class="so-g" href="mailto:contact@museduc.fr?subject=Une%20id%C3%A9e%20pour%20MusEduc"><span><i class="ph-fill ph-lightbulb"></i></span><b>Proposer une idée</b><small>une leçon, un jeu</small></a>
     </div>
     <p class="don-legal"><a href="legal.html#cgv" target="_blank" rel="noopener">Mentions légales et informations sur les dons</a></p>
   </div>`;
  if(typeof remonter==="function")remonter();
}
/* Partager MusEduc : la page de présentation (vitrine), par le menu de partage du
   téléphone quand il existe, sinon en copiant le lien. */
/* Le message donne envie de cliquer s'il parle à celui qui le reçoit : un
   professeur écrit à un collègue (temps gagné, notes prêtes, classe qui
   s'anime), un élève défie un camarade. Concret, court, personnel, sans
   promesse, et le lien arrive juste après une invitation à regarder. */
function partageMessage(){
  let t="anon"; try{ t=etatCompte().type; }catch(e){}
  if(t==="prof"||(typeof estCollegue==="function"&&estCollegue()))return {
    sujet:"Un outil pour tes cours d'éducation musicale",
    texte:"Salut ! J'utilise MusEduc avec mes classes et je pense que ça va te plaire.\n\n"
      +"· Les élèves s'entraînent seuls (lecture de notes, rythme, écoute, compositeurs) et progressent par paliers.\n"
      +"· Tu donnes un travail en deux clics et tu récupères les notes, prêtes pour Pronote.\n"
      +"· En classe, on lance un jeu au tableau sur les téléphones ou les tablettes : la salle se réveille d'un coup.\n\n"
      +"Gratuit, sans pub, rien à installer, et aucun nom d'élève n'est stocké.\n"
      +"Les mini-vidéos montrent tout en une minute :"};
  if(t==="eleve")return {
    sujet:"Viens me battre sur MusEduc",
    texte:"J'apprends la musique sur MusEduc et c'est vraiment un jeu : duel à la corde, L'ascension, le Calmar musical, des badges à gagner…\n"
      +"Je te mets au défi de faire mieux que moi 😉\n\n"
      +"Regarde à quoi ça ressemble :"};
  return {
    sujet:"Apprendre la musique en jouant : regarde ça",
    texte:"J'ai découvert MusEduc : on apprend la musique en jouant (lecture de notes, rythme, écoute, compositeurs) avec Maestro, et les professeurs suivent leurs classes.\n"
      +"Gratuit, sans pub, rien à installer.\n\n"
      +"Les mini-vidéos montrent tout en une minute :"};
}
async function partagerMusEduc(){
  const url=new URL("vitrine.html",location.href).href;
  const m=partageMessage(), sujet=m.sujet, texte=m.texte;
  /* Téléphone et tablette : le menu de partage du système (WhatsApp, Signal,
     Messages, e-mail…), l'élève choisit l'application. Sur ordinateur,
     navigator.share peut faire planter l'onglet (Chrome sous Windows :
     RESULT_CODE_KILLED_BAD_MESSAGE) : on ouvre la messagerie à la place. */
  const tactile=window.matchMedia&&window.matchMedia("(pointer:coarse)").matches;
  if(tactile&&navigator.share){
    try{ await navigator.share({title:"MusEduc",text:texte,url:url}); return; }
    catch(e){ if(e&&e.name==="AbortError")return; }
  }
  /* Ordinateur : un e-mail tout prêt dans la messagerie (Outlook, Thunderbird,
     Gmail si c'est la messagerie par défaut…), et le lien copié au cas où aucune
     messagerie ne s'ouvre. */
  const corps=texte+"\n\n"+url+"\n";
  const a=document.createElement("a");
  a.href="mailto:?subject="+encodeURIComponent(sujet)+"&body="+encodeURIComponent(corps);
  document.body.appendChild(a); a.click(); a.remove();
  let copie=false;
  try{ await navigator.clipboard.writeText(url); copie=true; }catch(e){}
  toast(copie?"Ta messagerie s'ouvre avec le message prêt. Le lien est aussi copié : tu peux le coller ailleurs."
             :"Ta messagerie s'ouvre avec le message prêt.");
}
/* Bannière de soutien bien visible (accueil du professeur et de l'élève en solo). */
